	window.triggerCapture = async () => { await refreshUpgradeAutomationExecutionSummary(); const s = window.schedulerSummary; const now = new Date(); const sched = getUpgradeAutomationScheduleState(s, globalSettings, now); window.schedulerCaptureRaw = JSON.parse(JSON.stringify(sched?.rows || [])); window.schedulerPendingPlanRows = sched?.rows || []; window.schedulerLastPlanSchedule = sched; window.schedulerCaptureNow = now; console.log('[Scheduler] CAPTURE rows:', sched?.rows?.length, 'rows'); return window.schedulerCaptureRaw; };
	window.triggerWrite = async () => { if (!window.schedulerPendingPlanRows?.length) { console.log('[Scheduler] No pending rows - run triggerCapture() first'); return; } const writeNow = window.schedulerCaptureNow || new Date(); console.log('[Scheduler] MANUAL WRITE starting at', writeNow.toISOString()); await applyUpgradeAutomationExecutionToCraftConfig(window.schedulerPendingPlanRows, window.schedulerLastPlanSchedule || {}, globalSettings, writeNow); console.log('[Scheduler] MANUAL WRITE complete'); }; // Viktor: manual capture
	let upgradeAutomationInfluxDebugLine = '';
	let upgradeAutomationInfluxDebugStatus = '';
	const UPGRADE_AUTOMATION_TARGET_BUFFER_DAYS = 10;
	const UPGRADE_AUTOMATION_LANDING_BUFFER_SECONDS = 30;
	const UPGRADE_AUTOMATION_MIN_JOB_CREW = 10;

	async function loadUpgradeAutomationEvents() {
		const raw = await GM.getValue(UPGRADE_AUTOMATION_EVENTS_KEY, '[]');
		try { const arr = JSON.parse(raw); return Array.isArray(arr) ? arr : []; } catch { return []; }
	}

	async function saveUpgradeAutomationEvents(events) {
		await GM.setValue(UPGRADE_AUTOMATION_EVENTS_KEY, JSON.stringify(events.slice(-5000)));
		scheduleSlyaStateBackup('upgrade-automation-events');
	}

	async function recordUpgradeAutomationEvent(evt) {
		const now = Date.now();
		const cutoff = now - 48 * 3600 * 1000;
		let events = await loadUpgradeAutomationEvents();
		events = events.filter(e => Number(e?.ts || 0) >= cutoff);
		events.push(evt);
		upgradeAutomationRecentEvents = events.filter(e => Number(e?.ts || 0) >= (now - 24 * 3600 * 1000));
		await saveUpgradeAutomationEvents(events);
		try { renderAssistStats(); } catch (e) {}
	}

	function cloneForSlyaStateBackup(value) {
		try { return JSON.parse(JSON.stringify(value || {})); } catch (e) { return {}; }
	}

	async function getGmValueKeys() {
		try {
			if (typeof GM !== 'undefined' && typeof GM.listValues === 'function') return await GM.listValues();
			if (typeof GM_listValues === 'function') return GM_listValues();
		} catch (error) {
			cLog(1, '[SLYA-STATE-BAK] failed to list GM values', error);
		}
		return [];
	}

	async function getParsedGmValue(key, fallback = null) {
		try {
			const raw = await GM.getValue(key, '');
			if (!raw) return fallback;
			return JSON.parse(raw);
		} catch (error) {
			return fallback;
		}
	}

	function isCurrentSlyaSettingsMissing(settings, rawSettingsData, parseError) {
		if (parseError) return true;
		if (!rawSettingsData || String(rawSettingsData).trim() === '' || String(rawSettingsData).trim() === '{}') return true;
		if (!settings || typeof settings !== 'object' || Array.isArray(settings)) return true;
		return Object.keys(settings).length === 0;
	}

	function isSlyaFleetConfigCandidate(key, data) {
		if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
		if (key === settingsGmKey || String(key).startsWith('craft')) return false;
		return data.assignment !== undefined
			|| data.mineResource !== undefined
			|| data.destCoord !== undefined
			|| data.starbaseCoord !== undefined
			|| data.moveType !== undefined
			|| data.maxCargo !== undefined
			|| data.maxAmmo !== undefined
			|| data.maxFuel !== undefined
			|| data.transportPlusTargets !== undefined
			|| data.scanBlock !== undefined;
	}

	async function buildSlyaStateBackupPayload(reason) {
		const keys = await getGmValueKeys();
		const keySet = new Set(keys);
		const settings = cloneForSlyaStateBackup(globalSettings);
		const fleetConfigs = {};
		const craftConfigs = {};
		const extraState = {};
		let fleetsForBackup = [];
		try { fleetsForBackup = Array.isArray(userFleets) ? userFleets : []; } catch (e) { fleetsForBackup = []; }

		if (fleetsForBackup.length) {
			for (const fleet of fleetsForBackup) {
				const key = fleet?.publicKey?.toString ? fleet.publicKey.toString() : String(fleet?.publicKey || '');
				if (!key) continue;
				const data = await getParsedGmValue(key, null);
				if (data) fleetConfigs[key] = data;
			}
		}
		for (const key of keySet) {
			if (fleetConfigs[key]) continue;
			const data = await getParsedGmValue(key, null);
			if (isSlyaFleetConfigCandidate(key, data)) fleetConfigs[key] = data;
		}

		let maxCraftSlot = Number(settings.craftingJobs || 0);
		for (const key of keySet) {
			const match = String(key).match(/^craft(\d+)$/);
			if (match) maxCraftSlot = Math.max(maxCraftSlot, Number(match[1] || 0));
		}
		for (let i = 1; i <= maxCraftSlot; i++) {
			const key = 'craft' + i;
			const data = await getParsedGmValue(key, null);
			if (data) craftConfigs[key] = data;
		}

		for (const key of keySet) {
			const shouldCapture = key === UPGRADE_AUTOMATION_EVENTS_KEY
				|| key === 'upgradeAutomationSchedulerObservedState'
				|| String(key).startsWith(UPGRADE_AUTOMATION_STATE_PREFIX)
				|| String(key).startsWith(UPGRADE_TELEMETRY_PREFIX);
			if (!shouldCapture) continue;
			const data = await getParsedGmValue(key, null);
			if (data) extraState[key] = data;
		}

		const activeCrafting = Object.values(craftConfigs).filter(craft => craft && craft.craftingId);
		const metadata = {
			generatedAtMs: Date.now(),
			reason: String(reason || 'unknown'),
			gmKeyCount: keySet.size,
			settingsKeyCount: Object.keys(settings || {}).length,
			fleetConfigCount: Object.keys(fleetConfigs || {}).length,
			craftConfigCount: Object.keys(craftConfigs || {}).length,
			activeCraftingCount: activeCrafting.length,
			extraStateCount: Object.keys(extraState || {}).length,
			lastConfigSaveAt: slyaLastConfigSaveAtMs ? new Date(slyaLastConfigSaveAtMs).toISOString() : null,
			lastStateBackupAt: slyaLastStateBackupAtMs ? new Date(slyaLastStateBackupAtMs).toISOString() : null,
			lastLeveldbBackupAt: slyaLastLeveldbBackupAtMs ? new Date(slyaLastLeveldbBackupAtMs).toISOString() : null
		};

		return {
			schemaVersion: SLYA_STATE_BACKUP_SCHEMA_VERSION,
			reason: String(reason || 'unknown'),
			aephiaVersion: AEPHIA_SLYA_VERSION,
			writtenAt: new Date().toISOString(),
			metadata,
			settings,
			fleetConfigs,
			craftConfigs,
			extraState,
			activeCrafting
		};
	}

	async function writeSlyaStateBackup(reason) {
		if (slyaStateBackupInFlight) {
			try { await appendUpgradeAutomationLog('[SLYA-STATE-BAK] skipped write reason=' + String(reason || 'unknown') + ' alreadyInFlight=true'); } catch (e) {}
			return;
		}
		if (typeof window === 'undefined' || !window.electronAPI?.writeSlyaStateBackup) return;
		slyaStateBackupInFlight = true;
		try {
			const payload = await buildSlyaStateBackupPayload(reason);
			const result = await window.electronAPI.writeSlyaStateBackup(payload);
			if (!result?.ok) cLog(1, '[SLYA-STATE-BAK] write failed', result);
			else {
				slyaLastStateBackupAtMs = Date.now();
				slyaStateBackupCache = payload;
				const meta = payload.metadata || {};
				const line = '[SLYA-STATE-BAK] write ok reason=' + String(reason || 'unknown')
					+ ' bytes=' + Number(result.bytes || 0)
					+ ' settingsKeys=' + Number(meta.settingsKeyCount || 0)
					+ ' fleets=' + Number(meta.fleetConfigCount || 0)
					+ ' crafts=' + Number(meta.craftConfigCount || 0)
					+ ' activeCrafts=' + Number(meta.activeCraftingCount || 0);
				try { cLog(2, line); } catch (e) {}
				try { await appendUpgradeAutomationLog(line); } catch (e) {}
			}
		} catch (error) {
			cLog(1, '[SLYA-STATE-BAK] write error', error);
		} finally {
			slyaStateBackupInFlight = false;
		}
	}

	async function runSlyaPeriodicBackup(reason = 'periodic-5min') {
		await writeSlyaStateBackup(reason);
		const now = Date.now();
		if (typeof window === 'undefined' || !window.electronAPI?.snapshotLeveldbToBackup) return;
		if (slyaLastLeveldbBackupAtMs && now - slyaLastLeveldbBackupAtMs < SLYA_LEVELDB_BACKUP_HEARTBEAT_MS) return;
		try {
			const result = await window.electronAPI.snapshotLeveldbToBackup();
			if (result?.ok) slyaLastLeveldbBackupAtMs = Date.now();
			const line = '[SLYA-STATE-BAK] leveldb periodic snapshot reason=' + String(reason || 'unknown')
				+ ' ok=' + !!result?.ok
				+ ' skipped=' + !!result?.skipped
				+ (result?.error ? ' error=' + String(result.error) : '');
			try { cLog(result?.ok ? 2 : 1, line); } catch (e) {}
			try { await appendUpgradeAutomationLog(line); } catch (e) {}
		} catch (error) {
			try { await appendUpgradeAutomationLog('[SLYA-STATE-BAK] leveldb periodic snapshot error=' + String(error?.message || error)); } catch (e) {}
		}
	}

	function queueLeveldbSafetyBackup(reason, options)
	{
		if (typeof window === 'undefined' || !window.electronAPI?.snapshotLeveldbToBackup) return;
		const tag = String(options?.tag || 'BAK');
		const backupEnqueuedAt = slyaPerfNowMs();
		const invoke = (delayMs) => {
			const start = () => {
				const backupStart = slyaPerfNowMs();
				try { emitSlyaTiming('[' + tag + '][LEVELDB-BACKUP-TIMING] reason=' + String(reason || 'unknown') + ' queue-delay=' + Math.round((backupStart - backupEnqueuedAt) * 10) / 10 + 'ms start'); } catch (e) {}
				window.electronAPI.snapshotLeveldbToBackup().then(result => {
					try { emitSlyaTiming('[' + tag + '][LEVELDB-BACKUP-TIMING] reason=' + String(reason || 'unknown') + ' duration=' + Math.round((slyaPerfNowMs() - backupStart) * 10) / 10 + 'ms ok=' + !!result?.ok + ' skipped=' + !!result?.skipped); } catch (e) {}
				}).catch(async e => {
					try { await appendUpgradeAutomationLog('[' + tag + '][BAK-ERROR] reason=' + String(reason || 'unknown') + ' err=' + String(e?.message || e)); } catch (e2) {}
				});
			};
			if (delayMs > 0) setTimeout(start, delayMs);
			else setTimeout(start, 0);
		};
		try { invoke(options?.delayMs || 0); }
		catch (e) { try { appendUpgradeAutomationLog('[' + tag + '][BAK-ERROR] reason=' + String(reason || 'unknown') + ' err=' + String(e?.message || e)).catch(() => {}); } catch (e2) {} }
	}

	function startSlyaStateBackupHeartbeat() {
		if (slyaStateBackupHeartbeatTimer || typeof window === 'undefined' || !window.electronAPI?.writeSlyaStateBackup) return;
		const tick = () => {
			runSlyaPeriodicBackup('periodic-5min').catch(error => {
				try { appendUpgradeAutomationLog('[SLYA-STATE-BAK] periodic backup error=' + String(error?.message || error)).catch(() => {}); } catch (e) {}
			});
			slyaStateBackupHeartbeatTimer = setTimeout(tick, SLYA_STATE_BACKUP_HEARTBEAT_MS);
		};
		slyaStateBackupHeartbeatTimer = setTimeout(tick, 60 * 1000);
	}

	function scheduleSlyaStateBackup(reason, delayMs = 1500) {
		if (typeof window === 'undefined' || !window.electronAPI?.writeSlyaStateBackup) return;
		if (slyaStateBackupTimer) clearTimeout(slyaStateBackupTimer);
		slyaStateBackupTimer = setTimeout(() => {
			slyaStateBackupTimer = null;
			writeSlyaStateBackup(reason);
		}, delayMs);
	}

	async function readLatestSlyaStateBackup() {
		if (slyaStateBackupCache) return slyaStateBackupCache;
		if (typeof window === 'undefined' || !window.electronAPI?.readSlyaStateBackup) return null;
		try {
			const result = await window.electronAPI.readSlyaStateBackup();
			const backup = result?.best || null;
			const currentAgeMs = result?.current?.writtenAt ? Date.now() - Date.parse(result.current.writtenAt) : null;
			const previousAgeMs = result?.previous?.writtenAt ? Date.now() - Date.parse(result.previous.writtenAt) : null;
			try {
				await appendUpgradeAutomationLog('[SLYA-STATE-BAK] read latest ok=' + !!backup
					+ ' currentAgeMin=' + (Number.isFinite(currentAgeMs) ? Math.round(currentAgeMs / 60000) : 'na')
					+ ' previousAgeMin=' + (Number.isFinite(previousAgeMs) ? Math.round(previousAgeMs / 60000) : 'na')
					+ ' selected=' + (backup === result?.current ? 'current' : backup === result?.previous ? 'previous' : 'none'));
			} catch (e) {}
			if (backup && Number(backup.schemaVersion || 0) === SLYA_STATE_BACKUP_SCHEMA_VERSION) {
				slyaStateBackupCache = backup;
				return backup;
			}
		} catch (error) {
			cLog(1, '[SLYA-STATE-BAK] read error', error);
		}
		return null;
	}

	async function restoreSlyaStateBackupIfCurrentSettingsMissing(reason, rawSettingsData = '', parseError = '') {
		if (!isCurrentSlyaSettingsMissing(globalSettings, rawSettingsData, parseError)) return false;
		const backup = await readLatestSlyaStateBackup();
		if (!backup || !backup.settings) return false;

		await GM.setValue(settingsGmKey, JSON.stringify(backup.settings));
		for (const [key, value] of Object.entries(backup.fleetConfigs || {})) await GM.setValue(key, JSON.stringify(value));
		// craftConfigs: restore only user-configured fields. The runtime-only
		// state (state, craftingId, craftingCoords, feeAtlas, nextAmount,
		// nextRuntime, lpAutomationUpdatedAt, lpAutomationCycleStamp, errorCount)
		// is re-derived on reload from on-chain via recoverCraftingProcessesForAllSlots
		// and from the optimizer's next cycle write via applyUpgradeAutomationExecutionToCraftConfig.
		// Keep amount and crew: those are user configuration, and dropping them
		// makes the external state backup incomplete after a blank-screen reload.
		const PERSISTENT_CRAFT_CONFIG_KEYS = ['coordinates', 'item', 'amount', 'crew', 'special', 'belowAmount'];
		for (const [key, value] of Object.entries(backup.craftConfigs || {})) {
			if (!value || typeof value !== 'object') continue;
			const filtered = {};
			for (const k of PERSISTENT_CRAFT_CONFIG_KEYS) {
				if (value[k] !== undefined) filtered[k] = value[k];
			}
			if (Object.keys(filtered).length) await GM.setValue(key, JSON.stringify(filtered));
		}
		for (const [key, value] of Object.entries(backup.extraState || {})) await GM.setValue(key, JSON.stringify(value));
		globalSettings = cloneForSlyaStateBackup(backup.settings);
		const backupAgeMs = backup.writtenAt ? Date.now() - Date.parse(backup.writtenAt) : null;
		const restoreLine = `[SLYA-STATE-BAK] restored missing current state from latest external backup reason=${String(reason || 'unknown')} backupVersion=${backup.aephiaVersion || 'unknown'} backupAgeMin=${Number.isFinite(backupAgeMs) ? Math.round(backupAgeMs / 60000) : 'na'} settingsKeys=${Object.keys(backup.settings || {}).length} fleets=${Object.keys(backup.fleetConfigs || {}).length} crafts=${Object.keys(backup.craftConfigs || {}).length} activeCrafts=${(backup.activeCrafting || []).length} parseError=${parseError ? String(parseError) : 'none'}`;
		cLog(1, restoreLine);
		try { await appendUpgradeAutomationLog(restoreLine); } catch (e) {}
		return true;
	}

	// Post-reload reconcile: make sure the current cycle's optimizer plan is in
	// GM even if the optimizer hasn't captured it yet this hour. The scheduler
	// captures at xx:57 and writes at xx:57-:58. If the panel reloads in the
	// middle of a non-standard cycle (e.g. phantom starbase was just resumed),
	// the persisted plan may be missing and the slot loops would have nothing
	// to act on for the current xx:59 target window. This re-derives the plan
	// from the LP execution summary, persists it, and writes the craft configs
	// immediately when the write deadline is already past.
	async function reconcileUpgradeAutomationCraftConfigsAfterReload(reason) {
		try {
			if (typeof globalSettings === 'undefined' || !globalSettings || !globalSettings.upgradeAutomationEnabled) return;
			const now = new Date();
			const persistedPlan = await loadUpgradeAutomationSchedulerPlan(globalSettings, now);
			if (persistedPlan && isUpgradeAutomationSchedulerPlanValidForHour(persistedPlan, globalSettings, now)) {
				hydrateUpgradeAutomationSchedulerPlan(persistedPlan);
				try { cLog(1, `[SLYA-RECONCILE] hydrated persisted plan cycleStamp=${persistedPlan.cycleStamp} rows=${(persistedPlan.rows || []).length} reason=${String(reason || 'unknown')}`); } catch (e) {}
				return;
			}
			if (!upgradeAutomationExecutionSummary) {
				try {
					const fetched = await fetchUpgradeAutomationExecutionSummary();
					if (fetched) {
						upgradeAutomationExecutionSummary = fetched;
						window.schedulerSummary = upgradeAutomationExecutionSummary;
					}
				} catch (e) { /* fall through; getUpgradeAutomationSchedulerRowsFromSummary will return empty */ }
			}
			const { rows, targetFinishAtUtc } = getUpgradeAutomationSchedulerRowsFromSummary(upgradeAutomationExecutionSummary || {}, globalSettings, now);
			if (!Array.isArray(rows) || !rows.length || !targetFinishAtUtc) {
				try { cLog(1, `[SLYA-RECONCILE] no current cycle plan derivable; waiting for xx:57 capture reason=${String(reason || 'unknown')}`); } catch (e) {}
				return;
			}
			const schedule = { targetFinishAtUtc };
			await persistUpgradeAutomationSchedulerPlan('reload-reconcile', rows, schedule, globalSettings, now);
			const writeAfter = getUpgradeAutomationSchedulerWriteAfterUtc({ targetFinishAtUtc });
			if (writeAfter && now.getTime() >= new Date(writeAfter).getTime()) {
				await applyUpgradeAutomationExecutionToCraftConfig(rows, schedule, globalSettings, now);
				await writeUpgradeAutomationSchedulerReceipt('reload-reconcile', { rows, targetFinishAtUtc }, globalSettings, now);
				try { cLog(1, `[SLYA-RECONCILE] wrote current cycle plan immediately cycleStamp=${getUpgradeAutomationCycleStamp(now, globalSettings)} rows=${rows.length} target=${targetFinishAtUtc} reason=${String(reason || 'unknown')}`); } catch (e) {}
			} else {
				try { cLog(1, `[SLYA-RECONCILE] persisted current cycle plan cycleStamp=${getUpgradeAutomationCycleStamp(now, globalSettings)} rows=${rows.length} target=${targetFinishAtUtc} writeAfter=${writeAfter} reason=${String(reason || 'unknown')}`); } catch (e) {}
			}
		} catch (e) {
			try { cLog(1, '[SLYA-RECONCILE] error:', e && e.message || e); } catch (_) {}
		}
	}

	async function refreshUpgradeAutomationInfluxStats() {
		try {
			const upgradeResult = await fetchInfluxUpgrading24h();
			upgradeAutomationInfluxUpgrade24h = upgradeResult?.map || {};
			upgradeAutomationInfluxUpgrade24hDebug = upgradeResult?.debug || '';
			upgradeAutomationInfluxUpgrade24hError = '';
		} catch (e) {
			upgradeAutomationInfluxUpgrade24h = {};
			upgradeAutomationInfluxUpgrade24hDebug = '';
			upgradeAutomationInfluxUpgrade24hError = String(e?.message || e || 'unknown_error');
		}
		try {
			const craftResult = await fetchInfluxCrafting24h();
			upgradeAutomationInfluxCraft24h = craftResult?.map || {};
			upgradeAutomationInfluxCraft24hError = '';
		} catch (e) {
			upgradeAutomationInfluxCraft24h = {};
			upgradeAutomationInfluxCraft24hError = String(e?.message || e || 'unknown_error');
		}
		try {
			const inventoryResult = await fetchInfluxInventory();
			upgradeAutomationInfluxInventory = inventoryResult?.map || {};
			upgradeAutomationInfluxInventoryError = '';
		} catch (e) {
			upgradeAutomationInfluxInventory = {};
			upgradeAutomationInfluxInventoryError = String(e?.message || e || 'unknown_error');
		}
		try {
			const inventoryGlobalResult = await fetchInfluxInventoryGlobal();
			upgradeAutomationInfluxInventoryGlobal = inventoryGlobalResult?.map || {};
			upgradeAutomationInfluxInventoryGlobalError = '';
		} catch (e) {
			upgradeAutomationInfluxInventoryGlobal = {};
			upgradeAutomationInfluxInventoryGlobalError = String(e?.message || e || 'unknown_error');
		}
		try {
			const inventoryDrainResult = await fetchInfluxInventoryGlobalWeightedDrain();
			upgradeAutomationInfluxInventoryGlobalWeightedDrain = inventoryDrainResult?.map || {};
			upgradeAutomationInfluxInventoryDrainError = '';
		} catch (e) {
			upgradeAutomationInfluxInventoryGlobalWeightedDrain = {};
			upgradeAutomationInfluxInventoryDrainError = String(e?.message || e || 'unknown_error');
		}
		try {
			const lpControlResult = await fetchUpgradeAutomationLpControl();
			if (lpControlResult) {
				upgradeAutomationLpControl = lpControlResult;
				upgradeAutomationLpControlError = '';
			} else {
				upgradeAutomationLpControlError = 'lp_control_empty_result';
			}
		} catch (e) {
			upgradeAutomationLpControlError = String(e?.message || e || 'unknown_error');
		}
		try { renderAssistStats(); } catch (e) {}
	}

	async function refreshUpgradeAutomationExecutionSummary() {
		try {
			const executionSummaryResult = await fetchUpgradeAutomationExecutionSummary();
			if (executionSummaryResult) {
				upgradeAutomationExecutionSummary = executionSummaryResult;
				window.schedulerSummary = upgradeAutomationExecutionSummary; // Viktor: debug access
				upgradeAutomationExecutionSummaryError = '';
			} else {
				upgradeAutomationExecutionSummaryError = 'execution_summary_empty_result';
			}
		} catch (e) {
			upgradeAutomationExecutionSummaryError = String(e?.message || e || 'unknown_error');
		}
		try { renderAssistStats(); } catch (e) {}
	}

	async function getUpgradeAutomationEventSumsWindow(nowMs = Date.now(), hours = 24) {
		const cutoff = nowMs - hours * 3600 * 1000;
		const events = (await loadUpgradeAutomationEvents()).filter(e => Number(e?.ts || 0) >= cutoff);
		if (hours === 24) upgradeAutomationRecentEvents = events;
		const upgrade = {}; const craft = {};
		for (const e of events) {
			const r = String(e?.resource || ''); const amt = Number(e?.amount || 0);
			if (!r || !Number.isFinite(amt) || amt <= 0) continue;
			if (e.kind === 'upgrade') upgrade[r] = (upgrade[r] || 0) + amt;
			if (e.kind === 'craft') craft[r] = (craft[r] || 0) + amt;
		}
		return { upgrade, craft, eventsCount: events.length, hours };
	}

	async function getUpgradeAutomationEventSumsLast24h(nowMs = Date.now()) {
		return await getUpgradeAutomationEventSumsWindow(nowMs, 24);
	}

	async function getUpgradeAutomationEventSumsLast72h(nowMs = Date.now()) {
		return await getUpgradeAutomationEventSumsWindow(nowMs, 72);
	}

	function computeBufferDaysMap(inventory = {}, sums = {}) {
		const result = {};
		const upgrade = sums.upgrade || {};
		const craft = sums.craft || {};
		for (const resource of Object.keys(inventory || {})) {
			const inv = Number(inventory[resource] || 0);
			const deficit = Number(upgrade[resource] || 0) - Number(craft[resource] || 0);
			result[resource] = deficit > 0 ? (inv / deficit) : null;
		}
		return result;
	}

	function formatUpgradeAutomationObservedDrainDebugLine(observedDrainMap = {}) {
		const order = ['Framework','Electronics','Power Source','Electromagnet','Field Stabilizer','Particle Accelerator','Radiation Absorber','Survey Data Unit'];
		return order.map(name => {
			const value = getUpgradeAutomationComponentValue(observedDrainMap, name);
			return name + ': ' + Math.round(value).toLocaleString();
		}).join(' | ');
	}

	function getUpgradeAutomationComponentValue(map = {}, componentName = '') {
		return Number(map?.[componentName] || (componentName === 'Survey Data Unit' ? map?.SDU : 0) || 0);
	}

	function getUpgradeAutomationEffectiveDrain(plannedDrain = 0, observedDrain = 0) {
		return Math.max(Number(plannedDrain || 0), Number(observedDrain || 0), 0);
	}

	function formatUpgradeAutomationInfluxRows(craftMap = {}, upgradeMap = {}, inventoryMap = {}, inventoryGlobalMap = {}, observedDrainMap = {}) {
		const order = ['Framework','Electronics','Power Source','Electromagnet','Field Stabilizer','Particle Accelerator','Radiation Absorber','Survey Data Unit'];
		let html = '';
		for (const name of order) {
			const craft = getUpgradeAutomationComponentValue(craftMap, name);
			const upgrade = getUpgradeAutomationComponentValue(upgradeMap, name);
			const inventory = getUpgradeAutomationComponentValue(inventoryMap, name);
			const inventoryGlobal = getUpgradeAutomationComponentValue(inventoryGlobalMap, name);
			const observedDrain = getUpgradeAutomationComponentValue(observedDrainMap, name);
			const plannedDrain = upgrade - craft;
			const effectiveDrain = getUpgradeAutomationEffectiveDrain(plannedDrain, observedDrain);
			const bufferDaysPhantom = upgrade > 0 ? (inventory / upgrade) : null;
			const bufferDaysGlobal = effectiveDrain > 0 ? (inventoryGlobal / effectiveDrain) : null;
			const phantomInventoryBlocked = inventory <= 0;
			const phantomLowBuffer = bufferDaysPhantom !== null && Number(bufferDaysPhantom) < 0.5;
			const phantomUpgradeEligible = !phantomInventoryBlocked;
			const displayName = name + (phantomInventoryBlocked ? ' (blocked)' : '');
			const phantomInventoryStyle = phantomInventoryBlocked ? ' style="color:#ff8080"' : '';
			const phantomBufferStyle = phantomLowBuffer ? ' style="color:#ff8080"' : '';
			html += '<tr><td style="padding-left:18px">' + displayName + '</td><td align="right">' + Math.round(upgrade).toLocaleString() + '</td><td align="right"' + phantomInventoryStyle + '>' + Math.round(inventory).toLocaleString() + '</td><td align="right"' + phantomBufferStyle + '>' + (bufferDaysPhantom === null ? '' : Number(bufferDaysPhantom).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })) + '</td><td align="right">' + Math.round(craft).toLocaleString() + '</td><td align="right">' + Math.round(inventoryGlobal).toLocaleString() + '</td><td align="right">' + Math.round(plannedDrain).toLocaleString() + '</td><td align="right">' + Math.round(observedDrain).toLocaleString() + '</td><td align="right">' + Math.round(effectiveDrain).toLocaleString() + '</td><td align="right">' + (!phantomUpgradeEligible || bufferDaysGlobal === null ? '' : Number(bufferDaysGlobal).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })) + '</td></tr>';
		}
		return html;
	}

	async function queryInfluxFlux(flux, influxUrlOverride = '', influxAuthOverride = '') {
		const effectiveUrl = String(influxUrlOverride || globalSettings.influxURL || '').trim();
		const effectiveAuth = String(influxAuthOverride || globalSettings.influxAuth || '').trim();
		if (!effectiveUrl || !effectiveAuth || !globalSettings.influxDB) throw new Error('influx_not_configured');
		const cleanUrl = effectiveUrl.split('?')[0].replace(/\/$/, '');
		const hostMatch = cleanUrl.match(/^(https?:\/\/[^/]+)/i);
		const baseHost = hostMatch ? hostMatch[1] : cleanUrl.replace(/\/api\/v3\/write[^/]*$/i, '').replace(/\/orgs\/[^/]+$/i, '');
		const url = baseHost.replace(/\/$/, '') + '/api/v2/query?org=' + encodeURIComponent('67793e21353b170');
		const headers = {
			'Accept': 'application/csv',
			'Content-Type': 'application/vnd.flux',
			'Authorization': 'Token ' + effectiveAuth.replace(/^Token\s+/i, '').replace(/^Bearer\s+/i, '')
		};
		const resp = await fetch(url, { method: 'POST', headers, body: flux });
		if (!resp.ok) {
			let errText = '';
			try { errText = await resp.text(); } catch (e) {}
			throw new Error(`influx_flux_${resp.status}${errText ? (':' + errText.slice(0, 300)) : ''}`);
		}
		return await resp.text();
	}

	function parseInfluxCsv(text) {
		const lines = String(text || '').split(/\r?\n/).filter(line => line.trim().length);
		let header = null;
		const rows = [];
		for (const line of lines) {
			if (line.startsWith('#')) continue;
			const cols = line.split(',').map(x => x.replace(/^"|"$/g, ''));
			if (!header) {
				header = cols;
				continue;
			}
			const row = {};
			header.forEach((name, idx) => { row[name] = cols[idx]; });
			rows.push(row);
		}
		return rows;
	}

	function parseInfluxNumber(value) {
		if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
		if (typeof value === 'string') {
			const n = Number(value.replace(/,/g, ''));
			return Number.isFinite(n) ? n : 0;
		}
		if (value && typeof value === 'object') {
			const candidates = [value.value, value.longValue, value.doubleValue, value.intValue, value.uint64Value, value.stringValue];
			for (const candidate of candidates) {
				const n = parseInfluxNumber(candidate);
				if (n !== 0 || candidate === 0 || candidate === '0') return n;
			}
		}
		return 0;
	}

	const UPGRADE_AUTOMATION_INFLUX_UNTAGGED_FALLBACK_UNTIL = '2026-07-12T08:00:00Z';
	const SLYA_RAW_STATS_INFLUX_UNTAGGED_FALLBACK_UNTIL = '2026-07-01T08:00:00Z';
	const UPGRADE_AUTOMATION_INFLUX_LEGACY_BUCKET_PREFIX = 'slya-lp-auto-influx-legacy-bucket:';

	function isUpgradeAutomationInfluxUntaggedFallbackActive(now = new Date()) {
		const cutoff = Date.parse(UPGRADE_AUTOMATION_INFLUX_UNTAGGED_FALLBACK_UNTIL);
		return Number.isFinite(cutoff) && now.getTime() < cutoff;
	}

	function isSlyaRawStatsInfluxUntaggedFallbackActive(now = new Date()) {
		const cutoff = Date.parse(SLYA_RAW_STATS_INFLUX_UNTAGGED_FALLBACK_UNTIL);
		return Number.isFinite(cutoff) && now.getTime() < cutoff;
	}

	function getUpgradeAutomationInfluxFactionTag() {
		return normalizeUpgradeAutomationLpInstance(globalSettings?.upgradeAutomationLpInstance || 'MUD');
	}

	function getSlyaInfluxInstanceTag() {
		const instanceName = String(globalSettings?.slyInstanceName || '').trim();
		return (instanceName || getUpgradeAutomationInfluxFactionTag()).replace(/"/g, '');
	}

	function getSlyaInfluxInstanceFluxFilter(row = 'r', allowUntaggedFallback = false) {
		const instanceTag = getSlyaInfluxInstanceTag();
		const factionTag = getUpgradeAutomationInfluxFactionTag();
		return `(if exists ${row}.instance then ${row}.instance == "${instanceTag}" else if exists ${row}.slyInstanceName then ${row}.slyInstanceName == "${instanceTag}" else if exists ${row}.sly_instance then ${row}.sly_instance == "${instanceTag}" else if exists ${row}.tag then ${row}.tag == "${instanceTag}" else if exists ${row}.faction then (${row}.faction == "${instanceTag}" or ${row}.faction == "${factionTag}") else ${allowUntaggedFallback ? 'true' : 'false'})`;
	}

	function shouldAllowSlyaRawStatsUntaggedFallback(bucket, currentBucket, rawFallbackActive) {
		if (!rawFallbackActive) return false;
		if (bucket && bucket !== currentBucket) return true;
		return currentBucket === 'slya' && getUpgradeAutomationInfluxFactionTag() === 'UST';
	}

	function getUpgradeAutomationInfluxFactionFluxFilter(now = new Date(), row = 'r') {
		const faction = String(getUpgradeAutomationInfluxFactionTag()).replace(/"/g, '');
		const tagged = `(exists ${row}.faction and ${row}.faction == "${faction}")`;
		if (!isUpgradeAutomationInfluxUntaggedFallbackActive(now)) return tagged;
		return `(if exists ${row}.faction then ${row}.faction == "${faction}" else true)`;
	}

	function getUpgradeAutomationInfluxTaggedIdentityFluxFilter(row = 'r') {
		const faction = String(getUpgradeAutomationInfluxFactionTag()).replace(/"/g, '');
		const instance = String(getSlyaInfluxInstanceTag()).replace(/"/g, '');
		return `(exists ${row}.faction and ${row}.faction == "${faction}" and exists ${row}.instance and ${row}.instance == "${instance}")`;
	}

	function sanitizeInfluxBucketName(bucketName = '') {
		return String(bucketName || '').trim().replace(/"/g, '');
	}

	function getUpgradeAutomationInfluxLegacyBucketKey() {
		return UPGRADE_AUTOMATION_INFLUX_LEGACY_BUCKET_PREFIX + getUpgradeAutomationInfluxFactionTag();
	}

	function getUpgradeAutomationDefaultLegacyInfluxBucket() {
		const faction = getUpgradeAutomationInfluxFactionTag();
		return faction === 'MUD' ? 'slya_mud' : '';
	}

	function rememberUpgradeAutomationInfluxLegacyBucket(now = new Date()) {
		if (!isUpgradeAutomationInfluxUntaggedFallbackActive(now)) return;
		const currentBucket = sanitizeInfluxBucketName(globalSettings?.influxDB || '');
		if (!currentBucket || currentBucket === 'slya') return;
		try {
			const key = getUpgradeAutomationInfluxLegacyBucketKey();
			const existing = sanitizeInfluxBucketName(localStorage.getItem(key) || '');
			if (!existing) localStorage.setItem(key, currentBucket);
		} catch (e) {}
	}

	function getUpgradeAutomationInfluxReadBuckets(now = new Date(), fallbackActive = isUpgradeAutomationInfluxUntaggedFallbackActive(now)) {
		const currentBucket = sanitizeInfluxBucketName(globalSettings?.influxDB || '');
		const buckets = [];
		if (currentBucket) buckets.push(currentBucket);
		if (fallbackActive) {
			rememberUpgradeAutomationInfluxLegacyBucket(now);
			try {
				const storedLegacy = sanitizeInfluxBucketName(localStorage.getItem(getUpgradeAutomationInfluxLegacyBucketKey()) || '');
				if (storedLegacy && storedLegacy !== currentBucket) buckets.push(storedLegacy);
			} catch (e) {}
			const defaultLegacy = sanitizeInfluxBucketName(getUpgradeAutomationDefaultLegacyInfluxBucket());
			if (defaultLegacy && defaultLegacy !== currentBucket) buckets.push(defaultLegacy);
		}
		return Array.from(new Set(buckets.filter(Boolean)));
	}

	function buildUpgradeAutomationInfluxSourceFlux(bucketNames = [], rangeLine = '', filterLines = []) {
		const buckets = Array.from(new Set((bucketNames || []).map(sanitizeInfluxBucketName).filter(Boolean)));
		const buildSource = bucket => [`from(bucket: "${bucket}")`, `  |> ${rangeLine}`, ...filterLines].join('\n');
		if (buckets.length <= 1) return buildSource(buckets[0] || sanitizeInfluxBucketName(globalSettings?.influxDB || ''));
		const queryNames = buckets.map((_, idx) => `lp_auto_bucket_${idx}`);
		return buckets.map((bucket, idx) => `${queryNames[idx]} = ${buildSource(bucket)}`).join('\n\n') + `\n\nunion(tables: [${queryNames.join(', ')}])`;
	}

	function buildSlyaRawStatsInfluxSourceFlux(rangeLine = '', filterBuilder = null, now = new Date()) {
		const currentBucket = sanitizeInfluxBucketName(globalSettings?.influxDB || '');
		const rawFallbackActive = isSlyaRawStatsInfluxUntaggedFallbackActive(now);
		const buckets = getUpgradeAutomationInfluxReadBuckets(now, rawFallbackActive);
		const queryNames = buckets.map((_, idx) => `slya_raw_bucket_${idx}`);
		const buildSource = (bucket, idx) => {
			const allowUntaggedFallback = shouldAllowSlyaRawStatsUntaggedFallback(bucket, currentBucket, rawFallbackActive);
			const instanceFilter = getSlyaInfluxInstanceFluxFilter('r', allowUntaggedFallback);
			const filterLines = typeof filterBuilder === 'function' ? (filterBuilder(instanceFilter) || []) : [];
			return `${queryNames[idx]} = ` + [`from(bucket: "${bucket}")`, `  |> ${rangeLine}`, ...filterLines].join('\n');
		};
		if (buckets.length <= 1) {
			const bucket = buckets[0] || currentBucket;
			const allowUntaggedFallback = shouldAllowSlyaRawStatsUntaggedFallback(bucket, currentBucket, rawFallbackActive);
			const instanceFilter = getSlyaInfluxInstanceFluxFilter('r', allowUntaggedFallback);
			const filterLines = typeof filterBuilder === 'function' ? (filterBuilder(instanceFilter) || []) : [];
			return [`from(bucket: "${bucket}")`, `  |> ${rangeLine}`, ...filterLines].join('\n');
		}
		return buckets.map(buildSource).join('\n\n') + `\n\nunion(tables: [${queryNames.join(', ')}])`;
	}

	async function fetchInfluxUpgrading24h() {
		const flux = `${buildSlyaRawStatsInfluxSourceFlux('range(start: -24h)', instanceFilter => [
			`  |> filter(fn: (r) => r._measurement == "upgrade" and r._field == "amount" and ${instanceFilter})`
		])}\n  |> group(columns: ["input"])\n  |> sum(column: "_value")\n  |> keep(columns: ["input", "_value"])\n  |> rename(columns: {input: "resource", _value: "upgrading_last_24h"})\n  |> sort(columns: ["resource"])`;
		const csv = await queryInfluxFlux(flux);
		const rows = parseInfluxCsv(csv);
		const out = {};
		for (const row of rows) {
			const resource = row?.resource;
			const rawValue = row?.upgrading_last_24h ?? 0;
			if (resource) out[String(resource)] = parseInfluxNumber(rawValue);
		}
		let preview = '';
		try {
			const firstRow = rows?.[0] ? JSON.stringify(rows[0]).slice(0, 220) : 'none';
			preview = `rows=${rows.length} first=${firstRow}`;
		} catch (e) {
			preview = 'debug_unavailable';
		}
		return { map: out, debug: preview };
	}

	async function fetchInfluxUpgradingTodayByComponent(now = new Date()) {
		const dayStartIso = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 0, 0, 0, 0)).toISOString();
		const flux = `${buildSlyaRawStatsInfluxSourceFlux(`range(start: ${dayStartIso}, stop: ${now.toISOString()})`, instanceFilter => [
			`  |> filter(fn: (r) => r._measurement == "upgrade" and r._field == "amount" and ${instanceFilter})`
		], now)}\n  |> group(columns: ["input"])\n  |> sum(column: "_value")\n  |> keep(columns: ["input", "_value"])\n  |> rename(columns: {input: "resource", _value: "upgrading_today"})\n  |> sort(columns: ["resource"])`;
		const csv = await queryInfluxFlux(flux);
		const rows = parseInfluxCsv(csv);
		const out = {};
		for (const row of rows) {
			const resource = row?.resource;
			const rawValue = row?.upgrading_today ?? 0;
			if (resource) out[String(resource)] = parseInfluxNumber(rawValue);
		}
		return { map: out };
	}

	async function fetchInfluxCrafting24h() {
		const flux = `${buildSlyaRawStatsInfluxSourceFlux('range(start: -72h)', instanceFilter => [
			`  |> filter(fn: (r) => r._measurement == "crafting" and r._field == "amount" and r.type == "Output" and ${instanceFilter})`
		])}\n  |> group(columns: ["output"])\n  |> sum(column: "_value")\n  |> map(fn: (r) => ({ r with _value: float(v: r._value) / 3.0 }))\n  |> keep(columns: ["output", "_value"])\n  |> rename(columns: {output: "resource", _value: "crafting_last_24h"})\n  |> sort(columns: ["resource"])`;
		const csv = await queryInfluxFlux(flux);
		const rows = parseInfluxCsv(csv);
		const out = {};
		for (const row of rows) {
			const resource = row?.resource;
			const rawValue = row?.crafting_last_24h ?? 0;
			if (resource) out[String(resource)] = parseInfluxNumber(rawValue);
		}
		const sduFlux = `${buildSlyaRawStatsInfluxSourceFlux('range(start: -72h)', instanceFilter => [
			`  |> filter(fn: (r) => r._measurement == "sdu" and r._field == "amount" and ${instanceFilter})`
		])}\n  |> group()\n  |> sum(column: "_value")\n  |> map(fn: (r) => ({ r with _value: float(v: r._value) / 3.0 }))\n  |> keep(columns: ["_value"])\n  |> rename(columns: {_value: "sdu_found_24h"})`;
		const sduCsv = await queryInfluxFlux(sduFlux);
		const sduRows = parseInfluxCsv(sduCsv);
		out.SDU = parseInfluxNumber(sduRows?.[0]?.sdu_found_24h ?? 0);
		return { map: out };
	}

	function getUpgradeAutomationInventoryFactionFilter() {
		const normalized = normalizeUpgradeAutomationLpInstance(globalSettings?.upgradeAutomationLpInstance || 'MUD');
		const starbasesByFaction = {
			MUD: ['MUD-PHANTOM','MUD-1','MUD-2','MUD-3','MUD-4','MUD-5','MRZ-1','MRZ-2','MRZ-3','MRZ-4','MRZ-5','MRZ-6','MRZ-7','MRZ-8','MRZ-9','MRZ-10','MRZ-11','MRZ-12'],
			ONI: ['ONI-PHANTOM','ONI-1','ONI-2','ONI-3','ONI-4','ONI-5','MRZ-13','MRZ-14','MRZ-18','MRZ-19','MRZ-20','MRZ-24','MRZ-25','MRZ-26','MRZ-29','MRZ-30','MRZ-31','MRZ-36'],
			UST: ['UST-PHANTOM','UST-1','UST-2','UST-3','UST-4','UST-5','MRZ-15','MRZ-16','MRZ-17','MRZ-21','MRZ-22','MRZ-23','MRZ-27','MRZ-28','MRZ-32','MRZ-33','MRZ-34','MRZ-35'],
		};
		const starbases = starbasesByFaction[normalized] || starbasesByFaction.MUD;
		return {
			phantomName: starbases[0],
			globalFilter: starbases.map(name => `r.starbase == "${name}"`).join(' or ')
		};
	}

	async function fetchInfluxInventory() {
		const factionInventory = getUpgradeAutomationInventoryFactionFilter();
		const sourceFlux = buildUpgradeAutomationInfluxSourceFlux(getUpgradeAutomationInfluxReadBuckets(), 'range(start: -7d)', [
			`  |> filter(fn: (r) => r._measurement == "starbase" and r._field == "curAmount" and r.starbase == "${factionInventory.phantomName}")`
		]);
		const flux = `${sourceFlux}\n  |> group(columns: ["rss"])\n  |> last()\n  |> keep(columns: ["rss", "_value"])\n  |> rename(columns: {rss: "resource", _value: "inventory"})\n  |> sort(columns: ["resource"])`;
		const csv = await queryInfluxFlux(flux);
		const rows = parseInfluxCsv(csv);
		const out = {};
		for (const row of rows) {
			const resource = row?.resource;
			const rawValue = row?.inventory ?? 0;
			if (resource) out[String(resource)] = parseInfluxNumber(rawValue);
		}
		return { map: out };
	}

	async function fetchInfluxInventoryGlobal() {
		const factionInventory = getUpgradeAutomationInventoryFactionFilter();
		const sourceFlux = buildUpgradeAutomationInfluxSourceFlux(getUpgradeAutomationInfluxReadBuckets(), 'range(start: -7d)', [
			`  |> filter(fn: (r) => r._measurement == "starbase" and r._field == "curAmount" and (${factionInventory.globalFilter}))`
		]);
		const flux = `${sourceFlux}\n  |> group(columns: ["rss", "starbase"])\n  |> last()\n  |> group(columns: ["rss"])\n  |> sum(column: "_value")\n  |> keep(columns: ["rss", "_value"])\n  |> rename(columns: {rss: "resource", _value: "inventory_global"})\n  |> sort(columns: ["resource"])`;
		const csv = await queryInfluxFlux(flux);
		const rows = parseInfluxCsv(csv);
		const out = {};
		for (const row of rows) {
			const resource = row?.resource;
			const rawValue = row?.inventory_global ?? 0;
			if (resource) out[String(resource)] = parseInfluxNumber(rawValue);
		}
		return { map: out };
	}

	function computeWeightedInventoryDrainFromRows(rows = []) {
		const byResource = {};
		for (const row of rows || []) {
			const resource = String(row?.resource || '');
			const time = String(row?._time || row?.time || '');
			if (!resource || !time) continue;
			const windowTime = new Date(time);
			const isCompleteUtcDailyWindow = Number.isFinite(windowTime.getTime())
				&& windowTime.getUTCHours() === 0
				&& windowTime.getUTCMinutes() === 0
				&& windowTime.getUTCSeconds() === 0
				&& windowTime.getUTCMilliseconds() === 0;
			if (!isCompleteUtcDailyWindow) continue;
			const value = parseInfluxNumber(row?.inventory_global ?? row?._value ?? 0);
			if (!byResource[resource]) byResource[resource] = [];
			byResource[resource].push({ time, value });
		}
		const out = {};
		for (const [resource, points] of Object.entries(byResource)) {
			const sorted = points
				.filter(p => Number.isFinite(Number(p.value)))
				.sort((a, b) => String(a.time).localeCompare(String(b.time)));
			if (sorted.length < 2) {
				out[resource] = 0;
				continue;
			}
			const recent = sorted.slice(-8);
			const drains = [];
			for (let i = 1; i < recent.length; i++) {
				drains.push(Number(recent[i - 1].value || 0) - Number(recent[i].value || 0));
			}
			const count = drains.length;
			let weightedSum = 0;
			let weightSum = 0;
			for (let i = 0; i < count; i++) {
				const weight = count <= 1 ? 1 : (1 + (i / (count - 1)));
				weightedSum += Number(drains[i] || 0) * weight;
				weightSum += weight;
			}
			out[resource] = weightSum > 0 ? (weightedSum / weightSum) : 0;
		}
		return out;
	}

	async function fetchInfluxInventoryGlobalWeightedDrain() {
		const factionInventory = getUpgradeAutomationInventoryFactionFilter();
		const sourceFlux = buildUpgradeAutomationInfluxSourceFlux(getUpgradeAutomationInfluxReadBuckets(), 'range(start: -8d)', [
			`  |> filter(fn: (r) => r._measurement == "starbase" and r._field == "curAmount" and (${factionInventory.globalFilter}))`
		]);
		const flux = `${sourceFlux}\n  |> aggregateWindow(every: 1d, fn: last, createEmpty: false)\n  |> group(columns: ["rss", "_time"])\n  |> sum(column: "_value")\n  |> keep(columns: ["rss", "_time", "_value"])\n  |> rename(columns: {rss: "resource", _value: "inventory_global"})\n  |> sort(columns: ["resource", "_time"])`;
		const csv = await queryInfluxFlux(flux);
		const rows = parseInfluxCsv(csv);
		return { map: computeWeightedInventoryDrainFromRows(rows) };
	}

	async function fetchUpgradeAutomationExpectedLpByEod(now = new Date()) {
		const empty = { value: null, snapshotTime: '', ageMs: null, stale: true, rows: 0, profiles: 0, processes: 0, error: '' };
		if (!globalSettings.influxURL || !globalSettings.influxAuth || !globalSettings.influxDB) return { ...empty, error: 'missing_influx_config' };
		try {
			const faction = String(getUpgradeAutomationInfluxFactionTag()).replace(/"/g, '');
			const instance = String(getSlyaInfluxInstanceTag()).replace(/"/g, '');
			const flux = `from(bucket: "${sanitizeInfluxBucketName(globalSettings.influxDB)}")
  |> range(start: -2h)
  |> filter(fn: (r) => r._measurement == "lp_per_profile")
  |> filter(fn: (r) => exists r.faction and r.faction == "${faction}")
  |> filter(fn: (r) => exists r.instance and r.instance == "${instance}")
  |> filter(fn: (r) => exists r.source and r.source == "active")
  |> filter(fn: (r) => r._field == "expectedLpByEod")
  |> keep(columns: ["_time", "_value", "profile", "component"])
  |> group()
  |> sort(columns: ["_time"])`;
			const rows = parseInfluxCsv(await queryInfluxFlux(flux));
			if (!rows.length) return { ...empty, error: 'no_lp_per_profile_rows' };
			const snapshotTime = rows.reduce((latest, row) => String(row?._time || '') > latest ? String(row._time) : latest, '');
			const snapshotRows = rows.filter(row => String(row?._time || '') === snapshotTime);
			const snapshotMs = Date.parse(snapshotTime);
			const ageMs = Number.isFinite(snapshotMs) ? Math.max(0, now.getTime() - snapshotMs) : null;
			const stale = !Number.isFinite(ageMs) || ageMs > 90 * 60 * 1000;
			const value = snapshotRows.reduce((sum, row) => sum + Math.max(0, parseInfluxNumber(row?._value)), 0);
			return {
				value: stale ? null : value,
				snapshotTime,
				ageMs,
				stale,
				rows: snapshotRows.length,
				profiles: new Set(snapshotRows.map(row => String(row?.profile || '')).filter(Boolean)).size,
				processes: null,
				error: stale ? 'stale_lp_per_profile_snapshot' : '',
				query: flux
			};
		} catch (e) {
			return { ...empty, error: String(e?.message || e || 'lp_per_profile_query_failed') };
		}
	}

	async function fetchUpgradeAutomationLpControl() {
		const now = new Date();
		const lpInstanceKey = normalizeUpgradeAutomationLpInstance(globalSettings?.upgradeAutomationLpInstance);
		const instanceId = (UPGRADE_AUTOMATION_FACTION_CONFIG[lpInstanceKey] || UPGRADE_AUTOMATION_FACTION_CONFIG.MUD).lpInstance;
		const series = await fetchUpgradeAutomationEpochSeries(instanceId);
		let influxTarget = { targetNowInflux: null, prevValue: null, nextValue: null, prevCount: 0, nextCount: 0, prevHour: null, nextHour: null, progress: 0 };
		try {
			influxTarget = await fetchUpgradeAutomationHourlyInfluxAverages(lpInstanceKey, now);
		} catch (e) {
			influxTarget = { targetNowInflux: null, prevValue: null, nextValue: null, prevCount: 0, nextCount: 0, prevHour: null, nextHour: null, progress: 0, error: String(e?.message || e || 'influx_target_failed') };
		}
		const effectiveTargetNow = Number.isFinite(Number(influxTarget.targetNowInflux)) && Number(influxTarget.targetNowInflux) > 0 ? Number(influxTarget.targetNowInflux) : null;
		const rawTargetNowInflux = Number.isFinite(Number(influxTarget.targetNowInflux)) ? Number(influxTarget.targetNowInflux) : null;
		let aephiaLpToday = null;
		try {
			aephiaLpToday = await fetchUpgradeAutomationAephiaLpToday(lpInstanceKey, now);
		} catch (e) {
			aephiaLpToday = null;
		}
		const control = computeUpgradeAutomationControl(series, now, effectiveTargetNow, aephiaLpToday);
		const state = await loadUpgradeAutomationState(instanceId);
		const dayKey = now.toISOString().slice(0, 10);
		const cumErr = state.dayKey === dayKey ? Number(state.cumErr || 0) : 0;
		const expectedLpByEod = await fetchUpgradeAutomationExpectedLpByEod(now);
		const expectedTotalLpByEod = expectedLpByEod.value != null && Number.isFinite(Number(expectedLpByEod.value)) ? control.todayTotal + Number(expectedLpByEod.value) : null;
		const ag = computeAggressivenessFromControl(control, cumErr, influxTarget, now, expectedTotalLpByEod);
		const aggressivenessActive = isUpgradeAutomationAggressivenessActive(now);
		const projectedLpToday = computeUpgradeAutomationProjectedLpToday(control, influxTarget, now);
		if (![control.progress, control.avg7Weighted, control.targetNow, control.todayTotal, ag.aggr].every(Number.isFinite)) {
			throw new Error('lp_control_invalid_values');
		}
		return {
			lpInstanceKey,
			lpInstanceId: instanceId,
			utcTime: now.toISOString().slice(11, 19),
			dayProgressPct: control.progress * 100,
			avg7Weighted: control.avg7Weighted,
			targetNow: Number(control.fallbackTargetNow || control.targetNow || 0),
			targetNowInflux: rawTargetNowInflux,
			effectiveTargetNow: Number(control.targetNow || 0),
			effectiveTargetNowSource: control.targetNowSource || 'epoch_fallback',
			targetNowInfluxPrev: influxTarget.prevValue,
			targetNowInfluxNext: influxTarget.nextValue,
			targetNowInfluxPrevCount: influxTarget.prevCount,
			targetNowInfluxNextCount: influxTarget.nextCount,
			targetNowInfluxPrevHour: influxTarget.prevHour,
			targetNowInfluxNextHour: influxTarget.nextHour,
			targetNowInfluxProgress: influxTarget.progress,
			targetNowInfluxFallbackUsed: !!influxTarget.fallbackUsed,
			targetNowInfluxDebug: influxTarget.debug || null,
			targetNowInfluxError: influxTarget.error || '',
			today: control.todayTotal,
			lpGap: control.targetNow - control.todayTotal,
			trend2: control.trend2,
			cumErr,
			aggressiveness: ag.aggr,
			aggressivenessActive,
			userPercent: ag.userPercent,
			rawAggressiveness: ag.rawAggr,
			aggrRelative: ag.aggrRel,
			aggrAbsolute: ag.aggrAbs,
			userScale: ag.userScale,
			absAdjustment: ag.absAdjustment || 0,
			projectedLpToday,
			expectedLpByEod: expectedLpByEod.value,
			expectedTotalLpByEod,
			expectedLpByEodSnapshotTime: expectedLpByEod.snapshotTime,
			expectedLpByEodAgeMs: expectedLpByEod.ageMs,
			expectedLpByEodRows: expectedLpByEod.rows,
			expectedLpByEodProfiles: expectedLpByEod.profiles,
			expectedLpByEodStale: expectedLpByEod.stale,
			expectedLpByEodError: expectedLpByEod.error
		};
	}

	function normalizeUpgradeAutomationLpInstance(value) {
		const key = String(value || '').toUpperCase();
		return key === 'ONI' || key === 'UST' || key === 'MUD' ? key : 'MUD';
	}

	function getUpgradeAutomationBufferTier(bufferDaysGlobal, inventoryGlobal = 0) {
		const b = Number(bufferDaysGlobal);
		const inv = Number(inventoryGlobal || 0);
		if (!Number.isFinite(b)) return inv > 0 ? 'A_INF' : 'D_ZERO';
		if (b > 15) return 'A';
		if (b >= 10) return 'B';
		if (b >= 5) return 'C';
		return 'D';
	}

	function getUpgradeAutomationBufferTierFloor(tier) {
		if (tier === 'A' || tier === 'A_INF') return 15;
		if (tier === 'B') return 10;
		if (tier === 'C') return 5;
		return 0;
	}

	function getUpgradeAutomationBufferGate(bufferDaysGlobal, inventoryGlobal = 0) {
		const tier = getUpgradeAutomationBufferTier(bufferDaysGlobal, inventoryGlobal);
		if (tier === 'A' || tier === 'A_INF') return 1;
		if (tier === 'B') return 0.5;
		if (tier === 'C') return 0.25;
		return 0;
	}

	function isUpgradeAutomationEligibleDestination(row, projected = null) {
		if (!row) return false;
		const inv = Number(row.inventoryGlobal || 0);
		const tier = projected?.finalTier ?? getUpgradeAutomationBufferTier((row.finalBufferDays ?? row.bufferDaysGlobal), inv);
		if (tier === 'A_INF') return inv > 0;
		if (tier === 'D' || tier === 'D_ZERO') return false;
		return true;
	}

	function projectUpgradeAutomationFinalRow(row, finalCrew, remainingHours) {
		const projectedCrew = Math.max(0, Math.floor(Number(finalCrew || 0)));
		const secondsPerUnit = Math.max(1, Number(row?.secondsPerUnit || 1));
		const lpPerUnit = Number(row?.lpPerUnit || 0);
		const installedToday = Math.floor(Number(row?.installedToday || 0));
		const craft24h = Number(row?.craft24h || 0);
		const observedDrain = Number(row?.observedDrain || 0);
		const inventoryGlobal = Number(row?.inventoryGlobal || 0);
		const secondsInRemainingHours = Math.max(0, Number(remainingHours || 0)) * 3600;
		const finalUpgradingHour = Math.floor(projectedCrew * 3600 / secondsPerUnit);
		const finalUpgradingDay = Math.floor(installedToday + (projectedCrew * secondsInRemainingHours) / secondsPerUnit);
		const finalLpTarget = Math.floor(finalUpgradingDay * lpPerUnit);
		const finalDeficitDay = finalUpgradingDay - craft24h;
		const finalEffectiveDrain = getUpgradeAutomationEffectiveDrain(finalDeficitDay, observedDrain);
		const finalBufferDays = finalEffectiveDrain > 0 ? (inventoryGlobal / finalEffectiveDrain) : (inventoryGlobal > 0 ? Number.POSITIVE_INFINITY : null);
		const finalTier = getUpgradeAutomationBufferTier(finalBufferDays, inventoryGlobal);
		const finalTierFloor = getUpgradeAutomationBufferTierFloor(finalTier);
		const finalTierSurplus = finalBufferDays == null
			? (inventoryGlobal > 0 ? Number.POSITIVE_INFINITY : Number.NEGATIVE_INFINITY)
			: (Number(finalBufferDays) - finalTierFloor);
		return {
			finalCrew: projectedCrew,
			finalUpgradingHour,
			finalUpgradingDay,
			finalLpTarget,
			finalDeficitDay,
			finalEffectiveDrain,
			finalBufferDays,
			finalTier,
			finalTierFloor,
			finalTierSurplus
		};
	}

	function getUpgradeAutomationLpPhantomName(instance = 'MUD') {
		const normalized = normalizeUpgradeAutomationLpInstance(instance);
		if (normalized === 'ONI') return 'ONI-PHANTOM';
		if (normalized === 'UST') return 'UST-PHANTOM';
		return 'MUD-PHANTOM';
	}

	function getUpgradeAutomationModeFromRemainingHours(remainingHours = 24) {
		const hours = Math.max(0, Math.floor(Number(remainingHours || 0)));
		return hours >= 13 ? 'neutral' : 'final';
	}

	function isUpgradeAutomationNeutralPhaseActive(settings = {}, now = new Date()) {
		const phaseHours = Math.max(0, Math.min(23, parseIntDefault(settings?.upgradeAutomationAggressivenessStartHour, 12)));
		return now.getUTCHours() < phaseHours;
	}

	function isUpgradeAutomationNextCycleTarget(settings = {}, now = new Date()) {
		const phaseHours = Math.max(0, Math.min(23, parseIntDefault(settings?.upgradeAutomationAggressivenessStartHour, 12)));
		const upcomingHour = (now.getUTCHours() + 1) % 24;
		return upcomingHour >= phaseHours;
	}

	function isUpgradeAutomationNeutralPhaseActivationWindow(now = new Date()) {
		const secondsPastHour = now.getUTCMinutes() * 60 + now.getUTCSeconds();
		return secondsPastHour >= 50 * 60 && secondsPastHour < 51 * 60;
	}

	function getUpgradeAutomationNeutralPhaseSnapshotKey(settings = {}, now = new Date()) {
		const phaseHours = Math.max(0, Math.min(23, parseIntDefault(settings?.upgradeAutomationAggressivenessStartHour, 12)));
		const cycleDay = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 0, 0, 0, 0));
		if (now.getUTCHours() >= phaseHours) cycleDay.setUTCDate(cycleDay.getUTCDate() + 1);
		return cycleDay.toISOString().slice(0, 10) + '|h=' + String(phaseHours);
	}

	function computeUpgradeAutomationNeutralPhaseAmount(row, settings = {}) {
		const phaseHours = Math.max(0, Math.min(23, parseIntDefault(settings?.upgradeAutomationAggressivenessStartHour, 12)));
		const phaseSeconds = Math.max(0, phaseHours * 3600 - 120);
		const crew = Math.max(0, Math.floor(Number(row?.crew || 0)));
		const secondsPerUnit = Math.max(1, Number(row?.secondsPerUnit || 1));
		return Math.floor((crew * phaseSeconds) / secondsPerUnit);
	}

	const UPGRADE_AUTOMATION_MANAGED_CRAFT_SLOTS = 8;

	function buildUpgradeAutomationExecutionPayload(summary, settings = {}, now = new Date()) {
		if (!summary?.neutralComponentPlan?.length) return { ready: false, reason: 'execution_summary_unavailable', rows: [] };
		const remainingHours = Math.max(0, Math.floor(Number(summary.remainingHours || 0)));
		const mode = getUpgradeAutomationModeFromRemainingHours(remainingHours);
		const normalizedInstance = normalizeUpgradeAutomationLpInstance(settings.upgradeAutomationLpInstance || 'MUD');
		const phantomName = getUpgradeAutomationLpPhantomName(normalizedInstance);
		const factionCfg = UPGRADE_AUTOMATION_FACTION_CONFIG[normalizedInstance] || UPGRADE_AUTOMATION_FACTION_CONFIG.MUD;
		const phantomCoords = String(factionCfg?.phantomCrewCoords || '0,-24');
		const startCraftSlot = Math.max(1, parseIntDefault(settings.upgradeAutomationStartCraftSlot, 1));
		const sourceRows = Array.isArray(summary.neutralComponentPlan) ? summary.neutralComponentPlan : [];
		const rows = [];
		const componentOrder = UPGRADE_AUTOMATION_NEUTRAL_COMPONENT_ORDER;
		const fixedRowsByComponent = new Map();
		for (const row of sourceRows) {
			const useNeutral = !isUpgradeAutomationNextCycleTarget(settings, now);
			const crew = Math.max(0, Math.floor(Number(useNeutral ? row.crew : (row.finalCrew !== undefined ? row.finalCrew : row.crew)) || 0));
			const neutralExecutionAmount = settings?.upgradeAutomationNeutralBlockSingleTx ? Number(row.neutralUpgradingPhase ?? computeUpgradeAutomationNeutralPhaseAmount(row, settings) ?? 0) : Number(row.neutralUpgradingHour || 0);
			const upgradingHour = Math.max(0, Math.floor(Number(useNeutral ? neutralExecutionAmount : (row.finalUpgradingHour !== undefined ? row.finalUpgradingHour : neutralExecutionAmount)) || 0));
			if (crew <= 0) continue;
			const componentName = String(row.displayName || row.name || '').trim();
			if (!componentName) continue;
			const craftItem = componentName === 'Survey Data Unit' ? 'SDU Upgrade' : (componentName + ' Upgrade');
			const orderIndex = componentOrder.indexOf(componentName);
			const rowData = {
				component: componentName,
				craftItem,
				starbase: phantomName,
				coordinates: phantomCoords,
				crew,
				upgradingHour,
				secondsPerUnit: Math.max(1, Number(row.secondsPerUnit || 1)),
				slotOrderIndex: orderIndex
			};
			if (!fixedRowsByComponent.has(componentName)) {
				fixedRowsByComponent.set(componentName, rowData);
			}
		}
		const slotRows = [];
		for (const componentName of componentOrder) {
			const orderIndex = componentOrder.indexOf(componentName);
			const existingRow = fixedRowsByComponent.get(componentName);
			if (existingRow) {
				slotRows.push(existingRow);
			} else {
				// Create empty row for this slot position even if no crew assigned
				const craftItem = componentName === 'Survey Data Unit' ? 'SDU Upgrade' : (componentName + ' Upgrade');
				slotRows.push({
					component: componentName,
					craftItem,
					starbase: phantomName,
					coordinates: phantomCoords,
					crew: 0,
					upgradingHour: 0,
					secondsPerUnit: 1,
					slotOrderIndex: orderIndex
				});
			}
		}
		const finalSlotRows = slotRows.map((row) => ({
			...row,
			craftSlot: startCraftSlot + (typeof row.slotOrderIndex === 'number' ? row.slotOrderIndex : 0),
			craftLabel: 'craft' + (startCraftSlot + (typeof row.slotOrderIndex === 'number' ? row.slotOrderIndex : 0))
		}));
		return {
			ready: true,
			mode,
			remainingHours,
			phantomName,
			startCraftSlot,
			rows: finalSlotRows,
			createdAt: now.toISOString()
		};
	}

	function getUpgradeAutomationScheduleState(summary, settings = {}, now = new Date()) {
		const payload = buildUpgradeAutomationExecutionPayload(summary, settings, now);
		const target = getUpgradeAutomationNextTargetWindow(now, settings);

		// Viktor: Per-component target + runtime computation
		const landingBufferSeconds = UPGRADE_AUTOMATION_LANDING_BUFFER_SECONDS;
		const minLeadSeconds = Math.max(300, parseIntDefault(settings?.upgradeAutomationMinLeadSeconds, 300));
		const liveStatusRows = getUpgradeAutomationLiveStatusRows();
		const targetMinute = 59;
		const targetSecond = Math.max(0, 60 - parseIntDefault(settings?.upgradeAutomationTargetOffsetSeconds, 60));
		const useNeutral = isUpgradeAutomationNeutralPhaseActive(settings, now);
		// nextXx59 = next upcoming xx:59 after now
		// nextNextXx59 = the one after that
		const nextXx59Ms = (() => {
			const cand = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), now.getUTCHours(), targetMinute, targetSecond, 0);
			return cand > now.getTime() ? cand : cand + 3600 * 1000;
		})();
		const nextNextXx59Ms = nextXx59Ms + 3600 * 1000;
		// Viktor fix: use the global target (which already has lead-time logic) as the base.
		// Only deviate to nextNextXx59 when upgrade finishes BETWEEN target and next window.
		const globalTargetMs = target.targetFinishAt.getTime();
		const rows = payload.rows || [];
		const scheduleRows = rows.map((row) => {
			const liveRow = findUpgradeAutomationLiveStatusRow(row.craftLabel, liveStatusRows);
			const liveState = String(liveRow?.state || '');
			const liveFinishAtUtcRaw = liveRow ? parseUpgradeAutomationLiveFinishAtUtc(liveState, now) : null;
			const liveFinishMs = Number.isFinite(Date.parse(liveFinishAtUtcRaw || '')) ? Date.parse(liveFinishAtUtcRaw) : null;
			const currentCrewActive = Math.max(0, Math.floor(Number(row.crew || 0)));
			const plannedCrew = useNeutral ? Math.max(0, Math.floor(Number(row.crew || 0))) : Math.max(0, Math.floor(Number(row.finalCrew || row.crew || 0)));
			const crewDelta = plannedCrew - currentCrewActive;
			const availableCrew = crewDelta < 0 ? (-crewDelta) : 0;
			return { row, liveRow, liveState, liveFinishMs, currentCrewActive, plannedCrew, crewDelta, availableCrew };
		});
		const donorTimeline = scheduleRows
			.map((x) => ({
				finishMs: x.liveFinishMs,
				releaseCrew: Math.max(0, x.currentCrewActive - x.plannedCrew)
			}))
			.filter((x) => Number.isFinite(x.finishMs) && x.releaseCrew > 0)
			.sort((a, b) => a.finishMs - b.finishMs);
		for (const item of scheduleRows) {
			const row = item.row;
			const liveFinishMs = item.liveFinishMs;
			row.liveFinishMs = liveFinishMs; // Viktor debug
			row.liveState = item.liveState || '';
			const nextCrew = item.plannedCrew;
			const upgradingHour = useNeutral ? Number(row.upgradingHour || 0) : Number(row.finalUpgradingHour || row.upgradingHour || 0);
			const nextXx59ForRow = !liveFinishMs ? globalTargetMs
				: (liveFinishMs >= globalTargetMs && liveFinishMs <= nextNextXx59Ms) ? nextNextXx59Ms
				: globalTargetMs;
			// A delayed/paused upgrade can leave its displayed finish time in the past.
			// The next upgrade cannot start before now; using that stale finish directly
			// would inflate the planned runtime and amount by the entire overdue period.
			let effectiveStartMs = Math.max(liveFinishMs || now.getTime(), now.getTime());
			let amountCapReason = '';
			let case3CurrentPhaseRate = 0;
			let case3SafeRuntimeSec = 0;
			if (item.crewDelta > 0) {
				let released = 0;
				let extraCrewAvailableAt = effectiveStartMs;
				for (const donor of donorTimeline) {
					if (donor.finishMs == null || donor.finishMs < effectiveStartMs) continue;
					released += donor.releaseCrew;
					extraCrewAvailableAt = donor.finishMs;
					if (released >= item.crewDelta) break;
				}
				if (released < item.crewDelta) {
					// Insufficient crew for the full planned run this cycle. Do not roll
					// effectiveStartMs to nextXx59ForRow and do not use the final-phase
					// rate for the whole window - that combination produced oversized
					// amounts (e.g. 2.79M Framework). Branch on what crew the slot has now.
					if (item.currentCrewActive > 0) {
						const secondsPerUnit = Math.max(1, Number(row.secondsPerUnit || 1));
						case3CurrentPhaseRate = Math.floor(item.currentCrewActive * 3600 / secondsPerUnit);
						const case3StartMs = Math.max(effectiveStartMs, now.getTime());
						case3SafeRuntimeSec = Math.max(0, Math.floor((nextXx59ForRow - case3StartMs - landingBufferSeconds * 1000) / 1000));
						amountCapReason = 'insufficient_crew_current_phase';
					} else {
						case3CurrentPhaseRate = 0;
						case3SafeRuntimeSec = 0;
						amountCapReason = 'insufficient_crew_no_crew';
					}
				} else {
					effectiveStartMs = Math.max(effectiveStartMs, extraCrewAvailableAt);
				}
			}
			const nextRuntimeMs = Math.max(0, nextXx59ForRow - effectiveStartMs - landingBufferSeconds * 1000);
			const nextRuntimeSec = Math.floor(nextRuntimeMs / 1000);
			const nextAmount = amountCapReason
				? (amountCapReason === 'insufficient_crew_current_phase'
					? Math.max(0, Math.floor(case3CurrentPhaseRate * case3SafeRuntimeSec / 3600))
					: 0)
				: Math.max(0, Math.floor(upgradingHour * (nextRuntimeSec / 3600)));
			row.nextXx59Utc = new Date(nextXx59ForRow).toISOString();
			row.nextRuntime = nextRuntimeSec;
			row.nextAmount = nextAmount;
			row.nextCrew = nextCrew;
			row.currentCrewActive = item.currentCrewActive;
			row.crewDelta = item.crewDelta;
			row.availableCrew = item.availableCrew;
			row.effectiveStartMs = effectiveStartMs;
			row.amountCapReason = amountCapReason || '';
			if (/^\s*Paused\s*\[/i.test(item.liveState || '') && !liveFinishMs) {
				console.log('[Scheduler][PausedNoFinishDebug]', {
					craft: row.craftLabel,
					state: item.liveState || '',
					treatedAsIdle: true,
					targetUtc: new Date(nextXx59ForRow).toISOString(),
					nextRuntimeSec,
					nowUtc: now.toISOString()
				});
			}
			if (nextCrew > 0 && nextAmount === 0) {
				const liveStateMatch = String(item.liveState || '').match(/\[(\d{1,2}:\d{2})\]/);
				const zeroAmountDebug = {
					craft: row.craftLabel,
					crew: nextCrew,
					upgradingHour,
					liveState: item.liveState || '',
					liveStateClock: liveStateMatch ? liveStateMatch[1] : '',
					liveFinishMs,
					liveFinishIso: liveFinishMs ? new Date(liveFinishMs).toISOString() : null,
					targetUtc: new Date(nextXx59ForRow).toISOString(),
					nextRuntimeSec,
					nowUtc: now.toISOString(),
					rolledToNextUtcDay: !!(liveFinishMs && liveFinishMs > now.getTime() + 12 * 3600 * 1000),
					amountCapReason: amountCapReason || ''
				};
				console.log('[Scheduler][ZeroAmountDebug]', zeroAmountDebug);
				appendUpgradeAutomationLog('[Scheduler][ZeroAmountDebug] ' + JSON.stringify(zeroAmountDebug)).catch(() => {});
			}
			if (amountCapReason) {
				const insufficientDebug = {
					craft: row.craftLabel,
					reason: amountCapReason,
					currentCrewActive: item.currentCrewActive,
					plannedCrew: item.plannedCrew,
					crewDelta: item.crewDelta,
					case3CurrentPhaseRate,
					case3SafeRuntimeSec,
					nextAmount,
					targetUtc: new Date(nextXx59ForRow).toISOString(),
					nowUtc: now.toISOString()
				};
				console.log('[Scheduler][InsufficientCrewDebug]', insufficientDebug);
				appendUpgradeAutomationLog('[Scheduler][InsufficientCrewDebug] ' + JSON.stringify(insufficientDebug)).catch(() => {});
			}
		}

		return {
			...payload,
			enabled: !!settings.upgradeAutomationEnabled,
			jobDurationSeconds: Math.max(0, target.targetFinishAt.getTime() - now.getTime()) / 1000,
			targetFinishAtUtc: target.targetFinishAt.toISOString(),
			secondsUntilTargetFinish: target.secondsUntilTargetFinish,
			targetReason: target.reason
		};
	}

	function getUpgradeAutomationNextTargetWindow(now = new Date(), settings = {}) {
		const minLeadSeconds = Math.max(60, parseIntDefault(settings.upgradeAutomationMinLeadSeconds, 300));
		const targetOffsetSeconds = Math.max(0, parseIntDefault(settings.upgradeAutomationTargetOffsetSeconds, 60));
		const targetMinute = 59;
		const targetSecond = Math.max(0, 60 - targetOffsetSeconds);
		let targetFinishAt = new Date(Date.UTC(
			now.getUTCFullYear(),
			now.getUTCMonth(),
			now.getUTCDate(),
			now.getUTCHours(),
			targetMinute,
			targetSecond,
			0
		));
		let reason = 'same_hour_:59';
		if ((targetFinishAt.getTime() - now.getTime()) / 1000 < minLeadSeconds) {
			targetFinishAt = new Date(Date.UTC(
				now.getUTCFullYear(),
				now.getUTCMonth(),
				now.getUTCDate(),
				now.getUTCHours() + 1,
				targetMinute,
				targetSecond,
				0
			));
			reason = 'next_hour_:59';
		}
		return {
			targetFinishAt,
			secondsUntilTargetFinish: Math.max(0, Math.floor((targetFinishAt.getTime() - now.getTime()) / 1000)),
			reason,
			minLeadSeconds,
			targetOffsetSeconds
		};
	}

	function getUpgradeAutomationManagedCraftLabels(settings = {}) {
		const startCraftSlot = Math.max(1, parseIntDefault(settings.upgradeAutomationStartCraftSlot, 1));
		return Array.from({ length: UPGRADE_AUTOMATION_MANAGED_CRAFT_SLOTS }, (_, i) => 'craft' + (startCraftSlot + i));
	}

	function getUpgradeAutomationFixedCraftConfigForLabel(label = '', settings = {}) {
		const match = String(label || '').trim().match(/^craft(\d+)$/i);
		if (!match) return null;
		const startCraftSlot = Math.max(1, parseIntDefault(settings.upgradeAutomationStartCraftSlot, 1));
		const orderIndex = Number(match[1]) - startCraftSlot;
		const componentName = UPGRADE_AUTOMATION_NEUTRAL_COMPONENT_ORDER[orderIndex];
		if (!componentName) return null;
		const normalizedInstance = normalizeUpgradeAutomationLpInstance(settings.upgradeAutomationLpInstance || 'MUD');
		const factionCfg = UPGRADE_AUTOMATION_FACTION_CONFIG[normalizedInstance] || UPGRADE_AUTOMATION_FACTION_CONFIG.MUD;
		return {
			item: componentName === 'Survey Data Unit' ? 'SDU Upgrade' : (componentName + ' Upgrade'),
			coordinates: String(factionCfg?.phantomCrewCoords || '0,-24')
		};
	}

	function isUpgradeAutomationSlotActive(slot = {}) {
		if (!slot) return false;
		const hasManagedFlag = !!slot.lpAutomationManaged;
		const hasWorkEvidence = !!(slot.item && Number(slot.amount || 0) > 0);
		const hasRuntimeEvidence = !!(Number(slot.crew || 0) > 0 && slot.coordinates);
		return hasManagedFlag && (hasWorkEvidence || hasRuntimeEvidence);
	}

	function getUpgradeAutomationCycleStamp(now = new Date(), settings = {}) {
		const target = getUpgradeAutomationNextTargetWindow(now, settings);
		return target.targetFinishAt.toISOString().slice(0, 16);
	}

	async function logUpgradeAutomationSchedulerEvent(message, details = null) {
		const line = '[Scheduler] ' + String(message || 'event') + (details ? ' ' + JSON.stringify(details) : '');
		try { console.log(line); } catch (e) {}
		try { await appendUpgradeAutomationLog(line); } catch (e) {}
	}

		function buildUpgradeAutomationSchedulerPlanPayload(stage, rows, schedule, settings = {}, now = new Date()) {
			const rowList = Array.isArray(rows) ? JSON.parse(JSON.stringify(rows)) : [];
			const targetFinishAtUtc = String(schedule?.targetFinishAtUtc || '');
			const writeAfterAt = targetFinishAtUtc ? new Date(new Date(targetFinishAtUtc).getTime() - 2 * 60 * 1000) : null;
			return {
				schemaVersion: 1,
				stage: String(stage || 'capture'),
				hour: now.getUTCHours(),
				cycleStamp: getUpgradeAutomationCycleStamp(now, settings),
				capturedAtUtc: now.toISOString(),
				targetFinishAtUtc,
				writeAfterUtc: writeAfterAt && !Number.isNaN(writeAfterAt.getTime()) ? writeAfterAt.toISOString() : '',
				rows: rowList
			};
		}

	function isUpgradeAutomationSchedulerPlanValidForHour(payload, settings = {}, now = new Date()) {
		return !!(
			payload &&
			String(payload.cycleStamp || '') === getUpgradeAutomationCycleStamp(now, settings) &&
			String(payload.targetFinishAtUtc || '') &&
			Array.isArray(payload.rows) &&
				payload.rows.length
			);
		}

		function getUpgradeAutomationSchedulerWriteAfterUtc(payload) {
			const explicit = String(payload?.writeAfterUtc || '');
			if (explicit) return explicit;
			const targetFinishAtUtc = String(payload?.targetFinishAtUtc || '');
			if (!targetFinishAtUtc) return '';
			const target = new Date(targetFinishAtUtc);
			if (Number.isNaN(target.getTime())) return '';
			// Target is the NEXT hour's xx:59, so the writable window opens 2 minutes
			// before the *current* hour's xx:57 (~62 min before the target). The
			// scheduler check at xx:57/xx:58 of the current hour then fires the write.
			return new Date(target.getTime() - 62 * 60 * 1000).toISOString();
		}

		function isUpgradeAutomationSchedulerPlanWriteDue(payload, now = new Date()) {
			const writeAfterUtc = getUpgradeAutomationSchedulerWriteAfterUtc(payload);
			if (!writeAfterUtc) return false;
			const writeAfter = new Date(writeAfterUtc);
			if (Number.isNaN(writeAfter.getTime())) return false;
			return now.getTime() >= writeAfter.getTime();
		}

	function hydrateUpgradeAutomationSchedulerPlan(payload) {
		if (!payload) return;
		upgradeAutomationPendingPlanRows = Array.isArray(payload.rows) ? JSON.parse(JSON.stringify(payload.rows)) : [];
		upgradeAutomationLastPlanSchedule = { targetFinishAtUtc: String(payload.targetFinishAtUtc || '') };
		upgradeAutomationPendingCaptureHour = Number(payload.hour);
		window.schedulerPendingPlanRows = upgradeAutomationPendingPlanRows;
		window.schedulerPendingCaptureHour = upgradeAutomationPendingCaptureHour;
		window.schedulerLastPlanSchedule = upgradeAutomationLastPlanSchedule;
		window.schedulerCaptureRaw = JSON.parse(JSON.stringify(upgradeAutomationPendingPlanRows));
	}

	async function persistUpgradeAutomationSchedulerPlan(stage, rows, schedule, settings = {}, now = new Date()) {
		const payload = buildUpgradeAutomationSchedulerPlanPayload(stage, rows, schedule, settings, now);
		if (!isUpgradeAutomationSchedulerPlanValidForHour(payload, settings, now)) return null;
		await GM.setValue(UPGRADE_AUTOMATION_SCHEDULER_PENDING_PLAN_KEY, JSON.stringify(payload));
		hydrateUpgradeAutomationSchedulerPlan(payload);
		return payload;
	}

	function getUpgradeAutomationSchedulerRowsFromSummary(summary, settings = {}, now = new Date()) {
		const scheduleState = summary ? getUpgradeAutomationScheduleState(summary, settings, now) : null;
		const targetFinishAtUtc = scheduleState?.targetFinishAtUtc || '';
		const rows = Array.isArray(scheduleState?.rows) ? JSON.parse(JSON.stringify(scheduleState.rows)) : [];
		return { rows, targetFinishAtUtc, scheduleState };
	}

	async function persistUpgradeAutomationSchedulerPlanFromSummary(stage, summary, settings = {}, now = new Date()) {
		const capture = getUpgradeAutomationSchedulerRowsFromSummary(summary, settings, now);
		const payload = await persistUpgradeAutomationSchedulerPlan(stage, capture.rows, { targetFinishAtUtc: capture.targetFinishAtUtc }, settings, now);
		return { ...capture, payload };
	}

	async function refreshUpgradeAutomationExecutionSummaryForScheduler(stage, now = new Date(), timeoutMs = 12000) {
		const startedAt = Date.now();
		await logUpgradeAutomationSchedulerEvent('CAPTURE refresh starting', { utc: now.toISOString(), stage });
		const refreshPromise = (async () => {
			await refreshUpgradeAutomationExecutionSummary();
			return { ok: true };
		})().catch(error => ({ ok: false, error }));
		const timeoutPromise = new Promise(resolve => {
			setTimeout(() => resolve({ ok: false, timeout: true }), timeoutMs);
		});
		const result = await Promise.race([refreshPromise, timeoutPromise]);
		const elapsedMs = Date.now() - startedAt;
		if (result?.timeout) {
			await logUpgradeAutomationSchedulerEvent('CAPTURE refresh timeout', { utc: new Date().toISOString(), stage, elapsedMs, timeoutMs });
		} else if (result?.ok) {
			await logUpgradeAutomationSchedulerEvent('CAPTURE refresh complete', { utc: new Date().toISOString(), stage, elapsedMs });
		} else {
			await logUpgradeAutomationSchedulerEvent('CAPTURE refresh error', { utc: new Date().toISOString(), stage, elapsedMs, err: String(result?.error?.message || result?.error || 'unknown_error') });
		}
		return result;
	}

	async function loadUpgradeAutomationSchedulerPlan(settings = {}, now = new Date()) {
		try {
			const raw = await GM.getValue(UPGRADE_AUTOMATION_SCHEDULER_PENDING_PLAN_KEY, '');
			const payload = raw ? JSON.parse(raw) : null;
			if (!isUpgradeAutomationSchedulerPlanValidForHour(payload, settings, now)) return null;
			return payload;
		} catch (e) {
			return null;
		}
	}

	async function writeUpgradeAutomationSchedulerReceipt(stage, payload, settings = {}, now = new Date()) {
		const receipt = {
			schemaVersion: 1,
			stage: String(stage || 'write'),
			hour: now.getUTCHours(),
			cycleStamp: getUpgradeAutomationCycleStamp(now, settings),
			writtenAtUtc: now.toISOString(),
			targetFinishAtUtc: String(payload?.targetFinishAtUtc || ''),
			rowCount: Array.isArray(payload?.rows) ? payload.rows.length : 0
		};
		await GM.setValue(UPGRADE_AUTOMATION_SCHEDULER_WRITE_RECEIPT_KEY, JSON.stringify(receipt));
		return receipt;
	}

	async function loadUpgradeAutomationSchedulerReceipt(settings = {}, now = new Date()) {
		try {
			const raw = await GM.getValue(UPGRADE_AUTOMATION_SCHEDULER_WRITE_RECEIPT_KEY, '');
			const receipt = raw ? JSON.parse(raw) : null;
			if (!receipt) return null;
			if (String(receipt.cycleStamp || '') !== getUpgradeAutomationCycleStamp(now, settings)) return null;
			return receipt;
		} catch (e) {
			return null;
		}
	}

	async function verifyUpgradeAutomationSchedulerPlanWritten(payload) {
		const rows = Array.isArray(payload?.rows) ? payload.rows : [];
		if (!rows.length) return { ok: false, reason: 'no_rows', checked: 0, failures: [] };
		const failures = [];
		for (const row of rows) {
			const craftLabel = String(row?.craftLabel || '');
			if (!craftLabel) continue;
			const slot = await getUpgradeAutomationCraftSlotState(craftLabel);
			const expectedAmount = 0;
			const expectedCrew = Math.max(0, Math.floor(Number(row.nextCrew || 0)));
			const actualAmount = Math.max(0, Math.floor(Number(slot?.amount || 0)));
			const actualCrew = Math.max(0, Math.floor(Number(slot?.crew || 0)));
			const actualCycleStamp = String(slot?.lpAutomationCycleStamp || '');
			if (actualAmount !== expectedAmount || actualCrew !== expectedCrew || actualCycleStamp !== String(payload?.cycleStamp || '')) {
				failures.push({ craftLabel, expectedAmount, actualAmount, expectedCrew, actualCrew, actualCycleStamp });
			}
		}
		return {
			ok: failures.length === 0,
			reason: failures.length ? 'slot_mismatch' : 'verified',
			checked: rows.length,
			failures: failures.slice(0, 5)
		};
	}

	function getUpgradeAutomationLiveStatusRows() {
		try {
			const raw = localStorage.getItem('slya-status-live');
			if (!raw) return [];
			const parsed = JSON.parse(raw);
			return Array.isArray(parsed?.rows) ? parsed.rows : [];
		} catch (e) {
			return [];
		}
	}

	function findUpgradeAutomationLiveStatusRow(craftLabel = '', rows = []) {
		const target = String(craftLabel || '').trim().toLowerCase();
		if (!target) return null;
		const exact = rows.find(row => String(row?.label || '').trim().toLowerCase() === target);
		if (exact) return exact;
		const prefix = rows.find(row => String(row?.label || '').trim().toLowerCase().startsWith(target + ' '));
		if (prefix) return prefix;
		const targetNum = parseInt((target.match(/^craft\s*(\d+)/i) || [])[1] || '', 10);
		if (Number.isFinite(targetNum)) {
			const numeric = rows.find(row => {
				const rowNum = parseInt((String(row?.label || '').trim().match(/^craft\s*(\d+)/i) || [])[1] || '', 10);
				return Number.isFinite(rowNum) && rowNum === targetNum;
			});
			if (numeric) return numeric;
		}
		return null;
	}

	function parseUpgradeAutomationLiveFinishAtUtc(stateText = '', now = new Date()) {
		const txt = String(stateText || '');
		if (!/^\s*Upgrading\s*\[/i.test(txt)) return '';
		const m = txt.match(/\[(\d{1,2}):(\d{2})\]/);
		if (!m) return '';
		const hourLocal = parseInt(m[1], 10);
		const minuteLocal = parseInt(m[2], 10);
		if (!Number.isFinite(hourLocal) || !Number.isFinite(minuteLocal)) return '';
		const candidateLocal = new Date(now.getTime());
		candidateLocal.setHours(hourLocal, minuteLocal, 0, 0);
		if (candidateLocal.getTime() < now.getTime()) {
			const nextOccurrence = new Date(candidateLocal.getTime());
			nextOccurrence.setDate(nextOccurrence.getDate() + 1);
			// An HH:mm-only panel state is ambiguous across midnight. Permit the
			// coming night only while it is reasonably near; otherwise an overdue
			// ghost (for example 00:58 observed at 07:00) becomes tomorrow's job.
			if (nextOccurrence.getTime() - now.getTime() > 12 * 3600 * 1000) return '';
			candidateLocal.setTime(nextOccurrence.getTime());
		}
		return candidateLocal.toISOString();
	}

	function shouldClearMissingUpgradeAutomationProcess(snapshotSlot = {}, currentSlot = {}, onChainIds = new Set()) {
		const snapshotId = String(snapshotSlot?.craftingId || '');
		const currentId = String(currentSlot?.craftingId || '');
		return !!(
			snapshotSlot?.lpAutomationManaged &&
			snapshotId && snapshotId !== '0' &&
			currentId === snapshotId &&
			!onChainIds.has(snapshotId)
		);
	}

	function parseUpgradeAutomationLiveRemainingMinutes(stateText = '') {
		const txt = String(stateText || '');
		const m = txt.match(/Paused\s*\[(\d+)m\s+left\]/i);
		return m ? Math.max(0, parseInt(m[1], 10) || 0) : null;
	}

	async function detectUpgradeAutomationCompletionEvent(settings = {}, now = new Date()) {
		const managedCraftLabels = getUpgradeAutomationManagedCraftLabels(settings);
		const previousState = JSON.parse(await GM.getValue('upgradeAutomationSchedulerObservedState', '{}') || '{}');
		const liveStatusRows = getUpgradeAutomationLiveStatusRows();
		const currentState = {};
		let completedCount = 0;
		let completedLabels = [];
		let activeCount = 0;
		for (const craftLabel of managedCraftLabels) {
			const slot = await getUpgradeAutomationCraftSlotState(craftLabel);
			const active = isUpgradeAutomationSlotActive(slot);
			if (active) activeCount++;
			const item = String(slot?.item || '');
			const amount = Number(slot?.amount || 0);
			const crew = Number(slot?.crew || 0);
			const coordinates = String(slot?.coordinates || '');
			const updatedAt = String(slot?.lpAutomationUpdatedAt || '');
			const targetFinishAt = String(slot?.lpAutomationTargetFinishAt || '');
			const liveRow = findUpgradeAutomationLiveStatusRow(craftLabel, liveStatusRows);
			const liveState = String(liveRow?.state || '');
			const liveFinishAtUtc = parseUpgradeAutomationLiveFinishAtUtc(liveState, now);
			const liveRemainingMinutes = parseUpgradeAutomationLiveRemainingMinutes(liveState);
			const liveActive = /Upgrading\s*\[|Paused\s*\[/.test(liveState);
			if (liveActive && !active) activeCount++;
			const currentManaged = !!(slot?.lpAutomationManaged || item || amount > 0 || targetFinishAt || updatedAt || coordinates);
			const prev = previousState?.[craftLabel] || {};
			const prevManaged = !!(prev?.managedEvidence || prev?.item || Number(prev?.amount || 0) > 0 || prev?.targetFinishAt || prev?.updatedAt || prev?.coordinates);
			const currentIdle = !active && !item && amount <= 0 && crew <= 0 && !coordinates;
			const rolledIntoNewManagedJob = !!(
				(prev.liveActive || prev.active) && (liveActive || active) && prevManaged && currentManaged && (
					String(prev?.liveFinishAtUtc || '') !== String(liveFinishAtUtc || '') ||
					String(prev?.liveState || '') !== String(liveState || '') ||
					String(prev?.targetFinishAt || '') !== String(targetFinishAt || '') ||
					String(prev?.updatedAt || '') !== String(updatedAt || '') ||
					String(prev?.item || '') !== String(item || '') ||
					Number(prev?.amount || 0) !== Number(amount || 0) ||
					Number(prev?.crew || 0) !== Number(crew || 0) ||
					String(prev?.coordinates || '') !== String(coordinates || '')
				)
			);
			const completed = !!(
				((prev.liveActive || prev.active) && !(liveActive || active) && currentIdle) || rolledIntoNewManagedJob
			);
			const carryForwardCompletion = !!(!(liveActive || active) && (currentManaged || prev.liveActive || prev.active || prevManaged));
			const lastObservedCompletionAt = completed ? now.toISOString() : (carryForwardCompletion ? String(prev?.lastObservedCompletionAt || '') : '');
			if (completed) {
				completedCount++;
				completedLabels.push(craftLabel);
			}
			currentState[craftLabel] = {
				active,
				liveActive,
				liveState,
				liveFinishAtUtc,
				liveRemainingMinutes,
				item,
				amount,
				crew,
				coordinates,
				updatedAt,
				targetFinishAt,
				managedEvidence: currentManaged,
				rolledIntoNewManagedJob,
				lastObservedCompletionAt
			};
		}
		await GM.setValue('upgradeAutomationSchedulerObservedState', JSON.stringify(currentState));
		return {
			completed: completedCount > 0,
			completedCount,
			completedLabels,
			activeCount,
			allIdle: activeCount === 0,
			currentState,
			previousState,
			completedAt: now.toISOString()
		};
	}

	async function getUpgradeAutomationCraftSlotState(craftLabel) {
		try {
			const raw = await GM.getValue(craftLabel, '{}');
			return raw ? JSON.parse(raw) : {};
		} catch (e) {
			return {};
		}
	}

	// Read-only panel refresh for non-LP-managed craft slots.
	// Walks each non-LP slot's saved state, re-queries on-chain CraftingInstance +
	// CraftingProcess accounts at the slot's craftingCoords, and updates the
	// displayed `state` text if the slot's saved `craftingId` is no longer live
	// on-chain (so the panel doesn't keep showing a stale "Waiting for crew" etc.).
	// Does NOT mutate craftingId. Does NOT call execCancelCraft. Does NOT touch
	// LP-managed slots. Does NOT write back to GM. Display-only, safe to run on
	// a timer.
	async function refreshNonLpCraftPanelFromChain() {
		if (typeof sageProgram === 'undefined' || !sageProgram || !sageProgram.account || !sageProgram.account.craftingInstance) return;
		if (typeof craftingProgram === 'undefined' || !craftingProgram || !craftingProgram.account || !craftingProgram.account.craftingProcess) return;
		if (typeof userProfileAcct === 'undefined' || !userProfileAcct) return;
		try {
			const settings = (typeof globalSettings !== 'undefined' && globalSettings) ? globalSettings : {};
			const totalCraftingJobs = Math.max(0, parseIntDefault(settings.craftingJobs, 0));
			if (!totalCraftingJobs) return;
			const startCraftSlot = Math.max(1, parseIntDefault(settings.upgradeAutomationStartCraftSlot, 1));
			const managedLabels = new Set(getUpgradeAutomationManagedCraftLabels(settings));

			// Build the list of non-LP slot labels: 1..totalCraftingJobs minus managed.
			const nonLpLabels = [];
			for (let i = 1; i <= totalCraftingJobs; i++) {
				const label = 'craft' + i;
				if (managedLabels.has(label)) continue;
				nonLpLabels.push(label);
			}
			if (!nonLpLabels.length) return;

			// Read each slot's saved state once. Skip slots without craftingCoords
			// (never started) or without a craftingId (idle).
			const slotByLabel = new Map();
			const slotByCoords = new Map();
			for (const label of nonLpLabels) {
				let slot;
				try {
					const raw = await GM.getValue(label, '{}');
					slot = raw ? JSON.parse(raw) : {};
				} catch (e) { continue; }
				const craftingId = Math.floor(Number(slot && slot.craftingId || 0));
				if (!craftingId) continue;
				const coords = String((slot && slot.craftingCoords) || (slot && slot.coordinates) || '').trim();
				if (!coords) continue;
				slotByLabel.set(label, { slot, craftingId, coords });
				if (!slotByCoords.has(coords)) slotByCoords.set(coords, []);
				slotByCoords.get(coords).push(label);
			}
			if (!slotByCoords.size) return;

			let updated = 0;
			for (const [coords, labels] of slotByCoords) {
				const coordParts = coords.split(',').map(v => parseInt(String(v).trim(), 10));
				if (coordParts.length !== 2 || !coordParts.every(Number.isFinite)) continue;
				let starbase;
				try { starbase = await getStarbaseFromCoords(coordParts[0], coordParts[1], true); } catch (e) { continue; }
				if (!starbase || !starbase.publicKey) continue;
				let starbasePlayer;
				try { starbasePlayer = await getStarbasePlayer(userProfileAcct, starbase.publicKey); } catch (e) { continue; }
				const starbasePlayerPk = starbasePlayer ? (starbasePlayer.publicKey || starbasePlayer) : null;
				if (!starbasePlayerPk) continue;

				let craftingInstances;
				try {
					craftingInstances = await sageProgram.account.craftingInstance.all([
						{ memcmp: { offset: 11, bytes: starbasePlayerPk.toBase58() } }
					]);
				} catch (e) { continue; }

				// Build the set of live craftingIds across all instances at this starbase.
				const liveCraftingIds = new Set();
				for (const craftingInstance of craftingInstances) {
					let craftingProcesses;
					try {
						craftingProcesses = await craftingProgram.account.craftingProcess.all([
							{ memcmp: { offset: 17, bytes: craftingInstance.publicKey.toBase58() } }
						]);
					} catch (e) { continue; }
					for (const cp of craftingProcesses) {
						try {
							const cid = cp && cp.account && cp.account.craftingId && cp.account.craftingId.toNumber
								? cp.account.craftingId.toNumber()
								: Number(cp && cp.account && cp.account.craftingId || 0);
							if (cid) liveCraftingIds.add(cid);
						} catch (e) { /* skip */ }
					}
				}

				// For each slot at these coords, if its saved craftingId is no longer
				// live on-chain, the slot is stale: update the displayed state to
				// 'Idle' and re-render. Do NOT write back to GM.
				for (const label of labels) {
					const rec = slotByLabel.get(label);
					if (!rec) continue;
					if (liveCraftingIds.has(rec.craftingId)) continue;
					const currentState = String((rec.slot && rec.slot.state) || '');
					if (currentState === 'Idle') continue;
					try { cLog(2, FleetTimeStamp(label), '[CRAFT-PANEL-STALE] saved craftingId', rec.craftingId, 'not found in live processes at', coords + '; displaying Idle'); } catch (e) {}
					try { updateFleetState({ label, state: 'Idle' }, 'Idle', true); } catch (e) {}
					updated += 1;
				}
			}

			if (updated > 0) {
				try { renderAssistStats(); } catch (e) {}
			}
		} catch (e) {
			try { cLog(1, '[CRAFT-PANEL-REFRESH] error:', e && e.message || e); } catch (_) {}
		}
	}

	function getUpgradeAutomationLpUpgradeRecipeNames() {
		return new Set(UPGRADE_AUTOMATION_NEUTRAL_COMPONENT_ORDER.map(componentName => {
			return componentName === 'Survey Data Unit' ? 'SDU Upgrade' : (componentName + ' Upgrade');
		}));
	}

	function getUpgradeAutomationUpgradeRecipeComponentName(recipeName = '') {
		const name = String(recipeName || '').trim();
		if (!name) return '';
		if (name === 'SDU Upgrade') return 'Survey Data Unit';
		if (!name.endsWith(' Upgrade')) return '';
		return name.slice(0, -8);
	}

	async function getUpgradeAutomationLpStarbaseContext(settings = {}) {
		const lpInstanceKey = normalizeUpgradeAutomationLpInstance(settings?.upgradeAutomationLpInstance || 'MUD');
		const factionCfg = UPGRADE_AUTOMATION_FACTION_CONFIG[lpInstanceKey] || UPGRADE_AUTOMATION_FACTION_CONFIG.MUD;
		const coords = String(factionCfg?.phantomCrewCoords || '0,-24');
		const coordParts = coords.split(',').map(v => parseInt(String(v).trim(), 10));
		if (coordParts.length !== 2 || !coordParts.every(Number.isFinite)) {
			return { error: 'invalid_lp_coords', coords };
		}
		const starbase = await getStarbaseFromCoords(coordParts[0], coordParts[1], true);
		if (!starbase) return { error: 'starbase_not_found', coords };
		const starbasePlayerAcct = userProfileAcct && starbase.publicKey ? await getStarbasePlayer(userProfileAcct, starbase.publicKey) : null;
		const starbasePlayer = starbasePlayerAcct?.publicKey || starbasePlayerAcct || null;
		if (!starbasePlayer) return { error: 'starbase_player_not_found', coords };
		const upgradeTime = await getStarbaseTime(starbase, 'Upgrade');
		return { lpInstanceKey, coords, starbase, starbasePlayer, upgradeTime };
	}

	async function getUpgradeAutomationLpUpgradeProcesses(context, settings = {}) {
		const recipeNames = getUpgradeAutomationLpUpgradeRecipeNames();
		const managedCraftLabels = getUpgradeAutomationManagedCraftLabels(settings);
		const managedCraftLabelSet = new Set(managedCraftLabels);
		const assignedByCraftingId = new Map();
		for (const craftLabel of managedCraftLabels) {
			const slot = await getUpgradeAutomationCraftSlotState(craftLabel);
			const craftingId = Math.max(0, Math.floor(Number(slot?.craftingId || 0)));
			if (craftingId) assignedByCraftingId.set(String(craftingId), craftLabel);
		}

		const craftingInstances = await sageProgram.account.craftingInstance.all([
			{
				memcmp: {
					offset: 11,
					bytes: context.starbasePlayer.toBase58(),
				},
			},
		]);

		const processes = [];
		for (const craftingInstance of craftingInstances) {
			const craftingProcesses = await craftingProgram.account.craftingProcess.all([
				{
					memcmp: {
						offset: 17,
						bytes: craftingInstance.publicKey.toBase58(),
					},
				},
			]);

			for (const craftingProcess of craftingProcesses) {
				const recipe = upgradeRecipes.find(item => item.publicKey.toString() === craftingProcess.account.recipe.toString());
				if (!recipe || !recipeNames.has(recipe.name)) continue;
				const craftingId = craftingProcess.account.craftingId.toNumber();
				if (!craftingId) continue;
				const status = maybeBnToNumber(craftingProcess.account.status, craftingProcess.account.status);
				if (![0, 1, 2, 3].includes(status)) continue;
				const remainingSeconds = Math.max(craftingProcess.account.endTime.toNumber() - context.upgradeTime.starbaseTime, 0);
				const completed = remainingSeconds <= 0 && [2, 3].includes(status);
				const assignedLabel = assignedByCraftingId.get(String(craftingId)) || '';
				processes.push({
					craftingProcess: craftingProcess.publicKey,
					craftingInstance: craftingInstance.publicKey,
					recipe: craftingProcess.account.recipe,
					recipeName: recipe.name,
					component: getUpgradeAutomationUpgradeRecipeComponentName(recipe.name),
					status,
					craftingId,
					endTime: craftingProcess.account.endTime.toNumber(),
					remainingSeconds,
					completed,
					assignedLabel: managedCraftLabelSet.has(assignedLabel) ? assignedLabel : ''
				});
			}
		}

		return processes.sort((a, b) => {
			if (a.completed !== b.completed) return a.completed ? -1 : 1;
			return a.endTime - b.endTime;
		});
	}

	function formatUpgradeAutomationRecoveredUpgradeState(process, context) {
		if (process.completed) return 'Upgrade Completing';
		const remainingSeconds = Math.max(0, Math.floor(Number(process.remainingSeconds || 0)));
		return context.upgradeTime?.resRemaining > 0
			? 'Upgrading [' + TimeToStr(new Date(Date.now() + remainingSeconds * 1000)) + ']'
			: 'Paused [' + parseInt(remainingSeconds / 60) + 'm remaining]';
	}

	async function findUpgradeAutomationSlotForProcess(process, managedCraftLabels, settings = {}) {
		if (process.assignedLabel) return process.assignedLabel;

		for (const craftLabel of managedCraftLabels) {
			const slot = await getUpgradeAutomationCraftSlotState(craftLabel);
			if (Number(slot?.craftingId || 0) > 0) continue;
			if (String(slot?.item || '') === process.recipeName) return craftLabel;
		}

		for (const craftLabel of managedCraftLabels) {
			const slot = await getUpgradeAutomationCraftSlotState(craftLabel);
			if (Number(slot?.craftingId || 0) > 0) continue;
			if (!String(slot?.item || '') && !Number(slot?.amount || 0) && !Number(slot?.crew || 0)) return craftLabel;
		}

		for (const craftLabel of managedCraftLabels) {
			const slot = await getUpgradeAutomationCraftSlotState(craftLabel);
			if (Number(slot?.craftingId || 0) > 0) continue;
			return craftLabel;
		}

		return '';
	}

	// ===== Per-profile LP tracking (SLY_19, rewritten 2026-07-21) =====
	// Discovers every StarbasePlayer at each configured faction upgrade starbase,
	// resolves its exact playerProfile, then aggregates live upgrade processes by
	// player profile across all configured starbases. The active snapshot is
	// independent of the wallet/profile loaded in this SLYA instance.
	const UPGRADE_AUTOMATION_LP_PER_PROFILE_CYCLE_MIN_MS = 60000; // in-run guard only
	const UPGRADE_AUTOMATION_STARBASE_PLAYER_STARBASE_OFFSET = 73;

	function getUpgradeAutomationLpPerProfileFactions() {
		const out = [];
		try {
			const currentInstance = String((typeof globalSettings !== 'undefined' && globalSettings && (globalSettings.slyInstanceName || globalSettings.fleetFaction)) || '').toUpperCase();
			const instanceToLp = currentInstance.startsWith('MUD') ? 1
				: currentInstance.startsWith('ONI') ? 2
				: currentInstance.startsWith('UST') ? 3
				: 0;
			for (const [faction, cfg] of Object.entries(UPGRADE_AUTOMATION_FACTION_CONFIG || {})) {
				if (!cfg || !Array.isArray(cfg.upgradeStarbaseCoords) || !cfg.upgradeStarbaseCoords.length) continue;
				const lpInstance = Number(cfg.lpInstance || 0);
				if (instanceToLp ? lpInstance !== instanceToLp : (!currentInstance || !currentInstance.includes(String(faction).toUpperCase()))) continue;
				out.push({
					faction: String(faction),
					lpInstance,
					starbaseCoords: cfg.upgradeStarbaseCoords.map(c => String(c))
				});
			}
		} catch (e) { /* caller logs empty configuration */ }
		return out;
	}

	function getUpgradeAutomationLpProcessQuantity(craftingProcess) {
		try {
			const raw = craftingProcess?.account?.quantity;
			const quantity = raw && typeof raw.toNumber === 'function' ? raw.toNumber() : Number(raw || 0);
			return Number.isSafeInteger(quantity) && quantity > 0 ? quantity : 0;
		} catch (e) { return 0; }
	}

	function getUpgradeAutomationComponentLpPerUnit(component) {
		const name = String(component || '').trim();
		return Number(UPGRADE_AUTOMATION_COMPONENT_LP[name] || (name === 'Survey Data Unit' ? UPGRADE_AUTOMATION_COMPONENT_LP.SDU : 0) || 0);
	}

	function computeUpgradeAutomationInstalledLp(installedTodayByComponent) {
		return Object.entries(installedTodayByComponent || {}).reduce((sum, [component, amount]) => {
			return sum + Math.max(0, Number(amount || 0)) * getUpgradeAutomationComponentLpPerUnit(component);
		}, 0);
	}

	function summarizeUpgradeAutomationUninstalledLp(processes) {
		let under24hLp = 0;
		let over24hLp = 0;
		let oldestOver24hAgeSeconds = 0;
		for (const process of (processes || [])) {
			if (!process?.pendingInstallation) continue;
			const lp = Math.max(0, Number(process.lp || 0));
			const overdueSeconds = Math.max(0, Number(process.overdueSeconds || 0));
			if (overdueSeconds > 86400) {
				over24hLp += lp;
				oldestOver24hAgeSeconds = Math.max(oldestOver24hAgeSeconds, overdueSeconds);
			} else under24hLp += lp;
		}
		return { under24hLp, over24hLp, oldestOver24hAgeSeconds };
	}

	function computeUpgradeAutomationSageEodSeconds(starbaseTime, now = new Date()) {
		const sageNow = Number(starbaseTime || 0);
		const utcEodMs = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1);
		const secondsUntilUtcEod = Math.max(0, Math.floor((utcEodMs - now.getTime()) / 1000));
		return sageNow + secondsUntilUtcEod;
	}

	function medianUpgradeAutomationRestartDelay(values) {
		const sorted = (values || []).map(Number).filter(value => Number.isFinite(value) && value >= 0).sort((a, b) => a - b);
		if (!sorted.length) return null;
		const middle = Math.floor(sorted.length / 2);
		return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
	}

	function collectUpgradeAutomationRestartGaps(historyRows, nowSeconds, filter) {
		const cutoff = Number(nowSeconds || 0) - 7 * 86400;
		const groups = new Map();
		for (const row of (historyRows || [])) {
			if (filter && !filter(row)) continue;
			const startTime = Number(row?.startTime || 0), endTime = Number(row?.endTime || 0);
			if (!startTime || !endTime || startTime < cutoff || startTime >= nowSeconds) continue;
			const key = [row.profile, row.starbase, row.component, row.recipeKey].map(value => String(value || '')).join('|');
			if (!groups.has(key)) groups.set(key, new Map());
			groups.get(key).set(String(row.process || row.craftingProcess || `${startTime}:${endTime}`), { startTime, endTime });
		}
		const gaps = [];
		for (const rows of groups.values()) {
			const ordered = Array.from(rows.values()).sort((x, y) => x.startTime - y.startTime);
			for (let i = 1; i < ordered.length; i++) {
				const gap = ordered[i].startTime - ordered[i - 1].endTime;
				if (gap >= -5) gaps.push(Math.max(0, gap));
			}
		}
		return gaps;
	}

	function estimateUpgradeAutomationRestartDelay(process, historyRows, nowSeconds) {
		const samePlayerComponent = row => String(row?.profile || '') === String(process?.profile || '') && String(row?.starbase || '') === String(process?.starbase || '') && String(row?.component || '') === String(process?.component || '') && String(row?.recipeKey || '') === String(process?.recipeKey || '');
		const sameComponent = row => String(row?.component || '') === String(process?.component || '') && String(row?.recipeKey || '') === String(process?.recipeKey || '');
		for (const [source, filter] of [['player_component', samePlayerComponent], ['component_fallback', sameComponent], ['global_fallback', null]]) {
			const gaps = collectUpgradeAutomationRestartGaps(historyRows, nowSeconds, filter);
			if (gaps.length >= 2) return { restartDelaySeconds: medianUpgradeAutomationRestartDelay(gaps), restartDelaySource: source, restartGapSamples: gaps.length, evidenceWindowDays: 7 };
		}
		return { restartDelaySeconds: 300, restartDelaySource: 'default_fallback', restartGapSamples: 0, evidenceWindowDays: 7 };
	}

	function applyUpgradeAutomationRestartDelays(processes, historyRows) {
		for (const process of (processes || [])) {
			const evidence = estimateUpgradeAutomationRestartDelay(process, historyRows, process.projectionNowSeconds || process.startTime);
			const projection = computeUpgradeAutomationLpProcessEodProjection(process.startTime, process.endTime, process.projectionNowSeconds, process.projectionEodSeconds, process.lp, process.quantity, evidence.restartDelaySeconds);
			Object.assign(process, projection, evidence, { active: projection.inFlightCompletionsByEod > 0, completesByEod: projection.inFlightCompletionsByEod > 0 });
		}
		return processes;
	}

	function computeUpgradeAutomationLpProcessEodProjection(startTime, endTime, nowSeconds, eodSeconds, lp, quantity, restartDelaySeconds = 300) {
		const start = Number(startTime || 0), end = Number(endTime || 0), now = Number(nowSeconds || 0), eod = Number(eodSeconds || 0);
		const durationSeconds = Number.isFinite(start) && Number.isFinite(end) && end > start ? end - start : 0;
		const delay = Math.max(0, Number(restartDelaySeconds || 0));
		const overdueSeconds = Math.max(0, now - end);
		const pendingInstallation = end <= now;
		const staleUninstalled = pendingInstallation && overdueSeconds > 86400;
		const remainingRestartDelaySeconds = pendingInstallation ? Math.max(0, delay - overdueSeconds) : delay;
		const firstCompletionAt = (pendingInstallation ? now : end) + remainingRestartDelaySeconds;
		const inFlightCompletionsByEod = !staleUninstalled && firstCompletionAt <= eod ? 1 : 0;
		const cadenceSeconds = durationSeconds + delay;
		const expectedCompletionsByEod = inFlightCompletionsByEod && cadenceSeconds > 0 ? 1 + Math.floor(Math.max(0, eod - firstCompletionAt) / cadenceSeconds) : inFlightCompletionsByEod;
		const unitLp = Math.max(0, Number(lp || 0)), unitQuantity = Math.max(0, Number(quantity || 0));
		return { durationSeconds, overdueSeconds, restartDelaySeconds: delay, remainingRestartDelaySeconds, staleUninstalled, pendingInstallation, inFlightCompletionsByEod, expectedCompletionsByEod, inFlightLpByEod: unitLp * inFlightCompletionsByEod, expectedLpByEod: unitLp * expectedCompletionsByEod, repeatLpByEod: unitLp * Math.max(0, expectedCompletionsByEod - inFlightCompletionsByEod), inFlightQuantityByEod: unitQuantity * inFlightCompletionsByEod, expectedQuantityByEod: unitQuantity * expectedCompletionsByEod };
	}

	async function fetchUpgradeAutomationRestartHistory(faction, now = new Date()) {
		const factionTag = String(faction || '').replace(/"/g, '');
		const flux = `from(bucket: "${sanitizeInfluxBucketName(globalSettings.influxDB)}")
  |> range(start: -7d, stop: ${now.toISOString()})
  |> filter(fn: (r) => r._measurement == "lp_upgrade_process_history" and r.faction == "${factionTag}")
  |> pivot(rowKey: ["_time", "profile", "process", "starbase", "component", "recipeKey"], columnKey: ["_field"], valueColumn: "_value")
  |> keep(columns: ["_time", "profile", "process", "starbase", "component", "recipeKey", "quantity", "startTime", "endTime", "durationSeconds"])
  |> group()`;
		try { return parseInfluxCsv(await queryInfluxFlux(flux)); }
		catch (e) {
			await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE] repeat history unavailable faction=${factionTag} err=${String(e?.message || e).slice(0, 200)}`);
			return [];
		}
	}

	async function getUpgradeAutomationLpPerProfileProcessesForStarbase(coords, now, accountSnapshot) {
		const out = [];
		const seenProcesses = new Set();
		const dbg = { starbasePlayers: 0, craftingInstances: 0, craftingProcesses: 0, droppedRecipe: 0, droppedQuantity: 0, droppedTime: 0, pushed: 0, bail: '' };
		try {
			const coordParts = String(coords || '').split(',').map(v => parseInt(String(v).trim(), 10));
			if (coordParts.length !== 2 || !coordParts.every(Number.isFinite)) { dbg.bail = 'invalid_coords'; return out; }
			const starbase = await getStarbaseFromCoords(coordParts[0], coordParts[1], true);
			if (!starbase?.publicKey) { dbg.bail = 'no_starbase'; return out; }

			let upgradeTime = null;
			try { upgradeTime = await getStarbaseTime(starbase, 'Upgrade'); } catch (e) { upgradeTime = null; }
			const starbaseTime = Number.isFinite(Number(upgradeTime?.starbaseTime))
				? Number(upgradeTime.starbaseTime)
				: Math.floor(now.getTime() / 1000);
			const sageEodSeconds = computeUpgradeAutomationSageEodSeconds(starbaseTime, now);

			const starbaseKey = starbase.publicKey.toBase58();
			const starbasePlayers = (accountSnapshot?.starbasePlayers || []).filter(row => row?.account?.starbase?.toBase58?.() === starbaseKey);
			dbg.starbasePlayers = (starbasePlayers || []).length;
			const recipeNames = getUpgradeAutomationLpUpgradeRecipeNames();

			const allCraftingInstances = accountSnapshot?.craftingInstances || [];
			const allCraftingProcesses = accountSnapshot?.craftingProcesses || [];
			const instancesByAuthority = new Map();
			for (const craftingInstance of allCraftingInstances) {
				const authority = craftingInstance?.account?.authority?.toBase58?.() || '';
				if (!authority) continue;
				if (!instancesByAuthority.has(authority)) instancesByAuthority.set(authority, []);
				instancesByAuthority.get(authority).push(craftingInstance);
			}
			const processesByAuthority = new Map();
			for (const craftingProcess of allCraftingProcesses) {
				const authority = craftingProcess?.account?.authority?.toBase58?.() || '';
				if (!authority) continue;
				if (!processesByAuthority.has(authority)) processesByAuthority.set(authority, []);
				processesByAuthority.get(authority).push(craftingProcess);
			}

			for (const starbasePlayer of (starbasePlayers || [])) {
				const profileKey = starbasePlayer?.account?.playerProfile;
				const profile = profileKey && typeof profileKey.toBase58 === 'function' ? profileKey.toBase58() : '';
				const starbasePlayerKey = starbasePlayer?.publicKey;
				if (!profile || !starbasePlayerKey) continue;
				const craftingInstances = instancesByAuthority.get(starbasePlayerKey.toBase58()) || [];
				dbg.craftingInstances += craftingInstances.length;

				for (const craftingInstance of craftingInstances) {
					const craftingProcesses = processesByAuthority.get(craftingInstance.publicKey.toBase58()) || [];
					dbg.craftingProcesses += craftingProcesses.length;
					for (const craftingProcess of (craftingProcesses || [])) {
						try {
							const processKey = craftingProcess.publicKey.toBase58();
							if (seenProcesses.has(processKey)) continue;
							seenProcesses.add(processKey);
							const recipe = upgradeRecipes.find(item => item.publicKey.toString() === craftingProcess.account.recipe.toString());
							if (!recipe || !recipeNames.has(recipe.name)) { dbg.droppedRecipe++; continue; }
							const quantity = getUpgradeAutomationLpProcessQuantity(craftingProcess);
							if (!quantity) { dbg.droppedQuantity++; continue; }
							const startTime = craftingProcess.account.startTime?.toNumber ? craftingProcess.account.startTime.toNumber() : Number(craftingProcess.account.startTime || 0);
							const endTime = craftingProcess.account.endTime?.toNumber ? craftingProcess.account.endTime.toNumber() : Number(craftingProcess.account.endTime || 0);
							if (!Number.isFinite(endTime) || endTime <= 0) { dbg.droppedTime++; continue; }
							const component = getUpgradeAutomationUpgradeRecipeComponentName(recipe.name);
							const lpPerUnit = Number(UPGRADE_AUTOMATION_COMPONENT_LP[component] || 0);
							if (!component || !lpPerUnit) { dbg.droppedRecipe++; continue; }
							const remainingSeconds = Math.max(endTime - starbaseTime, 0);
							const projection = computeUpgradeAutomationLpProcessEodProjection(startTime, endTime, starbaseTime, sageEodSeconds, lpPerUnit * quantity, quantity, false);
							out.push({
								profile,
								craftingProcess: processKey,
								starbase: coords,
								component,
								recipe: recipe.name,
								recipeKey: recipe.publicKey.toBase58(),
								quantity,
								lp: lpPerUnit * quantity,
								lpPerUnit,
								startTime,
								endTime,
								projectionNowSeconds: starbaseTime,
								projectionEodSeconds: sageEodSeconds,
								active: projection.inFlightCompletionsByEod > 0,
								remainingSeconds,
								completesByEod: projection.inFlightCompletionsByEod > 0,
								...projection
							});
							dbg.pushed++;
						} catch (e) { dbg.droppedRecipe++; }
					}
				}
			}
		} catch (e) {
			dbg.bail = `starbase_error:${String(e?.message || e).slice(0, 120)}`;
		} finally {
			out.scanOk = !dbg.bail;
			try {
				await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE] starbase=${coords} bail=${dbg.bail || 'none'} sp=${dbg.starbasePlayers} ci=${dbg.craftingInstances} cp=${dbg.craftingProcesses} dr=${dbg.droppedRecipe} dq=${dbg.droppedQuantity} dt=${dbg.droppedTime} pushed=${dbg.pushed}`);
			} catch (_) {}
		}
		return out;
	}

	function aggregateUpgradeAutomationLpPerProfile(processes) {
		const out = {};
		const seenProcesses = new Set();
		for (const p of (processes || [])) {
			if (!p?.active || !p?.profile || !p?.component || !p?.craftingProcess || seenProcesses.has(p.craftingProcess)) continue;
			seenProcesses.add(p.craftingProcess);
			if (!out[p.profile]) out[p.profile] = {};
			if (!out[p.profile][p.component]) {
				out[p.profile][p.component] = { lp: 0, quantity: 0, processCount: 0, lpByEod: 0, quantityByEod: 0, durationSeconds: 0, inFlightCompletionsByEod: 0, expectedCompletionsByEod: 0, expectedLpByEod: 0, repeatLpByEod: 0, expectedQuantityByEod: 0, lpPerUnit: Number(p.lpPerUnit || 0) };
			}
			const slot = out[p.profile][p.component];
			slot.lp += Number(p.lp || 0);
			slot.quantity += Number(p.quantity || 0);
			slot.processCount += 1;
			slot.lpByEod += Number(p.inFlightLpByEod || 0);
			slot.quantityByEod += Number(p.inFlightQuantityByEod || 0);
			slot.durationSeconds += Number(p.durationSeconds || 0);
			slot.inFlightCompletionsByEod += Number(p.inFlightCompletionsByEod || 0);
			slot.expectedCompletionsByEod += Number(p.expectedCompletionsByEod || 0);
			slot.expectedLpByEod += Number(p.expectedLpByEod || 0);
			slot.repeatLpByEod += Number(p.repeatLpByEod || 0);
			slot.expectedQuantityByEod += Number(p.expectedQuantityByEod || 0);
		}
		return out;
	}

	function buildUpgradeAutomationLpPerProfileRpcPlan(recipeKeys) {
		return Array.from(new Set((recipeKeys || []).map(String).filter(Boolean)))
			.map(bytes => [{ memcmp: { offset: 49, bytes } }]);
	}

	async function fetchUpgradeAutomationDecodedAccounts(publicKeys, accountName) {
		const unique = Array.from(new Map((publicKeys || []).filter(Boolean).map(pk => [pk.toBase58(), pk])).values());
		const out = [];
		for (let i = 0; i < unique.length; i += 100) {
			const keys = unique.slice(i, i + 100);
			const infos = await solanaReadConnection.getMultipleAccountsInfo(keys, { commitment: 'confirmed' });
			for (let j = 0; j < keys.length; j++) {
				if (!infos[j]?.data) continue;
				try { out.push({ publicKey: keys[j], account: sageProgram.coder.accounts.decode(accountName, infos[j].data) }); } catch (_) {}
			}
		}
		return out;
	}

	async function fetchUpgradeAutomationLpPerProfileAccountSnapshot() {
		const recipeKeys = upgradeRecipes.filter(recipe => getUpgradeAutomationLpUpgradeRecipeNames().has(recipe.name)).map(recipe => recipe.publicKey.toBase58());
		const craftingProcesses = [];
		for (const filters of buildUpgradeAutomationLpPerProfileRpcPlan(recipeKeys)) craftingProcesses.push(...await craftingProgram.account.craftingProcess.all(filters));
		const dedupedProcesses = Array.from(new Map(craftingProcesses.map(row => [row.publicKey.toBase58(), row])).values());
		const craftingInstances = await fetchUpgradeAutomationDecodedAccounts(dedupedProcesses.map(row => row.account.authority), 'craftingInstance');
		const starbasePlayers = await fetchUpgradeAutomationDecodedAccounts(craftingInstances.map(row => row.account.authority), 'starbasePlayer');
		return { craftingProcesses: dedupedProcesses, craftingInstances, starbasePlayers };
	}

	function mergeUpgradeAutomationLpPerProfileSignatureState(state, signatures) {
		const pending = new Map((state?.pending || []).filter(x => x?.signature).map(x => [x.signature, x]));
		for (const row of (signatures || []).slice().reverse()) {
			if (row?.signature && row.err == null && !pending.has(row.signature)) pending.set(row.signature, { signature: row.signature, blockTime: row.blockTime ?? null });
		}
		const newest = (signatures || []).find(x => x?.signature)?.signature || state?.cursor || '';
		return { cursor: newest, pending: Array.from(pending.values()) };
	}

	function updateUpgradeAutomationLpPerProfileWatchCohort(state, processes, nowSeconds) {
		const profiles = {};
		for (const [profile, entry] of Object.entries(state?.profiles || {})) {
			if (profile && Number(entry?.expiresAt || 0) > nowSeconds) profiles[profile] = { ...entry, pending: Array.isArray(entry?.pending) ? entry.pending : [] };
		}
		const expiresAt = (Math.floor(nowSeconds / 86400) + 1) * 86400 + 7200;
		for (const row of (processes || [])) {
			if (!row?.profile || !row?.active || Number(row?.expectedCompletionsByEod || 0) <= 0) continue;
			const prior = profiles[row.profile];
			profiles[row.profile] = prior
				? { ...prior, expiresAt: Math.max(Number(prior.expiresAt || 0), expiresAt) }
				: { firstSeenAt: nowSeconds, expiresAt, cursor: '', pending: [] };
		}
		return { profiles };
	}

	function buildUpgradeAutomationLpPerProfileTransactionQueue(profiles, limit) {
		const entries = Object.entries(profiles || {}).map(([profile, entry]) => ({ profile, pending: Array.isArray(entry?.pending) ? entry.pending : [], index: 0 }));
		const queue = [];
		while (queue.length < Math.max(0, Number(limit || 0))) {
			let added = false;
			for (const entry of entries) {
				if (queue.length >= limit || entry.index >= entry.pending.length) continue;
				queue.push({ profile: entry.profile, item: entry.pending[entry.index++] });
				added = true;
			}
			if (!added) break;
		}
		return queue;
	}

	function extractUpgradeAutomationLpPerProfileRedemptions(tx, signature, isSubmitInstruction) {
		if (!tx || tx?.meta?.err || !Number.isFinite(Number(tx.blockTime))) return [];
		const message = tx?.transaction?.message || {};
		const loaded = tx?.meta?.loadedAddresses || { writable: [], readonly: [] };
		const keys = [...(message.accountKeys || message.staticAccountKeys || []), ...(loaded.writable || []), ...(loaded.readonly || [])].map(k => k?.pubkey?.toBase58?.() || k?.toBase58?.() || String(k));
		const instructions = message.instructions || message.compiledInstructions || [];
		const pre = new Map((tx.meta.preTokenBalances || []).map(x => [Number(x.accountIndex), BigInt(x?.uiTokenAmount?.amount || 0)]));
		const post = new Map((tx.meta.postTokenBalances || []).map(x => [Number(x.accountIndex), BigInt(x?.uiTokenAmount?.amount || 0)]));
		const out = [];
		for (let instructionIndex = 0; instructionIndex < instructions.length; instructionIndex++) {
			const ix = instructions[instructionIndex];
			const programId = keys[Number(ix.programIdIndex)];
			if (!isSubmitInstruction(ix.data, programId)) continue;
			const accounts = ix.accounts || ix.accountKeyIndexes || [];
			if (accounts.length < 17) continue;
			const tokenFromIndex = Number(accounts[12]);
			const quantity = (pre.get(tokenFromIndex) || 0n) - (post.get(tokenFromIndex) || 0n);
			if (quantity <= 0n || quantity > BigInt(Number.MAX_SAFE_INTEGER)) continue;
			out.push({ signature, instructionIndex, blockTime: Number(tx.blockTime), starbase: keys[Number(accounts[1])], profile: keys[Number(accounts[16])], craftingProcess: keys[Number(accounts[4])], resourceRecipe: keys[Number(accounts[8])], quantity: Number(quantity) });
		}
		return out;
	}

	function getUpgradeAutomationLpPerProfileHistoryCacheKey(faction) {
		return `slyaUpgradeLpPerProfileHistory_v3_${String(faction || '')}_${String(getSlyaInfluxInstanceTag() || '')}`;
	}

	async function loadUpgradeAutomationLpPerProfileHistory(faction) {
		const fallback = { profiles: {} };
		try {
			const parsed = JSON.parse(String(await GM.getValue(getUpgradeAutomationLpPerProfileHistoryCacheKey(faction), JSON.stringify(fallback))));
			return parsed && parsed.profiles && typeof parsed.profiles === 'object' ? parsed : fallback;
		} catch (e) {
			await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE] history cache invalid faction=${faction} err=${String(e?.message || e)}`);
			return fallback;
		}
	}

	async function saveUpgradeAutomationLpPerProfileHistory(faction, state) {
		await GM.setValue(getUpgradeAutomationLpPerProfileHistoryCacheKey(faction), JSON.stringify(state || { profiles: {} }));
	}

	function formatUpgradeAutomationLpPerProfileCompletedInfluxLine(rows, faction) {
		const lines = [];
		const factionTag = String(faction || '').replace(/"/g, '');
		const instanceTag = getSlyaInfluxInstanceTag();
		for (const row of (rows || [])) {
			if (!row?.profile || !row?.craftingProcess || !row?.component || !row?.signature || !Number.isFinite(Number(row.blockTime))) continue;
			const tags = `faction=${influxEscape(factionTag)},instance=${influxEscape(String(instanceTag))},profile=${influxEscape(row.profile)},component=${influxEscape(row.component)},process=${influxEscape(row.craftingProcess)},signature=${influxEscape(row.signature)},instruction=${Math.round(Number(row.instructionIndex || 0))},source=redeemed`;
			const fields = `lp=${Math.round(Number(row.lp || 0))},quantity=${Math.round(Number(row.quantity || 0))}i,lpPerUnit=${Math.round(Number(row.lpPerUnit || 0))}i`;
			lines.push(`lp_per_profile,${tags} ${fields} ${Math.floor(Number(row.blockTime) * 1000)}`);
		}
		return lines.join('\n');
	}

	async function recordUpgradeAutomationLpPerProfileCompletions(rows, faction) {
		const line = formatUpgradeAutomationLpPerProfileCompletedInfluxLine(rows, faction);
		if (!line) return { sent: true, rows: 0 };
		const count = line.split('\n').length;
		await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE] redeemed write start faction=${faction} rows=${count}`);
		const sent = await sendToInflux(line);
		if (sent !== true) await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE] redeemed write failed faction=${faction} rows=${count} detail=${String(upgradeAutomationInfluxDebugStatus || 'unknown').slice(0, 500)}`);
		return { sent: sent === true, rows: count };
	}

	async function recordUpgradeAutomationLpRedemptionTotal(faction, now) {
		try {
			const factionCfg = UPGRADE_AUTOMATION_FACTION_CONFIG[normalizeUpgradeAutomationLpInstance(faction)];
			if (!factionCfg?.lpInstance) return { sent: false, totalLp: null, error: 'lp_instance_missing' };
			const dayIndex = Math.floor(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) / 86400000);
			const row = (await fetchUpgradeAutomationEpochSeries(factionCfg.lpInstance)).find(item => Number(item.dayIndex) === dayIndex);
			const totalLp = Number(row?.totalPoints);
			if (!Number.isSafeInteger(totalLp) || totalLp < 0) return { sent: false, totalLp: null, error: 'current_epoch_total_missing' };
			const tags = `faction=${influxEscape(faction)},instance=${influxEscape(String(getSlyaInfluxInstanceTag()))},source=authoritative`;
			const line = `lp_redemption_total,${tags} totalLp=${totalLp}i ${Math.floor(now.getTime())}`;
			return { sent: await sendToInflux(line) === true, totalLp, error: '' };
		} catch (e) {
			return { sent: false, totalLp: null, error: String(e?.message || e || 'total_lp_failed') };
		}
	}

	async function runUpgradeAutomationLpPerProfileRedemptionHistory(faction, processes, now) {
		const nowSeconds = Math.floor(now.getTime() / 1000);
		let state = updateUpgradeAutomationLpPerProfileWatchCohort(await loadUpgradeAutomationLpPerProfileHistory(faction), processes, nowSeconds);
		let discoveredCount = 0;
		for (const [profile, entry] of Object.entries(state.profiles)) {
			const signatures = [];
			const options = { limit: 100 };
			if (entry.cursor) options.until = entry.cursor;
			const rows = await solanaReadConnection.getSignaturesForAddress(new solanaWeb3.PublicKey(profile), options, 'finalized');
			signatures.push(...rows.filter(row => !Number.isFinite(Number(row.blockTime)) || Number(row.blockTime) >= Number(entry.firstSeenAt || nowSeconds)));
			discoveredCount += signatures.length;
			state.profiles[profile] = { ...entry, ...mergeUpgradeAutomationLpPerProfileSignatureState(entry, signatures) };
		}
		await saveUpgradeAutomationLpPerProfileHistory(faction, state);
		const processedByProfile = new Map();
		const redeemed = [];
		const diagnostics = { queued: 0, fetched: 0, unavailable: 0, failedTx: 0, instructions: 0, wrongProgram: 0, decodeFailed: 0, wrongInstruction: 0, submitMatched: 0, noRedemptionRow: 0, profileMismatch: 0, beforeWatch: 0, recipeMissing: 0, accepted: 0 };
		const recipeByKey = new Map(upgradeRecipes.map(recipe => [recipe.publicKey.toBase58(), recipe]));
		const queue = buildUpgradeAutomationLpPerProfileTransactionQueue(state.profiles, 250);
		diagnostics.queued = queue.length;
		for (let offset = 0; offset < queue.length; offset += 8) {
			const batch = queue.slice(offset, offset + 8);
			const txs = await Promise.all(batch.map(({ item }) => solanaReadConnection.getTransaction(item.signature, { commitment: 'finalized', maxSupportedTransactionVersion: 0 }).catch(() => null)));
			for (let i = 0; i < batch.length; i++) {
				const { profile, item } = batch[i];
				const entry = state.profiles[profile];
				const tx = txs[i];
				if (!tx) { diagnostics.unavailable++; continue; }
				diagnostics.fetched++;
				if (tx.meta?.err) diagnostics.failedTx++;
				const message = tx?.transaction?.message || {};
				const loaded = tx?.meta?.loadedAddresses || { writable: [], readonly: [] };
				const keys = [...(message.accountKeys || message.staticAccountKeys || []), ...(loaded.writable || []), ...(loaded.readonly || [])].map(key => key?.pubkey?.toBase58?.() || key?.toBase58?.() || String(key));
				for (const ix of (message.instructions || message.compiledInstructions || [])) {
					diagnostics.instructions++;
					if (keys[Number(ix.programIdIndex)] !== sageProgram.programId.toBase58()) { diagnostics.wrongProgram++; continue; }
					let decoded;
					try { decoded = sageProgram.coder.instruction.decode(ix.data, typeof ix.data === 'string' ? 'base58' : undefined); } catch (_) {}
					if (!decoded?.name) diagnostics.decodeFailed++;
					else if (decoded.name === 'submitStarbaseUpgradeResource') diagnostics.submitMatched++;
					else diagnostics.wrongInstruction++;
				}
				const rows = extractUpgradeAutomationLpPerProfileRedemptions(tx, item.signature, (data, programId) => {
					if (String(programId) !== sageProgram.programId.toBase58()) return false;
					try { return sageProgram.coder.instruction.decode(data, typeof data === 'string' ? 'base58' : undefined)?.name === 'submitStarbaseUpgradeResource'; } catch (_) { return false; }
				});
				if (!rows.length && !tx.meta?.err) diagnostics.noRedemptionRow++;
				for (const row of rows) {
					if (row.profile !== profile) { diagnostics.profileMismatch++; continue; }
					if (Number(row.blockTime) < Number(entry.firstSeenAt || 0)) { diagnostics.beforeWatch++; continue; }
					const recipe = recipeByKey.get(row.resourceRecipe);
					const component = recipe ? getUpgradeAutomationUpgradeRecipeComponentName(recipe.name) : '';
					const lpPerUnit = Number(UPGRADE_AUTOMATION_COMPONENT_LP[component] || 0);
					if (!component || !lpPerUnit) { diagnostics.recipeMissing++; continue; }
					redeemed.push({ ...row, component, lpPerUnit, lp: lpPerUnit * row.quantity });
					diagnostics.accepted++;
				}
				if (!processedByProfile.has(profile)) processedByProfile.set(profile, new Set());
				processedByProfile.get(profile).add(item.signature);
			}
		}
		const result = await recordUpgradeAutomationLpPerProfileCompletions(redeemed, faction);
		if (result.sent) {
			for (const [profile, processed] of processedByProfile) state.profiles[profile].pending = state.profiles[profile].pending.filter(row => !processed.has(row.signature));
			await saveUpgradeAutomationLpPerProfileHistory(faction, state);
		}
		const backlog = Object.values(state.profiles).reduce((sum, entry) => sum + entry.pending.length, 0);
		const processed = Array.from(processedByProfile.values()).reduce((sum, set) => sum + set.size, 0);
		await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE][HISTORY-DIAG] faction=${faction} ${Object.entries(diagnostics).map(([key, value]) => `${key}=${value}`).join(' ')}`);
		return { discovered: discoveredCount, processed, rows: result.rows, backlog, profiles: Object.keys(state.profiles).length };
	}

	function formatUpgradeAutomationLpPerProfileInfluxLine(aggregated, faction, now) {
		const lines = [];
		const factionTag = String(faction || '').replace(/"/g, '');
		const instanceTag = getSlyaInfluxInstanceTag();
		// The configured Influx write endpoint uses precision=ms, so line-protocol
		// timestamps must be milliseconds. Supplying nanoseconds here makes Influx
		// multiply the value again and reject the entire batch as an overflow.
		const ts = Math.floor(now.getTime());
		for (const profile of Object.keys(aggregated || {})) {
			for (const component of Object.keys(aggregated[profile] || {})) {
				const slot = aggregated[profile][component];
				if (!slot?.processCount) continue;
				const tags = `faction=${influxEscape(factionTag)},instance=${influxEscape(String(instanceTag))},profile=${influxEscape(profile)},component=${influxEscape(component)},source=active`;
				const fields = `lp=${Math.round(slot.lp)},quantity=${Math.round(slot.quantity)}i,processCount=${Math.round(slot.processCount)}i,lpPerUnit=${Math.round(slot.lpPerUnit)}i,lpByEod=${Math.round(slot.lpByEod)},quantityByEod=${Math.round(slot.quantityByEod)}i,durationSeconds=${Math.round(slot.durationSeconds)}i,inFlightCompletionsByEod=${Math.round(slot.inFlightCompletionsByEod)}i,expectedCompletionsByEod=${Math.round(slot.expectedCompletionsByEod)}i,expectedLpByEod=${Math.round(slot.expectedLpByEod)},repeatLpByEod=${Math.round(slot.repeatLpByEod)},expectedQuantityByEod=${Math.round(slot.expectedQuantityByEod)}i`;
				lines.push(`lp_per_profile,${tags} ${fields} ${ts}`);
			}
		}
		return lines.join('\n');
	}

	async function sendUpgradeAutomationLpPerProfileToInflux(aggregated, faction, now) {
		const line = formatUpgradeAutomationLpPerProfileInfluxLine(aggregated, faction, now);
		if (!line) return { sent: false, rows: 0 };
		const rows = line.split('\n').length;
		const sample = line.split('\n', 1)[0].slice(0, 500);
		await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE] write start faction=${faction} rows=${rows} bytes=${line.length} sample=${sample}`);
		const sent = await sendToInflux(line);
		if (sent !== true) {
			await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE] write failed faction=${faction} rows=${rows} detail=${String(upgradeAutomationInfluxDebugStatus || 'unknown').slice(0, 500)}`);
		}
		return { sent: sent === true, rows };
	}

	function formatUpgradeAutomationLpProcessHistoryInfluxLine(processes, faction, now, instanceOverride) {
		const lines = [];
		const factionTag = String(faction || '').replaceAll('"', '');
		const instanceTag = instanceOverride == null ? getSlyaInfluxInstanceTag() : instanceOverride;
		const ts = Math.floor(now.getTime());
		for (const row of (processes || [])) {
			if (!row?.profile || !row?.craftingProcess || !row?.starbase || !row?.component || !row?.recipeKey) continue;
			const tags = `faction=${influxEscape(factionTag)},instance=${influxEscape(String(instanceTag))},profile=${influxEscape(row.profile)},process=${influxEscape(row.craftingProcess)},starbase=${influxEscape(row.starbase)},component=${influxEscape(row.component)},recipe=${influxEscape(String(row.recipe || ''))},recipeKey=${influxEscape(row.recipeKey)},restartDelaySource=${influxEscape(String(row.restartDelaySource || 'default_fallback'))}`;
			const fields = `quantity=${Math.round(Number(row.quantity || 0))}i,lp=${Math.round(Number(row.lp || 0))},lpPerUnit=${Math.round(Number(row.lpPerUnit || 0))}i,startTime=${Math.round(Number(row.startTime || 0))}i,endTime=${Math.round(Number(row.endTime || 0))}i,durationSeconds=${Math.round(Number(row.durationSeconds || 0))}i,remainingSeconds=${Math.round(Number(row.remainingSeconds || 0))}i,pendingInstallation=${row.pendingInstallation === true},restartDelaySeconds=${Math.max(0, Math.round(Number(row.restartDelaySeconds || 0)))}i,restartGapSamples=${Math.max(0, Math.round(Number(row.restartGapSamples || 0)))}i,evidenceWindowDays=${Math.max(0, Math.round(Number(row.evidenceWindowDays || 7)))}i`;
			lines.push(`lp_upgrade_process_history,${tags} ${fields} ${ts}`);
		}
		return lines.join('\n');
	}

	async function sendUpgradeAutomationLpProcessHistoryToInflux(processes, faction, now) {
		const line = formatUpgradeAutomationLpProcessHistoryInfluxLine(processes, faction, now);
		if (!line) return { sent: true, rows: 0 };
		const rows = line.split('\n').length;
		const sent = await sendToInflux(line);
		if (sent !== true) await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PROCESS-HISTORY] write failed faction=${faction} rows=${rows} detail=${String(upgradeAutomationInfluxDebugStatus || 'unknown').slice(0, 500)}`);
		return { sent: sent === true, rows };
	}

	let lastUpgradeAutomationLpPerProfileCycleMs = 0;
	let upgradeAutomationLpPerProfileCycleInFlight = false;

	async function runUpgradeAutomationLpPerProfileCycle(now = new Date()) {
		if (!globalSettings.upgradeAutomationInfluxTracking) {
			await appendUpgradeAutomationLog('[UPGRADE-AUTO][LP-PER-PROFILE] skip: InfluxDB Performance Tracking disabled');
			return;
		}
		if (upgradeAutomationLpPerProfileCycleInFlight || now.getTime() - lastUpgradeAutomationLpPerProfileCycleMs < UPGRADE_AUTOMATION_LP_PER_PROFILE_CYCLE_MIN_MS) return;
		upgradeAutomationLpPerProfileCycleInFlight = true;
		lastUpgradeAutomationLpPerProfileCycleMs = now.getTime();
		try {
			if (!sageProgram?.account?.starbasePlayer || !sageProgram?.account?.craftingInstance || !craftingProgram?.account?.craftingProcess || !Array.isArray(upgradeRecipes) || !upgradeRecipes.length) {
				await appendUpgradeAutomationLog('[UPGRADE-AUTO][LP-PER-PROFILE] skip: chain programs or upgrade recipes not ready');
				return;
			}
			const factions = getUpgradeAutomationLpPerProfileFactions();
			if (!factions.length) {
				await appendUpgradeAutomationLog('[UPGRADE-AUTO][LP-PER-PROFILE] skip: no faction configuration for this instance');
				return;
			}
			// Fetch each account type once per cycle. Filtering 1,788 decoded accounts
			// in memory is substantially cheaper than issuing one RPC query for every
			// StarbasePlayer (192 at MUD Phantom in the validation probe).
			const accountSnapshot = await fetchUpgradeAutomationLpPerProfileAccountSnapshot();
			for (const { faction, starbaseCoords } of factions) {
				const allProcesses = [];
				let scansOk = true;
				for (const coords of starbaseCoords) {
					const rows = await getUpgradeAutomationLpPerProfileProcessesForStarbase(coords, now, accountSnapshot);
					if (rows.scanOk !== true) scansOk = false;
					allProcesses.push(...rows);
				}
				const restartHistory = await fetchUpgradeAutomationRestartHistory(faction, now);
				applyUpgradeAutomationRestartDelays(allProcesses, restartHistory);
				const aggregated = aggregateUpgradeAutomationLpPerProfile(allProcesses);
				upgradeAutomationUninstalledLp = summarizeUpgradeAutomationUninstalledLp(allProcesses);
				const result = await sendUpgradeAutomationLpPerProfileToInflux(aggregated, faction, now);
				const processHistory = await sendUpgradeAutomationLpProcessHistoryToInflux(allProcesses, faction, now);
				const history = await runUpgradeAutomationLpPerProfileRedemptionHistory(faction, allProcesses, now);
				const total = await recordUpgradeAutomationLpRedemptionTotal(faction, now);
				await appendUpgradeAutomationLog(`[UPGRADE-AUTO][LP-PER-PROFILE] faction=${faction} profiles=${Object.keys(aggregated).length} processes=${allProcesses.length} rows=${result.rows} sent=${result.sent} processHistoryRows=${processHistory.rows} processHistorySent=${processHistory.sent} redeemedRows=${history.rows} watchedProfiles=${history.profiles} historyProcessed=${history.processed} historyBacklog=${history.backlog} totalLp=${total.totalLp ?? 'missing'} totalSent=${total.sent} totalErr=${total.error || 'none'}`);
			}
		} finally {
			upgradeAutomationLpPerProfileCycleInFlight = false;
		}
	}

	async function reconcileUpgradeAutomationLpProcesses(settings = {}, reason = 'scheduler') {
		const managedCraftLabels = getUpgradeAutomationManagedCraftLabels(settings);
		const attachedLabels = new Set();
		const slotSnapshot = new Map();
		const result = {
			ok: false,
			reason,
			attachedLabels: [],
			bound: [],
			alreadyAssigned: [],
			unbound: [],
			activeCount: 0,
			completedCount: 0,
			cleared: [],
			error: ''
		};

		try {
			for (const craftLabel of managedCraftLabels) {
				slotSnapshot.set(craftLabel, await getUpgradeAutomationCraftSlotState(craftLabel));
			}
			const context = await getUpgradeAutomationLpStarbaseContext(settings);
			if (context?.error) {
				result.error = context.error;
				await logUpgradeAutomationSchedulerEvent('LP reconcile skipped', { reason, error: context.error, coords: context.coords || '' });
				return result;
			}

			const processes = await getUpgradeAutomationLpUpgradeProcesses(context, settings);
			const onChainIds = new Set(processes.map(process => String(process.craftingId || '')).filter(Boolean));
			result.activeCount = processes.filter(process => !process.completed).length;
			result.completedCount = processes.filter(process => process.completed).length;

			for (const process of processes) {
				const craftLabel = await findUpgradeAutomationSlotForProcess(process, managedCraftLabels, settings);
				if (!craftLabel) {
					result.unbound.push({ craftingId: process.craftingId, component: process.component, recipe: process.recipeName, completed: process.completed });
					continue;
				}

				attachedLabels.add(craftLabel);
				if (process.assignedLabel === craftLabel) {
					result.alreadyAssigned.push({ craftLabel, craftingId: process.craftingId, component: process.component, completed: process.completed });
					continue;
				}

				const existing = await getUpgradeAutomationCraftSlotState(craftLabel);
				const restoredSlot = {
					...(existing || {}),
					label: craftLabel,
					item: process.recipeName,
					coordinates: context.coords,
					craftingCoords: context.coords,
					craftingId: process.craftingId,
					state: formatUpgradeAutomationRecoveredUpgradeState(process, context),
					lpAutomationManaged: true,
					lpAutomationRecoveredAt: new Date().toISOString(),
					lpAutomationRecoveredReason: reason,
					lpAutomationRecoveredComponent: process.component
				};
				await saveCraftConfig(craftLabel, restoredSlot, 'lp-auto-reconcile-bind');
				recoveredCraftingProcessSlots.set(String(process.craftingId), craftLabel);
				result.bound.push({ craftLabel, craftingId: process.craftingId, component: process.component, completed: process.completed });
			}

			// Runtime equivalent of startCraft's process_not_found recovery. Compare
			// against the pre-query snapshot as well as the current value so a process
			// created concurrently with reconciliation is never cleared.
			for (const craftLabel of managedCraftLabels) {
				const snapshotSlot = slotSnapshot.get(craftLabel) || {};
				const currentSlot = await getUpgradeAutomationCraftSlotState(craftLabel);
				if (!shouldClearMissingUpgradeAutomationProcess(snapshotSlot, currentSlot, onChainIds)) continue;
				const missingCraftingId = currentSlot.craftingId;
				await saveCraftConfig(craftLabel, {
					...currentSlot,
					craftingId: 0,
					state: 'Idle',
					errorCount: 0,
					lpAutomationRecoveredAt: new Date().toISOString(),
					lpAutomationRecoveredReason: 'process_not_found_runtime'
				}, 'lp-auto-reconcile-clear-missing');
				recoveredCraftingProcessSlots.delete(String(missingCraftingId));
				result.cleared.push({ craftLabel, craftingId: missingCraftingId, reason: 'process_not_found' });
			}

			result.ok = true;
			result.attachedLabels = Array.from(attachedLabels);
			await logUpgradeAutomationSchedulerEvent('LP reconcile complete', {
				reason,
				activeCount: result.activeCount,
				completedCount: result.completedCount,
				attachedLabels: result.attachedLabels,
				bound: result.bound,
				cleared: result.cleared,
				unbound: result.unbound
			});
			return result;
		} catch (error) {
			result.error = String(error?.message || error || 'unknown_error');
			await logUpgradeAutomationSchedulerEvent('LP reconcile error', { reason, error: result.error });
			return result;
		}
	}

	// Scheduler write pass persists optimizer ownership: component + crew only.
	// Upgrade amounts are calculated just-in-time immediately before Upgrade Starting.
	// At xx:55: capture optimizer output -> stored in persisted pending plan
	// At xx:56: refresh the pending plan
	// At xx:57: write captured rows to config slots using the stored schedule
	// At xx:58: verify/retry the persisted write
	// This function is called by the 15s interval with the captured planRows and schedule.
	async function applyUpgradeAutomationExecutionToCraftConfig(planRows, schedule, settings = {}, now = new Date()) {
		const cycleStamp = getUpgradeAutomationCycleStamp(now, settings);
		const managedCraftLabels = getUpgradeAutomationManagedCraftLabels(settings);
		const completion = await detectUpgradeAutomationCompletionEvent(settings, now);
		const reconciliation = await reconcileUpgradeAutomationLpProcesses(settings, 'write-' + now.getUTCMinutes());
		const planRowsArr = Array.isArray(planRows) ? planRows : [];
		const scheduledCraftLabels = new Set();
		const targetFinishAtUtc = String(schedule?.targetFinishAtUtc || '');
		const writeSlotState = async (craftLabel, row, existing, crew) => {
			const fixedCraftConfig = getUpgradeAutomationFixedCraftConfigForLabel(craftLabel, settings) || {};
			await saveCraftConfig(craftLabel, {
				...(existing || {}),
				coordinates: String(row?.coordinates || fixedCraftConfig.coordinates || existing?.coordinates || ''),
				item: String(row?.craftItem || fixedCraftConfig.item || existing?.item || ''),
				amount: 0,
				crew,
				lpAutomationManaged: true,
				lpAutomationUpdatedAt: now.toISOString(),
				lpAutomationCycleStamp: cycleStamp,
				lpAutomationSecondsPerUnit: Math.max(1, Number(row?.secondsPerUnit || 1)),
				lpAutomationUpgradingHour: Math.max(0, Math.floor(Number(row?.finalUpgradingHour || row?.upgradingHour || 0))),
				lpAutomationTargetFinishAtUtc: String(row?.nextXx59Utc || targetFinishAtUtc || ''),
				lpAutomationPreviewAmount: Math.max(0, Math.floor(Number(row?.nextAmount || 0))),
				lpAutomationPreviewRuntime: Math.max(0, Math.floor(Number(row?.nextRuntime || 0))),
				lpAutomationAmountSetAt: '',
				// Remove the superseded v131 baseline/scaling state.
				lpAutomationPlannedAmount: undefined,
				lpAutomationPlannedRuntime: undefined,
				lpAutomationAmountAdjustedAt: undefined,
				lpAutomationAmountAdjustmentRatio: undefined,
				lpAutomationRemainingRuntime: undefined
			}, 'lp-auto-slot-crew-write');
		};

		// Write optimizer-selected crew. Amount remains zero until the slot is
		// actually ready to start, so delayed completions cannot launch stale work.
		for (const row of planRowsArr) {
			const craftLabel = String(row.craftLabel || '');
			if (!craftLabel) continue;
			scheduledCraftLabels.add(craftLabel);
			const existing = await getUpgradeAutomationCraftSlotState(craftLabel);
			const crew = Math.max(0, Math.floor(Number(row.nextCrew || 0)));
			const writtenUph = Math.max(0, Math.floor(Number(row.finalUpgradingHour || row.upgradingHour || 0)));
			row.writtenAmount = 0;
			row.writtenCrew = crew;
			row.writtenUph = writtenUph;
			row.writtenAtUtc = now.toISOString();
			await writeSlotState(craftLabel, row, existing, crew);
			let readBack = await getUpgradeAutomationCraftSlotState(craftLabel);
			const actualAmount = Math.max(0, Math.floor(Number(readBack?.amount || 0)));
			const missingCrew = crew > 0 && Math.max(0, Math.floor(Number(readBack?.crew || 0))) <= 0;
			if (actualAmount !== 0 || missingCrew) {
				console.log('[Scheduler][RetryWrite]', craftLabel, 'reason=', [actualAmount !== 0 ? 'stale_amount' : '', missingCrew ? 'missing_crew' : ''].filter(Boolean).join('+'), 'expectedAmount=0', 'expectedCrew=', crew, 'actualAmount=', actualAmount, 'actualCrew=', Math.floor(Number(readBack?.crew || 0)));
				await writeSlotState(craftLabel, row, readBack || existing, crew);
				readBack = await getUpgradeAutomationCraftSlotState(craftLabel);
			}
			console.log('[Scheduler] WROTE CREW', craftLabel, 'amount=0', 'crew=', crew, 'uph=', writtenUph, 'previewAmount=', Number(row.nextAmount || 0), 'previewRuntime=', Number(row.nextRuntime || 0), 'readBackAmount=', Math.floor(Number(readBack?.amount || 0)), 'readBackCrew=', Math.floor(Number(readBack?.crew || 0)));
		}

		// Viktor: Clear unscheduled slots - reassert fixed item/coordinates and zero amount/crew
		for (const craftLabel of managedCraftLabels) {
			if (scheduledCraftLabels.has(craftLabel)) continue;
			const existing = await getUpgradeAutomationCraftSlotState(craftLabel);
			const fixedCraftConfig = getUpgradeAutomationFixedCraftConfigForLabel(craftLabel, settings) || {};
			await saveCraftConfig(craftLabel, {
				...(existing || {}),
				coordinates: String(fixedCraftConfig.coordinates || existing?.coordinates || ''),
				item: String(fixedCraftConfig.item || existing?.item || ''),
				amount: 0,
				crew: 0,
				lpAutomationManaged: false,
				lpAutomationUpdatedAt: now.toISOString(),
				lpAutomationCycleStamp: cycleStamp
			}, 'lp-auto-slot-clear');
		}

		upgradeAutomationSchedulerDebug = JSON.stringify({
			now: now.toISOString(),
			cycleStamp,
			reason: 'simple_timed_write',
			status: 'simple_timed_write',
			targetFinishAtUtc,
			pendingRowCount: planRowsArr.length,
			readiness: {
				enabled: !!schedule?.enabled,
				ready: !!schedule?.ready,
				hasUpgrade: !!schedule?.hasUpgrade,
				hasCraft: !!schedule?.hasCraft,
				hasUserProfile: !!schedule?.hasUserProfile,
				hasFleets: !!schedule?.hasFleets
			},
			completion,
			reconciliation
		});

		return { wrote: true, reason: 'simple_timed_write', schedule, completion, reconciliation };
	}

	function getUpgradeAutomationCappedStartAmount(plannedAmount, availableInventory) {
		return Math.min(
			Math.max(0, Math.floor(Number(plannedAmount || 0))),
			Math.max(0, Math.floor(Number(availableInventory || 0)))
		);
	}

	function getUpgradeAutomationCargoAmountByMint(cargoHolds, componentMint) {
		const mint = String(componentMint || '');
		if(!mint) return 0;
		let total = 0;
		for(const cargoHold of (cargoHolds || [])) {
			const tokens = Array.isArray(cargoHold?.cargoHoldTokens) ? cargoHold.cargoHoldTokens : [cargoHold];
			for(const token of tokens) {
				const tokenMint = token?.tokenAcct?.account?.mint?.toString?.() || token?.mint?.toString?.() || '';
				if(String(tokenMint) !== mint) continue;
				const amount = Number(token?.tokenAcct?.account?.amount || token?.amount || 0);
				if(Number.isFinite(amount)) total += amount;
			}
		}
		return Math.max(0, total);
	}

	async function getUpgradeAutomationFreshInventoryForStart(slot) {
		const coordinates = String(slot?.coordinates || '').trim();
		const component = String(slot?.item || '').trim();
		const coordParts = coordinates.split(',').map(value => Number.parseInt(String(value).trim(), 10));
		if(coordParts.length !== 2 || !coordParts.every(Number.isFinite) || !component) throw new Error('invalid_upgrade_start_inventory_context');
		const starbase = await getStarbaseFromCoords(coordParts[0], coordParts[1], true);
		if(!starbase?.publicKey || !userProfileAcct) throw new Error('upgrade_start_starbase_unavailable');
		const starbasePlayer = await getStarbasePlayer(userProfileAcct, starbase.publicKey);
		if(!starbasePlayer?.publicKey) throw new Error('upgrade_start_starbase_player_unavailable');
		const cargo = await getStarbasePlayerCargoHolds(starbasePlayer.publicKey);
		const recipe = upgradeRecipes.find(item => String(item?.name || '') === component);
		const componentMint = recipe?.input?.[0]?.mint?.toString?.() || String(recipe?.input?.[0]?.mint || '');
		if(!componentMint) throw new Error('upgrade_start_component_mint_unavailable');
		return Math.max(0, Math.floor(getUpgradeAutomationCargoAmountByMint(cargo, componentMint)));
	}

	async function prepareUpgradeAutomationAmountForStart(userCraft, now = new Date()) {
		const craftLabel = String(userCraft?.label || '');
		if(!craftLabel) return userCraft;
		let slot = await getUpgradeAutomationCraftSlotState(craftLabel);
		if(String(slot?.state || '') !== 'Idle') return slot;

		// Recover LP ownership after stale/default state has stripped the marker.
		// Adoption is deliberately narrow: automation must be enabled and the slot,
		// fixed component, and phantom coordinates must all match this instance.
		if(!slot?.lpAutomationManaged) {
			const fixedCraftConfig = globalSettings.upgradeAutomationEnabled
				? getUpgradeAutomationFixedCraftConfigForLabel(craftLabel, globalSettings)
				: null;
			const matchesFixedConfig = !!fixedCraftConfig
				&& String(slot?.item || '') === String(fixedCraftConfig.item || '')
				&& String(slot?.coordinates || '') === String(fixedCraftConfig.coordinates || '');
			if(!matchesFixedConfig) return slot;
			slot = {
				...slot,
				lpAutomationManaged: true,
				lpAutomationUpdatedAt: now.toISOString()
			};
			await saveCraftConfig(craftLabel, slot, 'lp-auto-slot-adopt-before-start');
			await logUpgradeAutomationSchedulerEvent('Adopted fixed LP upgrade slot before start', {
				craftLabel,
				item: slot.item,
				coordinates: slot.coordinates,
				adoptedAtUtc: now.toISOString()
			});
		}

		const crew = Math.max(0, Math.floor(Number(slot.crew || 0)));
		if(crew <= 0 || !slot.item || !slot.coordinates) return slot;

		const recipe = upgradeRecipes.find(item => item.name === slot.item);
		const secondsPerUnit = Math.max(1, Number(slot.lpAutomationSecondsPerUnit || recipe?.duration || 1));
		let targetFinishMs = Date.parse(String(slot.lpAutomationTargetFinishAtUtc || ''));
		const nowMs = now.getTime();
		if(!Number.isFinite(targetFinishMs) || targetFinishMs <= nowMs + UPGRADE_AUTOMATION_LANDING_BUFFER_SECONDS * 1000) {
			targetFinishMs = getUpgradeAutomationNextTargetWindow(now, globalSettings).targetFinishAt.getTime();
		}
		const runtime = Math.max(0, Math.floor((targetFinishMs - nowMs - UPGRADE_AUTOMATION_LANDING_BUFFER_SECONDS * 1000) / 1000));
		const plannedAmount = Math.max(0, Math.floor((crew * runtime) / secondsPerUnit));
		let availableInventory;
		try {
			availableInventory = await getUpgradeAutomationFreshInventoryForStart(slot);
		} catch(error) {
			await logUpgradeAutomationSchedulerEvent('JIT inventory refresh failed; start skipped', {
				craftLabel,
				item: slot.item,
				coordinates: slot.coordinates,
				error: String(error?.message || error || 'unknown_error')
			});
			return slot;
		}
		const amount = getUpgradeAutomationCappedStartAmount(plannedAmount, availableInventory);
		if(amount <= 0) {
			await logUpgradeAutomationSchedulerEvent('JIT start skipped: starbase inventory empty', {
				craftLabel,
				item: slot.item,
				coordinates: slot.coordinates,
				plannedAmount,
				availableInventory
			});
			return slot;
		}
		const prepared = {
			...slot,
			amount,
			lpAutomationSecondsPerUnit: secondsPerUnit,
			lpAutomationUpgradingHour: Math.max(0, Math.floor(crew * 3600 / secondsPerUnit)),
			lpAutomationTargetFinishAtUtc: new Date(targetFinishMs).toISOString(),
			lpAutomationLaunchRuntime: runtime,
			lpAutomationAmountSetAt: now.toISOString()
		};
		await saveCraftConfig(craftLabel, prepared, 'lp-auto-jit-amount-before-start');
		const readBack = await getUpgradeAutomationCraftSlotState(craftLabel);
		const persistedAmount = Math.max(0, Math.floor(Number(readBack?.amount || 0)));
		await logUpgradeAutomationSchedulerEvent('Prepared JIT upgrade amount', {
			craftLabel,
			crew,
			secondsPerUnit,
			runtime,
			plannedAmount,
			availableInventory,
			amount,
			persistedAmount,
			targetFinishAtUtc: prepared.lpAutomationTargetFinishAtUtc,
			preparedAtUtc: now.toISOString()
		});
		if(persistedAmount !== amount) {
			await logUpgradeAutomationSchedulerEvent('JIT upgrade amount read-back mismatch', { craftLabel, amount, persistedAmount });
			return { ...readBack, amount: 0 };
		}
		return readBack;
	}

	function getUpgradeAutomationPlanningHorizon(now = new Date()) {
		const remainingHoursExact = Math.max(0, (Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1, 0, 0, 0, 0) - now.getTime()) / 3600000);
		const remainingHoursFloor = Math.floor(remainingHoursExact);
		const rolloverToNextUtcDay = now.getUTCHours() >= 23 || remainingHoursFloor <= 0;
		return {
			remainingHoursExact,
			remainingHoursFloor,
			planningHours: rolloverToNextUtcDay ? 24 : remainingHoursFloor,
			rolloverToNextUtcDay
		};
	}

	function computeUpgradeAutomationNeutralPlan(crewTotal, installedTodayByComponent = {}, now = new Date(), specialRiskControl = null, options = {}) {
		const totalCrew = Math.max(0, Math.floor(Number(crewTotal || 0)));
		const blockSpecialNeutral = options.blockSpecialNeutral !== false;
		const minCrewThreshold = totalCrew * 0.01;
		const planning = getUpgradeAutomationPlanningHorizon(now);
		const remainingHours = planning.planningHours;
		const secondsInRemainingHours = remainingHours * 3600;
		const riskControl = specialRiskControl || computeUpgradeAutomationSpecialRiskControl(null, now);
		const rows = [];
		for (const rawName of UPGRADE_AUTOMATION_NEUTRAL_COMPONENT_ORDER) {
			const canonicalName = rawName;
			const inventoryPhantom = getUpgradeAutomationComponentValue(upgradeAutomationInfluxInventory, canonicalName);
			const inventoryGlobal = getUpgradeAutomationComponentValue(upgradeAutomationInfluxInventoryGlobal, canonicalName);
			const craft24h = getUpgradeAutomationComponentValue(upgradeAutomationInfluxCraft24h, canonicalName);
			const upgrade24h = getUpgradeAutomationComponentValue(upgradeAutomationInfluxUpgrade24h, canonicalName);
			const observedDrain = getUpgradeAutomationComponentValue(upgradeAutomationInfluxInventoryGlobalWeightedDrain, canonicalName);
			const installedToday = Math.floor(Number(installedTodayByComponent[canonicalName] || (canonicalName === 'Survey Data Unit' ? installedTodayByComponent['SDU'] : 0) || 0));
			const secondsPerUnit = Number(UPGRADE_AUTOMATION_NEUTRAL_COMPONENT_SECONDS[canonicalName] || (canonicalName === 'Survey Data Unit' ? UPGRADE_AUTOMATION_NEUTRAL_COMPONENT_SECONDS['SDU'] : 0) || 0);
			const neutralTarget24h = inventoryGlobal / 10 + craft24h;
			const neutralTargetRemaining = Math.max(0, neutralTarget24h - installedToday);
			const deficit24h = upgrade24h - craft24h;
			const effectiveDrain24h = getUpgradeAutomationEffectiveDrain(deficit24h, observedDrain);
			const bufferDaysGlobal = effectiveDrain24h > 0 ? (inventoryGlobal / effectiveDrain24h) : null;
			const avgCrewNeeded = secondsPerUnit > 0 ? (neutralTargetRemaining * secondsPerUnit) / Math.max(1, secondsInRemainingHours) : 0;
			// Keep this aligned with formatUpgradeAutomationInfluxRows: Buffer Days Phantom = inventory / upgrading 24h.
			const bufferDaysPhantom = upgrade24h > 0 ? (inventoryPhantom / upgrade24h) : (inventoryPhantom > 0 ? Number.POSITIVE_INFINITY : null);
			const phantomInventoryBlocked = inventoryPhantom <= 0;
			const phantomLowBuffer = bufferDaysPhantom !== null && Number(bufferDaysPhantom) < 0.5;
			const phantomUpgradeEligible = !phantomInventoryBlocked;
			const specialRiskControlled = !!riskControl?.enabled && isUpgradeAutomationNeutralSpecialBlockedComponent(canonicalName);
			const specialRiskMultiplier = specialRiskControlled ? Math.max(0, Number(riskControl.multiplier || 0)) : 1;
			const specialMaxCrew = specialRiskControlled ? Math.min(totalCrew, Math.max(0, Math.floor(totalCrew * specialRiskMultiplier))) : Number.POSITIVE_INFINITY;
			const specialRiskBlocked = specialRiskControlled && specialMaxCrew <= 0;
			const neutralPhaseBlocked = blockSpecialNeutral && isUpgradeAutomationNeutralSpecialBlockedComponent(canonicalName);
			rows.push({
				key: canonicalName,
				name: canonicalName,
				displayName: canonicalName,
				installedToday,
				inventoryPhantom,
				inventoryGlobal,
				craft24h,
				observedDrain,
				secondsPerUnit,
				neutralTarget24h,
				neutralTargetRemaining,
				avgCrewNeeded,
				bufferDaysGlobal,
				phantomInventoryBlocked,
				phantomLowBuffer,
				phantomUpgradeEligible,
				neutralPhaseBlocked,
				targetPhaseBlocked: specialRiskBlocked,
				specialRiskControlled,
				specialRiskBlocked,
				specialRiskMultiplier,
				specialRiskMaxCrew: specialMaxCrew,
				specialRiskReason: specialRiskControlled ? String(riskControl.reason || '') : '',
				lpPerUnit: 0,
				lpPerSecond: 0,
				crew: 0,
				neutralUpgradingDay: 0,
				neutralUpgradingHour: 0,
				neutralLpTarget: 0,
				neutralBufferDays: null,
				finalCrew: 0,
				finalUpgradingHour: 0,
				finalUpgradingDay: 0,
				finalLpTarget: 0,
				finalBufferDays: null
			});
		}
		const activeRows = rows.filter(row => row.secondsPerUnit > 0 && row.phantomUpgradeEligible && !row.neutralPhaseBlocked && Number(row.inventoryGlobal || 0) > 0);
		const projectNeutralBufferDays = (row, crew) => {
			const projectedCrew = Math.max(0, Math.floor(Number(crew || 0)));
			const projectedNeutralUpgradingDay = projectedCrew > 0
				? Math.floor(row.installedToday + (projectedCrew * secondsInRemainingHours) / row.secondsPerUnit)
				: Math.floor(row.installedToday || 0);
			const projectedNeutralDeficitDay = projectedNeutralUpgradingDay - row.craft24h;
			const projectedNeutralEffectiveDrain = getUpgradeAutomationEffectiveDrain(projectedNeutralDeficitDay, row.observedDrain);
			if (projectedNeutralEffectiveDrain > 0) return row.inventoryGlobal / projectedNeutralEffectiveDrain;
			if (Number(row.inventoryGlobal || 0) > 0) return Number.POSITIVE_INFINITY;
			return null;
		};
		const isProjectedNeutralCrewAllowed = (row, crew) => {
			if (!row || !row.phantomUpgradeEligible || Number(row.inventoryPhantom || 0) <= 0 || Number(row.inventoryGlobal || 0) <= 0) return false;
			if (Number.isFinite(Number(row.specialRiskMaxCrew)) && Math.max(0, Math.floor(Number(crew || 0))) > Number(row.specialRiskMaxCrew)) return false;
			if (row.specialRiskControlled && Number.isFinite(Number(row.specialRiskMaxCrew))) {
				const projectedSpecialCrew = rows.reduce((sum, candidate) => {
					if (!candidate.specialRiskControlled) return sum;
					return sum + (candidate === row ? Math.max(0, Math.floor(Number(crew || 0))) : Math.max(0, Math.floor(Number(candidate.crew || 0))));
				}, 0);
				if (projectedSpecialCrew > Number(row.specialRiskMaxCrew)) return false;
			}
			return true;
		};
		if (activeRows.length && totalCrew > 0) {
			for (const row of activeRows) row.crew = 0;
			let usedCrew = 0;
			const isCurrentInfinity = row => {
				const currentNeutralUpgradingDay = Number(row.crew || 0) > 0
					? Math.floor(row.installedToday + (Number(row.crew || 0) * secondsInRemainingHours) / row.secondsPerUnit)
					: Math.floor(row.installedToday || 0);
				const currentNeutralDeficitDay = currentNeutralUpgradingDay - Number(row.craft24h || 0);
				return Number(row.inventoryGlobal || 0) > 0 && getUpgradeAutomationEffectiveDrain(currentNeutralDeficitDay, row.observedDrain) <= 0;
			};
			const neutralCrewStep = row => Number(row.crew || 0) === 0 ? UPGRADE_AUTOMATION_MIN_JOB_CREW : 1;
			for (const row of activeRows) {
				while (usedCrew < totalCrew && isCurrentInfinity(row)) {
					const crewStep = neutralCrewStep(row);
					const projectedCrew = Number(row.crew || 0) + crewStep;
					if (usedCrew + crewStep > totalCrew || !isProjectedNeutralCrewAllowed(row, projectedCrew)) break;
					row.crew += crewStep;
					usedCrew += crewStep;
				}
			}
			while (usedCrew < totalCrew) {
				const eligibleRows = activeRows.filter(row => {
					const crewStep = neutralCrewStep(row);
					return usedCrew + crewStep <= totalCrew && isProjectedNeutralCrewAllowed(row, Number(row.crew || 0) + crewStep);
				});
				if (!eligibleRows.length) break;
				const best = eligibleRows.sort((a, b) => {
					const aProjectedCrew = Number(a.crew || 0) + neutralCrewStep(a);
					const bProjectedCrew = Number(b.crew || 0) + neutralCrewStep(b);
					const aProjected = projectNeutralBufferDays(a, aProjectedCrew);
					const bProjected = projectNeutralBufferDays(b, bProjectedCrew);
					const aScore = Number.isFinite(Number(aProjected)) ? Number(aProjected) : Number.POSITIVE_INFINITY;
					const bScore = Number.isFinite(Number(bProjected)) ? Number(bProjected) : Number.POSITIVE_INFINITY;
					if (aScore !== bScore) return bScore - aScore;
					const aNeed = Math.abs(Number(a.avgCrewNeeded || 0) - aProjectedCrew);
					const bNeed = Math.abs(Number(b.avgCrewNeeded || 0) - bProjectedCrew);
					if (aNeed !== bNeed) return aNeed - bNeed;
					return String(a.displayName).localeCompare(String(b.displayName));
				})[0];
				if (!best) break;
				const crewStep = neutralCrewStep(best);
				best.crew += crewStep;
				usedCrew += crewStep;
			}
		}
		const neutralAssignedCrew = rows.reduce((sum, row) => sum + Math.max(0, Math.floor(Number(row.crew || 0))), 0);
		const neutralUnusedCrew = Math.max(0, totalCrew - neutralAssignedCrew);
		for (const row of rows) {
			const lpPerUnit = Number(UPGRADE_AUTOMATION_COMPONENT_LP[row.name] || (row.name === 'Survey Data Unit' ? UPGRADE_AUTOMATION_COMPONENT_LP['SDU'] : 0) || 0);
			row.lpPerUnit = lpPerUnit;
			row.lpPerSecond = row.secondsPerUnit > 0 ? (lpPerUnit / row.secondsPerUnit) : 0;
			row.neutralTotalCrew = totalCrew;
			row.neutralAssignedCrew = neutralAssignedCrew;
			row.neutralUnusedCrew = neutralUnusedCrew;
			if (row.crew > 0 && row.secondsPerUnit > 0) {
				row.neutralUpgradingHour = Math.floor((row.crew * 3600) / row.secondsPerUnit);
				row.neutralUpgradingDay = Math.floor(row.installedToday + (row.crew * secondsInRemainingHours) / row.secondsPerUnit);
				row.neutralLpTarget = Math.floor(row.neutralUpgradingDay * lpPerUnit);
				const neutralDeficitDay = row.neutralUpgradingDay - row.craft24h;
				const neutralEffectiveDrain = getUpgradeAutomationEffectiveDrain(neutralDeficitDay, row.observedDrain);
				row.neutralBufferDays = neutralEffectiveDrain > 0 ? (row.inventoryGlobal / neutralEffectiveDrain) : (Number(row.inventoryGlobal || 0) > 0 ? Number.POSITIVE_INFINITY : null);
			} else {
				row.neutralUpgradingDay = Math.floor(row.installedToday || 0);
				row.neutralUpgradingHour = 0;
				row.neutralLpTarget = Math.floor(Number(row.neutralUpgradingDay || 0) * lpPerUnit);
				const neutralDeficitDay = Number(row.neutralUpgradingDay || 0) - Number(row.craft24h || 0);
				const neutralEffectiveDrain = getUpgradeAutomationEffectiveDrain(neutralDeficitDay, row.observedDrain);
				row.neutralBufferDays = neutralEffectiveDrain > 0 ? (Number(row.inventoryGlobal || 0) / neutralEffectiveDrain) : (Number(row.inventoryGlobal || 0) > 0 ? Number.POSITIVE_INFINITY : null);
			}
			row.finalCrew = row.crew;
			row.finalUpgradingHour = row.neutralUpgradingHour;
			row.finalUpgradingDay = row.neutralUpgradingDay;
			row.finalLpTarget = row.neutralLpTarget;
			const finalDeficitDay = row.finalUpgradingDay - row.craft24h;
			const finalEffectiveDrain = getUpgradeAutomationEffectiveDrain(finalDeficitDay, row.observedDrain);
			row.finalBufferDays = finalEffectiveDrain > 0 ? (row.inventoryGlobal / finalEffectiveDrain) : (Number(row.inventoryGlobal || 0) > 0 ? Number.POSITIVE_INFINITY : null);
		}
		const cleanedRows = rows.map(({ remainder, scaledCrew, ...row }) => row);
		return cleanedRows;
	}

	function computeUpgradeAutomationRequestedLpTargetFullDay(pastRequestedLp = 0, rows = [], aggressiveness = 1, remainingNeutralHours = 0, remainingTargetHours = 0) {
		const useExecutableTargetBaseline = rows.some(row => row.targetPhaseBlocked);
		return Number(pastRequestedLp || 0) + rows.reduce((sum, row) => {
			const neutralHourly = Number(row.neutralUpgradingHour || 0);
			const targetBaselineHourly = useExecutableTargetBaseline
				? neutralHourly
				: Number(row.targetBaselineUpgradingHour ?? row.neutralUpgradingHour ?? 0);
			return sum + (
				neutralHourly * Number(remainingNeutralHours || 0)
				+ targetBaselineHourly * Number(aggressiveness || 0) * Number(remainingTargetHours || 0)
			) * Number(row.lpPerUnit || 0);
		}, 0);
	}

	function computeUpgradeAutomationNetAtlasPlan(neutralRows = [], componentMetrics = [], expectedTotalLpByEod = null, atlasPool = 0, now = new Date()) {
		const rows = neutralRows.map(row => ({ ...row }));
		const planning = getUpgradeAutomationPlanningHorizon(now);
		const remainingHours = planning.planningHours;
		const effectiveNow = now instanceof Date ? now : new Date(now);
		const fractionalUtcHour = effectiveNow.getUTCHours() + effectiveNow.getUTCMinutes() / 60 + effectiveNow.getUTCSeconds() / 3600;
		const neutralPhaseLength = Math.max(0, Math.min(23, Number(globalSettings?.upgradeAutomationAggressivenessStartHour ?? 12)));
		const targetProgress = Math.max(0, Math.min(1, (fractionalUtcHour - neutralPhaseLength) / Math.max(1, 23 - neutralPhaseLength)));
		const targetMultiplier = targetProgress * targetProgress * (3 - 2 * targetProgress);
		const neutralMultiplier = 1 - targetMultiplier;
		const redemption = Number(expectedTotalLpByEod);
		const pool = Number(atlasPool);
		const metricsByComponent = new Map((componentMetrics || []).map(metric => [getUpgradeAutomationPerformanceComponentName(metric?.component || ''), metric]));
		const lpValue = Number.isFinite(redemption) && redemption > 0 && Number.isFinite(pool) && pool > 0 ? pool / redemption : null;
		const syncRow = row => {
			const projected = projectUpgradeAutomationFinalRow(row, row.optimizer2Crew, remainingHours);
			row.optimizer2UpgradingHour = projected.finalUpgradingHour;
			row.optimizer2UpgradingDay = projected.finalUpgradingDay;
			row.optimizer2BufferDays = projected.finalBufferDays;
			return projected;
		};
		for (const row of rows) {
			const component = getUpgradeAutomationPerformanceComponentName(row.displayName || row.name || '');
			const metric = metricsByComponent.get(component);
			const gmPrice = Number(metric?.priceGm);
			const secondsPerUnit = Number(row.secondsPerUnit || 0);
			const lpPerUnit = Number(row.lpPerUnit || 0);
			row.optimizer2NetAtlasPerSecond = lpValue !== null && Number.isFinite(gmPrice) && gmPrice > 0 && secondsPerUnit > 0
				? ((lpPerUnit * lpValue) - gmPrice) / secondsPerUnit
				: null;
			row.optimizer2GmPrice = Number.isFinite(gmPrice) && gmPrice > 0 ? gmPrice : null;
			row.optimizer2Crew = Math.max(0, Math.floor(Number(row.crew || 0)));
			row.optimizer2Source = false;
			row.optimizer2Destination = false;
			syncRow(row);
		}
		const eligibleRows = rows.filter(row => row.phantomUpgradeEligible && Number(row.inventoryPhantom || 0) > 0 && row.optimizer2NetAtlasPerSecond !== null && Number.isFinite(Number(row.optimizer2NetAtlasPerSecond)));
		const simulate = (row, crew) => {
			const normalizedCrew = Math.max(0, Math.floor(Number(crew || 0)));
			if (normalizedCrew > 0 && normalizedCrew < UPGRADE_AUTOMATION_MIN_JOB_CREW) return { legal: false };
			const projected = projectUpgradeAutomationFinalRow(row, normalizedCrew, remainingHours);
			const inventoryFeasible = Number(projected.finalUpgradingHour || 0) <= Number(row.inventoryGlobal || 0);
			return { ...projected, legal: inventoryFeasible };
		};
		const orderedRows = [...eligibleRows].sort((a, b) => {
			const netDiff = Number(a.optimizer2NetAtlasPerSecond) - Number(b.optimizer2NetAtlasPerSecond);
			if (netDiff !== 0) return netDiff;
			return String(a.displayName || a.name || '').localeCompare(String(b.displayName || b.name || ''));
		});
		const economicMassOf = row => Number(row.inventoryPhantom || 0) * Number(row.optimizer2NetAtlasPerSecond || 0);
		let bestPartition = null;
		for (let boundary = 1; boundary < orderedRows.length; boundary++) {
			const sourceCandidates = orderedRows.slice(0, boundary);
			const destinationCandidates = orderedRows.slice(boundary);
			if (!sourceCandidates.some(row => Number(row.optimizer2Crew || 0) >= UPGRADE_AUTOMATION_MIN_JOB_CREW)) continue;
			const sourceMass = sourceCandidates.reduce((sum, row) => sum + economicMassOf(row), 0);
			const destMass = destinationCandidates.reduce((sum, row) => sum + economicMassOf(row), 0);
			const difference = Math.abs(sourceMass - destMass);
			if (!bestPartition || difference < bestPartition.difference) bestPartition = { sourceCandidates, destinationCandidates, sourceMass, destMass, difference };
		}
		const sourcePool = bestPartition?.sourceCandidates || [];
		const initialReceivers = (bestPartition?.destinationCandidates || []).filter(row => {
			const addCrew = Number(row.optimizer2Crew || 0) === 0 ? UPGRADE_AUTOMATION_MIN_JOB_CREW : 1;
			return simulate(row, Number(row.optimizer2Crew || 0) + addCrew).legal;
		});
		const destPool = initialReceivers;
		for (const row of sourcePool) row.optimizer2Source = true;
		for (const row of destPool) row.optimizer2Destination = true;
		const fullTransferableSourceCrew = sourcePool.reduce((sum, row) => sum + Math.max(0, Number(row.optimizer2Crew || 0)), 0);
		const rawMoveBudget = Math.round(fullTransferableSourceCrew * targetMultiplier);
		const sourceRemovalQuotas = new Map();
		let moveBudgetRemaining = rawMoveBudget;
		for (const row of sourcePool) {
			if (moveBudgetRemaining <= 0) break;
			const crew = Math.max(0, Number(row.optimizer2Crew || 0));
			let removal = Math.min(crew, moveBudgetRemaining);
			const retainedCrew = crew - removal;
			if (retainedCrew > 0 && retainedCrew < UPGRADE_AUTOMATION_MIN_JOB_CREW) {
				const leaveMinimumRemoval = Math.max(0, crew - UPGRADE_AUTOMATION_MIN_JOB_CREW);
				removal = Math.abs(removal - leaveMinimumRemoval) <= Math.abs(crew - removal) ? leaveMinimumRemoval : crew;
			}
			sourceRemovalQuotas.set(row, removal);
			moveBudgetRemaining -= removal;
			if (removal < crew) break;
		}
		const moveBudget = [...sourceRemovalQuotas.values()].reduce((sum, value) => sum + Number(value || 0), 0);
		const sourceReferenceNetAtlas = moveBudget > 0
			? sourcePool.reduce((sum, row) => sum + Number(sourceRemovalQuotas.get(row) || 0) * Number(row.optimizer2NetAtlasPerSecond || 0), 0) / moveBudget
			: 0;
		const destinationUplifts = destPool.map(row => ({ row, uplift: Math.max(0, Number(row.optimizer2NetAtlasPerSecond || 0) - sourceReferenceNetAtlas) }));
		const totalUplift = destinationUplifts.reduce((sum, entry) => sum + entry.uplift, 0);
		const destinationQuotas = new Map();
		if (moveBudget > 0 && totalUplift > 0) {
			const exactQuotas = destinationUplifts.map(entry => {
				const exact = moveBudget * entry.uplift / totalUplift;
				return { ...entry, exact, quota: Math.floor(exact), remainder: exact - Math.floor(exact) };
			});
			let unassigned = moveBudget - exactQuotas.reduce((sum, entry) => sum + entry.quota, 0);
			exactQuotas.sort((a, b) => b.remainder - a.remainder || Number(b.row.optimizer2NetAtlasPerSecond) - Number(a.row.optimizer2NetAtlasPerSecond));
			for (let index = 0; index < exactQuotas.length && unassigned > 0; index++, unassigned--) exactQuotas[index].quota += 1;
			for (const entry of exactQuotas) destinationQuotas.set(entry.row, entry.quota);
		}
		const sourceRemovedCrew = new Map(sourcePool.map(row => [row, 0]));
		const destinationAddedCrew = new Map(destPool.map(row => [row, 0]));
		const transferAmountFor = (src, dst) => Number(dst.optimizer2Crew || 0) === 0 ? UPGRADE_AUTOMATION_MIN_JOB_CREW : 1;
		const guardLimit = Math.max(1000, rows.length * Math.max(1, rows.reduce((sum, row) => sum + Number(row.optimizer2Crew || 0), 0)) * 6);
		let transfers = 0;
		for (let guard = 0; guard < guardLimit; guard++) {
			const atomicSource = sourcePool.find(row => Number(row.optimizer2Crew || 0) === UPGRADE_AUTOMATION_MIN_JOB_CREW && Number(sourceRemovalQuotas.get(row) || 0) - Number(sourceRemovedCrew.get(row) || 0) >= UPGRADE_AUTOMATION_MIN_JOB_CREW);
			if (atomicSource) {
				const atomicAllocations = new Map();
				let atomicRemaining = UPGRADE_AUTOMATION_MIN_JOB_CREW;
				const stoppedReceiver = destPool
					.filter(dst => Number(dst.optimizer2Crew || 0) === 0 && Number(destinationQuotas.get(dst) || 0) - Number(destinationAddedCrew.get(dst) || 0) >= UPGRADE_AUTOMATION_MIN_JOB_CREW)
					.sort((a, b) => Number(b.optimizer2NetAtlasPerSecond) - Number(a.optimizer2NetAtlasPerSecond))[0];
				if (stoppedReceiver) {
					atomicAllocations.set(stoppedReceiver, UPGRADE_AUTOMATION_MIN_JOB_CREW);
					atomicRemaining = 0;
				} else {
					while (atomicRemaining > 0) {
						const receiver = destPool
							.filter(dst => Number(dst.optimizer2Crew || 0) > 0)
							.map(dst => ({ dst, remaining: Number(destinationQuotas.get(dst) || 0) - Number(destinationAddedCrew.get(dst) || 0) - Number(atomicAllocations.get(dst) || 0) }))
							.filter(entry => entry.remaining > 0)
							.sort((a, b) => b.remaining - a.remaining || Number(b.dst.optimizer2NetAtlasPerSecond) - Number(a.dst.optimizer2NetAtlasPerSecond))[0];
						if (!receiver) break;
						atomicAllocations.set(receiver.dst, Number(atomicAllocations.get(receiver.dst) || 0) + 1);
						atomicRemaining -= 1;
					}
				}
				const atomicSourceSim = simulate(atomicSource, 0);
				const atomicDestinationsLegal = atomicRemaining === 0 && [...atomicAllocations.entries()].every(([dst, amount]) => simulate(dst, Number(dst.optimizer2Crew || 0) + amount).legal);
				if (atomicSourceSim.legal && atomicDestinationsLegal) {
					atomicSource.optimizer2Crew = 0;
					sourceRemovedCrew.set(atomicSource, Number(sourceRemovedCrew.get(atomicSource) || 0) + UPGRADE_AUTOMATION_MIN_JOB_CREW);
					syncRow(atomicSource);
					for (const [dst, amount] of atomicAllocations.entries()) {
						dst.optimizer2Crew += amount;
						destinationAddedCrew.set(dst, Number(destinationAddedCrew.get(dst) || 0) + amount);
						syncRow(dst);
					}
					transfers += UPGRADE_AUTOMATION_MIN_JOB_CREW;
					continue;
				}
			}
			let best = null;
			for (const src of sourcePool) {
				for (const dst of destPool) {
					if (src === dst || Number(src.optimizer2Crew || 0) <= 0) continue;
					const sourceQuotaRemaining = Number(sourceRemovalQuotas.get(src) || 0) - Number(sourceRemovedCrew.get(src) || 0);
					if (sourceQuotaRemaining <= 0) continue;
					if (Number(dst.optimizer2NetAtlasPerSecond) <= Number(src.optimizer2NetAtlasPerSecond)) continue;
					const transferAmount = transferAmountFor(src, dst);
					if (transferAmount <= 0 || Number(src.optimizer2Crew || 0) < transferAmount || sourceQuotaRemaining < transferAmount) continue;
					const quotaRemaining = Number(destinationQuotas.get(dst) || 0) - Number(destinationAddedCrew.get(dst) || 0);
					if (quotaRemaining <= 0) continue;
					const srcSim = simulate(src, Number(src.optimizer2Crew || 0) - transferAmount);
					const dstSim = simulate(dst, Number(dst.optimizer2Crew || 0) + transferAmount);
					if (!srcSim.legal || !dstSim.legal) continue;
					const improvement = transferAmount * (Number(dst.optimizer2NetAtlasPerSecond) - Number(src.optimizer2NetAtlasPerSecond));
					if (!(improvement > 0)) continue;
					if (!best || quotaRemaining > best.quotaRemaining || (quotaRemaining === best.quotaRemaining && improvement > best.improvement)) best = { src, dst, transferAmount, improvement, quotaRemaining };
				}
			}
			if (!best) break;
			best.src.optimizer2Crew -= best.transferAmount;
			sourceRemovedCrew.set(best.src, Number(sourceRemovedCrew.get(best.src) || 0) + best.transferAmount);
			best.dst.optimizer2Crew += best.transferAmount;
			destinationAddedCrew.set(best.dst, Number(destinationAddedCrew.get(best.dst) || 0) + best.transferAmount);
			syncRow(best.src);
			syncRow(best.dst);
			transfers += best.transferAmount;
		}
		return { rows, lpValue, expectedTotalLpByEod: redemption, atlasPool: pool, neutralMultiplier, targetMultiplier, fullTransferableSourceCrew, moveBudget, sourcePoolCount: sourcePool.length, destPoolCount: destPool.length, sourcePoolMass: Number(bestPartition?.sourceMass || 0), destPoolMass: Number(bestPartition?.destMass || 0), sourceReferenceNetAtlas, transfers };
	}

	function resolveUpgradeAutomationOptimizer2AtlasPool(lpInstance, pricingHistoryLatest = null) {
		const normalizedInstance = normalizeUpgradeAutomationLpInstance(lpInstance);
		const declaredOverride = Number(UPGRADE_AUTOMATION_ATLAS_POOL_OVERRIDES[normalizedInstance]);
		if (Number.isFinite(declaredOverride) && declaredOverride > 0) return declaredOverride;
		const historyPool = Number(pricingHistoryLatest?.atlasPool);
		return Number.isFinite(historyPool) && historyPool > 0 ? historyPool : 0;
	}

	function normalizeUpgradeAutomationOptimizerVersion(value) {
		return String(value || '').trim().toUpperCase() === 'O1' ? 'O1' : 'O2';
	}

	function selectUpgradeAutomationOptimizerPlan(requestedVersion, optimizer1Plan, optimizer2Plan) {
		const requested = normalizeUpgradeAutomationOptimizerVersion(requestedVersion);
		const optimizer1Rows = Array.isArray(optimizer1Plan?.rows) ? optimizer1Plan.rows : [];
		const optimizer2Ready = Array.isArray(optimizer2Plan?.rows)
			&& optimizer2Plan.rows.length > 0
			&& Number.isFinite(Number(optimizer2Plan.lpValue));
		if (requested !== 'O2' || !optimizer2Ready) {
			return {
				...optimizer1Plan,
				rows: optimizer1Rows,
				version: 'O1',
				requestedVersion: requested,
				fallbackReason: requested === 'O2' ? 'optimizer_2_inputs_unavailable' : ''
			};
		}
		const rows = optimizer2Plan.rows.map(row => ({
			...row,
			finalCrew: Math.max(0, Math.floor(Number(row.optimizer2Crew || 0))),
			finalUpgradingHour: Math.max(0, Math.floor(Number(row.optimizer2UpgradingHour || 0))),
			finalUpgradingDay: Math.max(0, Math.floor(Number(row.optimizer2UpgradingDay || 0))),
			finalLpTarget: Math.max(0, Math.floor(Number(row.optimizer2UpgradingDay || 0) * Number(row.lpPerUnit || 0))),
			finalBufferDays: row.optimizer2BufferDays ?? null,
			optimizerSource: !!row.optimizer2Source,
			optimizerDestination: !!row.optimizer2Destination
		}));
		return { ...optimizer2Plan, rows, version: 'O2', requestedVersion: requested, fallbackReason: '' };
	}

	function computeUpgradeAutomationFinalPlan(neutralRows = [], aggressiveness = 1, now = new Date()) {
		const rows = neutralRows.map(row => ({ ...row }));
		const planning = getUpgradeAutomationPlanningHorizon(now);
		const remainingHours = planning.planningHours;
		const neutralLpTargetTotal = rows.reduce((sum, row) => sum + Number(row.neutralUpgradingHour || 0) * remainingHours * Number(row.lpPerUnit || 0), 0);
		const aggrStartHour = Math.max(0, Math.min(23, parseIntDefault(globalSettings?.upgradeAutomationAggressivenessStartHour, 12)));
		const currentUtcHour = now.getUTCHours();
		const remainingNeutralHours = Math.max(0, Math.min(remainingHours, aggrStartHour - currentUtcHour));
		const remainingTargetHours = remainingHours - remainingNeutralHours;
		// A full dynamic-risk block intentionally keeps the executable (special-free)
		// allocation for target phase. Otherwise use the unrestricted baseline.
		const useExecutableTargetBaseline = rows.some(row => row.targetPhaseBlocked);
		const targetBaselineCrewFor = row => useExecutableTargetBaseline ? Number(row.crew || 0) : Number(row.targetBaselineCrew ?? row.crew ?? 0);
		const targetBaselineHourlyFor = row => useExecutableTargetBaseline ? Number(row.neutralUpgradingHour || 0) : Number(row.targetBaselineUpgradingHour ?? row.neutralUpgradingHour ?? 0);
		const targetFinalLp = Math.max(0, rows.reduce((sum, row) => sum + (Number(row.neutralUpgradingHour || 0) * remainingNeutralHours + targetBaselineHourlyFor(row) * Number(aggressiveness || 0) * remainingTargetHours) * Number(row.lpPerUnit || 0), 0));
		const direction = aggressiveness > 1 ? 'aggressive' : (aggressiveness < 1 ? 'suppressive' : 'neutral');
		const syncProjectedFields = row => {
			const projected = projectUpgradeAutomationFinalRow(row, row.finalCrew, remainingHours);
			row.finalUpgradingHour = projected.finalUpgradingHour;
			row.finalUpgradingDay = projected.finalUpgradingDay;
			row.finalLpTarget = projected.finalLpTarget;
			row.finalBufferDays = projected.finalBufferDays;
		};
		const bufferSortable = value => Number.isFinite(Number(value)) ? Number(value) : Number.POSITIVE_INFINITY;
		for (const row of rows) {
			row.finalCrew = Math.max(0, Math.floor(targetBaselineCrewFor(row)));
			syncProjectedFields(row);
		}
		const currentTotal = () => rows.reduce((sum, row) => sum + (Number(row.neutralUpgradingHour || 0) * remainingNeutralHours + Number(row.finalUpgradingHour || 0) * remainingTargetHours) * Number(row.lpPerUnit || 0), 0);
		if (direction === 'neutral' || !rows.length || !Number.isFinite(targetFinalLp)) return { rows, neutralLpTargetTotal, finalLpTargetTotal: currentTotal(), targetFinalLp };
		const simulateRow = (row, projectedCrew) => {
			if (!row?.phantomUpgradeEligible || row.targetPhaseBlocked) return { legal: false };
			if (!Number.isFinite(projectedCrew) || projectedCrew < 0) return { legal: false };
			const normalizedProjectedCrew = Math.max(0, Math.floor(Number(projectedCrew || 0)));
			if (normalizedProjectedCrew > 0 && normalizedProjectedCrew < UPGRADE_AUTOMATION_MIN_JOB_CREW) return { legal: false };
			if (Number.isFinite(Number(row.specialRiskMaxCrew)) && normalizedProjectedCrew > Number(row.specialRiskMaxCrew)) return { legal: false };
			if (row.specialRiskControlled && Number.isFinite(Number(row.specialRiskMaxCrew))) {
				const projectedSpecialCrew = rows.reduce((sum, candidate) => {
					if (!candidate.specialRiskControlled) return sum;
					return sum + (candidate === row ? Math.max(0, Math.floor(Number(projectedCrew || 0))) : Math.max(0, Math.floor(Number(candidate.finalCrew || 0))));
				}, 0);
				if (projectedSpecialCrew > Number(row.specialRiskMaxCrew)) return { legal: false };
			}
			const projected = projectUpgradeAutomationFinalRow(row, projectedCrew, remainingHours);
			const projectedHourly = Number(projected.finalUpgradingHour || 0);
			const availableInventory = Number(row.inventoryGlobal || 0);
			const inventoryFeasible = !Number.isFinite(projectedHourly) || projectedHourly <= availableInventory;
			return {
				legal: inventoryFeasible,
				projectedCrew: Math.max(0, Math.floor(Number(projectedCrew || 0))),
				projectedUpgradingHour: projected.finalUpgradingHour,
				projectedUpgradingDay: projected.finalUpgradingDay,
				projectedTotalComponentLp: (Number(row.neutralUpgradingHour || 0) * remainingNeutralHours + Number(projected.finalUpgradingHour || 0) * remainingTargetHours) * Number(row.lpPerUnit || 0),
				projectedBufferDays: projected.finalBufferDays,
				effectiveLpPerSecond: Number(row.lpPerSecond || 0),
				inventoryFeasible
			};
		};
		const pairDirectionAllowed = (srcSim, dstSim) => {
			if (direction === 'aggressive') return Number(dstSim.effectiveLpPerSecond || 0) > Number(srcSim.effectiveLpPerSecond || 0);
			if (direction === 'suppressive') return Number(dstSim.effectiveLpPerSecond || 0) < Number(srcSim.effectiveLpPerSecond || 0);
			return false;
		};
		const computeSpread = values => {
			const finite = values.map(v => Number(v)).filter(Number.isFinite);
			if (!finite.length) return 0;
			return Math.max(...finite) - Math.min(...finite);
		};
		const partitionDirection = direction === 'aggressive' ? 'low_to_high' : 'high_to_low';
		const initialAchievableLp = currentTotal();
		const targetSpan = Number(targetFinalLp || 0) - Number(neutralLpTargetTotal || 0);
		const progressToTarget = Math.abs(targetSpan) > 1e-9 ? ((Number(initialAchievableLp || 0) - Number(neutralLpTargetTotal || 0)) / targetSpan) : 1;
		const behindRatio = Math.max(0, Math.min(1, 1 - progressToTarget));
		const orderedRows = [...rows].sort((a, b) => {
			const lpsDiff = Number(a.lpPerSecond || 0) - Number(b.lpPerSecond || 0);
			if (lpsDiff !== 0) return lpsDiff;
			return String(a.displayName || a.name || '').localeCompare(String(b.displayName || b.name || ''));
		});
		const lpMassOf = row => Math.max(0, Number(row.inventoryPhantom || 0)) * Math.max(0, Number(UPGRADE_AUTOMATION_COMPONENT_LP[row.displayName] || UPGRADE_AUTOMATION_COMPONENT_LP[row.name] || 0));
		const poolSkewMultiplier = Math.max(0, Number(globalSettings?.upgradeAutomationPoolSkewMultiplier ?? 3));
		const skewStrength = 1 + behindRatio * poolSkewMultiplier;
		const sourceBias = direction === 'aggressive' ? skewStrength : 1;
		const destBias = direction === 'aggressive' ? 1 : skewStrength;
		const sourcePool = [];
		const destPool = [];
		const sourceNames = new Set();
		const destNames = new Set();
		const actualSourceNames = new Set();
		const actualDestNames = new Set();
		let left = 0;
		let right = orderedRows.length - 1;
		let sourceMass = 0;
		let destMass = 0;
		while (left <= right) {
			const wantSource = sourceMass * destBias <= destMass * sourceBias;
			if (wantSource) {
				const row = direction === 'aggressive' ? orderedRows[left++] : orderedRows[right--];
				if (!row || !row.phantomUpgradeEligible || row.targetPhaseBlocked) continue;
				const key = String(row.displayName || row.name || '');
				if (!sourceNames.has(key)) {
					sourcePool.push(row);
					sourceNames.add(key);
					sourceMass += lpMassOf(row);
				}
			} else {
				const row = direction === 'aggressive' ? orderedRows[right--] : orderedRows[left++];
				if (!row || !row.phantomUpgradeEligible || row.targetPhaseBlocked) continue;
				const key = String(row.displayName || row.name || '');
				if (!destNames.has(key)) {
					destPool.push(row);
					destNames.add(key);
					destMass += lpMassOf(row);
				}
			}
		}
		for (const row of orderedRows) {
			if (!row.phantomUpgradeEligible || row.targetPhaseBlocked) continue;
			const key = String(row.displayName || row.name || '');
			if (!sourceNames.has(key) && !destNames.has(key)) {
				if (sourceMass * destBias <= destMass * sourceBias) {
					sourcePool.push(row);
					sourceNames.add(key);
					sourceMass += lpMassOf(row);
				} else {
					destPool.push(row);
					destNames.add(key);
					destMass += lpMassOf(row);
				}
			}
		}
		// Risk control is a legality/cap layer, not a second directional optimizer.
		// FSTAB/SDU participate in the ordinary source/destination pools whenever
		// they are below the cap; no separate pass may force crew into them.
		let specialPriorityTargetCrew = 0;
		let specialPriorityActualCrew = rows.filter(row => row.specialRiskControlled).reduce((sum, row) => sum + Math.max(0, Math.floor(Number(row.finalCrew || 0))), 0);
		let specialPriorityTransfers = 0;
		let targetAddedIdleCrew = 0;
		const neutralUnusedCrew = Math.max(0, Math.floor(Number(rows.reduce((max, row) => Math.max(max, Number(row.neutralUnusedCrew || 0)), 0))));
		for (let added = 0; added < neutralUnusedCrew; added++) {
			const currentLp = currentTotal();
			const distanceNow = Math.abs(targetFinalLp - currentLp);
			const candidates = [];
			for (const dst of rows) {
				if (!dst || !dst.phantomUpgradeEligible || dst.targetPhaseBlocked) continue;
				const dstCurrentLp = (Number(dst.neutralUpgradingHour || 0) * remainingNeutralHours + Number(dst.finalUpgradingHour || 0) * remainingTargetHours) * Number(dst.lpPerUnit || 0);
				const dstSim = simulateRow(dst, Number(dst.finalCrew || 0) + 1);
				if (!dstSim.legal) continue;
				const totalAfter = currentLp - dstCurrentLp + Number(dstSim.projectedTotalComponentLp || 0);
				const distanceAfter = Math.abs(targetFinalLp - totalAfter);
				if (distanceAfter >= distanceNow) continue;
				candidates.push({ dst, dstSim, totalAfter, distanceAfter, lpDelta: totalAfter - currentLp });
			}
			if (!candidates.length) break;
			candidates.sort((a, b) => {
				if (a.distanceAfter !== b.distanceAfter) return a.distanceAfter - b.distanceAfter;
				const aDestCurrentBuffer = Number.isFinite(Number(a.dst.finalBufferDays)) ? Number(a.dst.finalBufferDays) : Number.POSITIVE_INFINITY;
				const bDestCurrentBuffer = Number.isFinite(Number(b.dst.finalBufferDays)) ? Number(b.dst.finalBufferDays) : Number.POSITIVE_INFINITY;
				if (aDestCurrentBuffer !== bDestCurrentBuffer) return bDestCurrentBuffer - aDestCurrentBuffer;
				const aDestLps = Number(a.dstSim.effectiveLpPerSecond || 0);
				const bDestLps = Number(b.dstSim.effectiveLpPerSecond || 0);
				if (aDestLps !== bDestLps) return direction === 'aggressive' ? (bDestLps - aDestLps) : (aDestLps - bDestLps);
				const aGain = Math.abs(Number(a.lpDelta || 0));
				const bGain = Math.abs(Number(b.lpDelta || 0));
				if (aGain !== bGain) return bGain - aGain;
				return String(a.dst.displayName || a.dst.name || '').localeCompare(String(b.dst.displayName || b.dst.name || ''));
			});
			const best = candidates[0];
			best.dst.finalCrew = Math.max(0, Number(best.dst.finalCrew || 0) + 1);
			syncProjectedFields(best.dst);
			actualDestNames.add(String(best.dst.displayName || best.dst.name || ''));
			targetAddedIdleCrew += 1;
		}
		const getTargetTransferAmount = (src, dst) => {
			const srcCrew = Math.max(0, Math.floor(Number(src?.finalCrew || 0)));
			const dstCrew = Math.max(0, Math.floor(Number(dst?.finalCrew || 0)));
			if (srcCrew <= 0) return 0;
			// Starting a stopped job is atomic: 0 -> minimum crew. All other moves are 1 crew.
			// The 1..9 illegal-allocations rule is enforced one level up by simulateRow, so any
			// transfer that would strand the donor is rejected there rather than auto-expanded here.
			let transferAmount = dstCrew === 0 ? UPGRADE_AUTOMATION_MIN_JOB_CREW : 1;
			if (transferAmount > srcCrew) return 0;
			return transferAmount;
		};
		const guardLimit = Math.max(1000, rows.length * Math.max(1, rows.reduce((sum, row) => sum + Math.max(0, Number(row.finalCrew || 0)), 0)) * 6);
		for (let guard = 0; guard < guardLimit; guard++) {
			const currentLp = currentTotal();
			const distanceNow = Math.abs(targetFinalLp - currentLp);
			if (distanceNow <= 0) break;
			const legalDonors = sourcePool
				.filter(src => Number(src.finalCrew || 0) >= 1)
				.map(src => ({
					src,
					currentBuffer: Number.isFinite(Number(src.finalBufferDays)) ? Number(src.finalBufferDays) : Number.POSITIVE_INFINITY
				}));
			if (!legalDonors.length) break;
			legalDonors.sort((a, b) => {
				if (a.currentBuffer !== b.currentBuffer) return a.currentBuffer - b.currentBuffer;
				const aLps = Number(a.src.lpPerSecond || 0);
				const bLps = Number(b.src.lpPerSecond || 0);
				if (aLps !== bLps) return direction === 'aggressive' ? (aLps - bLps) : (bLps - aLps);
				return String(a.src.displayName || a.src.name || '').localeCompare(String(b.src.displayName || b.src.name || ''));
			});
			let best = null;
			for (const donor of legalDonors) {
				const src = donor.src;
				const srcCurrentLp = (Number(src.neutralUpgradingHour || 0) * remainingNeutralHours + Number(src.finalUpgradingHour || 0) * remainingTargetHours) * Number(src.lpPerUnit || 0);
				const donorCandidates = [];
				for (const dst of destPool) {
					if (dst === src) continue;
					const transferAmount = getTargetTransferAmount(src, dst);
					if (transferAmount <= 0) continue;
					const srcSim = simulateRow(src, Number(src.finalCrew || 0) - transferAmount);
					const dstSim = simulateRow(dst, Number(dst.finalCrew || 0) + transferAmount);
					if (!srcSim.legal || !dstSim.legal) continue;
					if (!pairDirectionAllowed(srcSim, dstSim)) continue;
					const dstCurrentLp = (Number(dst.neutralUpgradingHour || 0) * remainingNeutralHours + Number(dst.finalUpgradingHour || 0) * remainingTargetHours) * Number(dst.lpPerUnit || 0);
					const totalAfter = currentLp - srcCurrentLp - dstCurrentLp + Number(srcSim.projectedTotalComponentLp || 0) + Number(dstSim.projectedTotalComponentLp || 0);
					const distanceAfter = Math.abs(targetFinalLp - totalAfter);
					if (distanceAfter >= distanceNow) continue;
					actualDestNames.add(String(dst.displayName || dst.name || ''));
					donorCandidates.push({
						src,
						dst,
						srcSim,
						dstSim,
						transferAmount,
						totalAfter,
						distanceAfter,
						lpDelta: totalAfter - currentLp
					});
				}
				if (!donorCandidates.length) continue;
				donorCandidates.sort((a, b) => {
					const aDestCurrentBuffer = Number.isFinite(Number(a.dst.finalBufferDays)) ? Number(a.dst.finalBufferDays) : Number.POSITIVE_INFINITY;
					const bDestCurrentBuffer = Number.isFinite(Number(b.dst.finalBufferDays)) ? Number(b.dst.finalBufferDays) : Number.POSITIVE_INFINITY;
					if (aDestCurrentBuffer !== bDestCurrentBuffer) return bDestCurrentBuffer - aDestCurrentBuffer;
					if (a.distanceAfter !== b.distanceAfter) return a.distanceAfter - b.distanceAfter;
					const aGain = Math.abs(Number(a.lpDelta || 0));
					const bGain = Math.abs(Number(b.lpDelta || 0));
					if (aGain !== bGain) return bGain - aGain;
					const aDestLps = Number(a.dstSim.effectiveLpPerSecond || 0);
					const bDestLps = Number(b.dstSim.effectiveLpPerSecond || 0);
					if (aDestLps !== bDestLps) return direction === 'aggressive' ? (bDestLps - aDestLps) : (aDestLps - bDestLps);
					return String(a.dst.displayName || a.dst.name || '').localeCompare(String(b.dst.displayName || b.dst.name || ''));
				});
				best = donorCandidates[0];
				break;
			}
			if (!best || best.distanceAfter >= distanceNow) break;
			for (const row of rows) {
				row.actualOptimizerSource = actualSourceNames.has(String(row.displayName || row.name || ''));
				row.actualOptimizerDestination = actualDestNames.has(String(row.displayName || row.name || ''));
			}
			actualSourceNames.add(String(best.src.displayName || best.src.name || ''));
			actualDestNames.add(String(best.dst.displayName || best.dst.name || ''));
			best.src.finalCrew = Math.max(0, Number(best.src.finalCrew || 0) - Number(best.transferAmount || 0));
			best.dst.finalCrew = Math.max(0, Number(best.dst.finalCrew || 0) + Number(best.transferAmount || 0));
			syncProjectedFields(best.src);
			syncProjectedFields(best.dst);
		}
		for (const row of rows) syncProjectedFields(row);
		for (const row of rows) {
			const optimizerKey = String(row.displayName || row.name || '');
			row.optimizerSource = sourceNames.has(optimizerKey);
			row.optimizerDestination = destNames.has(optimizerKey);
			row.actualOptimizerSource = actualSourceNames.has(optimizerKey);
			row.actualOptimizerDestination = actualDestNames.has(optimizerKey);
		}
		return {
			rows,
			neutralLpTargetTotal,
			finalLpTargetTotal: currentTotal(),
			targetFinalLp,
			sourcePoolCount: sourcePool.length,
			destPoolCount: destPool.length,
			sourcePoolMass: sourceMass,
			destPoolMass: destMass,
			poolSkewMultiplier,
			behindRatio,
			partitionDirection,
			specialPriorityTargetCrew,
			specialPriorityActualCrew,
			specialPriorityTransfers,
			targetAddedIdleCrew,
		};
	}
