				targetNow: Number(res.targetNow || 0),
				targetNowInflux: Number.isFinite(Number(res.targetNowInflux || 0)) ? Number(res.targetNowInflux || 0) : Number(res.targetNow || 0),
				targetNowInfluxPrevHour: Number(res.targetNowInfluxPrevHour || 0),
				targetNowInfluxNextHour: Number(res.targetNowInfluxNextHour || 0),
