	function updateFleetState(fleet, newState, overrideError) {
        if (!fleet || typeof fleet !== 'object') return;
        if ((typeof fleet.state == 'undefined') || !fleet.state.includes('ERROR') || overrideError) {
            fleet.state = newState;
            updateAssistStatus(fleet);
        }
	}

	async function handleRecoverableWarpCooldownError(fleet) {
		let retryAt = Date.now() + WARP_COOLDOWN_RETRY_BUFFER_MS;
		try {
			const fleetAcctInfo = await getAccountInfo(fleet.label, 'full fleet info', fleet.publicKey);
			const fleetAcctData = sageProgram.coder.accounts.decode('fleet', fleetAcctInfo.data);
			const warpCooldownExpiresAt = fleetAcctData.warpCooldownExpiresAt.toNumber() * 1000;
			if(Number.isFinite(warpCooldownExpiresAt) && warpCooldownExpiresAt > 0) {
				retryAt = Math.max(retryAt, warpCooldownExpiresAt + WARP_COOLDOWN_RETRY_BUFFER_MS);
			}
		} catch(e) {
			cLog(2, `${FleetTimeStamp(fleet.label)} Unable to refresh warp cooldown after recoverable ix error`, e);
		}

		const warpCDExpireTimeStr = `[${TimeToStr(new Date(retryAt))}]`;
		cLog(1, `${FleetTimeStamp(fleet.label)} Warp cooldown race, retrying after ${warpCDExpireTimeStr}`);
		updateFleetState(fleet, `Warp C/D ${warpCDExpireTimeStr}`, true);
		await wait(Math.max(1000, retryAt - Date.now()));
		if(fleet.state && fleet.state.includes('Warp C/D')) updateFleetState(fleet, 'Idle', true);
		return retryAt;
	}

	const TRANSPORT_UNLOAD_RETRY_DELAY_MS = 120000;
	const TRANSPORT_UNLOAD_RETRY_MAX = 3;
	const TRANSPORT_UNLOAD_RETRY_MARKER = 'Transport unload retry';

	function getTransportUnloadRetry(fleet) {
		if(!fleet || !fleet.state || !fleet.state.includes(TRANSPORT_UNLOAD_RETRY_MARKER)) return null;
		return {
			retryAt: Number(fleet.transportUnloadRetryAt || 0),
			count: Number(fleet.transportUnloadRetryCount || 0),
			coord: fleet.transportUnloadRetryCoord || ''
		};
	}

	function clearTransportUnloadRetry(fleet) {
		if(!fleet) return;
		fleet.transportUnloadRetryAt = 0;
		fleet.transportUnloadRetryCount = 0;
		fleet.transportUnloadRetryCoord = '';
		fleet.transportUnloadRetryError = '';
	}

	function scheduleTransportUnloadRetry(fleet, unloadResult, unloadCoord) {
		if(!globalSettings.transportStopOnError || !unloadResult || !unloadResult.error) return false;

		const retryCount = Number(fleet.transportUnloadRetryCount || 0) + 1;
		if(retryCount > TRANSPORT_UNLOAD_RETRY_MAX) {
			clearTransportUnloadRetry(fleet);
			cLog(1,`${FleetTimeStamp(fleet.label)} Transporting - ${fleet.state} (unload retry limit reached)`);
			return true;
		}

		const retryAt = Date.now() + TRANSPORT_UNLOAD_RETRY_DELAY_MS;
		const retryError = fleet.state || 'ERROR: Transport unload failed';
		fleet.transportUnloadRetryAt = retryAt;
		fleet.transportUnloadRetryCount = retryCount;
		fleet.transportUnloadRetryCoord = unloadCoord;
		fleet.transportUnloadRetryError = retryError;
		updateFleetState(fleet, `${retryError} | ${TRANSPORT_UNLOAD_RETRY_MARKER} ${retryCount}/${TRANSPORT_UNLOAD_RETRY_MAX} ⌛ ${TimeToStr(new Date(retryAt))}`, true);
		cLog(1,`${FleetTimeStamp(fleet.label)} ${TRANSPORT_UNLOAD_RETRY_MARKER} scheduled in ${Math.round(TRANSPORT_UNLOAD_RETRY_DELAY_MS / 1000)}s (${retryCount}/${TRANSPORT_UNLOAD_RETRY_MAX})`);
		return true;
	}

	function buildScanBlock(destX, destY, overridePattern, overridePatternLength) {
		let { scanBlockPattern, scanBlockLength }  = globalSettings;
		if(typeof overridePattern != "undefined" && overridePattern != '') {
			scanBlockPattern = overridePattern;
		}
		if(overridePatternLength) {
			scanBlockLength = overridePatternLength;
		}

		destX = Number(destX);
		destY = Number(destY);
		let scanBlock = [];
		if (isNaN(destX) || isNaN(destY)) return scanBlock;

		const tip = scanBlockLength - 1;

		if(scanBlockPattern == 'ring') {
			scanBlock.push([destX, destY]);
			scanBlock.push([destX+1, destY]);
			scanBlock.push([destX+2, destY]);
			scanBlock.push([destX+2, destY+1]);
			scanBlock.push([destX+2, destY+2]);
			scanBlock.push([destX+1, destY+2]);
			scanBlock.push([destX, destY+2]);
			scanBlock.push([destX, destY+1]);
		}
		else if(scanBlockPattern == 'spiral') {
			scanBlock.push([destX, destY]);
			scanBlock.push([destX-1, destY-1]);
			scanBlock.push([destX, destY-1]);
			scanBlock.push([destX+1, destY-1]);
			scanBlock.push([destX+1, destY]);
			scanBlock.push([destX+1, destY+1]);
			scanBlock.push([destX, destY+1]);
			scanBlock.push([destX-1, destY+1]);
			scanBlock.push([destX-1, destY]);
		}
		else if(scanBlockPattern == 'sly') {
			scanBlock.push([destX, destY]);
			scanBlock.push([destX-1, destY+1]);
			scanBlock.push([destX-2, destY+1]);
			scanBlock.push([destX-3, destY]);
			scanBlock.push([destX-3, destY-1]);
			scanBlock.push([destX-2, destY-2]);
			scanBlock.push([destX-1, destY-2]);
			scanBlock.push([destX, destY-3]);
			scanBlock.push([destX, destY-4]);
			scanBlock.push([destX-1, destY-5]);
			scanBlock.push([destX-2, destY-5]);
			scanBlock.push([destX-3, destY-4]);
		}
		else if(scanBlockPattern == 'up') {
			for(let i=0; i < scanBlockLength; i++) scanBlock.push([destX, destY + i]);
			for(let i=0; i < scanBlockLength; i++) scanBlock.push([destX + 1, destY + (tip - i)]);
		}
		else if(scanBlockPattern == 'down') {
			for(let i=0; i < scanBlockLength; i++) scanBlock.push([destX, destY - i]);
			for(let i=0; i < scanBlockLength; i++) scanBlock.push([destX + 1, destY - (tip - i)]);
		}
		else if(scanBlockPattern == 'left') {
			for(let i=0; i < scanBlockLength; i++) scanBlock.push([destX - i, destY]);
			for(let i=0; i < scanBlockLength; i++) scanBlock.push([destX - (tip - i), destY + 1]);
		}
		else if(scanBlockPattern == 'right') {
			for(let i=0; i < scanBlockLength; i++) scanBlock.push([destX + i, destY]);
			for(let i=0; i < scanBlockLength; i++) scanBlock.push([destX + (tip - i), destY + 1]);
		}
		else {
			//Default to square
			scanBlock.push([destX, destY]);
			scanBlock.push([destX+1, destY]);
			scanBlock.push([destX+1, destY+1]);
			scanBlock.push([destX, destY+1]);
		}

		return scanBlock;
	}

