	async function saveConfigImport() {
		let importText = document.querySelector('#importText');

		//Guard against clicking the wrong button
		if(importText.value.includes('sector_target')) {
			console.log('switching to fleet targets import...');
			await saveTargetsImport();
			return;
		}

		let jsonConfig = JSON.parse(importText.value);
		for (let key in jsonConfig) {
				let fleetObj = jsonConfig[key];
				let fleetJson = JSON.stringify(fleetObj);
				await GM.setValue(key, fleetJson);
		}
		scheduleSlyaStateBackup('config-import');
        await loadGlobalSettings();
		assistImportToggle();
	}

	async function saveTargetsImport() {
		let importText = document.querySelector('#importText');

		//Guard against clicking the wrong button
		if(!importText.value.includes('sector_target')) {
			console.log('switching to full fleet import...');
			await saveConfigImport();
			return;
		}

		let jsonTargets = JSON.parse(importText.value);
		for (let key in jsonTargets) {
			let destXStr = jsonTargets[key].sector_target[0].toString().trim();
			let destYStr = jsonTargets[key].sector_target[1].toString().trim();
			let scanBlock = buildScanBlock(destXStr, destYStr);
			let fleetSavedData = await GM.getValue(key, '{}');
			let fleetParsedData = JSON.parse(fleetSavedData);
			fleetParsedData.dest = destXStr + ',' + destYStr;
			fleetParsedData.scanBlock = scanBlock;
			await GM.setValue(key, JSON.stringify(fleetParsedData));
			let userFleetIndex = userFleets.findIndex(item => {return item.publicKey == key});
			userFleets[userFleetIndex].destCoord = destXStr + ',' + destYStr;
			userFleets[userFleetIndex].scanBlock = scanBlock;
		}
		scheduleSlyaStateBackup('targets-import');
		assistImportToggle();
	}

	async function saveSettingsInput() {
		const timingStart = slyaPerfNowMs();
		const timingMarks = [];
		let errBool = false;
		const errElem = document.querySelectorAll('#settings-modal-error');

		const scanBlockPattern = document.querySelector('#scanBlockPattern').value;
        const saveProfile = document.querySelector('#saveProfile').checked;
		const existingSavedProfile = Array.isArray(globalSettings?.savedProfile) ? globalSettings.savedProfile : [];
		const selectedSavedProfile = (userProfileAcct && userProfileKeyIdx !== undefined && userProfileKeyIdx !== null)
			? [userProfileAcct.toString(), userProfileKeyIdx, pointsProfileKeyIdx]
			: existingSavedProfile;

		globalSettings = {
			priorityFee: parseIntDefault(document.querySelector('#priorityFee').value, 1),
			minPriorityFeeForMultiIx: parseIntDefault(document.querySelector('#minPriorityFeeForMultiIx').value, 0),

			//autofee
			automaticFee: document.querySelector('#automaticFee').checked,
			automaticFeeStep: parseIntDefault(document.querySelector('#automaticFeeStep').value, 80),
			automaticFeeMin: parseIntDefault(document.querySelector('#automaticFeeMin').value, 1),
			automaticFeeMax: parseIntDefault(document.querySelector('#automaticFeeMax').value, 10000),
			automaticFeeTimeMin: parseIntDefault(document.querySelector('#automaticFeeTimeMin').value, 10),
			automaticFeeTimeMax: parseIntDefault(document.querySelector('#automaticFeeTimeMax').value, 70),

			craftingTxMultiplier: parseIntDefault(document.querySelector('#craftingTxMultiplier').value, 200),
			craftingTxAffectsAutoFee: document.querySelector('#craftingTxAffectsAutoFee').checked,

			transportKeep1: document.querySelector('#transportKeep1').checked,
			transportLoadUnloadSingleTx: document.querySelector('#transportLoadUnloadSingleTx').checked,
			transportUnloadsUnknownRSS: document.querySelector('#transportUnloadsUnknownRSS').checked,
			minerUnloadsAll: document.querySelector('#minerUnloadsAll').checked,
			minerSupplySingleTx: document.querySelector('#minerSupplySingleTx').checked,
			minerKeep1: document.querySelector('#minerKeep1').checked,
			starbaseKeep1: document.querySelector('#starbaseKeep1').checked,
			queueExitWarpSubwarp: document.querySelector('#queueExitWarpSubwarp').checked,
			aephiaApiKey: document.querySelector('#aephiaApiKey') ? parseStringDefault(document.querySelector('#aephiaApiKey').value,'') : parseStringDefault(globalSettings.aephiaApiKey,''),
			slyInstanceName: document.querySelector('#slyInstanceName') ? parseStringDefault(document.querySelector('#slyInstanceName').value,'') : parseStringDefault(globalSettings.slyInstanceName,''),
			upgradeAutomationInfluxTracking: document.querySelector('#upgradeAutomationInfluxTracking') ? document.querySelector('#upgradeAutomationInfluxTracking').checked : parseBoolDefault(globalSettings.upgradeAutomationInfluxTracking, false),
			heliusRpcURL: document.querySelector('#heliusRpcURL') ? parseStringDefault(document.querySelector('#heliusRpcURL').value,'') : parseStringDefault(globalSettings.heliusRpcURL,''),

			emailInterface: document.querySelector('#emailInterface') ? parseStringDefault(document.querySelector('#emailInterface').value,'') : parseStringDefault(globalSettings.emailInterface,''),

			influxURL: parseStringDefault(document.querySelector('#influxURL').value,''),
			influxAuth: parseStringDefault(document.querySelector('#influxAuth').value,''),
			influxDB: parseStringDefault(document.querySelector('#influxDB').value,''),
			scanMapURL: parseStringDefaultForced(document.querySelector('#scanMapURL').value,'https://slya.de/sdu.json'),

			emailFleetIxErrors: document.querySelector('#emailFleetIxErrors') ? document.querySelector('#emailFleetIxErrors').checked : !!globalSettings.emailFleetIxErrors,
			emailCraftIxErrors: document.querySelector('#emailCraftIxErrors') ? document.querySelector('#emailCraftIxErrors').checked : !!globalSettings.emailCraftIxErrors,
			emailNoCargoLoaded: document.querySelector('#emailNoCargoLoaded') ? document.querySelector('#emailNoCargoLoaded').checked : !!globalSettings.emailNoCargoLoaded,
			emailNotEnoughFFA: document.querySelector('#emailNotEnoughFFA') ? document.querySelector('#emailNotEnoughFFA').checked : !!globalSettings.emailNotEnoughFFA,

			fleetsPerColumn: parseIntDefault(document.querySelector('#fleetsPerColumn').value, 0),

			//lowPriorityFeeMultiplier: parseIntDefault(document.querySelector('#lowPriorityFeeMultiplier').value, 10),
            saveProfile: saveProfile,
            savedProfile: saveProfile ? selectedSavedProfile : [],
			confirmationCheckingDelay: parseIntDefault(document.querySelector('#confirmationCheckingDelay').value, 2000),
			debugLogLevel: parseIntDefault(document.querySelector('#debugLogLevel').value, 3),
            craftingJobs: parseIntDefault(document.querySelector('#craftingJobs').value, 4),
			subwarpShortDist: document.querySelector('#subwarpShortDist').checked,
			transportUseAmmoBank: document.querySelector('#transportUseAmmoBank').checked,
			transportStopOnError: document.querySelector('#transportStopOnError').checked,
			transportFuel100: document.querySelector('#transportFuel100').checked,
			fleetForceConsumableAmount: document.querySelector('#fleetForceConsumableAmount').checked,
			scanBlockPattern: scanBlockPattern ? scanBlockPattern : 'square',
			scanBlockLength: parseIntDefault(document.querySelector('#scanBlockLength').value, 5),
			scanBlockResetAfterResupply: document.querySelector('#scanBlockResetAfterResupply').checked,
			scanResupplyOnLowFuel: document.querySelector('#scanResupplyOnLowFuel').checked,
			scanSectorRegenTime: parseIntDefault(document.querySelector('#scanSectorRegenTime').value, 90),
			scanPauseTime: parseIntDefault(document.querySelector('#scanPauseTime').value, 600),
			scanStrikeCount: parseIntDefault(document.querySelector('#scanStrikeCount').value, 3),
			excludeFleets: parseStringDefault(document.querySelector('#excludeFleets').value, ''),
			statusPanelOpacity: parseIntDefault(document.querySelector('#statusPanelOpacity').value, 75),
			upgradeAutomationLpInstance: document.querySelector('#upgradeAutomationLpInstance') ? normalizeUpgradeAutomationLpInstance(document.querySelector('#upgradeAutomationLpInstance').value) : normalizeUpgradeAutomationLpInstance(globalSettings.upgradeAutomationLpInstance),
			upgradeAutomationEnabled: document.querySelector('#upgradeAutomationEnabled') ? document.querySelector('#upgradeAutomationEnabled').checked : !!globalSettings.upgradeAutomationEnabled,
			upgradeAutomationOptimizerVersion: document.querySelector('#upgradeAutomationOptimizerVersion') ? normalizeUpgradeAutomationOptimizerVersion(document.querySelector('#upgradeAutomationOptimizerVersion').value) : normalizeUpgradeAutomationOptimizerVersion(globalSettings.upgradeAutomationOptimizerVersion),
			upgradeAutomationStartCraftSlot: document.querySelector('#lpAutomationStartCraftSlot') ? parseIntDefault(document.querySelector('#lpAutomationStartCraftSlot').value, 1) : parseIntDefault(globalSettings.upgradeAutomationStartCraftSlot, 1),
			upgradeAutomationAggressivenessPct: document.querySelector('#upgradeAutomationAggressivenessPct') ? parseIntDefault(document.querySelector('#upgradeAutomationAggressivenessPct').value, 100) : parseIntDefault(globalSettings.upgradeAutomationAggressivenessPct, 100),
			upgradeAutomationAggressivenessStartHour: document.querySelector('#upgradeAutomationAggressivenessStartHour') ? parseIntDefault(document.querySelector('#upgradeAutomationAggressivenessStartHour').value, 12) : parseIntDefault(globalSettings.upgradeAutomationAggressivenessStartHour, 12),
			upgradeAutomationNeutralBlockSingleTx: document.querySelector('#upgradeAutomationNeutralBlockSingleTx') ? document.querySelector('#upgradeAutomationNeutralBlockSingleTx').checked : !!globalSettings.upgradeAutomationNeutralBlockSingleTx,
			upgradeAutomationBlockSpecialNeutral: document.querySelector('#upgradeAutomationBlockSpecialNeutral') ? document.querySelector('#upgradeAutomationBlockSpecialNeutral').checked : !!globalSettings.upgradeAutomationBlockSpecialNeutral,
			upgradeAutomationRelMultiplier: document.querySelector('#upgradeAutomationRelMultiplier') ? Number(document.querySelector('#upgradeAutomationRelMultiplier').value) : Math.max(0, Number(globalSettings.upgradeAutomationRelMultiplier ?? 1)),
			upgradeAutomationAbsAggrMultiplier: document.querySelector('#upgradeAutomationAbsAggrMultiplier') ? Number(document.querySelector('#upgradeAutomationAbsAggrMultiplier').value) : Math.max(0, Number(globalSettings.upgradeAutomationAbsAggrMultiplier ?? 1)),
			upgradeAutomationPoolSkewMultiplier: document.querySelector('#upgradeAutomationPoolSkewMultiplier') ? Number(document.querySelector('#upgradeAutomationPoolSkewMultiplier').value) : Math.max(0, Number(globalSettings.upgradeAutomationPoolSkewMultiplier ?? 3)),
			upgradeAutomationPhantomCrewUnlimited: document.querySelector('#phantomCrewUnlimitedToggle') ? document.querySelector('#phantomCrewUnlimitedToggle').checked : parseBoolDefault(globalSettings.upgradeAutomationPhantomCrewUnlimited, true),
			upgradeAutomationMaxPhantomCrew: document.querySelector('#upgradeAutomationMaxPhantomCrew') ? Math.max(0, parseIntDefault(document.querySelector('#upgradeAutomationMaxPhantomCrew').value, 0)) : Math.max(0, parseIntDefault(globalSettings.upgradeAutomationMaxPhantomCrew, 0)),
			autoStartScript: document.querySelector('#autoStartScript').checked,
			reloadPageOnFailedFleets: parseIntDefault(document.querySelector('#reloadPageOnFailedFleets').value, 0),
			...(window.electronAPI?.setWalletSecret ? {} : { mySecretKey: parseStringDefault(document.querySelector('#mySecretKey').value,'') }),
		}
		if (window.electronAPI?.setWalletSecret) {
			const enteredSecret = parseStringDefault(document.querySelector('#mySecretKey').value,'').trim();
			if (enteredSecret) {
				const secretResult = await window.electronAPI.setWalletSecret(enteredSecret);
				if (!secretResult?.ok) {
					errElem[0].textContent = 'Secret key was not saved: ' + String(secretResult?.error || 'unknown error');
					return;
				}
			}
		}
		slyaTimingMark(timingMarks, timingStart, 'read-inputs-build-settings');
		// just to be sure there are no bad mistakes, restrict both fee settings to 50k lamports
		if(globalSettings.automaticFeeMax > 50000) globalSettings.automaticFeeMax = 50000;
		if(globalSettings.priorityFee > 50000) globalSettings.priorityFee = 50000;

		const saveGlobalStart = slyaPerfNowMs();
		await saveGlobalSettings('global-settings-modal-save');
		timingMarks.push('saveGlobalSettings-await=' + Math.round((slyaPerfNowMs() - saveGlobalStart) * 10) / 10 + 'ms');
		const rebuildStart = slyaPerfNowMs();
		rebuildRpcPools();
		timingMarks.push('rebuild-rpc-pools=' + Math.round((slyaPerfNowMs() - rebuildStart) * 10) / 10 + 'ms');
		aephiaApiKeyValidation = { status: 'unknown', message: 'Aephia API key changed; validation required.', checkedAt: 0, tokenKey: '' };
		const lpAccessStart = slyaPerfNowMs();
		refreshLpAutomationMenuAccess(true);
		timingMarks.push('refresh-lp-menu-access=' + Math.round((slyaPerfNowMs() - lpAccessStart) * 10) / 10 + 'ms');

		if (errBool === false) {
			errElem[0].innerHTML = '';
			cLog(2, 'SYSTEM: Global Settings saved', globalSettings);
			const modalCloseStart = slyaPerfNowMs();
			settingsModalToggle();
			timingMarks.push('settings-modal-toggle=' + Math.round((slyaPerfNowMs() - modalCloseStart) * 10) / 10 + 'ms');
		}
		const emitModalTiming = () => {
			slyaTimingMark(timingMarks, timingStart, 'post-close-raf');
			emitSlyaTiming('[SETTINGS][MODAL-SAVE-TIMING] ' + timingMarks.join(' '));
		};
		if (typeof requestAnimationFrame !== 'undefined') {
			requestAnimationFrame(() => requestAnimationFrame(emitModalTiming));
		} else {
			emitModalTiming();
		}
	}

	let sensitiveFieldsVisible = false;
	function applySensitiveFieldMasking() {
		const selectors = ['#mySecretKey', '#aephiaApiKey', '#heliusRpcURL', '#influxAuth'];
		for (const selector of selectors) {
			const el = document.querySelector(selector);
			if (!el) continue;
			const hasValue = String(el.value || '').length > 0;
			const shouldMask = hasValue && !sensitiveFieldsVisible;
			el.style.webkitTextSecurity = shouldMask ? 'disc' : 'none';
			el.style.textSecurity = shouldMask ? 'disc' : 'none';
		}
		const toggleBtn = document.querySelector('#toggleSensitiveFields');
		if (toggleBtn) toggleBtn.textContent = sensitiveFieldsVisible ? 'Hide Sensitive Fields' : 'Show Sensitive Fields';
	}
