	async function assistProfileToggle(profiles) {
		return new Promise(async resolve => {
				let targetElem = document.querySelector('#profileModal');
				if (targetElem.style.display === 'none' && profiles) {
						targetElem.style.display = 'block';
						let contentElem = document.querySelector('#profileDiv');
						let transportOptStr = '';
						profiles.forEach( function(profile) {transportOptStr += '<option value="' + profile.profile + '">' + profile.name + '  [' + profile.profile + ']</option>';});
						let profileSelect = document.createElement('select');
						profileSelect.size = profiles.length + 1;
						profileSelect.style.padding = '2px 10px';
						profileSelect.innerHTML = transportOptStr;
						contentElem.append(profileSelect);
						profileSelect.onchange = function() {
								cLog(2, 'assistProfileToggle: profileSelect.value', profileSelect.value);
								let selected = profiles.find(o => o.profile === profileSelect.value);
								assistProfileToggle(null);
								resolve(selected);
						}
				} else {
						targetElem.style.display = 'none';
						resolve(null);
				}
		});
	}

	async function handleUndockAll() {
		for (let i=0, n=userFleets.length; i < n; i++) {
			let fleetAcctInfo = await solanaReadConnection.getAccountInfo(userFleets[i].publicKey);
			let [fleetState, extra] = getFleetState(fleetAcctInfo);
			if (fleetState === 'StarbaseLoadingBay') {
				let starbase = await sageProgram.account.starbase.fetch(extra.starbase);
				let coords = starbase.sector[0].toNumber() + ',' + starbase.sector[1].toNumber();
				await execUndock(userFleets[i], coords);
			}
		}
	}

	async function handleClean() {

		let fleetKeys = GM_listValues();
		let fleetKey = null;
		let removedCounter = 0;
		for (let i in fleetKeys) {

			fleetKey = fleetKeys[i];

			let fleetSavedData = await GM.getValue(fleetKey, '{}');
			let fleetParsedData = JSON.parse(fleetSavedData);

			if(typeof fleetParsedData.assignment == "undefined") continue; //skip crafting jobs and global settings

			if (!userFleets.some(item => item.publicKey.toString() === fleetKey)) {
				cLog(1,`Deleting ${fleetParsedData.name}`);
				GM.deleteValue(fleetKey);
				removedCounter++;
			}
		}
		let cleanBtn = document.querySelector('#cleanBtn');
		if(cleanBtn) cleanBtn.innerHTML = '' + removedCounter + ' removed';

		setTimeout(() => { if(cleanBtn) cleanBtn.innerHTML = 'Clean'; }, 2000);
	}

	async function handleMovement(i, moveDist, moveX, moveY, isStarbaseAndWarpSubwarp, movementDiagnostic = null) {
		if (movementDiagnostic) {
			Object.assign(movementDiagnostic, {
				started: true, completed: false, alreadyAtTarget: false,
				blockedReason: '', txSignature: '', chainStateBefore: '', chainStateAfter: '', targetReached: false,
				submissionStatus: 'not_attempted', confirmationStatus: 'not_attempted'
			});
		}
		let moveTime = 1;
		let warpCooldownFinished = 0;
		let fleetAcctInfo = await getAccountInfo(userFleets[i].label, 'full fleet info', userFleets[i].publicKey);
		let [fleetState, extra] = getFleetState(fleetAcctInfo, userFleets[i]);
		if (movementDiagnostic) movementDiagnostic.chainStateBefore = fleetState;

		//If fleet is in StarbaseLoadingBay (post-undock transitional state), wait for it to transition to Idle
		//so that the movement and InfluxDB write are not skipped
		if (fleetState == 'StarbaseLoadingBay' && moveDist && moveX !== null && moveX !== '' && moveY != null && moveY !== '') {
			cLog(2, `${FleetTimeStamp(userFleets[i].label)} Fleet in StarbaseLoadingBay, waiting for Idle transition`);
			for (let retryCount = 0; retryCount < 4 && fleetState == 'StarbaseLoadingBay'; retryCount++) {
				await wait(3000);
				fleetAcctInfo = await getAccountInfo(userFleets[i].label, 'full fleet info', userFleets[i].publicKey);
				[fleetState, extra] = getFleetState(fleetAcctInfo, userFleets[i]);
				cLog(3, `${FleetTimeStamp(userFleets[i].label)} retry ${retryCount + 1}/4: fleetState=${fleetState}`);
			}
		}

		//Fleet idle and needs to be moved?
		if (movementDiagnostic && fleetState != 'Idle') movementDiagnostic.blockedReason = 'second_chain_read_not_idle';
		if (movementDiagnostic && fleetState == 'Idle' && extra.length > 1 && extra[0] === moveX && extra[1] === moveY) {
			movementDiagnostic.alreadyAtTarget = true;
			movementDiagnostic.completed = true;
			movementDiagnostic.blockedReason = 'already_at_target';
		}
		if (fleetState == 'Idle' && extra.length > 1 && moveDist && moveX !== null && moveX !== '' && moveY != null && moveY !== '') {
			if (extra[0] !== moveX || extra[1] !== moveY) {
				let warpCost = calcWarpFuelReq(userFleets[i], extra, [moveX, moveY], isStarbaseAndWarpSubwarp);
				cLog(4, `${FleetTimeStamp(userFleets[i].label)} warpCost: ${warpCost}`);
				let subwarpCost = calculateSubwarpFuelBurn(userFleets[i], moveDist);
				let fleetCurrentFuelTank = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].fuelTank, {programId: tokenProgramPK});
				let currentFuel = fleetCurrentFuelTank.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.fuel.toString());
				let currentFuelCnt = currentFuel ? currentFuel.account.data.parsed.info.tokenAmount.uiAmount - userFleets[i].exitSubwarpWillBurnFuel : 0;

				let fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});
				let currentCargoFuel = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.fuel.toString());
				let currentCargoFuelCnt = currentCargoFuel ? currentCargoFuel.account.data.parsed.info.tokenAmount.uiAmount : 0;

				let shortSubwarp = moveDist < 1.5 && globalSettings.subwarpShortDist ? true : false;
				let fleetAcctData = sageProgram.coder.accounts.decode('fleet', fleetAcctInfo.data);
				let warpCooldownExpiresAt = fleetAcctData.warpCooldownExpiresAt.toNumber() * 1000;
				let forceSubwarp = false;
				if(!shortSubwarp && userFleets[i].moveType == 'warp-subwarp-warp' && Date.now() < warpCooldownExpiresAt) {
					let warpCooldownLeft = (warpCooldownExpiresAt - Date.now()) / 1000;
					let fullDistanceLeft = calculateMovementDistance(extra, [moveX,moveY]);
					let subwarpDistanceWhileCooldown = warpCooldownLeft * (userFleets[i].subwarpSpeed / 1e6);
					let maxSubwarpDistancePastCooldown = (userFleets[i].warpCooldown - warpCooldownLeft) * (userFleets[i].subwarpSpeed / 1e6); //how far could we subwarp in the past cooldown time?
					//if the past warp cooldown is too low that it would've allowed a subwarp, we subwarp if we can do at least 0.5 AU in the remaining time. If a lot more of the cooldown is done, we check if we can do at least 0.71 AU because moveX and moveY can be off by 0.49999 (=0.5) each (due to rounding) and sqrt(0.5*0.5+0.5*0.5)=0.707, so it is possible that the previous subwarp was 0.707 units off, but we don't want to subwarp again
					if(fullDistanceLeft > 0 && ((maxSubwarpDistancePastCooldown < 0.5 && subwarpDistanceWhileCooldown >= 0.5) || subwarpDistanceWhileCooldown >= 0.71)) {
						if(subwarpDistanceWhileCooldown < 1.415) subwarpDistanceWhileCooldown = 1.415; // we subwarp at least 1 sector in the direction of the target and we choose 1.415 (=sqrt(2) rounded up), so all 8 directions have the same chance
						let distanceRatio = Math.min(1, subwarpDistanceWhileCooldown / fullDistanceLeft);
						if(distanceRatio < 1) {
							let moveXNew = Math.round((moveX-extra[0]) * distanceRatio) + extra[0];
							let moveYNew = Math.round((moveY-extra[1]) * distanceRatio) + extra[1];
							let moveDistNew = calculateMovementDistance(extra, [moveXNew,moveYNew]);
							//if we would be near the target after subwarp, we subwarp the full distance if "subwarpShortDist" is enabled, so we only set the new coords if this isn't the case
							if(!globalSettings.subwarpShortDist || moveDist - moveDistNew >= 1.5) {
								moveX = moveXNew;
								moveY = moveYNew;
								moveDist = moveDistNew;

								//if we don't subwarp the full way to the target, we need to save the target (exactly as in the warp block below), just in case SLYA gets reloaded
								const fleetPK = userFleets[i].publicKey.toString();
								const fleetSavedData = await GM.getValue(fleetPK, '{}');
								const fleetParsedData = JSON.parse(fleetSavedData);
								fleetParsedData.moveTarget = userFleets[i].moveTarget;
								await saveFleetConfig(fleetPK, fleetParsedData, 'subwarp-target-save');
							}
						}
						forceSubwarp = true;
					}
				}

				//Should a warp be attempted?
				//if (userFleets[i].moveType == 'warp' && (currentFuelCnt + currentCargoFuelCnt) >= warpCost && !shortSubwarp) {
				if ((userFleets[i].moveType == 'warp' || userFleets[i].moveType == 'warp-subwarp-warp' || isStarbaseAndWarpSubwarp) && (currentFuelCnt + currentCargoFuelCnt) >= warpCost && !shortSubwarp && !forceSubwarp) {
					//let fleetAcctData = sageProgram.coder.accounts.decode('fleet', fleetAcctInfo.data);
					//let warpCooldownExpiresAt = fleetAcctData.warpCooldownExpiresAt.toNumber() * 1000;

					//Wait for cooldown
					while (Date.now() < warpCooldownExpiresAt) {
						if (!userFleets[i].state.includes('Warp C/D')) {
							const warpCDExpireTimeStr = `[${TimeToStr(new Date(warpCooldownExpiresAt))}]`;
							cLog(1,`${FleetTimeStamp(userFleets[i].label)} Awaiting Warp C/D ${warpCDExpireTimeStr}`);
							updateFleetState(userFleets[i], `Warp C/D ${warpCDExpireTimeStr}`);
						}

						//await wait(Math.max(1000, warpCooldownExpiresAt - Date.now()));
						if(warpCooldownExpiresAt - Date.now() < 5000) await wait(Math.max(1000, warpCooldownExpiresAt - Date.now()));
						else await wait(5000);
						if(userFleets[i].stopping) return;
					}
					await wait(WARP_COOLDOWN_RETRY_BUFFER_MS); //Extra wait to ensure accuracy

					const fleetPK = userFleets[i].publicKey.toString();
					const fleetSavedData = await GM.getValue(fleetPK, '{}');
					const fleetParsedData = JSON.parse(fleetSavedData);
					const assignment = fleetParsedData.assignment;

					//Calculate next warp point if more than 1 is needed to arrive at final destination
					if (moveDist > userFleets[i].maxWarpDistance / 100) {
						[moveX, moveY] = calcNextWarpPoint(userFleets[i].maxWarpDistance, extra, [moveX, moveY]);

						//Saves temporary waypoints for transports in case the page is refreshed mid-journey while using warp
						//const fleetPK = userFleets[i].publicKey.toString();
						//const fleetSavedData = await GM.getValue(fleetPK, '{}');
						//const fleetParsedData = JSON.parse(fleetSavedData);
						//cLog(3, `${FleetTimeStamp(userFleets[i].label)} moveTargets`, fleetParsedData.moveTarget, userFleets[i].moveTarget);
						fleetParsedData.moveTarget = userFleets[i].moveTarget;
						await saveFleetConfig(fleetPK, fleetParsedData, 'warp-target-save');

						//Update distance based on new warp target
						moveDist = calculateMovementDistance(extra, [moveX,moveY]);
					}

					moveTime = calculateWarpTime(userFleets[i], moveDist);
					const scanningMovementTime = calculateScanningMovementOpportunityCost(Date.now(), moveTime, userFleets[i].scanEnd);
					userFleets[i].scanOptimizationMovementContext = {
						fromX: extra[0], fromY: extra[1], toX: moveX, toY: moveY,
						distance: moveDist, expectedTravelSeconds: moveTime,
						burnedFuel: moveDist*(userFleets[i].warpFuelConsumptionRate/100), mode: 'warp',
						...scanningMovementTime
					};
					const movementEventContext = await reserveFleetTelemetryMovementEvent(userFleets[i], fleetParsedData);
					if (movementDiagnostic) movementDiagnostic.submissionStatus = 'attempted';
					const warpResult = await execWarp(userFleets[i], moveX, moveY, moveTime);
					if (movementDiagnostic) recordMovementTransactionDiagnostic(movementDiagnostic, warpResult?.txResult || warpResult);
					if(warpResult && warpResult.warpCooldownRetry) return warpResult.warpCooldownFinished;
						const movementStarbaseCoords = ConvertCoords(fleetParsedData.starbase || userFleets[i].starbaseCoord);
						const movementStarbaseContext = await getTelemetryStarbaseContextFromCoords(movementStarbaseCoords[0], movementStarbaseCoords[1]);
						const movementFactionTag = movementStarbaseContext.faction ? `,faction=${influxEscape(movementStarbaseContext.faction)}` : '';
						const burnedFuel = moveDist*(userFleets[i].warpFuelConsumptionRate/100);
						const movementTxResult = warpResult?.txResult || warpResult;
						const costCycle = await addFleetTelemetryMovementCost(userFleets[i], fleetParsedData, { burnedFuel, txResult: movementTxResult, destX: moveX, destY: moveY, eventContext: movementEventContext }, fleetCurrentCargo);
						const movementCycleTag = costCycle?.id ? `,cycleId=${influxEscape(costCycle.id)}` : '';
						const movementTags = `fleet=${influxEscape(userFleets[i].label)},fromX=${extra[0]},fromY=${extra[1]},toX=${moveX},toY=${moveY},assignment=${influxEscape(assignment || 'unknown')},starbase=${influxEscape(movementStarbaseContext.starbaseName || 'unknown')}${movementFactionTag}${movementCycleTag}`;
						const movementFields = `type="warp",burnedFuel=${burnedFuel},moveTime=${moveTime},moveDist=${moveDist}${buildSlyaTxCostInfluxFields(movementTxResult)}`;
						await sendToInflux(`movement,${movementTags} ${movementFields}`);
						await sendFleetMovementCargoTelemetry(userFleets[i], fleetParsedData, fleetCurrentCargo, movementTags, 'warp');
						if(userFleets[i].scanLastFuelAmount) userFleets[i].scanLastFuelAmount -= moveDist*(userFleets[i].warpFuelConsumptionRate/100);
						warpCooldownFinished = warpResult.warpCooldownFinished;
				} else if (currentFuelCnt + currentCargoFuelCnt >= subwarpCost) {
					const fleetPK = userFleets[i].publicKey.toString();
					const fleetSavedData = await GM.getValue(fleetPK, '{}');
					const fleetParsedData = JSON.parse(fleetSavedData);
					const assignment = fleetParsedData.assignment;
					moveTime = calculateSubwarpTime(userFleets[i], moveDist);
					const scanningMovementTime = calculateScanningMovementOpportunityCost(Date.now(), moveTime, userFleets[i].scanEnd);
					userFleets[i].scanOptimizationMovementContext = {
						fromX: extra[0], fromY: extra[1], toX: moveX, toY: moveY,
						distance: moveDist, expectedTravelSeconds: moveTime,
						burnedFuel: moveDist*(userFleets[i].subwarpFuelConsumptionRate/100), mode: 'subwarp',
						...scanningMovementTime
					};
					const movementEventContext = await reserveFleetTelemetryMovementEvent(userFleets[i], fleetParsedData);
					if (movementDiagnostic) movementDiagnostic.submissionStatus = 'attempted';
					const subwarpResult = await execSubwarp(userFleets[i], moveX, moveY, moveTime);
					if (movementDiagnostic) recordMovementTransactionDiagnostic(movementDiagnostic, subwarpResult);
						const movementStarbaseCoords = ConvertCoords(fleetParsedData.starbase || userFleets[i].starbaseCoord);
						const movementStarbaseContext = await getTelemetryStarbaseContextFromCoords(movementStarbaseCoords[0], movementStarbaseCoords[1]);
						const movementFactionTag = movementStarbaseContext.faction ? `,faction=${influxEscape(movementStarbaseContext.faction)}` : '';
						const burnedFuel = moveDist*(userFleets[i].subwarpFuelConsumptionRate/100);
						const costCycle = await addFleetTelemetryMovementCost(userFleets[i], fleetParsedData, { burnedFuel, txResult: subwarpResult, destX: moveX, destY: moveY, eventContext: movementEventContext }, fleetCurrentCargo);
						const movementCycleTag = costCycle?.id ? `,cycleId=${influxEscape(costCycle.id)}` : '';
						const movementTags = `fleet=${influxEscape(userFleets[i].label)},fromX=${extra[0]},fromY=${extra[1]},toX=${moveX},toY=${moveY},assignment=${influxEscape(assignment || 'unknown')},starbase=${influxEscape(movementStarbaseContext.starbaseName || 'unknown')}${movementFactionTag}${movementCycleTag}`;
						const movementFields = `type="subwarp",burnedFuel=${burnedFuel},moveTime=${moveTime},moveDist=${moveDist}${buildSlyaTxCostInfluxFields(subwarpResult)}`;
						await sendToInflux(`movement,${movementTags} ${movementFields}`);
						await sendFleetMovementCargoTelemetry(userFleets[i], fleetParsedData, fleetCurrentCargo, movementTags, 'subwarp');
						if(userFleets[i].scanLastFuelAmount) userFleets[i].scanLastFuelAmount -= moveDist*(userFleets[i].subwarpFuelConsumptionRate/100);
					} else {
					if (movementDiagnostic) movementDiagnostic.blockedReason = 'insufficient_or_invalid_fuel';
					cLog(1,`${FleetTimeStamp(userFleets[i].label)} Unable to move, lack of fuel`);
					if (!movementDiagnostic) {
						updateFleetState(userFleets[i], 'ERROR: Not enough fuel');
						if(globalSettings.emailNotEnoughFFA) await sendEMail(userFleets[i].label + ' not enough fuel', '');
					}
				}
			}
		}

		await wait(2000); //Allow time for RPC to update
		fleetAcctInfo = await getAccountInfo(userFleets[i].label, 'full fleet info', userFleets[i].publicKey);
		[fleetState, extra] = getFleetState(fleetAcctInfo, userFleets[i]);
		let warpFinish = fleetState == 'MoveWarp' ? extra.warpFinish.toNumber() * 1000 : 0;
		let subwarpFinish = fleetState == 'MoveSubwarp' ? extra.arrivalTime.toNumber() * 1000 : 0;
		let endTime = warpFinish > subwarpFinish ? warpFinish : subwarpFinish;

		const calcEndTime = Date.now() + moveTime * 1000;
		cLog(3, `${FleetTimeStamp(userFleets[i].label)} Expected arrival (chain): ${TimeToStr(new Date(endTime))}`);
		cLog(3, `${FleetTimeStamp(userFleets[i].label)} Expected arrival (calc): ${TimeToStr(new Date(calcEndTime))}`);

		//Sometimes the chain returns null, use calculated time as fallback
		if(!endTime) endTime = calcEndTime;

		userFleets[i].moveEnd = endTime;
		await wait(moveTime * 1000);
		while (endTime > Date.now()) {
			const newFleetState = 'Move [' + TimeToStr(new Date(endTime)) + ']';
			updateFleetState(userFleets[i], newFleetState);
			await wait(Math.max(1000, endTime - Date.now()));
		}

		//await wait(2000);

		let localQueueExitWarpSubwarp = false;
		if(globalSettings.queueExitWarpSubwarp) {
			//exclude scanning fleets from this feature, because we can't bundle a scan instruction with any other ix
			let fleetSavedData = await GM.getValue(userFleets[i].publicKey.toString(), '{}');
			let fleetParsedData = JSON.parse(fleetSavedData);
			if (fleetParsedData.assignment != 'Scan') localQueueExitWarpSubwarp = true;
		}

		if (fleetState == 'MoveWarp') {
			if (localQueueExitWarpSubwarp) {
				userFleets[i].exitWarpSubwarpPending = 1;
				updateFleetState(userFleets[i], 'Idle');
			} else {
				await execExitWarp(userFleets[i]);
			}
		} else if (fleetState == 'MoveSubwarp'){
			if (localQueueExitWarpSubwarp) {
				userFleets[i].exitWarpSubwarpPending = 2;
				updateFleetState(userFleets[i], 'Idle');
			} else {
				await execExitSubwarp(userFleets[i]);
			}
		}
		userFleets[i].scanOptimizationMovementContext = null;

		fleetAcctInfo = await getAccountInfo(userFleets[i].label, 'full fleet info', userFleets[i].publicKey);
		[fleetState, extra] = getFleetState(fleetAcctInfo, userFleets[i]);
		if (movementDiagnostic) {
			movementDiagnostic.chainStateAfter = fleetState;
			movementDiagnostic.targetReached = Boolean(fleetState == 'Idle' && Array.isArray(extra) && extra.length > 1 && extra[0] == moveX && extra[1] == moveY);
			const confirmedTransaction = movementDiagnostic.confirmationStatus === 'confirmed' && Boolean(movementDiagnostic.txSignature);
			if (!movementDiagnostic.alreadyAtTarget && (confirmedTransaction || movementDiagnostic.targetReached)) {
				movementDiagnostic.completed = true;
				movementDiagnostic.blockedReason = 'confirmed_movement';
			}
			if (!movementDiagnostic.blockedReason) movementDiagnostic.blockedReason = 'missing_prerequisite';
		}
		if (fleetState == 'Idle' && extra) {
				let targetX = userFleets[i].moveTarget != '' && userFleets[i].moveTarget.split(',').length > 1 ? userFleets[i].moveTarget.split(',')[0].trim() : '';
				let targetY = userFleets[i].moveTarget != '' && userFleets[i].moveTarget.split(',').length > 1 ? userFleets[i].moveTarget.split(',')[1].trim() : '';
				if (extra[0] == targetX && extra[1] == targetY) {
						//bugfix: moveTarget is string based, not an array!
						//userFleets[i].moveTarget = [];
						userFleets[i].moveTarget = '';
						let fleetSavedData = await GM.getValue(userFleets[i].publicKey.toString(), '{}');
						let fleetParsedData = JSON.parse(fleetSavedData);
						let fleetPK = userFleets[i].publicKey.toString();
						fleetParsedData.moveTarget = userFleets[i].moveTarget;
						await saveFleetConfig(fleetPK, fleetParsedData, 'warp-target-clear');
				}
		}

		return movementDiagnostic || warpCooldownFinished;
	}

	async function saveScanEnd(i) {
		const fleetPK = userFleets[i].publicKey.toString();
		const fleetSavedData = await GM.getValue(fleetPK, '{}');
		const fleetParsedData = JSON.parse(fleetSavedData);
		fleetParsedData.scanEnd = userFleets[i].scanEnd;
		await saveFleetConfig(fleetPK, fleetParsedData, 'scan-end-save');
	}

	const SCAN_SUBMISSION_RETRY_DELAY_MS = 10000;
	const MOVEMENT_DIAGNOSTIC_PREFIX = 'SLYA_MOVEMENT_DECISION';
	const MOVEMENT_DIAGNOSTIC_REASONS = Object.freeze([
		'second_chain_read_not_idle', 'already_at_target', 'insufficient_or_invalid_fuel',
		'missing_prerequisite', 'transaction_construction_failure', 'pre_submission_failure',
		'submission_failure', 'confirmation_failure', 'confirmed_movement', 'unexpected_exception'
	]);

	function sanitizeMovementDiagnosticError(error) {
		if (!error) return null;
		const message = String(error?.message || error).replace(/((?:api[-_ ]?key|authorization|token|secret|seed|private[-_ ]?key))\s*[:=]\s*\S+/gi, '$1=[redacted]').slice(0, 240);
		return { class: String(error?.name || 'Error').slice(0, 80), code: String(error?.code || '').slice(0, 80), message };
	}

	function classifyMovementDiagnosticFailure(error, diagnostic = {}) {
		const text = `${error?.name || ''} ${error?.code || ''} ${error?.message || error || ''}`.toLowerCase();
		if (/confirm|instructionerror/.test(text)) return 'confirmation_failure';
		if (/sendtransaction|submit|blockhash|rpc/.test(text)) return 'submission_failure';
		if (/construct|instruction|accountsstrict|invalid public key/.test(text)) return 'transaction_construction_failure';
		if (diagnostic.submissionStatus === 'attempted') return 'pre_submission_failure';
		return 'unexpected_exception';
	}

	function recordMovementTransactionDiagnostic(diagnostic, txResult) {
		diagnostic.txSignature = String(txResult?.slyaTxHash || txResult?.signature || '').slice(0, 128);
		if (!txResult) {
			diagnostic.submissionStatus = 'failed';
			diagnostic.confirmationStatus = 'not_confirmed';
			diagnostic.blockedReason = 'submission_failure';
		} else if (txResult?.meta?.err) {
			diagnostic.submissionStatus = diagnostic.txSignature ? 'submitted' : 'failed';
			diagnostic.confirmationStatus = 'failed';
			diagnostic.blockedReason = 'confirmation_failure';
			diagnostic.error = sanitizeMovementDiagnosticError(txResult.meta.err);
		} else if (diagnostic.txSignature && txResult?.meta) {
			diagnostic.submissionStatus = 'submitted';
			diagnostic.confirmationStatus = 'confirmed';
		} else {
			diagnostic.submissionStatus = diagnostic.txSignature ? 'submitted' : 'unknown';
			diagnostic.confirmationStatus = 'not_confirmed';
			diagnostic.blockedReason = 'confirmation_failure';
		}
	}

	function hasConfirmedMovementProof(result) {
		if (!result || result.alreadyAtTarget) return false;
		const confirmedTransaction = result.confirmationStatus === 'confirmed' && Boolean(result.txSignature);
		const confirmedChainTarget = result.chainStateAfter === 'Idle' && result.targetReached === true;
		return result.completed === true && (confirmedTransaction || confirmedChainTarget);
	}

	function emitMovementDecisionDiagnostic(event) {
		try { cLog(1, `${MOVEMENT_DIAGNOSTIC_PREFIX} ${JSON.stringify(event)}`); }
		catch (error) { try { console.warn(`${MOVEMENT_DIAGNOSTIC_PREFIX}_LOG_FAILURE`); } catch (_) {} }
	}

	async function handleScan(i, fleetCoords, destCoords) {
		const fleet = userFleets[i];
		const beforeScanEnd = Number(fleet.scanEnd || 0);
		const diagnostic = {
			schema: 'slya.movement-decision.v1', version: '0.7.35-262', timestampUtc: new Date().toISOString(),
			attemptId: `${Date.now().toString(36)}-${String(fleet.publicKey).slice(0, 8)}-${Number(fleet.iterCnt || 0)}`,
			instance: getSlyaInfluxInstanceTag(), faction: getUpgradeAutomationInfluxFactionTag(),
			profile: String(userProfileAcct || ''), fleetName: String(fleet.label || ''), fleetAccount: String(fleet.publicKey || ''),
			assignment: 'Scan', active: true, scanningEnabled: true, firstChainState: 'Idle', secondChainState: '',
			currentCoordinates: Array.isArray(fleetCoords) ? fleetCoords.slice(0, 2) : [], targetCoordinates: Array.isArray(destCoords) ? destCoords.slice(0, 2) : [],
			scanEndBefore: beforeScanEnd, lastConfirmedScan: fleet.lastScanCoord ? { coordinates: fleet.lastScanCoord } : null,
			retryAt: Number(fleet.scanSubmissionRetryAt || 0), eligible: Number(fleet.scanSubmissionRetryAt || 0) <= Date.now(),
			cooldownMs: Math.max(0, beforeScanEnd - Date.now()), schedulerDecision: 'skip', decisionReason: Number(fleet.scanSubmissionRetryAt || 0) > Date.now() ? 'retry_not_due' : 'not_evaluated',
			movement: { started: false, completed: false, alreadyAtTarget: false, blockedReason: '', txSignature: '', chainStateBefore: '', chainStateAfter: '', targetReached: false, submissionStatus: 'not_attempted', confirmationStatus: 'not_attempted' },
			scanSignature: '', finalScanDecision: 'not_attempted', persistenceDecision: 'unchanged'
		};
		try {
			return await handleScanCore(i, fleetCoords, destCoords, diagnostic);
		} catch (error) {
			diagnostic.movement.blockedReason = diagnostic.movement.blockedReason || classifyMovementDiagnosticFailure(error, diagnostic.movement);
			diagnostic.error = sanitizeMovementDiagnosticError(error);
			throw error;
		} finally {
			diagnostic.secondChainState = diagnostic.movement.chainStateBefore || '';
			diagnostic.scanEndAfter = Number(fleet.scanEnd || 0);
			if (diagnostic.persistenceDecision === 'unchanged') diagnostic.persistenceDecision = diagnostic.scanEndAfter !== beforeScanEnd ? 'scan_end_changed' : 'unchanged';
			if (diagnostic.scanEndAfter !== beforeScanEnd && !diagnostic.movement.txSignature && !diagnostic.scanSignature) diagnostic.decisionReason = 'scan_end_changed_without_signature';
			emitMovementDecisionDiagnostic(diagnostic);
		}
	}

	async function handleScanCore(i, fleetCoords, destCoords, diagnostic) {
		if(Number(userFleets[i].scanSubmissionRetryAt || 0) > Date.now()) return;

		let fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});
		let cargoCnt = fleetCurrentCargo.value.reduce((n, {account}) => n + account.data.parsed.info.tokenAmount.uiAmount * cargoItems.find(r => r.token == account.data.parsed.info.mint).size, 0);
		let currentFoodAcct = fleetCurrentCargo.value.find(item => item.pubkey.toString() === userFleets[i].foodToken.toString());
		let currentFoodCnt = currentFoodAcct && currentFoodAcct.account.data.parsed.info.delegatedAmount ? currentFoodAcct.account.data.parsed.info.delegatedAmount.uiAmount : 0;

		if(
			//Cargo full check for data runner fleets
			((userFleets[i].scanCost == 0) && (userFleets[i].cargoCapacity - cargoCnt < userFleets[i].sduPerScan)) ||
			//Food count check for regular scanning fleets
			(currentFoodCnt < userFleets[i].scanCost)
			|| (userFleets[i].scanForceResupply)
		) {
			await handleResupply(i, fleetCoords);
			return;
		}

		let moved = false;
		if ((fleetCoords[0] !== destCoords[0] || fleetCoords[1] !== destCoords[1])) {
			if (!userFleets[i].state.includes('Warp C/D')) {
				const starbaseCoords = ConvertCoords(userFleets[i].starbaseCoord);
				//cLog(4, `${FleetTimeStamp(userFleets[i].label)} starbaseCoords: ${starbaseCoords}`);

				let isStarbaseAndWarpSubwarp = (userFleets[i].moveType == 'warpsubwarp' && fleetCoords[0] == starbaseCoords[0] && fleetCoords[1] == starbaseCoords[1]);

				let fuelNeeded = 0;
				if (userFleets[i].moveType == 'warp' || userFleets[i].moveType == 'warp-subwarp-warp' || isStarbaseAndWarpSubwarp) {
					const warpCostFromFleetToDest = calcWarpFuelReq(userFleets[i], fleetCoords, destCoords, isStarbaseAndWarpSubwarp);
					//const warpCostFromDestToStarbase = calcWarpFuelReq(userFleets[i], destCoords, starbaseCoords);
					const warpCostFromDestToStarbase = userFleets[i].moveType == 'warpsubwarp' ? calculateSubwarpFuelBurn(userFleets[i], calculateMovementDistance(destCoords, starbaseCoords)) : calcWarpFuelReq(userFleets[i], destCoords, starbaseCoords);
					fuelNeeded = warpCostFromFleetToDest + warpCostFromDestToStarbase;
					cLog(4, `${FleetTimeStamp(userFleets[i].label)} Warp cost to target: ${warpCostFromFleetToDest}`);
					cLog(4, `${FleetTimeStamp(userFleets[i].label)} Warp cost to return: ${warpCostFromDestToStarbase}`);
					cLog(4, `${FleetTimeStamp(userFleets[i].label)} Warp cost total: ${fuelNeeded}`);
				} else {
					const distToTarget = calculateMovementDistance(fleetCoords, destCoords);
					const distFromTargetToStarbase = calculateMovementDistance(destCoords, starbaseCoords);
					fuelNeeded = calculateSubwarpFuelBurn(userFleets[i], distToTarget + distFromTargetToStarbase);
					cLog(4, `${FleetTimeStamp(userFleets[i].label)} Subwarp cost total: ${fuelNeeded}`);
				}

				const fleetCurrentFuelTank = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].fuelTank, {programId: tokenProgramPK});
				const currentFuel = fleetCurrentFuelTank.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.fuel.toString());
				const currentFuelCnt = currentFuel ? currentFuel.account.data.parsed.info.tokenAmount.uiAmount : 0;
				const fuelReadout = `Fuel: need ${Math.round(fuelNeeded)} / have ${Math.round(currentFuelCnt)}`;
				userFleets[i].scanLastFuelAmount = currentFuelCnt;
				if (currentFuelCnt > fuelNeeded) {
						cLog(1, `${FleetTimeStamp(userFleets[i].label)}`, fuelReadout);
						let moveDist = calculateMovementDistance(fleetCoords, destCoords);
						if (moveDist > 0) {
								diagnostic.schedulerDecision = 'move';
								diagnostic.decisionReason = 'target_coordinates_differ';
								try {
									await handleMovement(i, moveDist, destCoords[0], destCoords[1], isStarbaseAndWarpSubwarp, diagnostic.movement);
								} catch (error) {
									diagnostic.error = sanitizeMovementDiagnosticError(error);
									if (diagnostic.movement.confirmationStatus === 'confirmed' && diagnostic.movement.txSignature) {
										diagnostic.movement.completed = true;
										diagnostic.movement.blockedReason = 'confirmed_movement';
									} else {
										diagnostic.movement.blockedReason = diagnostic.movement.blockedReason || classifyMovementDiagnosticFailure(error, diagnostic.movement);
										return;
									}
								}
								if (diagnostic.movement.alreadyAtTarget) {
									fleetCoords = destCoords.slice(0, 2);
									diagnostic.schedulerDecision = 'scan';
									diagnostic.decisionReason = 'already_at_target';
								} else if (hasConfirmedMovementProof(diagnostic.movement)) {
									moved = true;
									const scanEndsIn = Math.max(0, userFleets[i].scanEnd - Date.now());
									//Clamp the scan end time to the cooldown if it is higher (due to paused scanning)
									userFleets[i].scanEnd = (scanEndsIn > userFleets[i].scanCooldown * 1000 ? userFleets[i].scanCooldown * 1000 : scanEndsIn) + Date.now(); //fixed a wrong time calculation
									diagnostic.persistenceDecision = 'scan_end_write_requested';
									await saveScanEnd(i);
									cLog(1,`${FleetTimeStamp(userFleets[i].label)} Movement finished`);
									userFleets[i].scanStrikes = 0;
								} else {
									return;
								}
						} else {
								cLog(1,`${FleetTimeStamp(userFleets[i].label)} Skipping movement`);
						}
				} else {
					cLog(1, `${FleetTimeStamp(userFleets[i].label)} ${fuelReadout} (low)`);
					diagnostic.movement.blockedReason = 'insufficient_or_invalid_fuel';
					if(globalSettings.scanResupplyOnLowFuel) {
						await handleResupply(i, fleetCoords);
						moved = true;
					} else {
						cLog(3, `${FleetTimeStamp(userFleets[i].label)} Moved:`, moved);
						return;
					}
				}
			}
		}

		if(userFleets[i].stopping) return;

		if (!moved && Date.now() > userFleets[i].scanEnd) {
			userFleets[i].lastScanCoord = userFleets[i].destCoord;
			if(!userFleets[i].scanStrikes) userFleets[i].scanStrikes = 0;
			diagnostic.schedulerDecision = 'scan';
			diagnostic.decisionReason = 'eligible_and_cooldown_elapsed';
			diagnostic.finalScanDecision = 'attempted';
			const scanResult = await execScan(userFleets[i], fleetCoords);
			diagnostic.scanSignature = String(scanResult?.slyaTxHash || scanResult?.signature || '').slice(0, 128);
			const scanSucceeded = Boolean(scanResult && scanResult.meta && !scanResult.meta.err);
			if(!scanSucceeded) {
				diagnostic.finalScanDecision = 'failed';
				const scanError = scanResult?.meta?.err ? JSON.stringify(scanResult.meta.err) : 'no confirmed transaction result';
				userFleets[i].scanSubmissionRetryAt = Date.now() + SCAN_SUBMISSION_RETRY_DELAY_MS;
				const retryAt = TimeToStr(new Date(userFleets[i].scanSubmissionRetryAt));
				cLog(1, `${FleetTimeStamp(userFleets[i].label)} Scan submission failed; retrying at ${retryAt}: ${scanError}`);
				updateFleetState(userFleets[i], `Scan retry [${retryAt}]`);
				return;
			}
			userFleets[i].scanSubmissionRetryAt = 0;
			diagnostic.finalScanDecision = 'confirmed';
			const changesSDU = getBalanceChange(scanResult, userFleets[i].sduToken.toString());
			const changesFood = getBalanceChange(scanResult, userFleets[i].foodToken.toString());
			const scanConditionLog = scanResult && scanResult.meta.logMessages ? scanResult.meta.logMessages.find(item => item.startsWith("Program log: SDU probability:")) : null;
			const scanCondition = scanConditionLog ? (Number(scanConditionLog.split(' ').pop())*100).toFixed(4) : 0;
			userFleets[i].foodCnt = changesFood.postBalance;
			userFleets[i].sduCnt = changesSDU.postBalance;

			let sduFound = 0;
			if (changesSDU.postBalance != changesSDU.preBalance) {
					sduFound = changesSDU.postBalance - changesSDU.preBalance;
					userFleets[i].scanSkipCnt = 0;
			}
			await alterStats('SDUs found',undefined,sduFound,'SDU',0);

			cLog(1,`${FleetTimeStamp(userFleets[i].label)} 📡 ${Math.round(scanCondition)}%${sduFound > 0 ? ` | 💰 FOUND: ${sduFound}` : ''}`);
			if(scanCondition < userFleets[i].scanMin2) {
				userFleets[i].scanStrikes = globalSettings.scanStrikeCount;
				cLog(3,`${FleetTimeStamp(userFleets[i].label)} ⚡⚡️ Instant strike out`);
			} else if(scanCondition < userFleets[i].scanMin3 && sduFound > 0) {
				userFleets[i].scanStrikes = globalSettings.scanStrikeCount;
				cLog(3,`${FleetTimeStamp(userFleets[i].label)} ⚡⚡️ Instant strike out`);
			} else if(scanCondition < userFleets[i].scanMin) {
				userFleets[i].scanStrikes++;
				cLog(3,`${FleetTimeStamp(userFleets[i].label)} ⚡️ Strike ${userFleets[i].scanStrikes} / ${globalSettings.scanStrikeCount}`);
			} else {
				userFleets[i].scanStrikes = 0;
				cLog(3,`${FleetTimeStamp(userFleets[i].label)} 🔙 Strikes reset`);
			}

			const struckOut = userFleets[i].scanStrikes >= globalSettings.scanStrikeCount;
			if(struckOut) {
				cLog(3,`${FleetTimeStamp(userFleets[i].label)} 🔺 Sector struck out`);
				userFleets[i].scanSkipCnt++;
			}

			let scanBlockPattern = globalSettings.scanBlockPattern;
			if(userFleets[i].scanPattern) scanBlockPattern=userFleets[i].scanPattern;

			//Iterate pattern positioning id (or reset to 0 if reached end)
			if(userFleets[i].scanMove && struckOut)
				if(!scanBlockPattern.includes('auto')) {
					userFleets[i].scanBlockIdx = userFleets[i].scanBlockIdx > userFleets[i].scanBlock.length - 2 ? 0 : userFleets[i].scanBlockIdx+1;
				} else {
					await handleScanAutoMovement(i, fleetCoords);
				}

			const needPause =
				(struckOut && !userFleets[i].scanMove) ||
				(userFleets[i].scanMove && userFleets[i].scanSkipCnt >= userFleets[i].scanBlock.length - 1 && !scanBlockPattern.includes('auto'))

			let pauseTelemetryFields = '';
			let pauseDurationSeconds = 0;
            let newState;
			if (needPause) {
				//userFleets[i].scanEnd = Date.now() + (globalSettings.scanPauseTime * 1000);
				const pauseDurationMs = Math.max(globalSettings.scanPauseTime * 1000, userFleets[i].scanCooldown * 1000 + 2000);
				pauseDurationSeconds = Math.ceil(pauseDurationMs / 1000);
				userFleets[i].scanEnd = Date.now() + pauseDurationMs;
				pauseTelemetryFields = `,pauseCount=1i,pauseSeconds=${pauseDurationSeconds}i`;
				//userFleets[i].state = `Scanning Paused [${TimeToStr(new Date(userFleets[i].scanEnd))}]`;
                newState = `Scanning Paused [${TimeToStr(new Date(userFleets[i].scanEnd))}]`;
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Scanning Paused due to low probability [${TimeToStr(new Date(userFleets[i].scanEnd))}]`);
				userFleets[i].scanSkipCnt = 0;
				userFleets[i].scanStrikes = 0;
			} else {
				let scanDelayMs = userFleets[i].scanCooldown * 1000 + 2000;
				if(sduFound) scanDelayMs = Math.max(scanDelayMs, globalSettings.scanSectorRegenTime * 1000);
				userFleets[i].scanEnd = Date.now() + scanDelayMs;
				//userFleets[i].state = `Scanned [${Math.round(scanCondition)}%]${sduFound ? ` +${sduFound}` : ''}`;
                newState = `Scanned [${Math.round(scanCondition)}%]${sduFound ? ` +${sduFound}` : ''}`;
			}

			//updateAssistStatus(userFleets[i]);
            updateFleetState(userFleets[i], newState);

			//Start resupply/unload immediately rather than waiting for scan cooldown
			//if(currentFoodCnt - userFleets[i].scanCost < userFleets[i].scanCost) userFleets[i].scanEnd = Date.now();
			if(((userFleets[i].scanCost == 0) && (userFleets[i].cargoCapacity - cargoCnt - sduFound < userFleets[i].sduPerScan)) || (currentFoodCnt - userFleets[i].scanCost < userFleets[i].scanCost)) userFleets[i].scanEnd = Date.now();

			//save the scan end time, so after a reload the fleet waits accordingly
			await saveScanEnd(i);

			let burnedFood = changesFood.preBalance - changesFood.postBalance;
			const sduStarbaseCoords = ConvertCoords(userFleets[i].starbaseCoord);
			const sduStarbaseContext = await getTelemetryStarbaseContextFromCoords(sduStarbaseCoords[0], sduStarbaseCoords[1]);
			await sendToInflux(`sdu,instance=${influxEscape(getSlyaInfluxInstanceTag())},faction=${influxEscape(getUpgradeAutomationInfluxFactionTag())},starbase=${influxEscape(sduStarbaseContext.starbaseName || 'unknown')},fleet=${influxEscape(userFleets[i].label)},sectorX=${fleetCoords[0]},sectorY=${fleetCoords[1]} amount=${sduFound},burnedFood=${burnedFood},chance=${scanCondition},cargoRoomLeft=${userFleets[i].cargoCapacity - cargoCnt - sduFound}${pauseTelemetryFields}${buildSlyaTxCostInfluxFields(scanResult)}`);
			const completedScanTelemetryState = getScanningOptimizationCompletedScanTelemetryState(userFleets[i]);
			const optimizationResupplyStartedAt = Number(userFleets[i].scanOptimizationResupplyStartedAt || 0);
			const resupplyExcludedSeconds = optimizationResupplyStartedAt > 0 ? Math.max(0, (Date.now() - optimizationResupplyStartedAt) / 1000) : 0;
			sendScanningOptimizationEvent(userFleets[i], 'scan_result', [
				`signature=${optimizationInfluxString(scanResult?.slyaTxHash || '')}`,
				`success=${scanResult && !scanResult?.meta?.err ? 'true' : 'false'}`,
				`durationMs=${Math.round(Number(scanResult?.slyaTxDurationMs || 0))}i`,
				`txFeeLamports=${Math.round(getSlyaTxFeeLamports(scanResult))}i`,
				`txCostSol=${getSlyaTxCostSol(scanResult)}`,
				`error=${optimizationInfluxString(scanResult?.meta?.err ? JSON.stringify(scanResult.meta.err) : '')}`,
				`sduFound=${Number(sduFound || 0)}`,
				`burnedFood=${Number(burnedFood || 0)}`,
				`chance=${Number(scanCondition || 0)}`,
				`cargoRoomLeft=${Number(userFleets[i].cargoCapacity - cargoCnt - sduFound)}`,
				`struckOut=${struckOut ? 'true' : 'false'}`,
				`pauseCount=${needPause ? 1 : 0}i`,
				`pauseSeconds=${pauseDurationSeconds}i`,
				`resupplyExcludedSeconds=${resupplyExcludedSeconds}`,
				`scanStrikes=${Math.round(Number(userFleets[i].scanStrikes || 0))}i`,
				`resultSectorX=${Number(fleetCoords[0] || 0)}`,
				`resultSectorY=${Number(fleetCoords[1] || 0)}`
			].join(','), ',operation=SCAN', scanResult && !scanResult?.meta?.err ? completedScanTelemetryState : null);
			if(scanResult && !scanResult?.meta?.err && optimizationResupplyStartedAt > 0) userFleets[i].scanOptimizationResupplyStartedAt = 0;
			if(scanResult && !scanResult?.meta?.err) await advanceScanningOptimizationAfterCompletedScan(userFleets[i]);

		}
		else if (!moved && Date.now() < userFleets[i].scanEnd && userFleets[i].state == 'Idle') {
			userFleets[i].lastScanCoord = userFleets[i].destCoord;
			const scanCDExpireTimeStr = `[${TimeToStr(new Date(userFleets[i].scanEnd))}]`;
			updateFleetState(userFleets[i], 'Waiting for scan cooldown ' + scanCDExpireTimeStr);
			//await wait(userFleets[i].scanEnd - Date.now());
		}
	}

	function influxEscape(val) {
		return val.replaceAll("\\","\\\\").replaceAll(" ","\\ ").replaceAll(",","\\,").replaceAll("=","\\=");
	}

	function buildInfluxWriteUrl(bucketOverride = '') {
		const rawUrl = String(globalSettings?.influxURL || '').trim();
		const bucket = String(bucketOverride || globalSettings?.influxDB || '').trim();
		if (!rawUrl || !bucket) return rawUrl;
		try {
			const url = new URL(rawUrl);
			const path = String(url.pathname || '').toLowerCase();
			if (path.includes('/api/v3/write')) {
				url.searchParams.set('db', bucket);
			} else if (path.includes('/api/v2/write')) {
				url.searchParams.set('bucket', bucket);
			}
			return url.toString();
		} catch (e) {
			return rawUrl;
		}
	}

	function sanitizeSlyaCostSourceInfluxError(status, statusText, errText) {
		let reason = String(errText || '').trim();
		try { reason = String(JSON.parse(reason)?.message || reason); } catch (e) {}
		const parsePrefix = "unable to parse '";
		if (reason.toLowerCase().startsWith(parsePrefix)) {
			const separator = reason.lastIndexOf("': ");
			reason = separator >= 0 ? `unable to parse: ${reason.slice(separator + 3)}` : 'unable to parse: detail redacted';
		}
		reason = reason
			.replace(/https?:\/\/\S+/gi, '[redacted-url]')
			.replace(/[A-Za-z0-9_-]{24,}/g, '[redacted-id]')
			.replace(/\s+/g, ' ')
			.slice(0, 160);
		return `http=${Number(status) || 0} ${String(statusText || '').replace(/\s+/g, ' ').slice(0, 40)} reason=${reason || 'none'}`.slice(0, 220);
	}

	async function sendToInflux(msg, bucketOverride = '') {
		if(!globalSettings.influxURL.length) return false;
		let message = '';
		let sent = false;
		const flushCostSourceOutbox = !String(bucketOverride || '').trim();
		const ownsCostSourceFlush = flushCostSourceOutbox && !slyaCostSourceFlushInFlight;
		if (ownsCostSourceFlush) slyaCostSourceFlushInFlight = true;
		let costSourceOutbox = null;
		let queuedCostEvents = [];
		try {
			costSourceOutbox = ownsCostSourceFlush ? await loadSlyaCostSourceOutbox() : null;
			queuedCostEvents = ownsCostSourceFlush ? snapshotSlyaCostSourceOutbox(costSourceOutbox) : [];
			const writeBody = queuedCostEvents.length ? composeSlyaScheduledInfluxBody(msg, queuedCostEvents) : msg;
			const queuedFuel = queuedCostEvents.filter(([, record]) => record.line.includes('eventType=fuel')).length;
			const queuedSol = queuedCostEvents.filter(([, record]) => record.line.includes('eventType=sol_fee')).length;
			const oldestPendingSeconds = getSlyaCostSourceOldestPendingAgeSeconds(costSourceOutbox);
			const missingSummary = JSON.stringify(slyaCostSourceMissingCounts);
			cLog(2, 'Sending message to influx:', msg);
			const influxWriteUrl = buildInfluxWriteUrl(bucketOverride);
			if (queuedCostEvents.length) slyaCostSourceCounters.attempted += queuedCostEvents.length;
			const response = await fetch(influxWriteUrl, {
				method: "POST",
				body: writeBody,
				headers: {
					"Authorization": (influxWriteUrl.includes('/v2/') ? "Token " : "Bearer ") + globalSettings.influxAuth
				}
			});
			if (!response.ok) {
				let errText = '';
				try { errText = await response.text(); } catch(e) {}
				message = 'Error while sending a request to influx: ' + response.status + ' ' + response.statusText + (errText ? (' ' + errText.slice(0, 300)) : '');
				upgradeAutomationInfluxDebugStatus = 'http ' + response.status + ' ' + response.statusText + (errText ? (': ' + errText.slice(0, 120)) : '');
				if (ownsCostSourceFlush && queuedCostEvents.length) {
					slyaCostSourceCounters.failed += queuedCostEvents.length;
					deferSlyaCostSourceEventSnapshot(costSourceOutbox, queuedCostEvents, response.headers?.get?.('Retry-After') || '');
					await persistSlyaCostSourceOutbox();
					const rejection = sanitizeSlyaCostSourceInfluxError(response.status, response.statusText, errText);
					await appendUpgradeAutomationLog(`[COST-SOURCE-OUTBOX] eligible=${slyaCostSourceCounters.eligible} queued=${slyaCostSourceCounters.queued} deduplicated=${slyaCostSourceCounters.deduplicated} pending=${costSourceOutbox.size} attempted=${slyaCostSourceCounters.attempted} accepted=${slyaCostSourceCounters.accepted} failed=${slyaCostSourceCounters.failed} batch=${queuedCostEvents.length} fuel=${queuedFuel} sol=${queuedSol} oldestPendingSeconds=${oldestPendingSeconds} ineligible=${missingSummary} rejection=${rejection}`);
					for (const key of Object.keys(slyaCostSourceMissingCounts)) delete slyaCostSourceMissingCounts[key];
				}
			} else {
				message = 'Influx: Request was successful.';
				upgradeAutomationInfluxDebugStatus = 'http ' + response.status + ' ' + response.statusText;
				sent = true;
				if (ownsCostSourceFlush && queuedCostEvents.length) {
					acknowledgeSlyaCostSourceEventSnapshot(costSourceOutbox, queuedCostEvents);
					await persistSlyaCostSourceOutbox();
					slyaCostSourceCounters.accepted += queuedCostEvents.length;
					await appendUpgradeAutomationLog(`[COST-SOURCE-OUTBOX] eligible=${slyaCostSourceCounters.eligible} queued=${slyaCostSourceCounters.queued} deduplicated=${slyaCostSourceCounters.deduplicated} pending=${costSourceOutbox.size} attempted=${slyaCostSourceCounters.attempted} accepted=${slyaCostSourceCounters.accepted} failed=${slyaCostSourceCounters.failed} batch=${queuedCostEvents.length} fuel=${queuedFuel} sol=${queuedSol} oldestPendingSeconds=${oldestPendingSeconds} ineligible=${missingSummary}`);
					for (const key of Object.keys(slyaCostSourceMissingCounts)) delete slyaCostSourceMissingCounts[key];
				}
			}
		} catch(error) {
			message = 'Error while sending a request to influx: ' + error.message;
			upgradeAutomationInfluxDebugStatus = 'fetch error: ' + error.message;
			if (ownsCostSourceFlush && queuedCostEvents.length) {
				slyaCostSourceCounters.failed += queuedCostEvents.length;
				deferSlyaCostSourceEventSnapshot(costSourceOutbox, queuedCostEvents);
				try { await persistSlyaCostSourceOutbox(); } catch (persistError) { cLog(1, 'Cost-source retry state persistence failed', persistError); }
				const rejection = sanitizeSlyaCostSourceInfluxError(0, 'network failure', error?.message || 'unknown');
				await appendUpgradeAutomationLog(`[COST-SOURCE-OUTBOX] eligible=${slyaCostSourceCounters.eligible} queued=${slyaCostSourceCounters.queued} deduplicated=${slyaCostSourceCounters.deduplicated} pending=${costSourceOutbox.size} attempted=${slyaCostSourceCounters.attempted} accepted=${slyaCostSourceCounters.accepted} failed=${slyaCostSourceCounters.failed} batch=${queuedCostEvents.length} fuel=${queuedCostEvents.filter(([, record]) => record.line.includes('eventType=fuel')).length} sol=${queuedCostEvents.filter(([, record]) => record.line.includes('eventType=sol_fee')).length} oldestPendingSeconds=${getSlyaCostSourceOldestPendingAgeSeconds(costSourceOutbox)} ineligible=${JSON.stringify(slyaCostSourceMissingCounts)} rejection=${rejection}`);
				for (const key of Object.keys(slyaCostSourceMissingCounts)) delete slyaCostSourceMissingCounts[key];
			}
		} finally {
			if (ownsCostSourceFlush) slyaCostSourceFlushInFlight = false;
		}
		cLog(2, message);
		return sent;
	}

	async function handleResupply(i, fleetCoords) {
		if(userFleets[i].scanOptimizationEnabled && !Number(userFleets[i].scanOptimizationResupplyStartedAt || 0)) {
			userFleets[i].scanOptimizationResupplyStartedAt = Date.now();
			await saveScanningOptimizationRuntime(userFleets[i], 'scan-optimization-resupply-start');
		}
		const errorWaitTime = 8 * 60 * 1000;
		const errorFuelRatio = 0.75;

		async function unloadSDU() {
			cLog(1,`${FleetTimeStamp(userFleets[i].label)} Unloading SDU`);

			//Get SDU count
			const fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});
			const currentSduCnt = fleetCurrentCargo.value.find(item => item.pubkey.toString() === userFleets[i].sduToken.toString())
			const sduCount = currentSduCnt ? currentSduCnt.account.data.parsed.info.tokenAmount.uiAmount : 0;

			//Unload all but 1 to keep SDU token account open
			if (sduCount > 1) {
				const sduToUnload = sduCount - 1;
				await execCargoFromFleetToStarbase(userFleets[i], userFleets[i].cargoHold, sduItem.token, userFleets[i].starbaseCoord, sduToUnload);
				cLog(2,`${FleetTimeStamp(userFleets[i].label)} Unloaded ${sduToUnload} SDU`);
				userFleets[i].sduCnt = 1;
			}
		}

		async function loadFood() {
			cLog(1,`${FleetTimeStamp(userFleets[i].label)} Loading Food`);

			//Update this just in case it's missing
			//await getAccountInfo(userFleets[i].label, 'fleet repair kit token', userFleets[i].repairKitToken) || await createPDA(userFleets[i].repairKitToken, userFleets[i].cargoHold, new solanaWeb3.PublicKey(toolItem.token), userFleets[i]);

			//Calculate occupied cargo count
			const preLoadCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});
			const preLoadCargoCount = preLoadCargo.value.reduce((n, {account}) => n + account.data.parsed.info.tokenAmount.uiAmount, 0);

			let foodCargoTypeAcct = cargoTypes.find(item => item.account.mint.toString() == sageGameAcct.account.mints.food);
			//Fill remaining cargo with Food
			await execCargoFromStarbaseToFleet(
				userFleets[i],
				userFleets[i].cargoHold,
				userFleets[i].foodToken,
				foodItem.token,
				foodCargoTypeAcct,
				userFleets[i].starbaseCoord,
				userFleets[i].cargoCapacity - preLoadCargoCount
			);

			//Wait for RPC to catch up
			await wait(2000);

			//Update food count
			const foodCargo = await solanaReadConnection.getTokenAccountBalance(userFleets[i].foodToken);
			userFleets[i].foodCnt = foodCargo.value.amount;

			//Was enough food loaded?
			if (userFleets[i].foodCnt < userFleets[i].scanCost) {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: Not enough food at starbase - waiting for more`);
				updateFleetState(userFleets[i], `ERROR: No food ⌛ ${TimeToStr(new Date(Date.now() + errorWaitTime))}`);

				//Wait a while before trying again
				await wait(errorWaitTime);
				await loadFood();
			} else {
				if(userFleets[i].state.includes('ERROR: No food ⌛')) {
					updateFleetState(userFleets[i], `Enough food loaded`, true);
				}
			}
		}

		async function loadFuel() {
			cLog(1,`${FleetTimeStamp(userFleets[i].label)} Refueling`);
			let fleetCurrentFuel = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].fuelTank, {programId: tokenProgramPK});
			let currentFuelCnt = fleetCurrentFuel.value.find(item => item.pubkey.toString() === userFleets[i].fuelToken.toString())

			let fuelCargoTypeAcct = cargoTypes.find(item => item.account.mint.toString() == sageGameAcct.account.mints.fuel);
			await execCargoFromStarbaseToFleet(
				userFleets[i],
				userFleets[i].fuelTank,
				userFleets[i].fuelToken,
				fuelItem.token, fuelCargoTypeAcct,
				userFleets[i].starbaseCoord,
				userFleets[i].fuelCapacity - currentFuelCnt.account.data.parsed.info.tokenAmount.uiAmount
			);

			//Allow rpc to catch up
			await wait(2000);

			//Update fuel count
			fleetCurrentFuel = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].fuelTank, {programId: tokenProgramPK});
			currentFuelCnt = fleetCurrentFuel.value.find(item => item.pubkey.toString() === userFleets[i].fuelToken.toString())
			userFleets[i].fuelCnt = currentFuelCnt.account.data.parsed.info.tokenAmount.uiAmount;

			//Was enough fuel loaded?
			if(userFleets[i].fuelCnt < userFleets[i].fuelCapacity * errorFuelRatio) {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: Not enough fuel at starbase - waiting for more`);
				updateFleetState(userFleets[i], `ERROR: No Fuel ⌛ ${TimeToStr(new Date(Date.now() + errorWaitTime))}`);

				//Wait a while before trying again
				await wait(errorWaitTime);
				await loadFuel();
			} else {
				if(userFleets[i].state.includes('ERROR: No Fuel ⌛')) {
					updateFleetState(userFleets[i], `Enough fuel loaded`, true);
				}
			}
		}

		userFleets[i].resupplying = true;
		if(globalSettings.scanBlockResetAfterResupply) userFleets[i].scanBlockIdx = 0;
		const baseCoords = ConvertCoords(userFleets[i].starbaseCoord);

		if (CoordsEqual(fleetCoords, baseCoords)) { //At starbase
			cLog(1,`${FleetTimeStamp(userFleets[i].label)} Resupply: Docking at starbase`);
			await execDock(userFleets[i], userFleets[i].starbaseCoord);

			updateFleetState(userFleets[i], 'Unloading');
			await unloadSDU();

			updateFleetState(userFleets[i], 'Loading');
			if (userFleets[i].scanCost > 0) await loadFood();
			await loadFuel();

			//Redundancy check to ensure all PDAs are present
			await createScannerPDAs(userFleets[i]);

			//Update last op to prevent fleet stall flagging
			userFleets[i].lastOp = Date.now();

			userFleets[i].scanAutoMoveTo = null;
			userFleets[i].scanStartForcedResupply = false;
			userFleets[i].scanForceResupply = false;
			userFleets[i].scanLastFuelAmount = undefined;

			//Undock
			await execUndock(userFleets[i], userFleets[i].starbaseCoord);
		} else { //Not at starbase - move there
			let moveDist = calculateMovementDistance(fleetCoords, baseCoords);
			if (moveDist > 0 && !userFleets[i].state.includes('Warp C/D')) {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Resupply: Moving to base`);
				updateFleetState(userFleets[i], 'Idle');
				await handleMovement(i, moveDist, baseCoords[0], baseCoords[1]);
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Resupply: Arrived at base`);
			} else {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Resupply: Already at base`);
			}
		}

		userFleets[i].resupplying = false;
	}

	async function handleMining(i, fleetState, fleetCoords, fleetMining) {
		let destX = userFleets[i].destCoord.split(',')[0].trim();
		let destY = userFleets[i].destCoord.split(',')[1].trim();
		let starbaseX = userFleets[i].starbaseCoord.split(',')[0].trim();
		let starbaseY = userFleets[i].starbaseCoord.split(',')[1].trim();
		/*let [mineItem] = await sageProgram.account.mineItem.all([
				{
						memcmp: {
								offset: 105,
								bytes: userFleets[i].mineResource,
						},
				},
		]);*/
        let mineItem = mineItems.find(item => item.account.mint.toString() === userFleets[i].mineResource);
		let resourceHardness = mineItem.account.resourceHardness;
		let planets = await getPlanetsFromCoords(destX, destY);
		let sageResource = null;
		let planet = null;
		for (let planetCheck of planets) {
			/*let resourceCheck = await sageProgram.account.resource.all([
				{
					memcmp: {
						offset: 41,
						bytes: planetCheck.publicKey,
					},
				},
				{
					memcmp: {
						offset: 73,
						bytes: mineItem.publicKey,
					},
				},
			]);*/
            let resourceCheck = await getMineableResourceFromPlanet(planetCheck.publicKey.toString(), mineItem.publicKey.toString());
			if (sageResource === null && resourceCheck && resourceCheck.publicKey) {
				sageResource = resourceCheck;
				planet = planetCheck
			}
		}
		let systemRichness = 0;
		if (sageResource && sageResource.account) {
			systemRichness = sageResource.account.systemRichness;
		} else {
			let resShort = cargoItems.find(r => r.token == userFleets[i].mineResource).name;
			cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: ${resShort} not found at mining location`);
			updateFleetState(userFleets[i], `ERROR: ${resShort} not found at mining location`);
            return;
		}
		// fleet PDA
		let [fleetResourceToken] = await BrowserAnchor.anchor.web3.PublicKey.findProgramAddressSync(
				[
						userFleets[i].cargoHold.toBuffer(),
						tokenProgramPK.toBuffer(),
						new solanaWeb3.PublicKey(userFleets[i].mineResource).toBuffer()
				],
				programPK
		);
		let [fleetFoodToken] = await BrowserAnchor.anchor.web3.PublicKey.findProgramAddressSync(
				[
						userFleets[i].cargoHold.toBuffer(),
						tokenProgramPK.toBuffer(),
						sageGameAcct.account.mints.food.toBuffer()
				],
				programPK
		);
		let [fleetAmmoToken] = await BrowserAnchor.anchor.web3.PublicKey.findProgramAddressSync(
				[
						userFleets[i].ammoBank.toBuffer(),
						tokenProgramPK.toBuffer(),
						sageGameAcct.account.mints.ammo.toBuffer()
				],
				programPK
		);
		let [fleetCargoAmmoToken] = await BrowserAnchor.anchor.web3.PublicKey.findProgramAddressSync(
				[
						userFleets[i].cargoHold.toBuffer(),
						tokenProgramPK.toBuffer(),
						sageGameAcct.account.mints.ammo.toBuffer()
				],
				programPK
		);
		let [fleetFuelToken] = await BrowserAnchor.anchor.web3.PublicKey.findProgramAddressSync(
				[
						userFleets[i].fuelTank.toBuffer(),
						tokenProgramPK.toBuffer(),
						new solanaWeb3.PublicKey(fuelItem.token).toBuffer()
				],
				programPK
		);

		let fleetCurrentFuelTank = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].fuelTank, {programId: tokenProgramPK});
		let currentFuel = fleetCurrentFuelTank.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.fuel.toString());
		let fleetFuelAcct = currentFuel ? currentFuel.pubkey : fleetFuelToken;
		let currentFuelCnt = currentFuel ? currentFuel.account.data.parsed.info.tokenAmount.uiAmount - userFleets[i].exitSubwarpWillBurnFuel : 0;
		let fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});
		//todo: cargoCnt currently assumes that 1 rss always takes 1 of the cargo room
		let cargoCnt = fleetCurrentCargo.value.reduce((n, {account}) => n + account.data.parsed.info.tokenAmount.uiAmount, 0);
		let currentFood = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.food.toString());
		let fleetFoodAcct = currentFood ? currentFood.pubkey : fleetFoodToken;
		let currentFoodCnt = currentFood ? currentFood.account.data.parsed.info.tokenAmount.uiAmount : 0;
		let currentResource = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === userFleets[i].mineResource);
		let fleetResourceAcct = currentResource ? currentResource.pubkey : fleetResourceToken;
		let currentResourceCnt = currentResource ? currentResource.account.data.parsed.info.tokenAmount.uiAmount : 0;
		let fleetCurrentAmmoBank = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].ammoBank, {programId: tokenProgramPK});
		let currentAmmo = fleetCurrentAmmoBank.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.ammo.toString());
		let fleetAmmoAcct = currentAmmo ? currentAmmo.pubkey : fleetAmmoToken;
		let currentAmmoCnt = currentAmmo ? currentAmmo.account.data.parsed.info.tokenAmount.uiAmount : 0;

		let miningDuration = calculateMiningDuration(userFleets[i].cargoCapacity - cargoCnt, userFleets[i].miningRate, resourceHardness, systemRichness);
		let foodForDuration = Math.ceil(miningDuration * (userFleets[i].foodConsumptionRate / 10000));
		let ammoForDuration = Math.ceil(miningDuration * (userFleets[i].ammoConsumptionRate / 10000));
		ammoForDuration = Math.min(userFleets[i].ammoCapacity, ammoForDuration);

		let distToTarget = calculateMovementDistance(fleetCoords, [destX,destY]);
		let distReturn = calculateMovementDistance([destX,destY], [starbaseX,starbaseY]);

		cLog(4, `${FleetTimeStamp(userFleets[i].label)} handleMining -> fleet:`, fleetCoords, `starbase:`, [starbaseX, starbaseY], `target:`, [destX, destY]);

		let isStarbaseAndWarpSubwarp = (userFleets[i].moveType == 'warpsubwarp' && ((fleetCoords[0] == starbaseX && fleetCoords[1] == starbaseY) || (fleetCoords[0] == destX && fleetCoords[1] == destY)));
		let isSourceStarbaseAndWarpSubwarp = (userFleets[i].moveType == 'warpsubwarp' && (fleetCoords[0] == starbaseX && fleetCoords[1] == starbaseY));

		const warpCostToTarget = fleetCoords.length == 2 ? calcWarpFuelReq(userFleets[i], fleetCoords, [destX, destY], isSourceStarbaseAndWarpSubwarp) : 0;
		let warpCost = warpCostToTarget +  calcWarpFuelReq(userFleets[i], [destX, destY], [starbaseX, starbaseY], userFleets[i].moveType == 'warpsubwarp') + userFleets[i].planetExitFuelAmount;
		let halfWarpCost = warpCostToTarget + calculateSubwarpFuelBurn(userFleets[i], distReturn) + userFleets[i].planetExitFuelAmount;
		let subwarpCost = calculateSubwarpFuelBurn(userFleets[i], distToTarget) + calculateSubwarpFuelBurn(userFleets[i], distReturn) + userFleets[i].planetExitFuelAmount;
		let fuelNeeded = userFleets[i].planetExitFuelAmount;
		if (userFleets[i].moveType == 'warp' || userFleets[i].moveType == 'warp-subwarp-warp' || isStarbaseAndWarpSubwarp) {
			fuelNeeded += userFleets[i].fuelCapacity < warpCost ? userFleets[i].fuelCapacity < halfWarpCost ? subwarpCost : halfWarpCost : warpCost;
		} else fuelNeeded += subwarpCost;

		async function handleMineMovement() {
			if (userFleets[i].moveTarget && userFleets[i].moveTarget !== '') {
				let targetX = userFleets[i].moveTarget.split(',').length > 1 ? userFleets[i].moveTarget.split(',')[0].trim() : '';
				let targetY = userFleets[i].moveTarget.split(',').length > 1 ? userFleets[i].moveTarget.split(',')[1].trim() : '';
				let moveDist = calculateMovementDistance(fleetCoords, [targetX,targetY]);
				if (moveDist > 0) {
					let warpCooldownFinished = await handleMovement(i, moveDist, targetX, targetY, isStarbaseAndWarpSubwarp);
				} else {
					cLog(1,`${FleetTimeStamp(userFleets[i].label)} Idle 💤`);
					updateFleetState(userFleets[i], 'Idle');
				}
			} else {
				const msg = 'ERROR: Fleet must start at Target or Starbase';
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Mining - ${msg}`);
				updateFleetState(userFleets[i], msg);
			}
		}

		if(fleetState !== 'Idle') userFleets[i].justResupplied=false;

		//Not mining?
		if (fleetState === 'Idle') {
			let errorResource = [];
			let needSupplies = false;

			//Hard-coded 60 second duration check: no point resuming mining if it'll take less than 1 minute to finish
			if (miningDuration < 60) {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Supplies low, only ${miningDuration} seconds left`);
				needSupplies = true;
			}
			else if (currentFuelCnt < fuelNeeded || currentAmmoCnt < ammoForDuration || currentFoodCnt < foodForDuration) {
				needSupplies = true;
			}

			//sometimes the RPC didn't catch up when we send the combined resupply tx - even after the loop wait time of 10 seconds. So we try to wait another 15+10 seconds if we think that's happening
			if(needSupplies && userFleets[i].justResupplied) {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Fleet just resupplied, but it is trying to resupply again. RPC sync problems? We wait some time to be sure`);
				updateFleetState(userFleets[i], 'Waiting ...');
				await wait(15000);
				updateFleetState(userFleets[i], 'Idle');
				userFleets[i].justResupplied=false;
				return;
			}
			userFleets[i].justResupplied=false;

			let minerSupplySingleTx=globalSettings.minerSupplySingleTx;

			//Needs Resupply?
			if (needSupplies) {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Need resupply`);

				//Recalulate requirements based on total cargo cap
				miningDuration = calculateMiningDuration(userFleets[i].cargoCapacity, userFleets[i].miningRate, resourceHardness, systemRichness);
				foodForDuration = Math.ceil(miningDuration * (userFleets[i].foodConsumptionRate / 10000));
				ammoForDuration = Math.ceil(miningDuration * (userFleets[i].ammoConsumptionRate / 10000));
				ammoForDuration = Math.min(userFleets[i].ammoCapacity, ammoForDuration);

				cLog(2, `${FleetTimeStamp(userFleets[i].label)} Calculated miningDuration: ${miningDuration}`);
				cLog(2, `${FleetTimeStamp(userFleets[i].label)} fuel: ${currentFuelCnt}/${fuelNeeded}`);
				cLog(2, `${FleetTimeStamp(userFleets[i].label)} ammo: ${currentAmmoCnt}/${ammoForDuration}`);
				//cLog(2, `${FleetTimeStamp(userFleets[i].label)} ammoForDuration: ${ammoForDuration} = miningDuration ${miningDuration} * (ammoConsumptionRate ${userFleets[i].ammoConsumptionRate} / 10000)`);
				cLog(2, `${FleetTimeStamp(userFleets[i].label)} food: ${currentFoodCnt}/${foodForDuration}`);

				if (fleetCoords[0] == starbaseX && fleetCoords[1] == starbaseY) {
					let transactions = [];
					let resp = await execDock(userFleets[i], userFleets[i].starbaseCoord, minerSupplySingleTx);
					if(minerSupplySingleTx && resp) {
						transactions.push(resp);
					}
					//await execDock(userFleets[i], userFleets[i].starbaseCoord);
					cLog(1,`${FleetTimeStamp(userFleets[i].label)} Unloading resource`);
					updateFleetState(userFleets[i], `Unloading`);

					let unloadAmount = 0;
					if(globalSettings.minerUnloadsAll) {
						for(let currentRes of fleetCurrentCargo.value) {

							// don't unload food
							if(currentRes.account.data.parsed.info.mint === sageGameAcct.account.mints.food.toString()) continue;

							let amountToUnload = currentRes.account.data.parsed.info.tokenAmount.uiAmount;
							if(globalSettings.minerKeep1 && amountToUnload > 0) { amountToUnload -= 1; }
							if (amountToUnload > 0) {
								resp = await execCargoFromFleetToStarbase(userFleets[i], userFleets[i].cargoHold, currentRes.account.data.parsed.info.mint, userFleets[i].starbaseCoord, amountToUnload, minerSupplySingleTx);
								if(minerSupplySingleTx && resp) {
									transactions.push(resp);
								}
								unloadAmount += amountToUnload;
							}
						}
					}
					else {
						unloadAmount = currentResourceCnt;
						if(globalSettings.minerKeep1 && unloadAmount > 0) { unloadAmount -= 1; }
						if (unloadAmount > 0) {
							resp = await execCargoFromFleetToStarbase(userFleets[i], userFleets[i].cargoHold, userFleets[i].mineResource, userFleets[i].starbaseCoord, unloadAmount, minerSupplySingleTx);
							if(minerSupplySingleTx && resp) {
								transactions.push(resp);
							}
							//await wait(2000);
						}
					}
					if(minerSupplySingleTx && unloadAmount > 0 && transactions.length > 0) {
						cLog(1,`${FleetTimeStamp(userFleets[i].label)} Split bundled miner resupply before loading after cargo unload`);
						updateFleetState(userFleets[i], `Executing resupply tx`);
						await txSliceAndSend(transactions, userFleets[i], 'RESUPPLY', 100, 6);
						transactions = [];
						if(userFleets[i].state.includes('ERROR')) return;
						await wait(1000);
						updateFleetState(userFleets[i], `Loading`);
					}

					//if (currentFuelCnt < userFleets[i].fuelCapacity) {
					if (currentFuelCnt < fuelNeeded) {
						cLog(1,`${FleetTimeStamp(userFleets[i].label)} Loading fuel`);
						updateFleetState(userFleets[i], `Loading`);
						let fuelCargoTypeAcct = cargoTypes.find(item => item.account.mint.toString() == sageGameAcct.account.mints.fuel);
						let fuelResp = await execCargoFromStarbaseToFleet(userFleets[i], userFleets[i].fuelTank, fleetFuelAcct, sageGameAcct.account.mints.fuel.toString(), fuelCargoTypeAcct, userFleets[i].starbaseCoord, userFleets[i].fuelCapacity - currentFuelCnt, globalSettings.fleetForceConsumableAmount, minerSupplySingleTx);
						if (fuelResp && fuelResp.name == 'NotEnoughResource') {
							cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: Not enough fuel`);
							errorResource.push('fuel');
						}
						else if(minerSupplySingleTx && fuelResp.tx) {
							transactions.push(fuelResp.tx);
						}
						//await wait(2000);
					} else { cLog(1,`${FleetTimeStamp(userFleets[i].label)} Fuel loading skipped: ${currentFuelCnt} / ${fuelNeeded}`); }

					if (currentAmmoCnt < ammoForDuration) {
						cLog(1,`${FleetTimeStamp(userFleets[i].label)} Loading ammo`);
						updateFleetState(userFleets[i], `Loading`);
						let ammoCargoTypeAcct = cargoTypes.find(item => item.account.mint.toString() == sageGameAcct.account.mints.ammo);
						let ammoResp = await execCargoFromStarbaseToFleet(userFleets[i], userFleets[i].ammoBank, fleetAmmoAcct, sageGameAcct.account.mints.ammo.toString(), ammoCargoTypeAcct, userFleets[i].starbaseCoord, userFleets[i].ammoCapacity - currentAmmoCnt, globalSettings.fleetForceConsumableAmount, minerSupplySingleTx);
						if (ammoResp && ammoResp.name == 'NotEnoughResource') {
							cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: Not enough ammo`);
							errorResource.push('ammo');
						}
						else if(minerSupplySingleTx && ammoResp.tx) {
							transactions.push(ammoResp.tx);
						}
						//await wait(2000);
					} else { cLog(1,`${FleetTimeStamp(userFleets[i].label)} Ammo loading skipped: ${currentAmmoCnt} / ${ammoForDuration}`); }

					// removed the following block, because we already have all the data, "miningduration" only needs to take the unload amount into account
					/*
					fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});
					cargoCnt = fleetCurrentCargo.value.reduce((n, {account}) => n + account.data.parsed.info.tokenAmount.uiAmount, 0);
					currentFood = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.food.toString());
					fleetFoodAcct = currentFood ? currentFood.pubkey : fleetFoodToken;
					currentFoodCnt = currentFood ? currentFood.account.data.parsed.info.tokenAmount.uiAmount : 0;
					miningDuration = calculateMiningDuration(userFleets[i].cargoCapacity - cargoCnt + currentFoodCnt, userFleets[i].miningRate, resourceHardness, systemRichness);
     					*/
					miningDuration = calculateMiningDuration(userFleets[i].cargoCapacity - cargoCnt + unloadAmount + currentFoodCnt, userFleets[i].miningRate, resourceHardness, systemRichness);
					foodForDuration = Math.ceil(miningDuration * (userFleets[i].foodConsumptionRate / 10000)) + (globalSettings.minerKeep1 ? 1 : 0);
					if (currentFoodCnt < foodForDuration) {
						cLog(1,`${FleetTimeStamp(userFleets[i].label)} Loading food`);
						updateFleetState(userFleets[i], `Loading`);
						let foodCargoTypeAcct = cargoTypes.find(item => item.account.mint.toString() == sageGameAcct.account.mints.food);
						let foodResp = await execCargoFromStarbaseToFleet(userFleets[i], userFleets[i].cargoHold, fleetFoodAcct, sageGameAcct.account.mints.food.toString(), foodCargoTypeAcct, userFleets[i].starbaseCoord, foodForDuration - currentFoodCnt, globalSettings.fleetForceConsumableAmount, minerSupplySingleTx);
						if (foodResp && foodResp.name == 'NotEnoughResource') {
							cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: Not enough food`);
							errorResource.push('food');
						}
						else if(minerSupplySingleTx && foodResp.tx) {
							transactions.push(foodResp.tx);
						}
						//await wait(2000);
					} else { cLog(1,`${FleetTimeStamp(userFleets[i].label)} Food loading skipped: ${currentFoodCnt} / ${foodForDuration}`); }

					updateFleetState(userFleets[i], `Loading`);

					if (errorResource.length > 0) {
						updateFleetState(userFleets[i], `ERROR: Not enough ${errorResource.toString()}`);
						if(globalSettings.emailNotEnoughFFA) await sendEMail(userFleets[i].label + ' not enough ' + errorResource.toString(), '');
					} else {
						//await execUndock(userFleets[i], userFleets[i].starbaseCoord);
						resp = await execUndock(userFleets[i], userFleets[i].starbaseCoord, minerSupplySingleTx);
						if(minerSupplySingleTx && resp) {
							updateFleetState(userFleets[i], `Executing resupply tx`);
							transactions.push(resp);
							//console.log(transactions);
							await txSliceAndSend(transactions, userFleets[i], 'RESUPPLY', 100, 6);
							updateFleetState(userFleets[i], 'Idle');
						}
						userFleets[i].justResupplied=true;
					}
					//await wait(2000);
					//userFleets[i].moveTarget = userFleets[i].destCoord;
				} else {
					if(userFleets[i].stopping) return;
					userFleets[i].moveTarget = userFleets[i].starbaseCoord;
					await handleMineMovement();
				}
			}

			//At mining area?
			else if (fleetCoords[0] == destX && fleetCoords[1] == destY) {
		if(userFleets[i].stopping) return;
                fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});
                cargoCnt = fleetCurrentCargo.value.reduce((n, {account}) => n + account.data.parsed.info.tokenAmount.uiAmount, 0);
                currentFood = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.food.toString());
                fleetFoodAcct = currentFood ? currentFood.pubkey : fleetFoodToken;
                currentFoodCnt = currentFood ? currentFood.account.data.parsed.info.tokenAmount.uiAmount : 0;
                miningDuration = calculateMiningDuration(userFleets[i].cargoCapacity - cargoCnt + currentFoodCnt, userFleets[i].miningRate, resourceHardness, systemRichness);
				await execStartMining(userFleets[i], mineItem, sageResource, planet);
				if (userFleets[i].state.slice(0, 5) !== 'ERROR') updateFleetState(userFleets[i], 'Mine [' + TimeToStr(new Date(Date.now()+(miningDuration * 1000))) + ']')

				//Wait for data to propagate through the RPCs
				await wait(20000);

				//Fetch update mining state from chain
				const fleetAcctInfo = await getAccountInfo(userFleets[i].label, 'full fleet info', userFleets[i].publicKey);
				const [fleetState, extra] = getFleetState(fleetAcctInfo, userFleets[i]);
				cLog(4, `${FleetTimeStamp(userFleets[i].label)} chain fleet state: ${fleetState}`);
				fleetMining = fleetState == 'MineAsteroid' ? extra : null;
			}

			//Move to mining area
			else {
				if(userFleets[i].stopping) return;
				userFleets[i].moveTarget = userFleets[i].destCoord;
				await handleMineMovement();
			}
		}

		if(userFleets[i].stopping) return;

		//Already mining?
		if (userFleets[i].state.slice(0, 4) === 'Mine' && fleetMining) {
            let maxMiningDuration = calculateMiningDuration(userFleets[i].cargoCapacity, userFleets[i].miningRate, resourceHardness, systemRichness);
            let mineTimePassed = (Date.now() / 1000) - fleetMining.start.toNumber();
            let foodConsumed = Math.ceil(mineTimePassed * (userFleets[i].foodConsumptionRate / 10000));
            let ammoConsumed = Math.ceil(mineTimePassed * (userFleets[i].ammoConsumptionRate / 10000));
            let resourceMined = Math.ceil(mineTimePassed * ((userFleets[i].miningRate/10000) * (systemRichness/100)) / (resourceHardness/100));
            let timeFoodRemaining = Math.ceil((currentFoodCnt - foodConsumed) / (userFleets[i].foodConsumptionRate / 10000));
            let timeAmmoRemaining = userFleets[i].ammoConsumptionRate > 0 ? Math.ceil((currentAmmoCnt - ammoConsumed) / (userFleets[i].ammoConsumptionRate / 10000)) : maxMiningDuration;

            //wrong calculation, fixed: we must not subtract the foodConsumed from the simulated cargo space, because the food doesn't exist anymore
            //we instead ignore the food needed for consumption completely

            //let simCurrentCargo = userFleets[i].cargoCapacity - cargoCnt - resourceMined + currentFoodCnt - foodConsumed;
            let foodMaxConsumed = Math.ceil(maxMiningDuration * (userFleets[i].foodConsumptionRate / 10000));
            let simCurrentCargo = userFleets[i].cargoCapacity - cargoCnt - resourceMined + foodMaxConsumed;

            let timeCargoRemaining = calculateMiningDuration(simCurrentCargo, userFleets[i].miningRate, resourceHardness, systemRichness);
            let timeLimit = Math.min(timeFoodRemaining, timeAmmoRemaining, timeCargoRemaining);
            let mineEnd = Date.now()+(timeLimit * 1000);
			userFleets[i].mineEnd = mineEnd;
			updateFleetState(userFleets[i], 'Mine [' + TimeToStr(new Date(mineEnd)) + ']')
			let sageResourceAcctInfo = await sageProgram.account.resource.fetch(fleetMining.resource);
			let mineItem = await sageProgram.account.mineItem.fetch(sageResourceAcctInfo.mineItem);
			if (Date.now() > (mineEnd)) {
				await execStopMining(userFleets[i], fleetMining.resource, sageResourceAcctInfo, sageResourceAcctInfo.mineItem, mineItem.mint);
            }
		}
	}

	function hasTransportManifest(manifest) {
		for (const entry of manifest)
			if(entry.res && entry.amt) return true;

		return false;
	}

	function transportManifestResourceSet(manifest) {
		const resources = new Set();
		for(const entry of manifest || []) {
			if(entry && entry.res && Number(entry.amt || 0) > 0) resources.add(entry.res);
		}
		return resources;
	}

	function transportUnloadLoadOverlap(unloadResult, loadManifest) {
		if(!unloadResult || !Array.isArray(unloadResult.unloadedResources) || unloadResult.unloadedResources.length < 1) return [];
		const loadResources = transportManifestResourceSet(loadManifest);
		return unloadResult.unloadedResources.filter(res => loadResources.has(res));
	}

	async function flushTransportBundle(fleet, transactions, reason, nextState = 'Loading') {
		if(transactions.length < 1) return { transactions, flushed: false };

		cLog(1,`${FleetTimeStamp(fleet.label)} Split bundled load/unload ${reason}`);
		updateFleetState(fleet, 'Exec tx bundle');
		await txSliceAndSend(transactions, fleet, 'LOAD/UNLOAD', 100, 5);
		if(fleet.state.includes('ERROR')) return { transactions: [], flushed: true, error: true };

		await wait(1000);
		if(nextState) updateFleetState(fleet, nextState);
		return { transactions: [], flushed: true };
	}

	async function flushTransportBundleForCargoOverlap(fleet, transactions, unloadResult, loadManifest, splitForAnyFollowup = false) {
		const overlap = transportUnloadLoadOverlap(unloadResult, loadManifest);
		const hasCargoUnload = unloadResult && Array.isArray(unloadResult.unloadedResources) && unloadResult.unloadedResources.length > 0;
		if(transactions.length < 1 || (!splitForAnyFollowup && overlap.length < 1) || (splitForAnyFollowup && !hasCargoUnload && overlap.length < 1)) return { transactions, flushed: false };

		const splitReason = overlap.length > 0 ? `before reloading same cargo: ${overlap.join(', ')}` : 'before loading after cargo unload';
		const result = await flushTransportBundle(fleet, transactions, splitReason, 'Loading');
		if(typeof clearTransportUnloadRetry === 'function') clearTransportUnloadRetry(fleet);
		return result;
	}

	function getParsedTokenAmount(parsedTokenAccounts, mint) {
		const tokenAccount = parsedTokenAccounts.value.find(item => item.account.data.parsed.info.mint === mint);
		return tokenAccount ? tokenAccount.account.data.parsed.info.tokenAmount.uiAmount : 0;
	}

	async function getTransportAmmoBankAmount(fleet) {
		if(!globalSettings.transportUseAmmoBank) return 0;
		const ammoMint = sageGameAcct.account.mints.ammo.toString();
		const fleetCurrentAmmoBank = await solanaReadConnection.getParsedTokenAccountsByOwner(fleet.ammoBank, {programId: tokenProgramPK});
		return getParsedTokenAmount(fleetCurrentAmmoBank, ammoMint);
	}

    async function checkCargo(currentManifest, destinationManifest, fleet) {
        const fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(fleet.cargoHold, {programId: tokenProgramPK});
        const cargoCnt = fleetCurrentCargo.value.reduce((n, {account}) => n + account.data.parsed.info.tokenAmount.uiAmount * cargoItems.find(r => r.token == account.data.parsed.info.mint).size, 0);
		const ammoMint = sageGameAcct.account.mints.ammo.toString();
		const destinationHasAmmo = destinationManifest.some(entry => entry.res === ammoMint && entry.amt > 0);
		const ammoBankAmount = destinationHasAmmo ? await getTransportAmmoBankAmount(fleet) : 0;
        let needToLoad = false;
        let needToUnload = false;
        for (const entry of destinationManifest) {
            if (entry.res && entry.amt > 0) {
                let currentCargoObj = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === entry.res);
                let currentCargoResAmt = currentCargoObj ? currentCargoObj.account.data.parsed.info.tokenAmount.uiAmount : 0;
				if(entry.res === ammoMint) currentCargoResAmt += ammoBankAmount;
                if (currentCargoResAmt < entry.amt) needToLoad = true;
                if (currentCargoResAmt > entry.amt) {
                    needToUnload = true;
                    currentManifest.push({res: entry.res, amt: currentCargoResAmt - entry.amt, extra: true});
                }
            }
        }

        for (const entry of currentManifest) {
            if (entry.res && entry.amt > 0) {
                let currentCargoObj = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === entry.res);
                let currentCargoResAmt = currentCargoObj ? currentCargoObj.account.data.parsed.info.tokenAmount.uiAmount : 0;
                if (currentCargoResAmt > (globalSettings.transportKeep1 ? 1 : 0)) needToUnload = true;
            }
        }

	//we check if the fleet has any cargo which isn't part of the current or destination manifest - to unload it
	if(globalSettings.transportUnloadsUnknownRSS) {
		for(let currentRes of fleetCurrentCargo.value) {
			if(currentManifest.findIndex(item => item.res == currentRes.account.data.parsed.info.mint) < 0 && destinationManifest.findIndex(item => item.res == currentRes.account.data.parsed.info.mint) < 0) {
				let amountToUnload = currentRes.account.data.parsed.info.tokenAmount.uiAmount;
				if(globalSettings.transportKeep1 && amountToUnload > 0) { amountToUnload -= 1; }
				if(amountToUnload > 0) {
					needToUnload = true;
					cLog(3,`${FleetTimeStamp(fleet.label)} Found rss that is not part of any transport manifest, unloading`, amountToUnload, 'of', currentRes.account.data.parsed.info.mint);
					currentManifest.push({res: currentRes.account.data.parsed.info.mint, amt: amountToUnload });
				}
			}
		}
	}

	        return {currentManifest, destinationManifest, needToLoad, needToUnload};
	    }

		async function getTransportRecoveryCargoAmounts(fleet) {
			const cargoAmounts = {};
			const fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(fleet.cargoHold, {programId: tokenProgramPK});
			for(const tokenAccount of fleetCurrentCargo.value) {
				const mint = tokenAccount.account.data.parsed.info.mint;
				const amount = Number(tokenAccount.account.data.parsed.info.tokenAmount.uiAmount || 0);
				if(mint && amount > 0) cargoAmounts[mint] = (cargoAmounts[mint] || 0) + amount;
			}

			if(globalSettings.transportUseAmmoBank) {
				const ammoMint = sageGameAcct.account.mints.ammo.toString();
				const ammoBankAmount = await getTransportAmmoBankAmount(fleet);
				if(ammoBankAmount > 0) cargoAmounts[ammoMint] = (cargoAmounts[ammoMint] || 0) + ammoBankAmount;
			}

			return cargoAmounts;
		}

		function scoreTransportRecoveryManifest(manifest, cargoAmounts) {
			let score = 0;
			const matches = [];
			const keepAmount = globalSettings.transportKeep1 ? 1 : 0;
			for(const entry of manifest || []) {
				if(!entry || !entry.res || !(Number(entry.amt || 0) > 0)) continue;
				const rawAmount = Number(cargoAmounts[entry.res] || 0);
				// A configured keep-one residue is not carried route cargo and must not
				// make both transport directions appear to match after a reload/update.
				const effectiveAmount = Math.max(0, rawAmount - keepAmount);
				if(effectiveAmount <= 0) continue;
				const cargoSize = Number((cargoItems.find(r => r.token == entry.res) || {}).size || 1);
				const matchedAmount = Math.min(effectiveAmount, Number(entry.amt || 0));
				score += matchedAmount * cargoSize;
				matches.push({ res: entry.res, have: rawAmount, effective: effectiveAmount, configured: Number(entry.amt || 0) });
			}
			return { score, matches };
		}

		function hasLoadedTransportCargoForManifest(manifest, cargoAmounts) {
			const configuredEntries = (manifest || []).filter(entry => entry && entry.res && Number(entry.amt || 0) > 0);
			return configuredEntries.length > 0 && configuredEntries.every(entry => {
				return Number(cargoAmounts[entry.res] || 0) >= Number(entry.amt || 0);
			});
		}

		function hasUsefulTransportCargoForManifest(manifest, cargoAmounts) {
			const keepAmount = globalSettings.transportKeep1 ? 1 : 0;
			return (manifest || []).some(entry => {
				if(!entry || !entry.res || !(Number(entry.amt || 0) > 0)) return false;
				return Number(cargoAmounts[entry.res] || 0) > keepAmount;
			});
		}

		async function resumeLoadedTransportDeparture(i, fleetState, fleetCoords, sourceCoord, destCoord, destinationManifest, arrivalManifest, moveType, roundTrip, routeIndex = null, logPrefix = 'Transporting', persistedMoveTarget = '') {
			if(fleetState !== 'Idle' || !CoordsEqual(fleetCoords, ConvertCoords(sourceCoord))) return false;
			const savedTarget = String(userFleets[i].moveTarget || persistedMoveTarget || '').trim();
			if(savedTarget) return false;
			const cargoAmounts = await getTransportRecoveryCargoAmounts(userFleets[i]);
			if(!hasLoadedTransportCargoForManifest(destinationManifest, cargoAmounts)) return false;

			// Recovery may only skip a stop that has nothing left to unload. Cargo for
			// the next leg (especially retained ammo-bank ammunition) is not proof that
			// the arriving leg was already processed. Otherwise a fleet can shuttle
			// forever while carrying passenger crew or inbound cargo through each stop.
			const arrivalCrew = Math.max(0, Math.floor(Number(arrivalManifest?.[0]?.crew || 0)));
			const passengerCrew = Math.max(0, Math.floor(Number(userFleets[i].crewCount || 0) - Number(userFleets[i].requiredCrew || 0)));
			const pendingCrewUnload = arrivalCrew > 0 && passengerCrew > 0;
			const pendingCargoUnload = hasLoadedTransportCargoForManifest(arrivalManifest, cargoAmounts);
			if(pendingCrewUnload || pendingCargoUnload) {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} ${logPrefix} - recovery departure blocked: arriving leg still has ${pendingCrewUnload ? passengerCrew + ' crew' : 'cargo'} to unload`);
				return false;
			}
			const configuredMoveType = moveType;
			if(configuredMoveType == 'automated') {
				userFleets[i].moveType = await resolveAutomatedTravelMode(userFleets[i], destinationManifest);
				userFleets[i].automatedTravelMoveType = userFleets[i].moveType;
			}

			// Loaded cargo proves which leg was prepared, but it does not prove the
			// propulsion tank was filled before the reload/update. Only bypass the
			// normal transport stop when the tank already satisfies that leg's fuel
			// policy. Otherwise fall through so the regular path can refuel locally.
			const fuelData = await getFleetFuelData(
				{ ...userFleets[i], moveType },
				ConvertCoords(sourceCoord),
				ConvertCoords(destCoord),
				roundTrip
			);
			if(fuelData.amount < fuelData.fuelNeeded) {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} ${logPrefix} - cargo is already onboard but fuel is ${fuelData.amount}/${fuelData.fuelNeeded}; resuming normal refuel path`);
				return false;
			}

			const recovery = {
				recovered: true,
				reason: 'loaded_cargo_at_source_after_restart',
				leg: { sourceCoord, destCoord, destinationManifest, moveType: userFleets[i].moveType, configuredMoveType, routeIndex }
			};
			cLog(1,`${FleetTimeStamp(userFleets[i].label)} ${logPrefix} - cargo for ${destCoord} is already onboard; skipping reload`);
			await recoverTransportMovement(i, fleetCoords, recovery, logPrefix);
			return true;
		}

		async function inferTransportRecoveryLeg(fleet, candidates, preferredRouteIndex = null) {
			const cargoAmounts = await getTransportRecoveryCargoAmounts(fleet);
			const scoredCandidates = (candidates || []).map(candidate => {
				const manifestScore = scoreTransportRecoveryManifest(candidate.destinationManifest || candidate.manifest || [], cargoAmounts);
				return { ...candidate, score: manifestScore.score, matches: manifestScore.matches };
			});
			const activeCandidates = scoredCandidates.filter(candidate => candidate.score > 0);

			if(preferredRouteIndex !== null && preferredRouteIndex !== undefined) {
				const preferred = activeCandidates.find(candidate => Number(candidate.routeIndex) === Number(preferredRouteIndex));
				if(preferred) return { recovered: true, reason: 'preferred_route_cargo_match', leg: preferred, cargoAmounts, candidates: scoredCandidates };
				const indexed = scoredCandidates.find(candidate => Number(candidate.routeIndex) === Number(preferredRouteIndex));
				if(indexed) return { recovered: true, reason: activeCandidates.length > 1 ? 'preferred_route_ambiguous_cargo' : 'preferred_route_index', leg: indexed, cargoAmounts, candidates: scoredCandidates };
			}

			if(activeCandidates.length === 1) {
				return { recovered: true, reason: 'single_cargo_match', leg: activeCandidates[0], cargoAmounts, candidates: scoredCandidates };
			}

			return {
				recovered: false,
				reason: activeCandidates.length > 1 ? 'ambiguous_cargo_match' : 'no_cargo_match',
				cargoAmounts,
				candidates: scoredCandidates
			};
		}

		async function recoverTransportMovement(i, fleetCoords, recovery, logPrefix) {
			const leg = recovery && recovery.leg;
			if(!leg || !leg.destCoord) return false;
			let effectiveMoveType = leg.moveType || userFleets[i].moveType;
			const configuredMoveType = leg.configuredMoveType || effectiveMoveType;
			if(effectiveMoveType == 'automated') effectiveMoveType = await resolveAutomatedTravelMode(userFleets[i], leg.destinationManifest || []);
			userFleets[i].moveType = effectiveMoveType;
			await persistFleetTransportRouteState(i, effectiveMoveType, leg.destCoord, leg.routeIndex, configuredMoveType);
			cLog(1,`${FleetTimeStamp(userFleets[i].label)} ${logPrefix} - recovered route to ${leg.destCoord} (${recovery.reason})`);
			const [targetX, targetY] = ConvertCoords(leg.destCoord);
			const moveDist = calculateMovementDistance(fleetCoords, [targetX, targetY]);
			let isStarbaseAndWarpSubwarp = false;
			if((leg.moveType || userFleets[i].moveType) == 'warpsubwarp') {
				const sourceCoords = leg.sourceCoord ? ConvertCoords(leg.sourceCoord) : [];
				const destCoords = leg.destCoord ? ConvertCoords(leg.destCoord) : [];
				isStarbaseAndWarpSubwarp =
					CoordsEqual(fleetCoords, sourceCoords) ||
					CoordsEqual(fleetCoords, destCoords);
			}
			await handleMovement(i, moveDist, targetX, targetY, isStarbaseAndWarpSubwarp);
			return true;
		}

		async function handleCrewUnloading(fleet, starbaseCoords, amount, returnTx) {
	return new Promise(async resolve => {

	    let starbaseX = starbaseCoords.split(',')[0].trim();
	    let starbaseY = starbaseCoords.split(',')[1].trim();
	    let starbase = await getStarbaseFromCoords(starbaseX, starbaseY);
	    let starbasePlayer = await getStarbasePlayer(userProfileAcct,starbase.publicKey);
	    starbasePlayer = starbasePlayer ? starbasePlayer.publicKey : await execRegisterStarbasePlayer(fleet, starbaseCoords);

			let txUnload = { instruction: await sageProgram.methods.unloadFleetCrew({count: new BrowserAnchor.anchor.BN(amount), keyIndex: new BrowserAnchor.anchor.BN(userProfileKeyIdx) }).accountsStrict({
				fleetAndOwner: {
						key: userPublicKey,
						owningProfile: userProfileAcct,
						owningProfileFaction: userProfileFactionAcct.publicKey,
						fleet: fleet.publicKey
				},
				starbaseAndStarbasePlayer: {
					starbase: starbase.publicKey,
					starbasePlayer: starbasePlayer
				},
				gameId: sageGameAcct.publicKey
			}).remainingAccounts([{
					pubkey: starbase.publicKey,
					isSigner: false,
					isWritable: false
			}]).instruction()}
			cLog(1,`${FleetTimeStamp(fleet.label)} Unloading crew`);
			updateFleetState(fleet, 'Unloading crew');
			//let txResult = await txSignAndSend(txUnload, fleet, 'UNLOAD CREW', 100);

			let txResult;
			if(returnTx) {
				txResult = txUnload;
			} else {
				txResult = await txSignAndSend(txUnload, fleet, 'UNLOAD CREW', 100);
			}

			resolve(txResult);
		});
	}
	async function handleCrewLoading(fleet, starbaseCoords, amount, returnTx) {
		return new Promise(async resolve => {

		    let starbaseX = starbaseCoords.split(',')[0].trim();
		    let starbaseY = starbaseCoords.split(',')[1].trim();
		    let starbase = await getStarbaseFromCoords(starbaseX, starbaseY);
		    let starbasePlayer = await getStarbasePlayer(userProfileAcct,starbase.publicKey);
		    starbasePlayer = starbasePlayer ? starbasePlayer.publicKey : await execRegisterStarbasePlayer(fleet, starbaseCoords);

		    let starbasePlayerInfo = await sageProgram.account.starbasePlayer.fetch(starbasePlayer);
		    let availableCrew = starbasePlayerInfo.totalCrew - starbasePlayerInfo.busyCrew.toNumber();
		    cLog(3,`${FleetTimeStamp(fleet.label)} Available crew at starbase:`, availableCrew);
		    if(availableCrew < amount) amount = availableCrew;

		    let txResult;
		    if(amount <= 0) {
				txResult = {name: "NotEnoughCrew"};
		    } else {

			    let txLoad = { instruction: await sageProgram.methods.loadFleetCrew({count: new BrowserAnchor.anchor.BN(amount), keyIndex: new BrowserAnchor.anchor.BN(userProfileKeyIdx) }).accountsStrict({
					fleetAndOwner: {
							key: userPublicKey,
							owningProfile: userProfileAcct,
							owningProfileFaction: userProfileFactionAcct.publicKey,
							fleet: fleet.publicKey
					},
					starbaseAndStarbasePlayer: {
						starbase: starbase.publicKey,
						starbasePlayer: starbasePlayer
					},
					gameId: sageGameAcct.publicKey
			    }).remainingAccounts([{
						pubkey: starbase.publicKey,
						isSigner: false,
						isWritable: false
			    }]).instruction()}
			    cLog(1,`${FleetTimeStamp(fleet.label)} Loading crew`);
			    updateFleetState(fleet, 'Loading crew');
			    //txResult = await txSignAndSend(txLoad, fleet, 'LOAD CREW', 100);
			    if(returnTx) {
			    	txResult = txLoad;
			    } else {
				txResult = await txSignAndSend(txLoad, fleet, 'LOAD CREW', 100);
			    }
		    }

		    resolve(txResult);
		});
	}

	function getLegacyTransportManifestEntry(fleetParsedData, prefix, includeCrew = false, totalContext = {}) {
		const res = fleetParsedData[prefix] || '';
		const amt = fleetParsedData[prefix + 'Perc'] || 0;
		const crew = includeCrew ? (fleetParsedData[prefix + 'Crew'] || 0) : 0;
		const cargoTotalKey = getTransportTotalKey(res, amt, totalContext.sourceCoord, totalContext.destCoord, totalContext.routePrefix);
		const crewTotalKey = getTransportCrewTotalKey(crew, totalContext.sourceCoord, totalContext.destCoord, totalContext.routePrefix);
		return {
			res: res,
			amt: amt,
			crew: crew,
			totalPrefix: prefix,
			cargoTotal: !!fleetParsedData[prefix + 'Total'],
			cargoDispatched: getTransportSavedDispatched(fleetParsedData, prefix + 'Total', prefix + 'Dispatched', prefix + 'TotalKey', cargoTotalKey),
			cargoTotalKey: cargoTotalKey,
			crewTotal: includeCrew && !!fleetParsedData[prefix + 'CrewTotal'],
			crewDispatched: includeCrew ? getTransportSavedDispatched(fleetParsedData, prefix + 'CrewTotal', prefix + 'CrewDispatched', prefix + 'CrewTotalKey', crewTotalKey) : 0,
			crewTotalKey: crewTotalKey
		};
	}

	async function persistLegacyTransportManifestTotals(i, manifest) {
		const fleetPK = userFleets[i].publicKey.toString();
		const fleetSavedData = await GM.getValue(fleetPK, '{}');
		const fleetParsedData = JSON.parse(fleetSavedData);
		for(const entry of manifest) {
			if(!entry || !entry.totalPrefix) continue;
			const prefix = entry.totalPrefix;
			fleetParsedData[prefix + 'Total'] = !!entry.cargoTotal;
			fleetParsedData[prefix + 'Dispatched'] = Math.max(0, Math.floor(Number(entry.cargoDispatched || 0)));
			fleetParsedData[prefix + 'TotalKey'] = entry.cargoTotalKey || getTransportTotalKey(entry.res, entry.amt);
			if(entry.crewTotal || Object.prototype.hasOwnProperty.call(fleetParsedData, prefix + 'CrewTotal')) {
				fleetParsedData[prefix + 'CrewTotal'] = !!entry.crewTotal;
				fleetParsedData[prefix + 'CrewDispatched'] = Math.max(0, Math.floor(Number(entry.crewDispatched || 0)));
				fleetParsedData[prefix + 'CrewTotalKey'] = entry.crewTotalKey || getTransportCrewTotalKey(entry.crew);
			}
		}
		await saveFleetConfig(fleetPK, fleetParsedData, 'transport-config-save');
	}

    async function handleTransport(i, fleetState, fleetCoords) {
        const [destX, destY] = ConvertCoords(userFleets[i].destCoord);
        const [starbaseX, starbaseY] = ConvertCoords(userFleets[i].starbaseCoord);

        const fleetParsedData = JSON.parse(await GM.getValue(userFleets[i].publicKey.toString(), '{}'));
		const configuredMoveType = transportSubwarpPrefToMoveType(fleetParsedData.subwarpPref || 0);
		if(configuredMoveType == 'automated') userFleets[i].moveType = 'warp';
		const targetTotalContext = getLegacyTransportTotalContext('transportResource1', userFleets[i].starbaseCoord, userFleets[i].destCoord);
		const starbaseTotalContext = getLegacyTransportTotalContext('transportSBResource1', userFleets[i].starbaseCoord, userFleets[i].destCoord);
        let targetCargoManifest = [
            getLegacyTransportManifestEntry(fleetParsedData, 'transportResource1', true, targetTotalContext),
            getLegacyTransportManifestEntry(fleetParsedData, 'transportResource2', false, getLegacyTransportTotalContext('transportResource2', userFleets[i].starbaseCoord, userFleets[i].destCoord)),
            getLegacyTransportManifestEntry(fleetParsedData, 'transportResource3', false, getLegacyTransportTotalContext('transportResource3', userFleets[i].starbaseCoord, userFleets[i].destCoord)),
            getLegacyTransportManifestEntry(fleetParsedData, 'transportResource4', false, getLegacyTransportTotalContext('transportResource4', userFleets[i].starbaseCoord, userFleets[i].destCoord)),
        ];
        let starbaseCargoManifest = [
            getLegacyTransportManifestEntry(fleetParsedData, 'transportSBResource1', true, starbaseTotalContext),
            getLegacyTransportManifestEntry(fleetParsedData, 'transportSBResource2', false, getLegacyTransportTotalContext('transportSBResource2', userFleets[i].starbaseCoord, userFleets[i].destCoord)),
            getLegacyTransportManifestEntry(fleetParsedData, 'transportSBResource3', false, getLegacyTransportTotalContext('transportSBResource3', userFleets[i].starbaseCoord, userFleets[i].destCoord)),
            getLegacyTransportManifestEntry(fleetParsedData, 'transportSBResource4', false, getLegacyTransportTotalContext('transportSBResource4', userFleets[i].starbaseCoord, userFleets[i].destCoord)),
        ];
        const hasTargetManifest = hasTransportManifest(targetCargoManifest);
        const hasStarbaseManifest = hasTransportManifest(starbaseCargoManifest);

		if(fleetState === 'Idle' && fleetCoords[0] == starbaseX && fleetCoords[1] == starbaseY) {
			await maybeFinalizeFleetTelemetryCostCycle(userFleets[i], fleetParsedData, getFleetTelemetryHomeStarbaseName(userFleets[i], fleetParsedData), 2);
		}

		// After an app reload/update, moveTarget is not guaranteed to survive in
		// memory. If the fleet is still idle at a route source but already carries
		// meaningful cargo for the departing leg, loading has already completed.
		// Resume movement instead of trying to top up the manifest and ending in
		// "No cargo loaded" when the starbase has nothing further to transfer.
		if(await resumeLoadedTransportDeparture(i, fleetState, fleetCoords, userFleets[i].starbaseCoord, userFleets[i].destCoord, targetCargoManifest, starbaseCargoManifest, userFleets[i].moveType, true, null, 'Transporting', fleetParsedData.moveTarget)) return;
		if(await resumeLoadedTransportDeparture(i, fleetState, fleetCoords, userFleets[i].destCoord, userFleets[i].starbaseCoord, starbaseCargoManifest, targetCargoManifest, userFleets[i].moveType, false, null, 'Transporting', fleetParsedData.moveTarget)) return;

        //let moveDist = calculateMovementDistance([starbaseX,starbaseY], [destX,destY]);
        if (fleetState === 'Idle') {
            // Fleet at starbase?
            if (fleetCoords[0] == starbaseX && fleetCoords[1] == starbaseY) {
                userFleets[i].resupplying = true;

				const targetTotalManifest = cloneTransportManifest(targetCargoManifest);
				let targetLoadManifest = applyTransportTotalRemaining(targetTotalManifest);
                let checkCargoResult = await checkCargo(starbaseCargoManifest, targetLoadManifest, userFleets[i]);
                starbaseCargoManifest = checkCargoResult.currentManifest;
                targetLoadManifest = checkCargoResult.destinationManifest;

		let needToUnloadCrew = 0;
		if((starbaseCargoManifest[0].crew > 0) && (userFleets[i].passengerCapacity > 0) && (userFleets[i].crewCount - userFleets[i].requiredCrew > 0)) {
			needToUnloadCrew = userFleets[i].crewCount - userFleets[i].requiredCrew;
		}
		let needToLoadCrew = 0;
		if((targetLoadManifest[0].crew > 0) && (userFleets[i].passengerCapacity > 0) && ((userFleets[i].requiredCrew + userFleets[i].passengerCapacity - userFleets[i].crewCount - needToUnloadCrew) > 0)) {
			needToLoadCrew = Math.min(userFleets[i].requiredCrew + userFleets[i].passengerCapacity - userFleets[i].crewCount, targetLoadManifest[0].crew);
		}
		logTransportCrewDecision(userFleets[i], 'to target', targetTotalManifest, targetLoadManifest, starbaseCargoManifest, needToLoadCrew, needToUnloadCrew);
		if(starbaseCargoManifest[0].crew > 0 || targetLoadManifest[0].crew > 0) cLog(3, `${FleetTimeStamp(userFleets[i].label)} crew:`, userFleets[i].crewCount, 'passengerCapacity:', userFleets[i].passengerCapacity, 'required crew:', userFleets[i].requiredCrew, 'load:', needToLoadCrew, 'unload:', needToUnloadCrew);

                const fuelData = await getFleetFuelData(userFleets[i], [starbaseX, starbaseY], [destX, destY], true);
		//previously we only checked for "fuelData.fuelNeeded > 0" below, but fuelNeeded is always greater than 0 - it is just the fuel needed for the warp/subwarp.
		//this broke the check if the fleet needs to do the dock/undock sequence and the sequence was always executed
		//We need to explicitly calculate the needed fuel minus the available fuel, just like in handleTransportRefueling()
		const fuelEntry = targetLoadManifest.find(e => e.res === sageGameAcct.account.mints.fuel.toString()) || {amt: 0};
		const totalFuel = fuelData.fuelNeeded + fuelEntry.amt;
		let fuelToAdd = Math.min(fuelData.capacity, totalFuel) - fuelData.amount;
		// Check for "Fuel to 100% for transporters" (roundTrip only = source starbase)
		if(fuelToAdd > 0 && globalSettings.transportFuel100 && fuelToAdd < fuelData.capacity - fuelData.amount) fuelToAdd = fuelData.capacity - fuelData.amount;

		cLog(3,`${FleetTimeStamp(userFleets[i].label)} Fuel needed`, fuelData.fuelNeeded, '/ fuel found', fuelData.amount, '/ fuel to add', fuelToAdd, '/ needToLoad', checkCargoResult.needToLoad, '/ needToUnload', checkCargoResult.needToUnload, '/ needToLoadCrew', needToLoadCrew, '/ needToUnloadCrew', needToUnloadCrew);

                //if (checkCargoResult.needToLoad || checkCargoResult.needToUnload || fuelData.fuelNeeded > 0 || needToLoadCrew || needToUnloadCrew) {
                if (checkCargoResult.needToLoad || checkCargoResult.needToUnload || fuelToAdd > 0 || needToLoadCrew > 0 || needToUnloadCrew > 0) {
                    //await execDock(userFleets[i], userFleets[i].starbaseCoord);
                    let transportLoadUnloadSingleTx=globalSettings.transportLoadUnloadSingleTx;
                    let transactions = [];
                    let unloadedAmountInTransaction = 0;
					let loadedCrew = 0;
					let loadedCargo = {};

                    let resp = await execDock(userFleets[i], userFleets[i].starbaseCoord, transportLoadUnloadSingleTx);
                    if(transportLoadUnloadSingleTx && resp) {
			transactions.push(resp);
                    }

                    if(needToUnloadCrew) {
			resp = await handleCrewUnloading(userFleets[i], userFleets[i].starbaseCoord, needToUnloadCrew, transportLoadUnloadSingleTx);
			if(transportLoadUnloadSingleTx && resp) {
				transactions.push(resp);
			}
                    }
                    if(needToLoadCrew) {
			let crewResp = await handleCrewLoading(userFleets[i], userFleets[i].starbaseCoord, needToLoadCrew, transportLoadUnloadSingleTx);
			if (crewResp && crewResp.name == 'NotEnoughCrew') {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Transporting - WARNING: Not enough crew`);
				updateFleetState(userFleets[i], 'WARNING: Not enough crew');
			}
			else if(transportLoadUnloadSingleTx && crewResp) {
				transactions.push(crewResp);
				loadedCrew = needToLoadCrew;
			} else if(crewResp) {
				loadedCrew = needToLoadCrew;
			}
                    }

                    if (hasStarbaseManifest || checkCargoResult.needToUnload) {
                        resp = await handleTransportUnloading(userFleets[i], userFleets[i].starbaseCoord, starbaseCargoManifest, transportLoadUnloadSingleTx);
                        if(scheduleTransportUnloadRetry(userFleets[i], resp, userFleets[i].starbaseCoord)) {
				userFleets[i].resupplying = false;
				return;
			}
			clearTransportUnloadRetry(userFleets[i]);
                        if(transportLoadUnloadSingleTx) {
				transactions = transactions.concat(resp.transactions);
				unloadedAmountInTransaction = resp.unloadedAmount;
					const splitResult = await flushTransportBundleForCargoOverlap(userFleets[i], transactions, resp, targetLoadManifest, checkCargoResult.needToLoad || fuelToAdd > 0);
				transactions = splitResult.transactions;
				if(splitResult.flushed) {
					unloadedAmountInTransaction = 0;
				}
				if(splitResult.error) {
					userFleets[i].resupplying = false;
					return;
				}
				/*
				if(hasTargetManifest) {
					//if we need to load something, make sure we execute the unload transactions first
					updateFleetState(userFleets[i], 'Exec tx bundle');
					await txSliceAndSend(transactions, userFleets[i], 'LOAD/UNLOAD', 100, 5);
					transactions = [];
				}
    				*/
			}
                    } else cLog(1,`${FleetTimeStamp(userFleets[i].label)} Unloading skipped - No resources specified`);

                    //Refueling at Starbase
                    let refuelResp = await handleTransportRefueling(userFleets[i], userFleets[i].starbaseCoord, [starbaseX, starbaseY], [destX, destY], true, 0, targetLoadManifest, transportLoadUnloadSingleTx);
                    const fuelLoadedThisStop = Math.max(0, Number(refuelResp.alreadyLoaded || 0));
                    if (refuelResp.status === 0) {
                        userFleets[i].state = refuelResp.detail;
                        return;
                    } else if(transportLoadUnloadSingleTx && refuelResp && refuelResp.transactions) {
			transactions = transactions.concat(refuelResp.transactions);
			if(refuelResp.transactions.length > 0) {
				const splitResult = await flushTransportBundle(userFleets[i], transactions, 'after fuel refuel before cargo load/undock', 'Loading');
				transactions = splitResult.transactions;
				if(splitResult.flushed) {
					unloadedAmountInTransaction = 0;
					refuelResp.alreadyLoaded = 0;
				}
				if(splitResult.error) {
					userFleets[i].resupplying = false;
					return;
				}
			}
                    }

                    let fuelIndex = targetLoadManifest.findIndex(e => e.res === sageGameAcct.account.mints.fuel.toString());
                    if (fuelIndex > -1) {
                        targetLoadManifest[fuelIndex].amt = targetLoadManifest[fuelIndex].amt - refuelResp.amount;
                        //when using a combined load tx, we need to take into account the amount loaded into the fuel tank, because the starbase still reports the original amount (otherwise we may get an ix error instead a "NotEnoughResource" error)
                        if(transportLoadUnloadSingleTx && refuelResp.alreadyLoaded) targetLoadManifest[fuelIndex].alreadyLoadedInTransaction = refuelResp.alreadyLoaded;
                    }

                    //Loading at Starbase
                    if (hasTransportManifest(targetLoadManifest)) {
                        const loadedCargoResult = await handleTransportLoading(i, userFleets[i].starbaseCoord, targetLoadManifest, transportLoadUnloadSingleTx, transportLoadUnloadSingleTx ? unloadedAmountInTransaction : 0, fuelLoadedThisStop);
                        cLog(4,`${FleetTimeStamp(userFleets[i].label)} loadedCargo: `, loadedCargoResult.success);
                        if(!loadedCargoResult.success) {
                            //const newFleetState = `ERROR: No more cargo to load`;
                            //cLog(1,`${FleetTimeStamp(userFleets[i].label)} ${newFleetState}`);
                            //userFleets[i].state = newFleetState;
                            cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: Unexpected error on cargo load.`);
                            userFleets[i].resupplying = false;
                            return;
                        } else if(transportLoadUnloadSingleTx) {
                            transactions = transactions.concat(loadedCargoResult.transactions);
				if(loadedCargoResult.transactions.length > 0) {
					const splitResult = await flushTransportBundle(userFleets[i], transactions, 'after cargo load before undock', 'Loading');
					transactions = splitResult.transactions;
					if(splitResult.error) {
						userFleets[i].resupplying = false;
						return;
					}
				}
			}
						loadedCargo = loadedCargoResult.loadedCargo || {};
                    } else cLog(1,`${FleetTimeStamp(userFleets[i].label)} Loading skipped - No resources specified`);

                    let undockResult = await execUndock(userFleets[i], userFleets[i].starbaseCoord, transportLoadUnloadSingleTx);
                    if(transportLoadUnloadSingleTx) {
			updateFleetState(userFleets[i], 'Exec tx bundle');
			transactions.push(undockResult);
			undockResult = await txSliceAndSend(transactions, userFleets[i], 'LOAD/UNLOAD', 100, 5);
			updateFleetState(userFleets[i], 'Idle');
                    }
                    //cLog(4,`${FleetTimeStamp(userFleets[i].label)} userFleets[i]: `, undockResult);
                    let fleetState = await solanaReadConnection.getAccountInfoAndContext(userFleets[i].publicKey, {minContextSlot: undockResult.slot});
					applyTransportLoadedTotals(targetTotalManifest, loadedCargo, loadedCrew);
					await persistLegacyTransportManifestTotals(i, targetTotalManifest);
                }
				if(configuredMoveType == 'automated') {
					userFleets[i].moveType = await resolveAutomatedTravelMode(userFleets[i], targetTotalManifest);
					userFleets[i].automatedTravelMoveType = userFleets[i].moveType;
				}
                userFleets[i].moveTarget = userFleets[i].destCoord;
                userFleets[i].resupplying = false;
                cLog(3,`${FleetTimeStamp(userFleets[i].label)} userFleets[i]: `, userFleets[i]);
            }

            // Fleet at target?
            else if (fleetCoords[0] == destX && fleetCoords[1] == destY) {
                userFleets[i].resupplying = true;

				const starbaseTotalManifest = cloneTransportManifest(starbaseCargoManifest);
				let starbaseLoadManifest = applyTransportTotalRemaining(starbaseTotalManifest);
                let checkCargoResult = await checkCargo(targetCargoManifest, starbaseLoadManifest, userFleets[i]);
                targetCargoManifest = checkCargoResult.currentManifest;
                starbaseLoadManifest = checkCargoResult.destinationManifest;

		let needToUnloadCrew = 0;
		if((targetCargoManifest[0].crew > 0) && (userFleets[i].passengerCapacity > 0) && (userFleets[i].crewCount - userFleets[i].requiredCrew > 0)) {
			needToUnloadCrew = userFleets[i].crewCount - userFleets[i].requiredCrew;
		}
		let needToLoadCrew = 0;
		if((starbaseLoadManifest[0].crew > 0) && (userFleets[i].passengerCapacity > 0) && ((userFleets[i].requiredCrew + userFleets[i].passengerCapacity - userFleets[i].crewCount - needToUnloadCrew) > 0)) {
			needToLoadCrew = Math.min(userFleets[i].requiredCrew + userFleets[i].passengerCapacity - userFleets[i].crewCount, starbaseLoadManifest[0].crew);
		}
		logTransportCrewDecision(userFleets[i], 'to starbase', starbaseTotalManifest, starbaseLoadManifest, targetCargoManifest, needToLoadCrew, needToUnloadCrew);
		if(starbaseLoadManifest[0].crew > 0 || targetCargoManifest[0].crew > 0) cLog(3, `${FleetTimeStamp(userFleets[i].label)} crew:`, userFleets[i].crewCount, 'passengerCapacity:', userFleets[i].passengerCapacity, 'required crew:', userFleets[i].requiredCrew, 'load:', needToLoadCrew, 'unload:', needToUnloadCrew);

                const fuelData = await getFleetFuelData(userFleets[i], [destX, destY], [starbaseX, starbaseY], false);
		//previously we only checked for "fuelData.fuelNeeded > 0" below, but fuelNeeded is always greater than 0 - it is just the fuel needed for the warp/subwarp.
		//We need to explicitly calculate the needed fuel minus the available fuel, just like in handleTransportRefueling()
		const fuelEntry = starbaseLoadManifest.find(e => e.res === sageGameAcct.account.mints.fuel.toString()) || {amt: 0};
		const totalFuel = fuelData.fuelNeeded + fuelEntry.amt;
		let fuelToAdd = Math.min(fuelData.capacity, totalFuel) - fuelData.amount;

		cLog(3,`${FleetTimeStamp(userFleets[i].label)} Fuel needed`, fuelData.fuelNeeded, '/ fuel found', fuelData.amount, '/ fuel to add', fuelToAdd, '/ needToLoad', checkCargoResult.needToLoad, '/ needToUnload', checkCargoResult.needToUnload, '/ needToLoadCrew', needToLoadCrew, '/ needToUnloadCrew', needToUnloadCrew);

                if (checkCargoResult.needToLoad || checkCargoResult.needToUnload || fuelToAdd > 0 || needToLoadCrew > 0 || needToUnloadCrew > 0) {
                    //await execDock(userFleets[i], userFleets[i].destCoord);
                    let transportLoadUnloadSingleTx=globalSettings.transportLoadUnloadSingleTx;
                    let transactions = [];
                    let unloadedAmountInTransaction = 0;
					let loadedCrew = 0;
					let loadedCargo = {};

                    let resp = await execDock(userFleets[i], userFleets[i].destCoord, transportLoadUnloadSingleTx);
                    if(transportLoadUnloadSingleTx && resp) {
			transactions.push(resp);
                    }

                    if(needToUnloadCrew) {
			resp = await handleCrewUnloading(userFleets[i], userFleets[i].destCoord, needToUnloadCrew, transportLoadUnloadSingleTx);
			if(transportLoadUnloadSingleTx && resp) {
				transactions.push(resp);
			}
                    }
                    if(needToLoadCrew) {
			let crewResp = await handleCrewLoading(userFleets[i], userFleets[i].destCoord, needToLoadCrew, transportLoadUnloadSingleTx);
			if (crewResp && crewResp.name == 'NotEnoughCrew') {
				cLog(1,`${FleetTimeStamp(userFleets[i].label)} Transporting - WARNING: Not enough crew`);
				updateFleetState(userFleets[i], 'WARNING: Not enough crew');
			} else if(transportLoadUnloadSingleTx && crewResp) {
				transactions.push(crewResp);
				loadedCrew = needToLoadCrew;
			} else if(crewResp) {
				loadedCrew = needToLoadCrew;
			}
                    }

                    //Unloading at Target
                    let fuelUnloadDeficit = 0; //How far short of the manifest was the amount of fuel unloaded?
                    if (hasTargetManifest || checkCargoResult.needToUnload) {
                        const unloadResult = await handleTransportUnloading(userFleets[i], userFleets[i].destCoord, targetCargoManifest, transportLoadUnloadSingleTx);
                        fuelUnloadDeficit = unloadResult.fuelUnloadDeficit;
                        if(scheduleTransportUnloadRetry(userFleets[i], unloadResult, userFleets[i].destCoord)) {
				userFleets[i].resupplying = false;
				return;
			}
			clearTransportUnloadRetry(userFleets[i]);
                        if(transportLoadUnloadSingleTx) {
				transactions = transactions.concat(unloadResult.transactions);
				unloadedAmountInTransaction = unloadResult.unloadedAmount;
					const splitResult = await flushTransportBundleForCargoOverlap(userFleets[i], transactions, unloadResult, starbaseLoadManifest, checkCargoResult.needToLoad || fuelToAdd > 0);
				transactions = splitResult.transactions;
				if(splitResult.flushed) unloadedAmountInTransaction = 0;
				if(splitResult.error) {
					userFleets[i].resupplying = false;
					return;
				}
				/*
				if(hasStarbaseManifest) {
					//if we need to load something, make sure we execute the unload transactions first
					updateFleetState(userFleets[i], 'Exec tx bundle');
					await txSliceAndSend(transactions, userFleets[i], 'LOAD/UNLOAD', 100, 5);
					transactions = [];
				}
    				*/
			}
                    } else cLog(1,`${FleetTimeStamp(userFleets[i].label)} Unloading skipped - No resources specified`);

                    //Refueling at Target
                    let refuelResp = await handleTransportRefueling(userFleets[i], userFleets[i].destCoord, [destX, destY], [starbaseX, starbaseY], false, fuelUnloadDeficit, starbaseLoadManifest, transportLoadUnloadSingleTx);
                    const fuelLoadedThisStop = Math.max(0, Number(refuelResp.alreadyLoaded || 0));
                    if (refuelResp.status === 0) {
                        userFleets[i].state = refuelResp.detail;
                        return;
                    } else if(transportLoadUnloadSingleTx && refuelResp && refuelResp.transactions) {
			transactions = transactions.concat(refuelResp.transactions);
			if(refuelResp.transactions.length > 0) {
				const splitResult = await flushTransportBundle(userFleets[i], transactions, 'after fuel refuel before cargo load/undock', 'Loading');
				transactions = splitResult.transactions;
				if(splitResult.flushed) {
					unloadedAmountInTransaction = 0;
					refuelResp.alreadyLoaded = 0;
				}
				if(splitResult.error) {
					userFleets[i].resupplying = false;
					return;
				}
			}
                    }

                    let fuelIndex = starbaseLoadManifest.findIndex(e => e.res === sageGameAcct.account.mints.fuel.toString());
                    if (fuelIndex > -1) {
                        starbaseLoadManifest[fuelIndex].amt = starbaseLoadManifest[fuelIndex].amt - refuelResp.amount;
                    }

                    //Loading at Target
                    if(hasTransportManifest(starbaseLoadManifest)) {
                        const loadedCargoResult = await handleTransportLoading(i, userFleets[i].destCoord, starbaseLoadManifest, transportLoadUnloadSingleTx, transportLoadUnloadSingleTx ? unloadedAmountInTransaction : 0, fuelLoadedThisStop);
                        cLog(4,`${FleetTimeStamp(userFleets[i].label)} loadedCargo: `, loadedCargoResult.success);
                        if(!loadedCargoResult.success) {
                            //const newFleetState = `ERROR: No more cargo to load`;
                            //cLog(1,`${FleetTimeStamp(userFleets[i].label)} ${newFleetState}`);
                            //userFleets[i].state = newFleetState;
                            cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: Unexpected error on cargo load.`);
                            userFleets[i].resupplying = false;
                            return;
                        } else if(transportLoadUnloadSingleTx) {
				transactions = transactions.concat(loadedCargoResult.transactions);
				if(loadedCargoResult.transactions.length > 0) {
					const splitResult = await flushTransportBundle(userFleets[i], transactions, 'after cargo load before undock', 'Loading');
					transactions = splitResult.transactions;
					if(splitResult.error) {
						userFleets[i].resupplying = false;
						return;
					}
				}
			}
			loadedCargo = loadedCargoResult.loadedCargo || {};
                    } else cLog(1,`${FleetTimeStamp(userFleets[i].label)} Loading skipped - No resources specified`);

                    let undockResult = await execUndock(userFleets[i], userFleets[i].destCoord, transportLoadUnloadSingleTx);
                    if(transportLoadUnloadSingleTx) {
			transactions.push(undockResult);
			updateFleetState(userFleets[i], 'Exec tx bundle');
			undockResult = await txSliceAndSend(transactions, userFleets[i], 'LOAD/UNLOAD', 100, 5);
			updateFleetState(userFleets[i], 'Idle');
                    }
                    //cLog(4,`${FleetTimeStamp(userFleets[i].label)} userFleets[i]: `, undockResult);
                    let fleetState = await solanaReadConnection.getAccountInfoAndContext(userFleets[i].publicKey, {minContextSlot: undockResult.slot});
					applyTransportLoadedTotals(starbaseTotalManifest, loadedCargo, loadedCrew);
					await persistLegacyTransportManifestTotals(i, starbaseTotalManifest);
                }
				if(configuredMoveType == 'automated') {
					userFleets[i].moveType = await resolveAutomatedTravelMode(userFleets[i], starbaseTotalManifest);
					userFleets[i].automatedTravelMoveType = userFleets[i].moveType;
				}
                userFleets[i].moveTarget = userFleets[i].starbaseCoord;
                userFleets[i].resupplying = false;
                cLog(3,`${FleetTimeStamp(userFleets[i].label)} userFleets[i]: `, userFleets[i]);
            }

            if(userFleets[i].stopping) return;

			const savedMoveTarget = typeof fleetParsedData.moveTarget === 'string' ? fleetParsedData.moveTarget.trim() : '';
			const currentMoveTarget = typeof userFleets[i].moveTarget === 'string' ? userFleets[i].moveTarget.trim() : '';
			// Persisted route state is the strongest recovery signal. Prefer it over
			// cargo inference (and over a stale in-memory target) when it is valid.
			const activeMoveTarget = CoordsValid(ConvertCoords(savedMoveTarget))
				? savedMoveTarget
				: (CoordsValid(ConvertCoords(currentMoveTarget)) ? currentMoveTarget : '');
	            if (activeMoveTarget !== '') {
				userFleets[i].moveTarget = activeMoveTarget;
	                const targetX = activeMoveTarget.split(',').length > 1 ? activeMoveTarget.split(',')[0].trim() : '';
	                const targetY = activeMoveTarget.split(',').length > 1 ? activeMoveTarget.split(',')[1].trim() : '';
	                const moveDist = calculateMovementDistance(fleetCoords, [targetX,targetY]);
			let isStarbaseAndWarpSubwarp = userFleets[i].moveType == 'warpsubwarp' && ((fleetCoords[0] == starbaseX && fleetCoords[1] == starbaseY) || (fleetCoords[0] == destX && fleetCoords[1] == destY));
	                await handleMovement(i, moveDist, targetX, targetY, isStarbaseAndWarpSubwarp);
	            } else {
					const recovery = await inferTransportRecoveryLeg(userFleets[i], [
						{
							label: 'to target',
							sourceCoord: userFleets[i].starbaseCoord,
							destCoord: userFleets[i].destCoord,
							moveType: userFleets[i].moveType,
							routeIndex: null,
							destinationManifest: targetCargoManifest
						},
						{
							label: 'to starbase',
							sourceCoord: userFleets[i].destCoord,
							destCoord: userFleets[i].starbaseCoord,
							moveType: userFleets[i].moveType,
							routeIndex: null,
							destinationManifest: starbaseCargoManifest
						}
					]);
					if(recovery.recovered) {
						await recoverTransportMovement(i, fleetCoords, recovery, 'Transporting');
					} else {
						cLog(1,`${FleetTimeStamp(userFleets[i].label)} Transporting - ERROR: Fleet must start at Target or Starbase (${recovery.reason})`);
						updateFleetState(userFleets[i], 'ERROR: Fleet must start at Target or Starbase');
					}
	            }
	        }
	    }

	function getTransportPlusLegs(fleetParsedData, starbaseCoord, target1Coord) {
		const transportPlusTargets = getTransportPlusTargets(fleetParsedData, target1Coord);
		if(transportPlusTargets.length < 1) return [];
		const transportPlusRouteContexts = getTransportPlusRouteContexts(starbaseCoord, transportPlusTargets);
		const transportPlusRoutes = getTransportPlusRoutes(fleetParsedData, transportPlusTargets.length + 1, transportPlusRouteContexts);
		const transportPlusLegs = [];

		for(let routeIndex=0; routeIndex<transportPlusRoutes.length; routeIndex++) {
			const sourceCoord = routeIndex === 0 ? starbaseCoord : transportPlusTargets[routeIndex - 1];
			const destCoord = routeIndex < transportPlusTargets.length ? transportPlusTargets[routeIndex] : starbaseCoord;
			const previousRouteIndex = routeIndex === 0 ? transportPlusRoutes.length - 1 : routeIndex - 1;
			transportPlusLegs.push({
				routeIndex: routeIndex,
				sourceCoord: sourceCoord,
				destCoord: destCoord,
				currentManifest: cloneTransportManifest(transportPlusRoutes[previousRouteIndex].manifest),
				destinationManifest: cloneTransportManifest(transportPlusRoutes[routeIndex].manifest),
				moveType: transportPlusRoutes[routeIndex].moveType,
				roundTrip: routeIndex === 0
			});
		}

		return transportPlusLegs;
	}

	async function persistTransportPlusRouteManifestTotals(i, routeIndex, manifest) {
		if(routeIndex === null || routeIndex === undefined) return;
		const fleetPK = userFleets[i].publicKey.toString();
		const fleetSavedData = await GM.getValue(fleetPK, '{}');
		const fleetParsedData = JSON.parse(fleetSavedData);
		if(!Array.isArray(fleetParsedData.transportPlusRoutes) || !fleetParsedData.transportPlusRoutes[routeIndex]) return;
		const routeManifest = Array.isArray(fleetParsedData.transportPlusRoutes[routeIndex].manifest) ? fleetParsedData.transportPlusRoutes[routeIndex].manifest : [];
		for(let entryIndex=0; entryIndex<manifest.length; entryIndex++) {
			const sourceEntry = manifest[entryIndex] || {};
			const targetEntry = routeManifest[entryIndex] || {};
			if(sourceEntry.cargoTotal) {
				targetEntry.res = sourceEntry.res || targetEntry.res || '';
				targetEntry.amt = Math.max(0, Math.floor(Number(sourceEntry.amt || 0)));
			}
			targetEntry.cargoTotal = !!sourceEntry.cargoTotal;
			targetEntry.cargoDispatched = Math.max(0, Math.floor(Number(sourceEntry.cargoDispatched || 0)));
			targetEntry.cargoTotalKey = sourceEntry.cargoTotalKey || getTransportTotalKey(sourceEntry.res, sourceEntry.amt);
			if(sourceEntry.crewTotal) {
				targetEntry.crew = Math.max(0, Math.floor(Number(sourceEntry.crew || 0)));
			}
			targetEntry.crewTotal = !!sourceEntry.crewTotal;
			targetEntry.crewDispatched = Math.max(0, Math.floor(Number(sourceEntry.crewDispatched || 0)));
			targetEntry.crewTotalKey = sourceEntry.crewTotalKey || getTransportCrewTotalKey(sourceEntry.crew);
			routeManifest[entryIndex] = targetEntry;
		}
		fleetParsedData.transportPlusRoutes[routeIndex].manifest = routeManifest;
		await saveFleetConfig(fleetPK, fleetParsedData, 'transport-routes-save');
	}

	async function handleTransportStop(i, sourceCoord, destCoord, currentManifest, destinationManifest, moveType, roundTrip, routeIndex = null) {
		const sourceCoords = ConvertCoords(sourceCoord);
		const destCoords = ConvertCoords(destCoord);
		const configuredMoveType = moveType;
		userFleets[i].moveType = configuredMoveType == 'automated' ? 'warp' : configuredMoveType;
		userFleets[i].resupplying = true;

		let sourceCargoManifest = cloneTransportManifest(currentManifest);
		const destinationTotalManifest = cloneTransportManifest(destinationManifest);
		let destinationCargoManifest = applyTransportTotalRemaining(destinationTotalManifest);
		const hasSourceManifest = hasTransportManifest(sourceCargoManifest);
		const hasDestinationManifest = hasTransportManifest(destinationCargoManifest);

		let checkCargoResult = await checkCargo(sourceCargoManifest, destinationCargoManifest, userFleets[i]);
		sourceCargoManifest = checkCargoResult.currentManifest;
		destinationCargoManifest = checkCargoResult.destinationManifest;

		let needToUnloadCrew = 0;
		if((sourceCargoManifest[0].crew > 0) && (userFleets[i].passengerCapacity > 0) && (userFleets[i].crewCount - userFleets[i].requiredCrew > 0)) {
			needToUnloadCrew = userFleets[i].crewCount - userFleets[i].requiredCrew;
		}
		let needToLoadCrew = 0;
		if((destinationCargoManifest[0].crew > 0) && (userFleets[i].passengerCapacity > 0) && ((userFleets[i].requiredCrew + userFleets[i].passengerCapacity - userFleets[i].crewCount - needToUnloadCrew) > 0)) {
			needToLoadCrew = Math.min(userFleets[i].requiredCrew + userFleets[i].passengerCapacity - userFleets[i].crewCount, destinationCargoManifest[0].crew);
		}
		logTransportCrewDecision(userFleets[i], `${sourceCoord} -> ${destCoord}`, destinationTotalManifest, destinationCargoManifest, sourceCargoManifest, needToLoadCrew, needToUnloadCrew);
		if(sourceCargoManifest[0].crew > 0 || destinationCargoManifest[0].crew > 0) cLog(3, `${FleetTimeStamp(userFleets[i].label)} crew:`, userFleets[i].crewCount, 'passengerCapacity:', userFleets[i].passengerCapacity, 'required crew:', userFleets[i].requiredCrew, 'load:', needToLoadCrew, 'unload:', needToUnloadCrew);

		const fuelData = await getFleetFuelData(userFleets[i], sourceCoords, destCoords, roundTrip);
		const fuelEntry = destinationCargoManifest.find(e => e.res === sageGameAcct.account.mints.fuel.toString()) || {amt: 0};
		const totalFuel = fuelData.fuelNeeded + fuelEntry.amt;
		let fuelToAdd = Math.min(fuelData.capacity, totalFuel) - fuelData.amount;
		if(fuelToAdd > 0 && globalSettings.transportFuel100 && roundTrip && fuelToAdd < fuelData.capacity - fuelData.amount) fuelToAdd = fuelData.capacity - fuelData.amount;

		cLog(3,`${FleetTimeStamp(userFleets[i].label)} Fuel needed`, fuelData.fuelNeeded, '/ fuel found', fuelData.amount, '/ fuel to add', fuelToAdd, '/ needToLoad', checkCargoResult.needToLoad, '/ needToUnload', checkCargoResult.needToUnload, '/ needToLoadCrew', needToLoadCrew, '/ needToUnloadCrew', needToUnloadCrew);

		if (checkCargoResult.needToLoad || checkCargoResult.needToUnload || fuelToAdd > 0 || needToLoadCrew > 0 || needToUnloadCrew > 0) {
			let transportLoadUnloadSingleTx=globalSettings.transportLoadUnloadSingleTx;
			let transactions = [];
			let unloadedAmountInTransaction = 0;
			let loadedCrew = 0;
			let loadedCargo = {};

			let resp = await execDock(userFleets[i], sourceCoord, transportLoadUnloadSingleTx);
			if(transportLoadUnloadSingleTx && resp) {
				transactions.push(resp);
			}

			if(needToUnloadCrew) {
				resp = await handleCrewUnloading(userFleets[i], sourceCoord, needToUnloadCrew, transportLoadUnloadSingleTx);
				if(transportLoadUnloadSingleTx && resp) {
					transactions.push(resp);
				}
			}
			if(needToLoadCrew) {
				let crewResp = await handleCrewLoading(userFleets[i], sourceCoord, needToLoadCrew, transportLoadUnloadSingleTx);
				if (crewResp && crewResp.name == 'NotEnoughCrew') {
					cLog(1,`${FleetTimeStamp(userFleets[i].label)} Transporting - WARNING: Not enough crew`);
					updateFleetState(userFleets[i], 'WARNING: Not enough crew');
				} else if(transportLoadUnloadSingleTx && crewResp) {
					transactions.push(crewResp);
					loadedCrew = needToLoadCrew;
				} else if(crewResp) {
					loadedCrew = needToLoadCrew;
				}
			}

			let fuelUnloadDeficit = 0;
			if (hasSourceManifest || checkCargoResult.needToUnload) {
				const unloadResult = await handleTransportUnloading(userFleets[i], sourceCoord, sourceCargoManifest, transportLoadUnloadSingleTx);
				fuelUnloadDeficit = unloadResult.fuelUnloadDeficit;
				if(scheduleTransportUnloadRetry(userFleets[i], unloadResult, sourceCoord)) {
					userFleets[i].resupplying = false;
					return false;
				}
				clearTransportUnloadRetry(userFleets[i]);
				if(transportLoadUnloadSingleTx) {
					transactions = transactions.concat(unloadResult.transactions);
					unloadedAmountInTransaction = unloadResult.unloadedAmount;
					const splitResult = await flushTransportBundleForCargoOverlap(userFleets[i], transactions, unloadResult, destinationCargoManifest, checkCargoResult.needToLoad || fuelToAdd > 0);
					transactions = splitResult.transactions;
					if(splitResult.flushed) {
						unloadedAmountInTransaction = 0;
					}
					if(splitResult.error) {
						userFleets[i].resupplying = false;
						return false;
					}
				}
			} else cLog(1,`${FleetTimeStamp(userFleets[i].label)} Unloading skipped - No resources specified`);

			let refuelResp = await handleTransportRefueling(userFleets[i], sourceCoord, sourceCoords, destCoords, roundTrip, roundTrip ? 0 : fuelUnloadDeficit, destinationCargoManifest, transportLoadUnloadSingleTx);
			const fuelLoadedThisStop = Math.max(0, Number(refuelResp.alreadyLoaded || 0));
			if (refuelResp.status === 0) {
				userFleets[i].state = refuelResp.detail;
				return false;
			} else if(transportLoadUnloadSingleTx && refuelResp && refuelResp.transactions) {
				transactions = transactions.concat(refuelResp.transactions);
				if(refuelResp.transactions.length > 0) {
					const splitResult = await flushTransportBundle(userFleets[i], transactions, 'after fuel refuel before cargo load/undock', 'Loading');
					transactions = splitResult.transactions;
					if(splitResult.flushed) {
						unloadedAmountInTransaction = 0;
						refuelResp.alreadyLoaded = 0;
					}
					if(splitResult.error) {
						userFleets[i].resupplying = false;
						return false;
					}
				}
			}

			let fuelIndex = destinationCargoManifest.findIndex(e => e.res === sageGameAcct.account.mints.fuel.toString());
			if (fuelIndex > -1) {
				destinationCargoManifest[fuelIndex].amt = destinationCargoManifest[fuelIndex].amt - refuelResp.amount;
				if(transportLoadUnloadSingleTx && refuelResp.alreadyLoaded) destinationCargoManifest[fuelIndex].alreadyLoadedInTransaction = refuelResp.alreadyLoaded;
			}

			if(hasDestinationManifest) {
				const loadedCargoResult = await handleTransportLoading(i, sourceCoord, destinationCargoManifest, transportLoadUnloadSingleTx, transportLoadUnloadSingleTx ? unloadedAmountInTransaction : 0, fuelLoadedThisStop);
				cLog(4,`${FleetTimeStamp(userFleets[i].label)} loadedCargo: `, loadedCargoResult.success);
				if(!loadedCargoResult.success) {
					cLog(1,`${FleetTimeStamp(userFleets[i].label)} ERROR: Unexpected error on cargo load.`);
					userFleets[i].resupplying = false;
					return false;
				} else if(transportLoadUnloadSingleTx) {
					transactions = transactions.concat(loadedCargoResult.transactions);
					if(loadedCargoResult.transactions.length > 0) {
						const splitResult = await flushTransportBundle(userFleets[i], transactions, 'after cargo load before undock', 'Loading');
						transactions = splitResult.transactions;
						if(splitResult.error) {
							userFleets[i].resupplying = false;
							return false;
						}
					}
				}
				loadedCargo = loadedCargoResult.loadedCargo || {};
			} else cLog(1,`${FleetTimeStamp(userFleets[i].label)} Loading skipped - No resources specified`);

			let undockResult = await execUndock(userFleets[i], sourceCoord, transportLoadUnloadSingleTx);
			if(transportLoadUnloadSingleTx) {
				updateFleetState(userFleets[i], 'Exec tx bundle');
				transactions.push(undockResult);
				undockResult = await txSliceAndSend(transactions, userFleets[i], 'LOAD/UNLOAD', 100, 5);
				updateFleetState(userFleets[i], 'Idle');
			}
			let fleetState = await solanaReadConnection.getAccountInfoAndContext(userFleets[i].publicKey, {minContextSlot: undockResult.slot});
			applyTransportLoadedTotals(destinationTotalManifest, loadedCargo, loadedCrew);
			await persistTransportPlusRouteManifestTotals(i, routeIndex, destinationTotalManifest);
		}

		if(configuredMoveType == 'automated') {
			userFleets[i].moveType = await resolveAutomatedTravelMode(userFleets[i], destinationTotalManifest);
			userFleets[i].automatedTravelMoveType = userFleets[i].moveType;
		}
		await persistFleetTransportRouteState(i, userFleets[i].moveType, destCoord, routeIndex, configuredMoveType);
		userFleets[i].resupplying = false;
		cLog(3,`${FleetTimeStamp(userFleets[i].label)} userFleets[i]: `, userFleets[i]);
		return true;
	}

	async function handleSupplyChain(i, fleetState, fleetCoords) {
		const fleetParsedData = JSON.parse(await GM.getValue(userFleets[i].publicKey.toString(), '{}'));
		const transportPlusLegs = getTransportPlusLegs(fleetParsedData, userFleets[i].starbaseCoord, userFleets[i].destCoord);
		const activeTransportPlusRouteIndex = getTransportPlusRouteIndex(fleetParsedData, transportPlusLegs.length);
		if(transportPlusLegs.length < 2 || transportPlusLegs.some(route => !route.sourceCoord || !route.destCoord)) {
			cLog(1,`${FleetTimeStamp(userFleets[i].label)} Supply Chain - ERROR: Missing route coordinates`);
			updateFleetState(userFleets[i], 'ERROR: Missing Supply Chain route');
			return;
		}

		let activeLeg = null;
		if (fleetState === 'Idle' && activeTransportPlusRouteIndex === transportPlusLegs.length - 1) {
			const completedLeg = transportPlusLegs[activeTransportPlusRouteIndex];
			if(completedLeg && CoordsEqual(fleetCoords, ConvertCoords(completedLeg.destCoord))) {
				await maybeFinalizeFleetTelemetryCostCycle(userFleets[i], fleetParsedData, getFleetTelemetryHomeStarbaseName(userFleets[i], fleetParsedData), transportPlusLegs.length);
			}
		}
		if (fleetState === 'Idle') {
			if(activeTransportPlusRouteIndex !== null) {
				const indexedLeg = transportPlusLegs[activeTransportPlusRouteIndex];
				if(indexedLeg && CoordsEqual(fleetCoords, ConvertCoords(indexedLeg.destCoord))) {
					activeLeg = transportPlusLegs[(activeTransportPlusRouteIndex + 1) % transportPlusLegs.length];
				} else if(indexedLeg && CoordsEqual(fleetCoords, ConvertCoords(indexedLeg.sourceCoord))) {
					activeLeg = indexedLeg;
				}
			}
			if(!activeLeg) activeLeg = transportPlusLegs.find(route => CoordsEqual(fleetCoords, ConvertCoords(route.sourceCoord)));
			if(activeLeg) {
				const handled = await handleTransportStop(i, activeLeg.sourceCoord, activeLeg.destCoord, activeLeg.currentManifest, activeLeg.destinationManifest, activeLeg.moveType, activeLeg.roundTrip, activeLeg.routeIndex);
				if(handled === false) return;
			}
		}

		if(userFleets[i].stopping) return;

			const activeMoveTarget = userFleets[i].moveTarget && userFleets[i].moveTarget !== '' ? userFleets[i].moveTarget : (fleetParsedData.moveTarget || '');
			if (activeMoveTarget !== '') {
				const activeMoveTargetCoords = ConvertCoords(activeMoveTarget);
				if(!activeLeg && activeTransportPlusRouteIndex !== null) {
					const indexedLeg = transportPlusLegs[activeTransportPlusRouteIndex];
					if(indexedLeg && CoordsEqual(ConvertCoords(indexedLeg.destCoord), activeMoveTargetCoords)) activeLeg = indexedLeg;
				}
				if(!activeLeg) activeLeg = transportPlusLegs.find(route => CoordsEqual(ConvertCoords(route.destCoord), activeMoveTargetCoords));
				if(activeLeg) {
					userFleets[i].moveType = activeLeg.moveType == 'automated' ? (userFleets[i].automatedTravelMoveType || 'subwarp') : activeLeg.moveType;
					userFleets[i].moveTarget = activeMoveTarget;
					userFleets[i].transportPlusRouteIndex = activeLeg.routeIndex;
				}
				const targetX = activeMoveTarget.split(',').length > 1 ? activeMoveTarget.split(',')[0].trim() : '';
				const targetY = activeMoveTarget.split(',').length > 1 ? activeMoveTarget.split(',')[1].trim() : '';
				const moveDist = calculateMovementDistance(fleetCoords, [targetX,targetY]);
				let isStarbaseAndWarpSubwarp = false;
				if(activeLeg && userFleets[i].moveType == 'warpsubwarp') {
					const activeSourceCoords = ConvertCoords(activeLeg.sourceCoord);
					const activeDestCoords = ConvertCoords(activeLeg.destCoord);
					isStarbaseAndWarpSubwarp =
						(fleetCoords[0] == activeSourceCoords[0] && fleetCoords[1] == activeSourceCoords[1]) ||
						(fleetCoords[0] == activeDestCoords[0] && fleetCoords[1] == activeDestCoords[1]);
				}
				await handleMovement(i, moveDist, targetX, targetY, isStarbaseAndWarpSubwarp);
			} else {
				let recovery = await inferTransportRecoveryLeg(userFleets[i], transportPlusLegs.map(leg => ({
					label: `${leg.sourceCoord} -> ${leg.destCoord}`,
					sourceCoord: leg.sourceCoord,
					destCoord: leg.destCoord,
					moveType: leg.moveType,
					routeIndex: leg.routeIndex,
					destinationManifest: leg.destinationManifest
				})), activeTransportPlusRouteIndex);
				if(recovery.recovered) {
					await recoverTransportMovement(i, fleetCoords, recovery, 'Supply Chain');
				} else {
					cLog(1,`${FleetTimeStamp(userFleets[i].label)} Supply Chain - ERROR: Fleet must start at Starbase or a configured target (${recovery.reason})`);
					updateFleetState(userFleets[i], 'ERROR: Fleet must start at Starbase or a configured target');
				}
			}
		}

	async function getFleetFuelData(fleet, currentPos, targetPos, roundTrip = true) {
		const moveDist = calculateMovementDistance(currentPos, targetPos);
		const fleetCurrentFuelTank = await solanaReadConnection.getParsedTokenAccountsByOwner(fleet.fuelTank, {programId: tokenProgramPK});
		const token = fleetCurrentFuelTank.value.find(item => item.account.data.parsed.info.mint === sageGameAcct.account.mints.fuel.toString());
		const account = token ? token.pubkey : await getFleetFuelToken(fleet);
		const amount = token ? token.account.data.parsed.info.tokenAmount.uiAmount - fleet.exitSubwarpWillBurnFuel : 0;
        const warpCost = calcWarpFuelReq(fleet, currentPos, targetPos, fleet.moveType == 'warpsubwarp');
        const subwarpCost = Math.ceil(calculateSubwarpFuelBurn(fleet, moveDist));

        //Calculate fuel needed
        const costMultiplier = roundTrip ? 2 : 1;
        let fuelNeeded = 0;
        if (fleet.moveType == 'warp' || fleet.moveType == 'warpsubwarp' || fleet.moveType == 'warp-subwarp-warp') {
            fuelNeeded = warpCost * costMultiplier;
            if (fuelNeeded > fleet.fuelCapacity) fuelNeeded = roundTrip ? warpCost + subwarpCost : subwarpCost;
        } else {
            fuelNeeded = subwarpCost * costMultiplier;
        }

		//cLog(4, `${FleetTimeStamp(fleet.label)} getFleetFuelData -> calcWarpFuelReq:`, currentPos, targetPos);
		return {
			account,
			token,
			amount,
			capacity: fleet.fuelCapacity,
			warpCost: warpCost,
			subwarpCost: subwarpCost,
            fuelNeeded: fuelNeeded
		}
	}

	async function fuelFleet(fleet, dockCoords, account, amount, returnTx) {
		cLog(1,`${FleetTimeStamp(fleet.label)} Filling fuel tank: ${amount}`);
		let fuelCargoTypeAcct = cargoTypes.find(item => item.account.mint.toString() == sageGameAcct.account.mints.fuel);
		const fuelResp = await execCargoFromStarbaseToFleet(
			fleet,
			fleet.fuelTank,
			account,
			sageGameAcct.account.mints.fuel.toString(),
			fuelCargoTypeAcct,
			dockCoords,
			amount,
			globalSettings.fleetForceConsumableAmount,
			returnTx
		);

		return fuelResp;
	}

	async function handleTransportRefueling(fleet, starbaseCoord, currentPos, targetPos, roundTrip = true, amountToDropOff = 0, transportManifest, returnTx) {
		cLog(1,`${FleetTimeStamp(fleet.label)} ⛽ Refueling`);
		updateFleetState(fleet, 'Refueling');
        let fuelResp = {status: 0, detail: '', amount: 0};

		const fuelData = await getFleetFuelData(fleet, currentPos, targetPos, roundTrip);

        /*
		//Calculate fuel needed
		const costMultiplier = roundTrip ? 2 : 1;
		let fuelNeeded = 0;
		if (fleet.moveType == 'warp') {
			fuelNeeded = fuelData.warpCost * costMultiplier;
			if(fuelNeeded > fuelData.capacity)
				if(roundTrip) fuelNeeded = fuelData.warpCost + fuelData.subwarpCost;
				else fuelNeeded = fuelData.subwarpCost;
		} else fuelNeeded = fuelData.subwarpCost * costMultiplier;
        */

		if(fuelData.fuelNeeded > fuelData.capacity) {
			cLog(1,`${FleetTimeStamp(fleet.label)} ERROR: Fuel tank too small for round trip`);
            fuelResp.detail = 'ERROR: Fuel tank too small for round trip';
			return fuelResp;
		}

        const fuelEntry = transportManifest.find(e => e.res === sageGameAcct.account.mints.fuel.toString()) || {amt: 0};

		//Log fuel readouts
		const extraFuel = Math.floor(fuelData.amount - fuelData.fuelNeeded);
		cLog(2, `${FleetTimeStamp(fleet.label)} Current Fuel: ${fuelData.amount}`);
		cLog(2, `${FleetTimeStamp(fleet.label)} Warp Cost: ${fuelData.warpCost}`);
		cLog(2, `${FleetTimeStamp(fleet.label)} Subwarp Cost: ${fuelData.subwarpCost}`);
        cLog(2, `${FleetTimeStamp(fleet.label)} Fuel To Transport: ${fuelEntry.amt}`);
		cLog(2, `${FleetTimeStamp(fleet.label)} Extra Fuel: ${extraFuel}`);

		let transactions = [];
		let alreadyLoaded=0;

		//Unload extra fuel from tank
		if(amountToDropOff > 0) {
			const fuelToUnload = Math.min(amountToDropOff, extraFuel);
			if (fuelToUnload > 0) {
				cLog(1,`${FleetTimeStamp(fleet.label)} Unloading extra fuel: ${fuelToUnload}`);
				let resp = await execCargoFromFleetToStarbase(fleet, fleet.fuelTank, sageGameAcct.account.mints.fuel.toString(), starbaseCoord, fuelToUnload, returnTx);
				alreadyLoaded -= fuelToUnload;
				if(returnTx && resp) {
					transactions.push(resp);
				}
			}
		}

		//Calculate amount of fuel to add to the tank
        const totalFuel = fuelData.fuelNeeded + fuelEntry.amt;
		let fuelToAdd = Math.min(fuelData.capacity, totalFuel) - fuelData.amount;
		fuelResp.alreadyLoaded = alreadyLoaded;

		//Bail if already has enough
		if (fuelToAdd <= 0) {
            fuelResp.status = 1;
            fuelResp.amount = fuelData.amount + fuelToAdd - fuelData.fuelNeeded;
            if(transactions.length > 0) fuelResp.transactions = transactions;
            return fuelResp;
        }

        if(globalSettings.transportFuel100 && roundTrip && fuelToAdd < fuelData.capacity - fuelData.amount) {
            fuelToAdd = fuelData.capacity - fuelData.amount;
        }

		//Put in the fuel
        let execResp = await fuelFleet(fleet, starbaseCoord, fuelData.account, fuelToAdd, returnTx);

        if (execResp && execResp.name == 'NotEnoughResource') {
			cLog(1,`${FleetTimeStamp(fleet.label)} ERROR: Not enough fuel`);
			if(globalSettings.emailNotEnoughFFA) await sendEMail(fleet.label + ' not enough fuel', '');
            fuelResp.detail = 'ERROR: Not enough fuel';
		} else {
            fuelResp.status = 1;
            fuelResp.amount = fuelData.amount + fuelToAdd - fuelData.fuelNeeded;
            alreadyLoaded += fuelToAdd;
            fuelResp.alreadyLoaded = alreadyLoaded;
            if(returnTx && execResp.tx) {
		transactions.push(execResp.tx);
            }
        }
		if(transactions.length > 0) fuelResp.transactions = transactions;

		return fuelResp
	}

	/*
	async function txSliceAndSend(transactions, fleet, opName, priorityFeeMultiplier, maxInstructionsPerTx) {
		let txResult;
		for (let chunk = 0; chunk < transactions.length; chunk += maxInstructionsPerTx) {
			let transactionsSlice = transactions.slice(chunk, chunk + maxInstructionsPerTx);
			if(transactionsSlice.length == 1)
				txResult = await txSignAndSend(transactionsSlice[0], fleet, opName, priorityFeeMultiplier );
			else
				txResult = await txSignAndSend(transactionsSlice, fleet, opName, priorityFeeMultiplier );
		}
		return txResult;
	}
 	*/

	//new approach: squeeze as much as possible into a transaction by calculating the exact tx sizes, only make another tx if the max tx size is exceeded
	async function txSliceAndSend(transactions, fleet, opName, priorityFeeMultiplier, maxInstructionsPerTx) {
		// TODO: maxInstructionsPerTx is not longer used, remove later
		let txResult;
		let curPos=0;
		let curSize=1;
		let lastBlock=null;
		let allTxSlices=[];

		if(fleet.exitWarpSubwarpPending) {
			const fleetAcctInfo = fleet.publicKey ? await getAccountInfo(fleet.label, 'queued exit state', fleet.publicKey) : null;
			const chainStateTag = fleetAcctInfo ? fleetAcctInfo.data.subarray(439)[0] : null;
			if(fleet.exitWarpSubwarpPending == 1 && chainStateTag == 3) {
				transactions = [await execExitWarp(fleet, true)].concat(transactions);
			} else if(fleet.exitWarpSubwarpPending == 2 && chainStateTag == 4) {
				transactions = [await execExitSubwarp(fleet, true)].concat(transactions);
			} else {
				cLog(1,`${FleetTimeStamp(fleet.label)} Skipping stale queued exit warp/subwarp, chain state tag: ${chainStateTag}`);
			}
			fleet.exitWarpSubwarpPending = 0;
			fleet.exitSubwarpWillBurnFuel = 0;
		}

		while(curPos+curSize <= transactions.length) {

			let instructions = [];
			const priorityFee = 5;
			let curBlock = transactions.slice(curPos, curPos + curSize);

			instructions.push(solanaWeb3.ComputeBudgetProgram.setComputeUnitPrice({microLamports: priorityFee}));
			curBlock.forEach(item => instructions.push(item.instruction))

			let latestBH = 'EkSnNWid2cvwEVnVx9aBqawnmiCNiDgp3gUdkDPTKN1N'; //dummy block hash
			let messageV0 = new solanaWeb3.TransactionMessage({
				payerKey: userPublicKey,
				recentBlockhash: latestBH,
				instructions,
			}).compileToV0Message(addressLookupTables);
			let tx = new solanaWeb3.VersionedTransaction(messageV0);
			//if (extraSigner) tx.sign([extraSigner]);
			let txSize = 9999;
			try {
				txSize = tx.serialize().length;
			} catch (err) {
				// couldn't serialize due to "RangeError: encoding overruns Uint8Array", so we reached the limit, txSize is still 9999 now and we will use the tx from the previous loop
			}

			// check the size (use 1216 as max size instead of 1232, just to be sure, so we have 16 bytes of free space)
			// the first ix should always fit into a tx
			if(curSize > 1 && txSize > 1216) {
				allTxSlices.push(lastBlock);
				lastBlock = null;
				curPos += curSize - 1;
				curSize = 1;
			} else {
				curSize += 1;
			}

			lastBlock = curBlock;
		}
		if(lastBlock) {
			allTxSlices.push(lastBlock);
		}

		const sentTxResults = [];
		for (const transactionsSlice of allTxSlices) {
			if(transactionsSlice.length == 1)
				txResult = await txSignAndSend(transactionsSlice[0], fleet, opName, priorityFeeMultiplier );
			else
				txResult = await txSignAndSend(transactionsSlice, fleet, opName, priorityFeeMultiplier );
			if(txResult) sentTxResults.push(txResult);
			if(fleet.state.includes('ERROR')) break;
		}
		annotateSlyaTxCostAggregate(txResult, sentTxResults);
		return txResult;
	}

	async function handleTransportUnloading(fleet, starbaseCoord, transportManifest, returnTx) {
		cLog(1,`${FleetTimeStamp(fleet.label)} 🚚 Unloading Transport`);
		updateFleetState(fleet, 'Unloading');

		const ammoMint = sageGameAcct.account.mints.ammo.toString();
		const fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(fleet.cargoHold, {programId: tokenProgramPK});

		let transactions = [];
		let unloadedAmount = 0;
		let unloadedResources = [];
		let error = false;

		//Unloading resources from manifest
		let fuelUnloadDeficit = 0;
		let ammoUnloadDeficit = 0;
		const unloadEntriesByMint = new Map();
		for (const entry of transportManifest) {
			if (!entry || entry.res === '' || !(entry.amt > 0)) continue;
			let unloadEntry = unloadEntriesByMint.get(entry.res);
			if(!unloadEntry) {
				unloadEntry = { res: entry.res, plannedAmount: 0, extraAmount: 0, unloadAll: false, count: 0 };
				unloadEntriesByMint.set(entry.res, unloadEntry);
			}
			unloadEntry.count++;
			if(entry.extra) {
				unloadEntry.extraAmount += Number(entry.amt || 0);
			} else {
				unloadEntry.plannedAmount += Number(entry.amt || 0);
				unloadEntry.unloadAll = true;
			}
		}

		for (const entry of unloadEntriesByMint.values()) {
			const isFuel = entry.res === sageGameAcct.account.mints.fuel.toString();
			const isAmmo = entry.res === ammoMint;
			const currentRes = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === entry.res);
			const currentResCnt = currentRes ? currentRes.account.data.parsed.info.tokenAmount.uiAmount : 0;
			if(entry.count > 1) cLog(1,`${FleetTimeStamp(fleet.label)} Merged duplicate unload entries for ${entry.res}`);

			let amountToUnload = entry.unloadAll ? currentResCnt : Math.min(currentResCnt, entry.extraAmount);
			if(globalSettings.transportKeep1 && amountToUnload > 0) { amountToUnload -= 1; }
			if (amountToUnload > 0) {
				cLog(1,`${FleetTimeStamp(fleet.label)} Unloading ${amountToUnload} ${entry.res}`);
				let resp = await execCargoFromFleetToStarbase(fleet, fleet.cargoHold, entry.res, starbaseCoord, amountToUnload, returnTx);
				if(returnTx && resp) {
					transactions.push(resp);
				}
				if(isFuel) fuelUnloadDeficit = Math.max(0, entry.plannedAmount - amountToUnload);
				if(isAmmo) ammoUnloadDeficit = Math.max(0, entry.plannedAmount - amountToUnload);
				unloadedAmount += amountToUnload * cargoItems.find(r => r.token == entry.res).size;
				unloadedResources.push(entry.res);
				if(fleet.state.includes('ERROR')) {
					error = true;
					break;
				}
			} else {
				cLog(1,`${FleetTimeStamp(fleet.label)} Unload ${entry.res} skipped - none found in ship's cargo hold`);
				if(isFuel) fuelUnloadDeficit = entry.plannedAmount;
				if(isAmmo) ammoUnloadDeficit = entry.plannedAmount;
			}
			//if (resource == sageGameAcct.account.mints.fuel.toString() && resMax < resAmt) extraFuel = resAmt - resMax;
			//if (resource == ammoMint.toString() && resMax < resAmt) ammoToUnload = resAmt - resMax;
		}

		//Ammo bank unloading
		const ammoEntry = globalSettings.transportUseAmmoBank ? unloadEntriesByMint.get(ammoMint) : undefined;
		if (!error && ammoEntry) {
			let fleetCurrentAmmoBank = await solanaReadConnection.getParsedTokenAccountsByOwner(fleet.ammoBank, {programId: tokenProgramPK});
			let currentAmmo = fleetCurrentAmmoBank.value.find(item => item.account.data.parsed.info.mint === ammoMint);
			let currentAmmoCnt = currentAmmo ? currentAmmo.account.data.parsed.info.tokenAmount.uiAmount : 0;
			let ammoToUnload = Math.min(currentAmmoCnt, ammoUnloadDeficit);
			if(globalSettings.transportKeep1 && ammoToUnload > 0) { ammoToUnload -= 1; }
			if (ammoToUnload > 0) {
				cLog(1,`${FleetTimeStamp(fleet.label)} Unloading Ammobanks: ${ammoToUnload}`);
				let resp = await execCargoFromFleetToStarbase(fleet, fleet.ammoBank, ammoMint, starbaseCoord, ammoToUnload, returnTx);
				if(returnTx && resp) {
					transactions.push(resp);
				}
				unloadedResources.push(ammoMint);
				if(fleet.state.includes('ERROR')) {
					error = true;
				}
			}
		}

		return { fuelUnloadDeficit, transactions, unloadedAmount, unloadedResources: Array.from(new Set(unloadedResources)), error };
	}

	async function handleTransportLoading(i, starbaseCoords, transportManifest, returnTx, alreadyUnloadedInTransaction, fuelLoadedThisStop = 0) {
		cLog(1,`${FleetTimeStamp(userFleets[i].label)} 📦 Loading Transport`);
		updateFleetState(userFleets[i], 'Loading');

		//Calculate remaining free cargo space
		cLog(2,`${FleetTimeStamp(userFleets[i].label)} Calculating cargoSpace ...`);
		const fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});

		//Use ammo banks if possible
		const ammoMint = sageGameAcct.account.mints.ammo.toString();
		const ammoEntry = globalSettings.transportUseAmmoBank ? transportManifest.find(e => e.res === ammoMint) : undefined;
		const ammoEntryIndex = ammoEntry ? transportManifest.findIndex(e => e === ammoEntry) : -1;
		let resp = null;
		let transactions = [];
		let loadedCargo = {};
		let ammoLoadingIntoAmmoBank = 0;
		let ammoAlreadyInAmmoBank = 0;
		if(ammoEntry) {
			const ammoAlreadyInCargo = getParsedTokenAmount(fleetCurrentCargo, ammoMint);
			const ammoBankTarget = Math.max(0, ammoEntry.amt - ammoAlreadyInCargo);
			resp = await execLoadFleetAmmo(userFleets[i], starbaseCoords, ammoBankTarget, returnTx);
			ammoLoadingIntoAmmoBank = resp.amountLoaded;
			ammoAlreadyInAmmoBank = resp.currentAmount || 0;
		}
		const ammoInAmmoBankForManifest = ammoEntry ? Math.min(ammoEntry.amt, ammoAlreadyInAmmoBank + ammoLoadingIntoAmmoBank) : 0;
		if(ammoEntryIndex > -1 && ammoLoadingIntoAmmoBank > 0) loadedCargo[ammoEntryIndex] = (loadedCargo[ammoEntryIndex] || 0) + ammoLoadingIntoAmmoBank;
		if(returnTx && resp && resp.transaction) {
			transactions.push(resp.transaction);
			//when using a combined load tx, we need to take into account the amount loaded into the fuel tank, because the starbase still reports the original amount (otherwise we may get an ix error instead a "NotEnoughResource" error)
			ammoEntry.alreadyLoadedInTransaction = ammoLoadingIntoAmmoBank;
		}

        const cargoCnt = fleetCurrentCargo.value.reduce((n, {account}) => n + account.data.parsed.info.tokenAmount.uiAmount * cargoItems.find(r => r.token == account.data.parsed.info.mint).size, 0);
        let cargoSpace = userFleets[i].cargoCapacity - cargoCnt;
        if(alreadyUnloadedInTransaction) cargoSpace += alreadyUnloadedInTransaction;
        const startingCargoSpace = cargoSpace;
        let expectedCnt = 0;
        cLog(2,`${FleetTimeStamp(userFleets[i].label)} cargoSpace remaining: ${cargoSpace}`);

		let notEnoughInfo = '';
		for (let entryIndex=0; entryIndex<transportManifest.length; entryIndex++) {
			const entry = transportManifest[entryIndex];
			if (entry.res && entry.amt > 0) {
				if(cargoSpace < 1) {
					cLog(1,`${FleetTimeStamp(userFleets[i].label)} Cargo full - remaining loading process skipped`);
					break;
				}

				const [fleetResourceToken] = await BrowserAnchor.anchor.web3.PublicKey.findProgramAddressSync(
					[
						userFleets[i].cargoHold.toBuffer(),
						tokenProgramPK.toBuffer(),
						new solanaWeb3.PublicKey(entry.res).toBuffer()
					],
					programPK
				);
				const currentRes = fleetCurrentCargo.value.find(item => item.account.data.parsed.info.mint === entry.res);
				const fleetResAcct = currentRes ? currentRes.pubkey : fleetResourceToken;
				const resCargoTypeAcct = cargoTypes.find(item => item.account.mint.toString() == entry.res);
				const currentResAmt = currentRes ? currentRes.account.data.parsed.info.tokenAmount.uiAmount : 0;

				//Deduct ammo already loaded into ammobank if applicable
				const isAmmo = entry.res === ammoMint;
				//For ammo SLYA didn't check the ammo in the cargo room, added
				const missingCargoAmount = isAmmo ? entry.amt - ammoInAmmoBankForManifest - currentResAmt : entry.amt - currentResAmt;
				const resMax = Math.floor(Math.min(cargoSpace / cargoItems.find(r => r.token == entry.res).size, Math.max(0, missingCargoAmount)));
				expectedCnt += resMax;
				if (resMax > 0) {
					cLog(1,`${FleetTimeStamp(userFleets[i].label)} Attempting to load ${resMax} ${entry.res} from ${starbaseCoords}`);
					const resp = await execCargoFromStarbaseToFleet(
						userFleets[i],
						userFleets[i].cargoHold,
						fleetResAcct,
						entry.res,
						resCargoTypeAcct,
						starbaseCoords,
						resMax,
						false,
						returnTx,
						((returnTx && entry.alreadyLoadedInTransaction) ? entry.alreadyLoadedInTransaction : 0)
					);
                    cLog(1,`${FleetTimeStamp(userFleets[i].label)} Loaded ${resp.amount} ${entry.res}: `, resp);
                    cargoSpace -= resp && resp.amount ? cargoItems.find(r => r.token == entry.res).size * resp.amount : 0;
					if(resp && resp.amount) loadedCargo[entryIndex] = (loadedCargo[entryIndex] || 0) + resp.amount;

					if (resp && resp.name == 'NotEnoughResource') {
						const resShort = cargoItems.find(r => r.token == entry.res).name;
						cLog(1,`${FleetTimeStamp(userFleets[i].label)} Not enough ${resShort}`);
						notEnoughInfo += 'Not enough ' + resShort + '\n';
					}
					else if(returnTx && resp && resp.tx) {
						transactions.push(resp.tx);
					}
				}
			}
		}

		//Return true if cargo was added
		//const fleetCurrentCargo = await solanaReadConnection.getParsedTokenAccountsByOwner(userFleets[i].cargoHold, {programId: tokenProgramPK});
		//const cargoCnt = fleetCurrentCargo.value.reduce((n, {account}) => n + account.data.parsed.info.tokenAmount.uiAmount, 0);

		//cLog(3,`${FleetTimeStamp(userFleets[i].label)} Loading finished with ${cargoCnt} total cargo loaded`);

		const cargoHoldLoadedThisStop = Math.max(0, startingCargoSpace - cargoSpace);
		const totalLoadedThisStop = cargoHoldLoadedThisStop + Math.max(0, ammoLoadingIntoAmmoBank) + Math.max(0, Number(fuelLoadedThisStop || 0));
		const cargoAlreadyOnboard = {};
		for(const tokenAccount of fleetCurrentCargo.value) {
			const mint = tokenAccount.account.data.parsed.info.mint;
			cargoAlreadyOnboard[mint] = (cargoAlreadyOnboard[mint] || 0) + Number(tokenAccount.account.data.parsed.info.tokenAmount.uiAmount || 0);
		}
		if(ammoEntry) cargoAlreadyOnboard[ammoMint] = (cargoAlreadyOnboard[ammoMint] || 0) + ammoAlreadyInAmmoBank;
	        if (totalLoadedThisStop <= 0 && expectedCnt > 0 && !hasUsefulTransportCargoForManifest(transportManifest, cargoAlreadyOnboard)) {
	            updateFleetState(userFleets[i], 'ERROR: No cargo loaded');
	            cLog(2,`${FleetTimeStamp(userFleets[i].label)} ERROR: No cargo, ammo, or fuel loaded`);
	            if(globalSettings.emailNoCargoLoaded) await sendEMail(userFleets[i].label + ' no cargo loaded', notEnoughInfo);
	        }
		return { success: !userFleets[i].state.includes('ERROR'), transactions: transactions, loadedCargo: loadedCargo};
	}

	function startupScanBlockCheck(i, fleetCoords) {
		if(!userFleets[i].startupScanBlockCheck && fleetCoords.length > 0) {
			//Calculate current scanBlockIdx
			userFleets[i].startupScanBlockCheck = true;

			if(userFleets[i].scanMove) {
					cLog(2, `${FleetTimeStamp(userFleets[i].label)} Checking scanBlock`, userFleets[i].scanBlock);
					for (let s=0; s < userFleets[i].scanBlock.length - 1; s++) {
							const testCoords = userFleets[i].scanBlock[s];
							if (fleetCoords[0] == testCoords[0] && fleetCoords[1] == testCoords[1])
							{
									if(userFleets[i].scanBlockIdx != s) {
											userFleets[i].scanBlockIdx = s;
											cLog(2, `${FleetTimeStamp(userFleets[i].label)} Resuming scanBlockIdx: ${s}`);
									}
									break;
							}
					}
			}
		}
	}

	function updateFleetMiscStats(fleet, fleetAcctInfo) {
		let fleetAcctData = sageProgram.coder.accounts.decode('fleet', fleetAcctInfo.data);
		fleet.requiredCrew = fleetAcctData.stats.miscStats.requiredCrew;
		fleet.passengerCapacity = fleetAcctData.stats.miscStats.passengerCapacity;
		fleet.crewCount = fleetAcctData.stats.miscStats.crewCount;
	}

	let lastScanMapRead = 0;
	let lastScanMapCache=null;
	let lastScanMapIsUpdating = false;
	async function readScanMap() {

		//if a concurrent call is reading the map, we wait until the read is done (up to 10 seconds)
		let loopCounter = 0;
        	while (lastScanMapIsUpdating && loopCounter < 50) {
			await wait(200);
			loopCounter++;
		}
		if(lastScanMapRead <= Date.now()-30*1000) {

			lastScanMapIsUpdating = true;
			lastScanMapCache = null;
			lastScanMapRead = Date.now();
			let message = '';
			try {
				cLog(1, 'Requesting the SDU file');
				const response = await fetch(globalSettings.scanMapURL);
				if (!response.ok) {
					message = 'Error while reading the SDU file: ' + response.status + ' ' + response.statusText;
				} else {
					const result = await response.json();
					if(result.timestamp < Date.now() - 60*10*1000) {
						cLog(1, 'Error: SDU file too old');
					} else {
						lastScanMapCache = result.scans;
					}
				}
			} catch(error) {
				message = 'Error while requesting the SDU file: ' + error.message;
			}
			lastScanMapIsUpdating = false;
			if(message) cLog(1, message);
		} else {
			//console.log('Reading cached scan map');
		}

		return lastScanMapCache;
	}

	async function scanTargetStillValid(i,fleetCoords) {
		let scanData = await readScanMap();
		if(!scanData) {
			userFleets[i].fontColor = 'yellow';
			updateAssistStatus(userFleets[i]);
			return true;
		}
		let scanX = fleetCoords[0];
		let scanY = fleetCoords[1];
		let scan = scanData.find(item => item.x == scanX && item.y == scanY);
		let cooldownLeft = (userFleets[i].scanEnd - Date.now())/1000;
		let lowerThreshold = userFleets[i].scanCooldown * (userFleets[i].scanCheckWhileCooldownLeft/100);
		if(userFleets[i].scanCooldown - lowerThreshold <= 0) return true; //prevent division by zero

		if(cooldownLeft < lowerThreshold) {
			cLog(3,`${FleetTimeStamp(userFleets[i].label)} SAM scan coord`,scanX,`/`,scanY,` lower cooldown threshold reached, fleet stays here until scan.`);
			return true;
		}

		let currentThreshold = (cooldownLeft - lowerThreshold) / (userFleets[i].scanCooldown - lowerThreshold) * userFleets[i].scanMin2;

		if(scan && scan.c * 100 < currentThreshold) {
			cLog(3,`${FleetTimeStamp(userFleets[i].label)} SAM scan coord`,scanX,`/`,scanY,`turned bad while waiting for the cooldown.`);
			return false;
		}

		const nearbyAdvantageThreshold = getScanningNearbyAdvantageThreshold(scan?.c * 100, userFleets[i].scanNearbyAdvantage);
		if(nearbyAdvantageThreshold !== null) {
			userFleets[i].scanProactiveMoveThreshold = nearbyAdvantageThreshold;
			cLog(3, `${FleetTimeStamp(userFleets[i].label)} SAM checking for sector at least ${nearbyAdvantageThreshold}% (${userFleets[i].scanNearbyAdvantage} points better).`);
			return false;
		}
		cLog(3,`${FleetTimeStamp(userFleets[i].label)} SAM scan coord`,scanX,`/`,scanY,`still valid.`);
		return true;
	}

	async function scanAutoHasEnoughFuel(i, fleetCoords) {
		if(!userFleets[i].scanHomeAtPercent || userFleets[i].scanHomeAtPercent <= 100) return true;
		const starbaseCoords = ConvertCoords(userFleets[i].starbaseCoord);
		if(userFleets[i].scanStartForcedResupply) return false;
		let fuelNeeded = 0;
		if (userFleets[i].moveType == 'warp' || userFleets[i].moveType == 'warp-subwarp-warp') {
			fuelNeeded = calcWarpFuelReq(userFleets[i], fleetCoords, starbaseCoords);
		} else {
			const distFromTargetToStarbase = calculateMovementDistance(fleetCoords, starbaseCoords);
			fuelNeeded = calculateSubwarpFuelBurn(userFleets[i], distFromTargetToStarbase);
		}
		cLog(3,`${FleetTimeStamp(userFleets[i].label)} SAM last fuel amount`,userFleets[i].scanLastFuelAmount,'fuelNeeded',fuelNeeded,'fuelNeededAlt',(fuelNeeded*(userFleets[i].scanHomeAtPercent/100)));
		const hasEnoughFuel = (typeof userFleets[i].scanLastFuelAmount == 'undefined' || userFleets[i].scanLastFuelAmount > fuelNeeded * (userFleets[i].scanHomeAtPercent/100));
		if(!hasEnoughFuel) userFleets[i].scanStartForcedResupply = true;
		return hasEnoughFuel;
	}

